insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-01','3~4','중국어','중국어와 한자 만나기','중국어는 어떤 글자로 쓰고, 어떻게 읽을까?','assets/img/l_c3-01.jpg',$j${"intro": "식당 메뉴판이나 과자 봉지에서 네모난 글자를 본 적 있나요? 그 글자가 바로 한자예요. 오늘은 중국어가 어떤 말인지, 한자는 어떻게 생겨났는지 알아봐요.", "sections": [{"heading": "중국어는 세계에서 아주 많은 사람이 쓰는 말이에요", "paras": ["중국어는 중국(中国, Zhōngguó, 중궈) 사람들이 쓰는 말이에요. 세계에서 가장 많은 사람이 쓰는 말 가운데 하나예요.", "중국은 땅이 넓어서 지역마다 말이 조금씩 달라요. 그래서 모두가 함께 알아듣는 '표준 중국어'를 학교에서 배워요. 우리가 배울 말도 바로 이 표준 중국어예요.", "중국어를 중국어로 中文(Zhōngwén, 중원)이라고 해요."], "example": "中国(Zhōngguó, 중궈) = 중국 / 中文(Zhōngwén, 중원) = 중국어", "figure": "세계 지도에서 한국과 중국이 가깝게 붙어 있는 모습을 보여 주는 그림"}, {"heading": "한자는 그림에서 생겨났어요", "paras": ["중국어는 알파벳이나 한글 대신 한자(汉字, hànzì, 한쯔)로 써요. 한자 한 글자에는 소리와 함께 뜻이 들어 있어요.", "아주 옛날 사람들은 눈에 보이는 것을 그림으로 그렸어요. 그 그림이 점점 간단해져서 한자가 되었어요. 봉우리가 셋 있는 산 모양은 山(shān, 산), 둥근 해 모양은 日(rì, 르)이 되었지요.", "사람이 걷는 옆모습은 人(rén, 런), 벌린 입 모양은 口(kǒu, 커우)가 되었어요. 글자를 보며 어떤 그림이었을지 상상해 보세요."], "example": "⛰️ 山(shān, 산) 산 / 💧 水(shuǐ, 수이) 물 / ☀️ 日(rì, 르) 해 / 🌙 月(yuè, 위에) 달", "figure": "산, 물줄기, 해, 달 그림이 차례로 한자 山, 水, 日, 月 모양으로 바뀌어 가는 모습"}, {"heading": "중국에서는 간단하게 줄인 한자를 써요", "paras": ["한자는 획(한 번에 긋는 선)이 많아서 쓰기 어려운 글자가 많아요. 그래서 중국에서는 획을 줄여 간단하게 만든 '간체자'를 써요.", "옛날 모양 그대로인 한자는 '번체자'라고 해요. 우리나라 책이나 간판에 나오는 한자는 대부분 번체자예요.", "예를 들어 '배우다'라는 뜻의 한자는 번체자로 學, 간체자로 学이라고 써요. 우리는 간체자로 중국어를 배워요."], "example": "번체자 學 → 간체자 学 (배우다) / 번체자 漢 → 간체자 汉 (한나라, 한자의 '한')", "figure": "획이 많은 한자와 간단해진 한자를 나란히 놓고 비교하는 카드 두 장"}, {"heading": "소리는 '병음'으로 알 수 있어요", "paras": ["한자만 보고는 어떻게 읽는지 알기 어려워요. 그래서 중국에서는 알파벳으로 소리를 적어 주는데, 이것을 '병음'이라고 해요.", "병음 위에는 ā, á, ǎ, à 같은 작은 표시가 붙어요. 이것은 소리의 높낮이인 '성조'를 알려 줘요. 다음 시간에 자세히 배워요.", "같은 한자라도 우리나라 한자음과 중국어 소리는 달라요. 人은 우리말 한자음으로 '인'이지만 중국어로는 rén(런)이라고 읽어요."], "example": "大(dà, 다) 크다 / 小(xiǎo, 샤오) 작다 / 人(rén, 런) 사람", "figure": "한자 카드 아래에 알파벳 병음이 적힌 작은 카드가 붙어 있는 모습"}], "keywords": [{"word": "한자", "meaning": "중국어를 적는 글자. 한 글자마다 뜻과 소리가 있어요."}, {"word": "간체자", "meaning": "획을 줄여 간단하게 만든 한자. 중국에서 써요."}, {"word": "번체자", "meaning": "옛날 모양 그대로 획이 많은 한자."}, {"word": "병음", "meaning": "한자의 중국어 소리를 알파벳으로 적은 것."}, {"word": "성조", "meaning": "중국어 소리의 높낮이. 병음 위에 표시해요."}], "expressions": [{"en": "中国", "ko": "중국", "note": "Zhōngguó (중궈)"}, {"en": "中文", "ko": "중국어", "note": "Zhōngwén (중원)"}, {"en": "汉字", "ko": "한자", "note": "hànzì (한쯔)"}, {"en": "人", "ko": "사람", "note": "rén (런)"}, {"en": "口", "ko": "입", "note": "kǒu (커우)"}, {"en": "山", "ko": "산", "note": "shān (산)"}, {"en": "水", "ko": "물", "note": "shuǐ (수이)"}, {"en": "日", "ko": "해, 날", "note": "rì (르)"}, {"en": "月", "ko": "달", "note": "yuè (위에)"}, {"en": "大", "ko": "크다", "note": "dà (다)"}, {"en": "小", "ko": "작다", "note": "xiǎo (샤오)"}], "quiz": [{"q": "중국어를 적을 때 쓰는 글자는 무엇일까요?", "choices": ["한글", "한자", "가나", "알파벳"], "answer": 1, "explain": "중국어는 뜻과 소리를 함께 담은 글자인 한자로 써요."}, {"q": "해의 둥근 모양에서 생긴 한자는 무엇일까요?", "choices": ["山", "口", "日", "人"], "answer": 2, "explain": "日(rì)은 둥근 해를 본떠 만든 글자예요."}, {"q": "중국에서 쓰는, 획을 줄여 간단하게 만든 한자를 무엇이라고 할까요?", "choices": ["간체자", "번체자", "병음", "성조"], "answer": 0, "explain": "중국에서는 획을 줄인 간체자를 써요. 옛날 모양 그대로인 한자는 번체자예요."}, {"q": "한자의 중국어 소리를 알파벳으로 적은 것은 무엇일까요?", "choices": ["성조", "번체자", "간체자", "병음"], "answer": 3, "explain": "병음은 한자 읽는 법을 알파벳으로 적은 것이에요."}, {"q": "人의 중국어 소리로 알맞은 것은 무엇일까요?", "choices": ["shān", "kǒu", "rén", "dà"], "answer": 2, "explain": "人은 중국어로 rén(런)이라고 읽어요. 우리말 한자음 '인'과 달라요."}], "summary": ["중국어는 한자로 쓰고, 중국에서는 획을 줄인 간체자를 써요.", "山, 水, 日, 月, 人, 口 같은 한자는 사물의 모양을 본떠 만들었어요.", "한자의 소리는 알파벳으로 적은 병음으로 알 수 있고, 병음 위 표시는 성조예요."], "parent_tip": "아이들은 우리말 한자음(人=인)과 중국어 소리(rén)를 섞어 읽기 쉽습니다. 두 소리를 나란히 말해 보며 다르다는 것을 느끼게 해 주세요. 집 안의 물건(물, 해, 산 사진)을 보며 '이건 한자로 어떻게 생겼을까?' 하고 함께 그려 보면 좋습니다."}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','중국어와 한자 만나기',1,'c3-01' where not exists (select 1 from public.topics where lesson_slug='c3-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-02','3~4','중국어','성조 네 가지','같은 ''마''인데 왜 뜻이 다를까?','assets/img/l_c3-02.jpg',$j${"intro": "중국어에서 '마'라고 말하면 엄마가 될 수도 있고, 말(동물)이 될 수도 있어요. 비밀은 소리의 높낮이인 '성조'에 있어요. 오늘은 성조 네 가지를 노래하듯 익혀 봐요.", "sections": [{"heading": "성조는 소리의 높낮이예요", "paras": ["중국어의 모든 글자에는 정해진 소리 높낮이가 있어요. 이것을 '성조'라고 해요.", "성조는 1성, 2성, 3성, 4성 네 가지가 있어요. 같은 ma라도 성조가 다르면 전혀 다른 뜻이 돼요.", "그래서 중국어를 배울 때는 소리와 함께 성조도 꼭 같이 외워야 해요."], "example": "妈(mā, 마) 엄마 / 麻(má, 마) 삼(옷감을 만드는 풀) / 马(mǎ, 마) 말 / 骂(mà, 마) 꾸짖다", "figure": "엄마, 삼베 풀, 말, 화난 얼굴 그림 위에 각각 ma 소리와 성조 화살표가 그려진 네 칸 그림"}, {"heading": "1성과 2성: 쭉~ 그리고 위로!", "paras": ["1성(ā)은 높은 소리를 처음부터 끝까지 평평하게 쭉 이어요. '도레미파솔'의 '솔' 높이로 길게 '마~' 하고 노래하듯 말해요.", "2성(á)은 낮은 곳에서 높은 곳으로 올라가요. 친구 말을 못 알아듣고 '어?' 하고 되물을 때처럼 소리를 위로 올려요."], "example": "1성: 妈(mā) 엄마, 八(bā, 빠) 여덟 / 2성: 麻(má) 삼, 十(shí, 스) 열", "figure": "수평으로 쭉 뻗은 화살표(1성)와 왼쪽 아래에서 오른쪽 위로 올라가는 화살표(2성)"}, {"heading": "3성과 4성: 내려갔다 올라오고, 뚝!", "paras": ["3성(ǎ)은 낮게 내려갔다가 살짝 올라와요. '아~하!' 하고 무언가를 알았을 때처럼 목소리를 아래로 눌렀다가 올려요.", "4성(à)은 높은 곳에서 아래로 뚝 떨어져요. 멀리 있는 친구를 '야!' 하고 짧고 힘 있게 부르는 느낌이에요.", "손으로 성조 모양을 그리며 말하면 훨씬 쉽게 익힐 수 있어요."], "example": "3성: 马(mǎ) 말, 五(wǔ, 우) 다섯 / 4성: 骂(mà) 꾸짖다, 四(sì, 쓰) 넷", "figure": "V자처럼 내려갔다 올라가는 화살표(3성)와 위에서 아래로 떨어지는 화살표(4성)"}, {"heading": "성조 표시는 이렇게 붙여요", "paras": ["성조 표시는 병음의 모음(a, o, e, i, u, ü) 위에 붙여요. 자음 위에는 붙이지 않아요.", "모음이 여러 개면 a가 있을 때 a 위에, a가 없으면 o나 e 위에 붙여요. iu와 ui는 뒤 글자 위에 붙여요. 예를 들어 六은 liù, 水는 shuǐ예요.", "표시 없이 짧고 가볍게 읽는 소리도 있어요. 이것을 '경성'이라고 해요. 물을 때 쓰는 吗(ma)가 경성이에요."], "example": "hǎo(好) → a 위 / duō(多) → o 위 / liù(六) → u 위 / 吗(ma) → 표시 없음(경성)", "figure": "병음 카드에서 모음 위에 성조 표시가 붙는 자리를 동그라미로 표시한 그림"}], "keywords": [{"word": "성조", "meaning": "중국어 글자마다 정해진 소리의 높낮이"}, {"word": "1성", "meaning": "높고 평평하게 쭉 이어지는 소리 (ā)"}, {"word": "2성", "meaning": "아래에서 위로 올라가는 소리 (á)"}, {"word": "3성", "meaning": "낮게 내려갔다가 살짝 올라오는 소리 (ǎ)"}, {"word": "4성", "meaning": "위에서 아래로 뚝 떨어지는 소리 (à)"}, {"word": "경성", "meaning": "성조 표시 없이 짧고 가볍게 읽는 소리"}], "expressions": [{"en": "妈", "ko": "엄마", "note": "mā (마, 1성)"}, {"en": "麻", "ko": "삼(옷감을 만드는 풀)", "note": "má (마, 2성)"}, {"en": "马", "ko": "말(동물)", "note": "mǎ (마, 3성)"}, {"en": "骂", "ko": "꾸짖다", "note": "mà (마, 4성)"}, {"en": "吗", "ko": "~니?(물을 때 문장 끝에 붙여요)", "note": "ma (마, 경성)"}, {"en": "八", "ko": "여덟", "note": "bā (빠, 1성)"}, {"en": "十", "ko": "열", "note": "shí (스, 2성)"}, {"en": "五", "ko": "다섯", "note": "wǔ (우, 3성)"}, {"en": "四", "ko": "넷", "note": "sì (쓰, 4성)"}], "quiz": [{"q": "처음부터 끝까지 높고 평평하게 쭉 이어지는 성조는 무엇일까요?", "choices": ["1성", "2성", "3성", "4성"], "answer": 0, "explain": "1성은 '솔' 높이로 평평하게 길게 내는 소리예요."}, {"q": "'말(동물)'을 뜻하는 马의 병음으로 알맞은 것은 무엇일까요?", "choices": ["mā", "má", "mǎ", "mà"], "answer": 2, "explain": "马는 3성 mǎ예요. 낮게 내려갔다가 살짝 올라와요."}, {"q": "'야!' 하고 부를 때처럼 위에서 아래로 뚝 떨어지는 성조는 무엇일까요?", "choices": ["1성", "2성", "3성", "4성"], "answer": 3, "explain": "4성(à)은 높은 곳에서 아래로 짧고 힘 있게 떨어져요."}, {"q": "성조 표시는 병음의 어디에 붙일까요?", "choices": ["자음 위", "모음 위", "글자 맨 앞", "글자 맨 뒤"], "answer": 1, "explain": "성조 표시는 a, o, e, i, u, ü 같은 모음 위에 붙여요."}, {"q": "성조 표시 없이 짧고 가볍게 읽는 吗(ma)의 소리를 무엇이라고 할까요?", "choices": ["1성", "경성", "3성", "4성"], "answer": 1, "explain": "성조 표시가 없고 가볍게 읽는 소리를 경성이라고 해요."}], "summary": ["중국어에는 1성, 2성, 3성, 4성 네 가지 성조가 있어요.", "1성은 쭉, 2성은 위로, 3성은 내려갔다 올라오고, 4성은 뚝 떨어져요.", "성조 표시는 모음 위에 붙이고, 표시 없이 가볍게 읽는 소리는 경성이에요."], "parent_tip": "아이들은 2성과 3성을 가장 많이 헷갈립니다. 손가락으로 성조 모양을 허공에 그리며 함께 소리 내 보세요. '妈 mā, 麻 má, 马 mǎ, 骂 mà'를 노래처럼 반복하고, 부모님이 하나를 말하면 아이가 몇 성인지 손가락으로 맞히는 놀이를 해 보세요."}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','성조 네 가지',2,'c3-02' where not exists (select 1 from public.topics where lesson_slug='c3-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-03','3~4','중국어','병음 운모','병음의 뒷소리 ''운모''는 어떻게 읽을까?','assets/img/l_c3-03.jpg',$j${"intro": "한글 '마'가 ㅁ과 ㅏ로 이루어진 것처럼, 중국어 병음 mā도 앞소리와 뒷소리로 나눌 수 있어요. 오늘은 뒷소리인 '운모'를 소리 내어 익혀 봐요.", "sections": [{"heading": "병음은 앞소리와 뒷소리로 나뉘어요", "paras": ["병음의 앞소리를 '성모', 뒷소리를 '운모'라고 해요. 한글로 치면 성모는 자음, 운모는 모음과 비슷해요.", "예를 들어 妈(mā, 마)는 성모 m과 운모 a가 만나서 된 소리예요. 성조 표시는 운모 위에 붙어요.", "운모는 성모 없이 혼자서도 글자 소리가 될 수 있어요."], "example": "妈 mā = m(성모) + a(운모) / 狗 gǒu = g(성모) + ou(운모)", "figure": "mā라는 병음 카드를 m 카드와 a 카드 두 장으로 나누는 그림"}, {"heading": "기본 운모 여섯 개: a o e i u ü", "paras": ["a는 입을 크게 벌려 '아', o는 입술을 둥글게 하고 '오어', e는 입을 살짝 벌리고 '으어'처럼 소리 내요.", "i는 '이', u는 입술을 앞으로 내밀고 '우'예요. ü는 입술을 동그랗게 모은 채 '이'라고 말하면 '위'처럼 소리 나요.", "운모가 혼자 글자 소리가 될 때는 앞에 y나 w를 붙여요. i는 yi, u는 wu, ü는 yu(두 점을 빼요)라고 써요."], "example": "饿 è(으어) 배고프다 / 一 yī(이) 하나 / 五 wǔ(우) 다섯 / 鱼 yú(위) 물고기 / 绿 lǜ(뤼) 초록", "figure": "입 모양 여섯 개를 그린 얼굴 그림: 크게 벌린 입, 둥근 입, 살짝 벌린 입, 옆으로 벌린 입, 내민 입, 동그랗게 모은 입"}, {"heading": "두 소리가 합쳐진 운모: ai ei ao ou", "paras": ["두 모음이 이어지면 앞소리를 크게, 뒷소리를 살짝 붙여 한 번에 미끄러지듯 읽어요.", "ai는 '아이', ei는 '에이', ao는 '아오', ou는 '어우'처럼 소리 나요. ou를 '오우'가 아니라 '어우'에 가깝게 읽는 것에 주의해요."], "example": "爱 ài(아이) 사랑하다 / 黑 hēi(헤이) 검다 / 猫 māo(마오) 고양이 / 狗 gǒu(거우) 개", "figure": "고양이와 강아지가 나란히 앉아 있고 그 옆에 하트가 떠 있는 그림"}, {"heading": "콧소리로 끝나는 운모: an en ang eng ong", "paras": ["n으로 끝나면 혀끝을 윗잇몸에 붙이며 '안', '언'처럼 끝내요. ng로 끝나면 혀 뒤쪽을 올려 '앙', '엉'처럼 코로 소리를 울려요.", "an과 ang, en과 eng은 비슷해 보이지만 다른 소리예요. 끝소리를 잘 듣고 구별해 봐요. ong은 '옹'과 '웅' 사이 소리예요."], "example": "门 mén(먼) 문 / 糖 táng(탕) 사탕 / 三 sān(싼) 셋", "figure": "입 옆에 혀 위치를 보여 주는 옆모습 그림 두 개: 혀끝이 윗잇몸에 닿은 모습과 혀 뒤쪽이 올라간 모습"}], "keywords": [{"word": "운모", "meaning": "병음의 뒷소리. 한글의 모음과 비슷해요."}, {"word": "성모", "meaning": "병음의 앞소리. 한글의 자음과 비슷해요."}, {"word": "ü", "meaning": "입술을 동그랗게 모으고 '이'라고 하는 소리(위)"}, {"word": "콧소리 운모", "meaning": "n이나 ng로 끝나 코를 울리는 운모(an, ang 등)"}], "expressions": [{"en": "一", "ko": "하나", "note": "yī (이)"}, {"en": "五", "ko": "다섯", "note": "wǔ (우)"}, {"en": "饿", "ko": "배고프다", "note": "è (으어)"}, {"en": "我", "ko": "나", "note": "wǒ (워)"}, {"en": "鱼", "ko": "물고기", "note": "yú (위)"}, {"en": "绿", "ko": "초록", "note": "lǜ (뤼)"}, {"en": "爱", "ko": "사랑하다", "note": "ài (아이)"}, {"en": "黑", "ko": "검다", "note": "hēi (헤이)"}, {"en": "猫", "ko": "고양이", "note": "māo (마오)"}, {"en": "狗", "ko": "개", "note": "gǒu (거우)"}, {"en": "门", "ko": "문", "note": "mén (먼)"}, {"en": "糖", "ko": "사탕", "note": "táng (탕)"}], "quiz": [{"q": "병음 mā에서 운모는 무엇일까요?", "choices": ["m", "a", "ā와 m 모두", "없어요"], "answer": 1, "explain": "mā는 성모 m과 운모 a로 되어 있어요."}, {"q": "입술을 동그랗게 모은 채 '이'라고 말하는 운모는 무엇일까요?", "choices": ["u", "o", "ü", "e"], "answer": 2, "explain": "ü는 입술은 '우' 모양, 혀는 '이' 자리에 두고 내는 소리예요."}, {"q": "'고양이' 猫의 병음으로 알맞은 것은 무엇일까요?", "choices": ["māo", "mōu", "mēi", "mán"], "answer": 0, "explain": "猫는 m + ao로 māo(마오)예요."}, {"q": "狗(gǒu)의 운모 ou는 어떻게 소리 날까요?", "choices": ["오우", "아오", "에이", "어우"], "answer": 3, "explain": "ou는 '어우'에 가깝게 읽어요. 그래서 狗는 '거우'처럼 들려요."}, {"q": "糖(táng)처럼 혀 뒤쪽을 올려 코로 울리며 끝나는 운모는 무엇일까요?", "choices": ["an", "ang", "ai", "ei"], "answer": 1, "explain": "ng로 끝나는 ang은 '앙'처럼 코를 울려요."}], "summary": ["병음은 앞소리 성모와 뒷소리 운모로 나뉘고, 성조 표시는 운모 위에 붙어요.", "기본 운모는 a o e i u ü 여섯 개이고, ü는 입술을 모으고 '이'라고 해요.", "ai ei ao ou처럼 이어지는 운모와 an ang처럼 콧소리로 끝나는 운모가 있어요."], "parent_tip": "e를 한국어 '에'로, ou를 '오우'로 읽는 실수가 가장 흔합니다. 거울 앞에서 아이와 함께 입 모양을 보며 a·o·e·i·u·ü를 차례로 말해 보세요. '안'과 '앙'을 번갈아 말하고 어느 쪽인지 맞히는 귀 훈련도 도움이 됩니다."}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','병음 운모',3,'c3-03' where not exists (select 1 from public.topics where lesson_slug='c3-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-04','3~4','중국어','병음 성모','병음의 앞소리 ''성모''는 몇 개나 될까?','assets/img/l_c3-04.jpg',$j${"intro": "한글에 ㄱ, ㄴ, ㄷ 같은 자음이 있듯이 중국어 병음에도 앞소리 '성모'가 있어요. 입술, 혀끝, 혀뿌리를 어떻게 쓰는지 알면 성모 21개도 금방 읽을 수 있어요.", "sections": [{"heading": "성모는 21개, 소리 나는 곳으로 묶어요", "paras": ["성모는 모두 21개예요. 소리를 내는 자리가 같은 것끼리 묶으면 외우기 쉬워요.", "입술: b p m f / 혀끝: d t n l / 혀뿌리: g k h / 혓바닥: j q x / 혀를 만 소리: zh ch sh r / 혀끝 앞니 소리: z c s", "f는 한국어에 없는 소리예요. 윗니를 아랫입술에 살짝 대고 바람을 내보내요."], "example": "飞 fēi(페이) 날다 / 你 nǐ(니) 너 / 来 lái(라이) 오다", "figure": "얼굴 옆모습에 입술, 혀끝, 혀뿌리, 혓바닥 자리를 색깔 점으로 표시한 그림"}, {"heading": "바람을 약하게, 바람을 세게", "paras": ["b와 p, d와 t, g와 k는 짝이에요. b, d, g는 바람을 약하게 내서 'ㅂ(ㅃ)', 'ㄷ(ㄸ)', 'ㄱ(ㄲ)'에 가깝고, p, t, k는 바람을 세게 내서 'ㅍ', 'ㅌ', 'ㅋ'에 가까워요.", "입 앞에 휴지를 대고 말해 보세요. p, t, k를 말할 때는 휴지가 펄럭이고, b, d, g를 말할 때는 거의 움직이지 않아요."], "example": "爸爸 bàba(빠바) 아빠 ↔ 怕 pà(파) 무서워하다 / 大 dà(다) 크다 ↔ 他 tā(타) 그 / 哥哥 gēge(거거) 형 ↔ 看 kàn(칸) 보다", "figure": "아이가 입 앞에 휴지 한 장을 들고 소리를 내자 휴지가 펄럭이는 그림"}, {"heading": "j q x 와 zh ch sh r", "paras": ["j, q, x는 혓바닥을 입천장 가까이 넓게 대고 '지', '치', '시'처럼 소리 내요.", "zh, ch, sh, r는 혀끝을 위로 동그랗게 말아 올리고 'ㅈ', 'ㅊ', 'ㅅ', 'ㄹ'을 내요. 그래서 '혀를 만 소리'라고 불러요.", "zh는 j와, ch는 q와, sh는 x와 비슷해 보이지만 혀 모양이 달라요."], "example": "鸡 jī(지) 닭 / 七 qī(치) 일곱 / 西 xī(시) 서쪽 / 书 shū(수) 책 / 吃 chī(츠) 먹다", "figure": "혀를 납작하게 편 모습과 혀끝을 위로 말아 올린 모습을 나란히 그린 입속 그림"}, {"heading": "z c s 와 '으' 소리 i", "paras": ["z, c, s는 혀끝을 윗니 뒤에 대고 'ㅉ', 'ㅊ', 'ㅆ'처럼 소리 내요.", "zi, ci, si와 zhi, chi, shi, ri에서 i는 '이'가 아니라 '으'에 가깝게 소리 나요. 그래서 字 zì는 '쯔', 吃 chī는 '츠'처럼 들려요.", "이렇게 성모와 운모를 합치고 성조까지 붙이면 낱말을 읽을 수 있어요."], "example": "字 zì(쯔) 글자 / 菜 cài(차이) 채소 / 三 sān(싼) 셋", "figure": "성모 카드 z와 운모 카드 i, 성조 카드 4성을 이어 붙여 zì를 만드는 그림"}], "keywords": [{"word": "성모", "meaning": "병음의 앞소리. 21개가 있어요."}, {"word": "바람 센 소리", "meaning": "p, t, k처럼 바람을 세게 내보내는 성모"}, {"word": "혀를 만 소리", "meaning": "zh, ch, sh, r처럼 혀끝을 말아 올려 내는 성모"}, {"word": "f", "meaning": "윗니를 아랫입술에 대고 내는 소리. 한국어에 없어요."}], "expressions": [{"en": "爸爸", "ko": "아빠", "note": "bàba (빠바)"}, {"en": "怕", "ko": "무서워하다", "note": "pà (파)"}, {"en": "飞", "ko": "날다", "note": "fēi (페이)"}, {"en": "他", "ko": "그(남자)", "note": "tā (타)"}, {"en": "你", "ko": "너", "note": "nǐ (니)"}, {"en": "来", "ko": "오다", "note": "lái (라이)"}, {"en": "哥哥", "ko": "형, 오빠", "note": "gēge (거거)"}, {"en": "看", "ko": "보다", "note": "kàn (칸)"}, {"en": "鸡", "ko": "닭", "note": "jī (지)"}, {"en": "七", "ko": "일곱", "note": "qī (치)"}, {"en": "书", "ko": "책", "note": "shū (수)"}, {"en": "字", "ko": "글자", "note": "zì (쯔)"}], "quiz": [{"q": "중국어 병음의 성모는 모두 몇 개일까요?", "choices": ["6개", "14개", "21개", "26개"], "answer": 2, "explain": "성모는 b부터 s까지 모두 21개예요."}, {"q": "윗니를 아랫입술에 살짝 대고 내는 성모는 무엇일까요?", "choices": ["f", "h", "b", "p"], "answer": 0, "explain": "f는 윗니와 아랫입술 사이로 바람을 내보내는 소리예요."}, {"q": "입 앞의 휴지가 펄럭일 만큼 바람을 세게 내는 성모는 무엇일까요?", "choices": ["b", "d", "g", "t"], "answer": 3, "explain": "t는 바람을 세게 내는 소리예요. b, d, g는 바람이 약해요."}, {"q": "혀끝을 위로 말아 올려 내는 성모는 무엇일까요?", "choices": ["x", "sh", "s", "j"], "answer": 1, "explain": "zh, ch, sh, r는 혀를 말아 내는 소리예요."}, {"q": "字(zì)는 어떤 소리에 가까울까요?", "choices": ["지", "찌", "쯔", "치"], "answer": 2, "explain": "z 뒤의 i는 '으'처럼 소리 나서 字 zì는 '쯔'에 가까워요."}], "summary": ["성모는 병음의 앞소리로 21개이고, 소리 나는 자리끼리 묶어 외워요.", "b·d·g는 바람이 약하고, p·t·k는 바람이 세요.", "zh·ch·sh·r는 혀를 말고, z·c·s·zh·ch·sh·r 뒤의 i는 '으'처럼 읽어요."], "parent_tip": "아이들은 j/zh, q/ch, x/sh를 가장 헷갈려 합니다. 혀를 납작하게 펴는지, 말아 올리는지 거울로 확인하게 해 주세요. 휴지 한 장으로 b와 p를 비교하는 놀이는 아이들이 아주 좋아합니다."}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','병음 성모',4,'c3-04' where not exists (select 1 from public.topics where lesson_slug='c3-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-05','3~4','중국어','인사하기 你好','중국 친구에게 뭐라고 인사할까?','assets/img/l_c3-05.jpg',$j${"intro": "새 친구를 만나면 가장 먼저 인사를 하지요. 중국어 인사 你好(nǐ hǎo, 니 하오) 하나만 알아도 중국 친구와 웃으며 이야기를 시작할 수 있어요.", "sections": [{"heading": "언제나 쓸 수 있는 인사 你好", "paras": ["你好(nǐ hǎo, 니 하오)는 '안녕'이라는 뜻이에요. 你(nǐ)는 '너', 好(hǎo)는 '좋다'라는 뜻이라서 '너 좋니? 잘 지내?' 하는 마음이 담겨 있어요.", "친구가 你好! 하고 인사하면 나도 똑같이 你好! 하고 대답하면 돼요.", "你와 好는 둘 다 3성이에요. 3성 두 개가 이어지면 앞 글자는 2성처럼 살짝 올려 '니(ní) 하오'로 말하면 자연스러워요."], "example": "A: 你好！(nǐ hǎo, 니 하오) 안녕! / B: 你好！(nǐ hǎo, 니 하오) 안녕!", "figure": "두 아이가 손을 흔들며 인사하는 모습"}, {"heading": "어른과 여러 사람에게 하는 인사", "paras": ["할머니, 할아버지 같은 어른께는 你 대신 높임말 您(nín)을 써서 您好(nín hǎo, 닌 하오)라고 인사해요.", "선생님께는 老师好(lǎoshī hǎo, 라오스 하오)라고 해요. 老师는 '선생님'이에요.", "친구 여러 명에게는 你们好(nǐmen hǎo, 니먼 하오), 모두에게 한꺼번에 인사할 때는 大家好(dàjiā hǎo, 다지아 하오)라고 해요."], "example": "老师好！(lǎoshī hǎo) 선생님, 안녕하세요! / 大家好！(dàjiā hǎo) 여러분, 안녕하세요!", "figure": "교실 앞에서 학생들이 선생님께 고개를 숙여 인사하는 모습"}, {"heading": "아침, 저녁, 자기 전 인사", "paras": ["아침에는 早上好(zǎoshang hǎo, 짜오상 하오)라고 해요. '좋은 아침'이라는 뜻이에요.", "저녁에 만나면 晚上好(wǎnshang hǎo, 완상 하오)라고 인사해요.", "잠자리에 들기 전에는 晚安(wǎn'ān, 완안)이라고 말해요. '잘 자'라는 뜻이에요."], "example": "🌅 早上好(zǎoshang hǎo) 좋은 아침 / 🌆 晚上好(wǎnshang hǎo) 저녁 인사 / 🌙 晚安(wǎn'ān) 잘 자", "figure": "해가 뜨는 아침, 노을 지는 저녁, 달이 뜬 밤을 세 칸으로 나눈 그림"}, {"heading": "헤어질 때 인사", "paras": ["헤어질 때는 再见(zàijiàn, 짜이지엔)이라고 해요. '다시 만나'라는 뜻이에요.", "내일 또 만날 친구에게는 明天见(míngtiān jiàn, 밍티엔 지엔)이라고 말해요. 明天은 '내일', 见은 '만나다'예요."], "example": "A: 再见！(zàijiàn) 잘 가! / B: 明天见！(míngtiān jiàn) 내일 만나!", "figure": "학교 정문 앞에서 아이들이 손을 흔들며 헤어지는 모습"}], "keywords": [{"word": "你好", "meaning": "nǐ hǎo(니 하오). 언제나 쓰는 인사 '안녕'"}, {"word": "您", "meaning": "nín(닌). 어른을 높여 부르는 '당신'"}, {"word": "老师", "meaning": "lǎoshī(라오스). 선생님"}, {"word": "再见", "meaning": "zàijiàn(짜이지엔). 헤어질 때 인사"}], "expressions": [{"en": "你好", "ko": "안녕", "note": "nǐ hǎo (니 하오)"}, {"en": "您好", "ko": "안녕하세요(어른께 높여서)", "note": "nín hǎo (닌 하오)"}, {"en": "老师好", "ko": "선생님, 안녕하세요", "note": "lǎoshī hǎo (라오스 하오)"}, {"en": "你们好", "ko": "얘들아, 안녕(여러 명에게)", "note": "nǐmen hǎo (니먼 하오)"}, {"en": "大家好", "ko": "여러분, 안녕하세요", "note": "dàjiā hǎo (다지아 하오)"}, {"en": "早上好", "ko": "좋은 아침(아침 인사)", "note": "zǎoshang hǎo (짜오상 하오)"}, {"en": "晚上好", "ko": "저녁 인사", "note": "wǎnshang hǎo (완상 하오)"}, {"en": "晚安", "ko": "잘 자", "note": "wǎn'ān (완안)"}, {"en": "再见", "ko": "잘 가, 다시 만나", "note": "zàijiàn (짜이지엔)"}, {"en": "明天见", "ko": "내일 만나", "note": "míngtiān jiàn (밍티엔 지엔)"}], "quiz": [{"q": "중국 친구를 처음 만났을 때 하는 인사는 무엇일까요?", "choices": ["再见", "晚安", "你好", "明天见"], "answer": 2, "explain": "你好(nǐ hǎo)는 만났을 때 하는 '안녕' 인사예요."}, {"q": "할아버지께 높여서 인사할 때 알맞은 말은 무엇일까요?", "choices": ["您好", "你们好", "晚安", "再见"], "answer": 0, "explain": "어른께는 你 대신 높임말 您을 써서 您好(nín hǎo)라고 해요."}, {"q": "자기 전에 가족에게 하는 인사는 무엇일까요?", "choices": ["早上好", "晚上好", "老师好", "晚安"], "answer": 3, "explain": "晚安(wǎn'ān)은 '잘 자'라는 뜻이에요."}, {"q": "'내일 만나'라는 뜻의 인사는 무엇일까요?", "choices": ["大家好", "明天见", "你好", "早上好"], "answer": 1, "explain": "明天(내일) + 见(만나다) = 明天见(míngtiān jiàn)이에요."}, {"q": "再见의 병음으로 알맞은 것은 무엇일까요?", "choices": ["zàijiàn", "zǎoshang", "wǎn'ān", "dàjiā"], "answer": 0, "explain": "再见은 zàijiàn(짜이지엔)이라고 읽어요."}], "summary": ["만나면 你好(nǐ hǎo), 어른께는 您好(nín hǎo), 선생님께는 老师好(lǎoshī hǎo)라고 해요.", "아침에는 早上好, 저녁에는 晚上好, 자기 전에는 晚安이라고 해요.", "헤어질 때는 再见(zàijiàn), 내일 또 만나면 明天见(míngtiān jiàn)이라고 해요."], "parent_tip": "아이가 어른께도 你好를 쓰는 경우가 많으니, 높임말 您好를 함께 연습해 주세요. 하루 동안 집에서 아침에는 早上好, 잠들기 전에는 晚安으로 인사를 주고받는 '중국어 인사 하루'를 해 보면 금방 익숙해집니다."}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','인사하기 你好',5,'c3-05' where not exists (select 1 from public.topics where lesson_slug='c3-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-06','3~4','중국어','숫자 1~10','중국어로 하나부터 열까지 셀 수 있을까?','assets/img/l_c3-06.jpg',$j${"intro": "계단을 오를 때, 사탕을 나눌 때 우리는 숫자를 세요. 중국어 숫자 열 개만 알면 나이도, 전화번호도 말할 수 있어요. 손가락을 펴고 같이 세어 봐요!", "sections": [{"heading": "一, 二, 三은 줄의 개수예요", "paras": ["一(yī, 이)은 1, 二(èr, 얼)은 2, 三(sān, 싼)은 3이에요.", "세 글자는 가로줄 개수가 숫자와 같아요. 줄 하나는 1, 줄 둘은 2, 줄 셋은 3이라서 쉽게 외울 수 있어요.", "二(èr)는 혀끝을 살짝 말아 올리며 '얼'처럼 소리 내요."], "example": "🍎 一(yī) / 🍎🍎 二(èr) / 🍎🍎🍎 三(sān)", "figure": "가로줄 하나, 둘, 셋이 그어진 카드 옆에 사과가 하나, 둘, 셋 놓인 그림"}, {"heading": "四, 五, 六", "paras": ["四(sì, 쓰)는 4, 五(wǔ, 우)는 5, 六(liù, 리우)는 6이에요.", "四(sì)는 4성으로 뚝 떨어지고, 혀끝을 윗니 뒤에 대고 '쓰'라고 해요. 열을 뜻하는 十(shí, 스)과 헷갈리지 않게 조심해요.", "五(wǔ)는 3성이라 낮게 눌렀다가 살짝 올려요."], "example": "四(sì) 4 / 五(wǔ) 5 / 六(liù) 6", "figure": "주사위 눈 4, 5, 6이 나란히 놓인 그림"}, {"heading": "七, 八, 九, 十 그리고 零", "paras": ["七(qī, 치)는 7, 八(bā, 빠)는 8, 九(jiǔ, 지우)는 9, 十(shí, 스)은 10이에요.", "아무것도 없는 0은 零(líng, 링)이라고 해요. 전화번호를 말할 때 자주 써요.", "十(shí)은 혀를 말아 2성으로 올리며 '스', 四(sì)는 혀를 펴고 4성으로 내리며 '쓰'예요."], "example": "七(qī) 7 / 八(bā) 8 / 九(jiǔ) 9 / 十(shí) 10 / 零(líng) 0", "figure": "1부터 10까지 숫자가 적힌 계단을 아이가 한 칸씩 올라가는 그림"}, {"heading": "중국에서는 한 손으로 열까지 세요", "paras": ["중국 사람들은 한 손으로 1부터 10까지 나타내요. 1~5는 우리처럼 손가락을 펴요.", "六은 엄지와 새끼손가락만 펴고, 七은 엄지·검지·중지 끝을 모아요. 八은 엄지와 검지를 펴서 'ㄴ' 모양을 만들고, 九는 검지를 갈고리처럼 구부려요.", "十은 두 검지를 십자로 겹치거나 주먹을 쥐어 나타내요. 시장에서 값을 말할 때 자주 써요."], "example": "🤙 六(liù) / 🤌 七(qī) / 八(bā)은 엄지+검지 'ㄴ' 모양", "figure": "중국식 손가락 숫자 6, 7, 8, 9, 10을 한 손으로 만든 다섯 개의 손 모양 그림"}], "keywords": [{"word": "一 二 三", "meaning": "yī èr sān. 1, 2, 3. 가로줄 개수가 숫자예요."}, {"word": "四와 十", "meaning": "sì(4)와 shí(10). 소리가 비슷해 헷갈리기 쉬워요."}, {"word": "零", "meaning": "líng(링). 숫자 0"}, {"word": "손가락 숫자", "meaning": "중국에서 한 손으로 1~10을 나타내는 방법"}], "expressions": [{"en": "零", "ko": "0", "note": "líng (링)"}, {"en": "一", "ko": "1, 하나", "note": "yī (이)"}, {"en": "二", "ko": "2, 둘", "note": "èr (얼)"}, {"en": "三", "ko": "3, 셋", "note": "sān (싼)"}, {"en": "四", "ko": "4, 넷", "note": "sì (쓰)"}, {"en": "五", "ko": "5, 다섯", "note": "wǔ (우)"}, {"en": "六", "ko": "6, 여섯", "note": "liù (리우)"}, {"en": "七", "ko": "7, 일곱", "note": "qī (치)"}, {"en": "八", "ko": "8, 여덟", "note": "bā (빠)"}, {"en": "九", "ko": "9, 아홉", "note": "jiǔ (지우)"}, {"en": "十", "ko": "10, 열", "note": "shí (스)"}], "quiz": [{"q": "🍎🍎🍎 사과의 수를 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["一", "二", "三", "四"], "answer": 2, "explain": "사과가 3개이므로 三(sān)이에요. 가로줄도 3개예요."}, {"q": "九의 뜻은 무엇일까요?", "choices": ["9", "6", "7", "8"], "answer": 0, "explain": "九(jiǔ, 지우)는 9예요."}, {"q": "숫자 4를 뜻하는 四의 병음은 무엇일까요?", "choices": ["shí", "sān", "sì", "liù"], "answer": 2, "explain": "四는 4성 sì(쓰)예요. shí는 10을 뜻하는 十이에요."}, {"q": "二 + 三 = ? 알맞은 것을 고르세요.", "choices": ["四", "六", "七", "五"], "answer": 3, "explain": "2 + 3 = 5이므로 五(wǔ)예요."}, {"q": "중국 손가락 숫자에서 엄지와 새끼손가락만 펴면 몇일까요?", "choices": ["六", "八", "九", "十"], "answer": 0, "explain": "엄지와 새끼손가락을 펴면 六(liù, 6)이에요."}], "summary": ["一(yī) 二(èr) 三(sān) 四(sì) 五(wǔ) 六(liù) 七(qī) 八(bā) 九(jiǔ) 十(shí), 그리고 0은 零(líng)이에요.", "四(sì, 4성)와 十(shí, 2성)은 소리가 비슷하니 성조와 혀 모양으로 구별해요.", "중국에서는 한 손가락 모양으로 6~10도 나타내요."], "parent_tip": "四(sì)와 十(shí)를 구별하는 것이 가장 어렵습니다. 계단을 오르거나 간식을 셀 때 중국어로 세어 보게 하고, 부모님이 손가락 숫자를 보여 주면 아이가 중국어로 말하는 놀이를 해 보세요. 집 전화번호를 중국어로 말해 보는 것도 좋은 연습입니다."}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','숫자 1~10',6,'c3-06' where not exists (select 1 from public.topics where lesson_slug='c3-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-07','3~4','중국어','가족 부르기','우리 가족을 중국어로 어떻게 부를까?','assets/img/l_c3-07.jpg',$j${"intro": "아빠, 엄마, 형, 누나… 우리 가족을 부르는 말은 매일 쓰지요. 중국어로는 같은 글자를 두 번 겹쳐 부르는 경우가 많아서 아주 귀엽게 들려요.", "sections": [{"heading": "아빠와 엄마", "paras": ["아빠는 爸爸(bàba, 빠바), 엄마는 妈妈(māma, 마마)라고 불러요.", "같은 글자를 두 번 쓰고, 두 번째 글자는 성조 없이 짧고 가볍게(경성) 읽어요.", "妈妈의 妈는 성조 시간에 배운 1성 mā예요. 기억나지요?"], "example": "👨 爸爸(bàba, 빠바) 아빠 / 👩 妈妈(māma, 마마) 엄마", "figure": "아빠와 엄마가 아이의 양손을 잡고 걷는 가족 그림"}, {"heading": "형제자매 부르기", "paras": ["나보다 나이 많은 남자 형제는 哥哥(gēge, 거거), 나이 많은 여자 형제는 姐姐(jiějie, 지에지에)라고 해요.", "나보다 어린 남자 형제는 弟弟(dìdi, 띠디), 어린 여자 형제는 妹妹(mèimei, 메이메이)예요.", "한국어는 내가 남자면 '형·누나', 여자면 '오빠·언니'로 다르게 부르지요? 중국어는 내가 누구든 상관없이 哥哥, 姐姐라고 불러요."], "example": "👦 哥哥(gēge) 형·오빠 / 👧 姐姐(jiějie) 누나·언니 / 🧒 弟弟(dìdi) 남동생 / 👶 妹妹(mèimei) 여동생", "figure": "키 순서대로 서 있는 네 남매 그림, 형·누나는 크게, 동생들은 작게"}, {"heading": "할아버지와 할머니", "paras": ["아빠의 아버지, 어머니는 爷爷(yéye, 예예)와 奶奶(nǎinai, 나이나이)라고 불러요.", "엄마의 아버지, 어머니는 外公(wàigōng, 와이궁)과 外婆(wàipó, 와이포)라고 해요. 外(wài)는 '바깥'이라는 뜻이라서 우리말 '외할아버지, 외할머니'와 비슷해요."], "example": "👴 爷爷(yéye) 할아버지 / 👵 奶奶(nǎinai) 할머니 / 外公(wàigōng) 외할아버지 / 外婆(wàipó) 외할머니", "figure": "할아버지, 할머니와 외할아버지, 외할머니가 양쪽에 앉아 있는 가족 사진 같은 그림"}, {"heading": "가족을 소개해요", "paras": ["사진을 보여 주며 가족을 소개할 때는 这是我…(zhè shì wǒ…, 저 스 워…)라고 해요. '이 사람은 나의 …예요'라는 뜻이에요.", "我(wǒ)는 '나'예요. 가족을 사랑한다고 말하고 싶으면 我爱…(wǒ ài…, 워 아이…)라고 해요."], "example": "这是我妈妈。(zhè shì wǒ māma, 저 스 워 마마) 이분은 우리 엄마예요. / 我爱爸爸。(wǒ ài bàba, 워 아이 빠바) 나는 아빠를 사랑해요.", "figure": "아이가 가족사진 액자를 들고 친구에게 보여 주는 모습"}], "keywords": [{"word": "爸爸·妈妈", "meaning": "bàba(빠바) 아빠, māma(마마) 엄마"}, {"word": "哥哥·姐姐", "meaning": "나보다 나이 많은 형·오빠 / 누나·언니"}, {"word": "弟弟·妹妹", "meaning": "나보다 어린 남동생 / 여동생"}, {"word": "这是我…", "meaning": "zhè shì wǒ…(저 스 워). 이 사람은 나의 …예요"}], "expressions": [{"en": "爸爸", "ko": "아빠", "note": "bàba (빠바)"}, {"en": "妈妈", "ko": "엄마", "note": "māma (마마)"}, {"en": "哥哥", "ko": "형, 오빠", "note": "gēge (거거)"}, {"en": "姐姐", "ko": "누나, 언니", "note": "jiějie (지에지에)"}, {"en": "弟弟", "ko": "남동생", "note": "dìdi (띠디)"}, {"en": "妹妹", "ko": "여동생", "note": "mèimei (메이메이)"}, {"en": "爷爷", "ko": "할아버지(아빠의 아버지)", "note": "yéye (예예)"}, {"en": "奶奶", "ko": "할머니(아빠의 어머니)", "note": "nǎinai (나이나이)"}, {"en": "外公", "ko": "외할아버지", "note": "wàigōng (와이궁)"}, {"en": "外婆", "ko": "외할머니", "note": "wàipó (와이포)"}, {"en": "这是我妈妈", "ko": "이분은 우리 엄마예요", "note": "zhè shì wǒ māma (저 스 워 마마)"}, {"en": "我爱爸爸", "ko": "나는 아빠를 사랑해요", "note": "wǒ ài bàba (워 아이 빠바)"}], "quiz": [{"q": "'아빠'를 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["妈妈", "爸爸", "哥哥", "爷爷"], "answer": 1, "explain": "아빠는 爸爸(bàba, 빠바)예요."}, {"q": "妹妹의 뜻은 무엇일까요?", "choices": ["누나", "남동생", "여동생", "할머니"], "answer": 2, "explain": "妹妹(mèimei)는 나보다 어린 여자 형제, 여동생이에요."}, {"q": "여자아이가 나이 많은 남자 형제(오빠)를 부를 때 쓰는 말은 무엇일까요?", "choices": ["哥哥", "弟弟", "姐姐", "爸爸"], "answer": 0, "explain": "중국어는 말하는 사람이 남자든 여자든 나이 많은 남자 형제를 哥哥라고 해요."}, {"q": "아빠의 어머니(할머니)는 중국어로 무엇일까요?", "choices": ["外婆", "妈妈", "姐姐", "奶奶"], "answer": 3, "explain": "아빠의 어머니는 奶奶(nǎinai), 엄마의 어머니는 外婆(wàipó)예요."}, {"q": "'이분은 우리 아빠예요'를 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["我爱爸爸。", "这是我妈妈。", "这是我爸爸。", "我爱妈妈。"], "answer": 2, "explain": "这是我…(이 사람은 나의 …)에 爸爸를 넣어 这是我爸爸。라고 해요."}], "summary": ["아빠는 爸爸(bàba), 엄마는 妈妈(māma)이고, 두 번째 글자는 가볍게 읽어요.", "哥哥·姐姐·弟弟·妹妹는 말하는 사람이 남자든 여자든 똑같이 써요.", "这是我…(zhè shì wǒ…)로 가족을 소개하고, 我爱…로 사랑을 표현해요."], "parent_tip": "한국어와 달리 말하는 사람의 성별에 따라 호칭이 바뀌지 않는다는 점을 아이가 신기해합니다. 가족사진을 보며 '这是我…'로 한 사람씩 소개하는 놀이를 해 보세요. 두 번째 글자를 가볍게(경성) 읽는지도 함께 들어 봐 주세요."}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','가족 부르기',7,'c3-07' where not exists (select 1 from public.topics where lesson_slug='c3-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-08','3~4','중국어','색깔','무지개 색깔을 중국어로 말해 볼까?','assets/img/l_c3-08.jpg',$j${"intro": "크레파스 상자를 열면 알록달록한 색이 가득하지요. 중국어 색깔 이름은 대부분 끝에 色(sè, 써)가 붙어서 규칙만 알면 쉽게 외울 수 있어요.", "sections": [{"heading": "색깔 이름 끝에는 色가 붙어요", "paras": ["중국어로 '색깔'은 颜色(yánsè, 옌써)라고 해요.", "색깔 이름은 대부분 '어떤 색' + 色(sè)로 만들어요. 色는 '색'이라는 뜻이에요. 우리말 '빨간색, 노란색'의 '색'과 같아요.", "色(sè)의 e는 '으어'에 가깝게 읽어서 '써'처럼 들려요."], "example": "红(hóng) + 色(sè) = 红色(hóngsè, 훙써) 빨간색", "figure": "크레파스 상자가 열려 있고 여러 색 크레파스가 나란히 놓인 모습"}, {"heading": "빨강, 노랑, 파랑, 초록", "paras": ["빨간색은 红色(hóngsè, 훙써), 노란색은 黄色(huángsè, 황써)예요.", "파란색은 蓝色(lánsè, 란써), 초록색은 绿色(lǜsè, 뤼써)예요. 绿의 ü는 입술을 동그랗게 모으고 '위'처럼 소리 내요.", "红色와 黄色는 소리가 비슷하니 hóng(훙)과 huáng(황)을 잘 구별해요."], "example": "🍎 红色(hóngsè) / 🍌 黄色(huángsè) / 🌊 蓝色(lánsè) / 🌳 绿色(lǜsè)", "figure": "빨간 사과, 노란 바나나, 파란 바다, 초록 나무가 네 칸에 그려진 그림"}, {"heading": "흰색, 검은색 그리고 더 많은 색", "paras": ["흰색은 白色(báisè, 바이써), 검은색은 黑色(hēisè, 헤이써)예요. 판다는 白色와 黑色로 되어 있지요.", "분홍색은 粉色(fěnsè, 펀써), 보라색은 紫色(zǐsè, 쯔써), 주황색은 橙色(chéngsè, 청써)예요.", "중국에서 빨간색은 행운과 기쁨을 뜻해서, 설날에 빨간 봉투에 세뱃돈을 넣어 주고 빨간 장식을 많이 달아요."], "example": "🐼 白色(báisè) + 黑色(hēisè) / 🌸 粉色(fěnsè) / 🍇 紫色(zǐsè) / 🍊 橙色(chéngsè)", "figure": "빨간 등불과 빨간 봉투로 꾸민 중국 설날 거리 풍경"}, {"heading": "좋아하는 색을 말해요", "paras": ["'무슨 색이에요?'는 什么颜色？(shénme yánsè, 선머 옌써)라고 물어요. 什么(shénme)는 '무엇, 무슨'이에요.", "좋아하는 색을 말할 때는 我喜欢…(wǒ xǐhuan…, 워 시환…)을 써요. 喜欢(xǐhuan)은 '좋아하다'예요.", "친구에게 你喜欢什么颜色？(nǐ xǐhuan shénme yánsè, 니 시환 선머 옌써)라고 물으면 '너는 무슨 색을 좋아해?'라는 뜻이에요."], "example": "A: 你喜欢什么颜色？ 너는 무슨 색을 좋아해? / B: 我喜欢红色。(wǒ xǐhuan hóngsè, 워 시환 훙써) 나는 빨간색을 좋아해.", "figure": "두 아이가 색종이를 고르며 이야기하는 모습"}], "keywords": [{"word": "颜色", "meaning": "yánsè(옌써). 색깔"}, {"word": "色", "meaning": "sè(써). 색깔 이름 끝에 붙는 '색'"}, {"word": "什么", "meaning": "shénme(선머). 무엇, 무슨"}, {"word": "喜欢", "meaning": "xǐhuan(시환). 좋아하다"}], "expressions": [{"en": "颜色", "ko": "색깔", "note": "yánsè (옌써)"}, {"en": "红色", "ko": "빨간색", "note": "hóngsè (훙써)"}, {"en": "黄色", "ko": "노란색", "note": "huángsè (황써)"}, {"en": "蓝色", "ko": "파란색", "note": "lánsè (란써)"}, {"en": "绿色", "ko": "초록색", "note": "lǜsè (뤼써)"}, {"en": "白色", "ko": "흰색", "note": "báisè (바이써)"}, {"en": "黑色", "ko": "검은색", "note": "hēisè (헤이써)"}, {"en": "粉色", "ko": "분홍색", "note": "fěnsè (펀써)"}, {"en": "紫色", "ko": "보라색", "note": "zǐsè (쯔써)"}, {"en": "橙色", "ko": "주황색", "note": "chéngsè (청써)"}, {"en": "什么颜色", "ko": "무슨 색", "note": "shénme yánsè (선머 옌써)"}, {"en": "我喜欢红色", "ko": "나는 빨간색을 좋아해요", "note": "wǒ xǐhuan hóngsè (워 시환 훙써)"}], "quiz": [{"q": "🍎 사과의 빨간색을 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["黄色", "红色", "绿色", "白色"], "answer": 1, "explain": "빨간색은 红色(hóngsè, 훙써)예요."}, {"q": "蓝色의 뜻은 무엇일까요?", "choices": ["노란색", "보라색", "검은색", "파란색"], "answer": 3, "explain": "蓝色(lánsè, 란써)는 파란색이에요."}, {"q": "중국어 색깔 이름 끝에 자주 붙는 '색'이라는 뜻의 글자는 무엇일까요?", "choices": ["色", "红", "白", "爱"], "answer": 0, "explain": "色(sè)는 '색'이라는 뜻이라 红色, 黄色처럼 색깔 이름 끝에 붙어요."}, {"q": "绿色의 병음으로 알맞은 것은 무엇일까요?", "choices": ["lánsè", "hóngsè", "lǜsè", "zǐsè"], "answer": 2, "explain": "绿色는 lǜsè(뤼써)예요. ü의 두 점을 꼭 써요."}, {"q": "'나는 빨간색을 좋아해요.'를 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["我喜欢红色。", "什么颜色？", "我喜欢黑色。", "这是红色。"], "answer": 0, "explain": "我喜欢(나는 좋아해요) + 红色(빨간색) = 我喜欢红色。예요."}], "summary": ["색깔은 颜色(yánsè)이고, 색 이름 끝에는 色(sè)가 붙어요.", "红色 빨강, 黄色 노랑, 蓝色 파랑, 绿色 초록, 白色 흰색, 黑色 검정, 粉色 분홍, 紫色 보라, 橙色 주황이에요.", "什么颜色？로 묻고, 我喜欢…으로 좋아하는 색을 말해요."], "parent_tip": "红色(hóng)와 黄色(huáng)를 헷갈리는 아이가 많습니다. 집 안 물건을 가리키며 '什么颜色？' 하고 묻고 아이가 색 이름으로 대답하는 놀이를 해 보세요. 중국에서 빨간색이 행운의 색이라는 문화 이야기도 아이들이 흥미로워합니다."}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','색깔',8,'c3-08' where not exists (select 1 from public.topics where lesson_slug='c3-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-09','3~4','중국어','고마워요·미안해요','고마울 때와 미안할 때 중국어로 뭐라고 할까?','assets/img/l_c3-09.jpg',$j${"intro": "친구가 지우개를 빌려주면 '고마워!', 실수로 부딪히면 '미안해!'라고 말하지요. 이 두 마디는 어느 나라에서나 가장 소중한 말이에요. 중국어로도 배워 봐요.", "sections": [{"heading": "고마울 때는 谢谢", "paras": ["고마울 때는 谢谢(xièxie, 씨에시에)라고 해요. 같은 글자를 두 번 쓰고, 두 번째 谢는 가볍게 읽어요.", "누구에게 고마운지 말하고 싶으면 뒤에 사람을 붙여요. 谢谢你(xièxie nǐ)는 '너에게 고마워', 谢谢老师(xièxie lǎoshī)는 '선생님, 고맙습니다'예요."], "example": "🎁 谢谢！(xièxie, 씨에시에) 고마워! / 谢谢妈妈！(xièxie māma) 엄마, 고마워요!", "figure": "아이가 친구에게 선물 상자를 받으며 웃는 모습"}, {"heading": "'고마워'에 대답하기", "paras": ["누군가 谢谢라고 하면 不客气(bú kèqi, 부 커치)라고 대답해요. '천만에, 별말씀을'이라는 뜻이에요.", "不用谢(bú yòng xiè, 부 융 씨에)라고 해도 돼요. '고마워할 필요 없어'라는 뜻이에요.", "不는 원래 bù지만 이 두 표현에서는 bú로 읽어요. 지금은 표현째로 소리를 외우면 돼요."], "example": "A: 谢谢你！(xièxie nǐ) 고마워! / B: 不客气！(bú kèqi) 천만에!", "figure": "한 아이가 연필을 건네주고 다른 아이가 고개를 숙여 고마워하는 모습"}, {"heading": "미안할 때는 对不起", "paras": ["미안할 때는 对不起(duìbuqǐ, 뚜이부치)라고 해요. 가운데 不는 가볍게 읽어요.", "누군가 对不起라고 하면 没关系(méi guānxi, 메이 관시)라고 대답해요. '괜찮아'라는 뜻이에요.", "가볍게 '괜찮아, 별일 아니야'라고 할 때는 没事(méi shì, 메이 스)라고도 해요."], "example": "A: 对不起！(duìbuqǐ, 뚜이부치) 미안해! / B: 没关系！(méi guānxi, 메이 관시) 괜찮아!", "figure": "복도에서 부딪힌 두 아이 중 한 명이 사과하고 다른 아이가 손을 내저으며 괜찮다고 하는 모습"}, {"heading": "공손하게 권할 때는 请", "paras": ["请(qǐng, 칭)은 '~하세요, ~해 주세요'처럼 공손하게 권할 때 행동 앞에 붙여요.", "손님이 문을 두드리면 请进(qǐng jìn, 칭 진) '들어오세요', 자리를 권할 때는 请坐(qǐng zuò, 칭 쭈어) '앉으세요'라고 해요."], "example": "🚪 请进！(qǐng jìn) 들어오세요! / 🪑 请坐！(qǐng zuò) 앉으세요!", "figure": "아이가 문을 열고 손님에게 들어오라고 손짓하는 모습"}], "keywords": [{"word": "谢谢", "meaning": "xièxie(씨에시에). 고마워요"}, {"word": "不客气", "meaning": "bú kèqi(부 커치). 천만에요"}, {"word": "对不起", "meaning": "duìbuqǐ(뚜이부치). 미안해요"}, {"word": "没关系", "meaning": "méi guānxi(메이 관시). 괜찮아요"}, {"word": "请", "meaning": "qǐng(칭). ~하세요(공손하게 권할 때)"}], "expressions": [{"en": "谢谢", "ko": "고마워요", "note": "xièxie (씨에시에)"}, {"en": "谢谢你", "ko": "(너에게) 고마워", "note": "xièxie nǐ (씨에시에 니)"}, {"en": "谢谢老师", "ko": "선생님, 고맙습니다", "note": "xièxie lǎoshī (씨에시에 라오스)"}, {"en": "不客气", "ko": "천만에요", "note": "bú kèqi (부 커치)"}, {"en": "不用谢", "ko": "고마워할 필요 없어요", "note": "bú yòng xiè (부 융 씨에)"}, {"en": "对不起", "ko": "미안해요", "note": "duìbuqǐ (뚜이부치)"}, {"en": "没关系", "ko": "괜찮아요", "note": "méi guānxi (메이 관시)"}, {"en": "没事", "ko": "괜찮아, 별일 아니야", "note": "méi shì (메이 스)"}, {"en": "请进", "ko": "들어오세요", "note": "qǐng jìn (칭 진)"}, {"en": "请坐", "ko": "앉으세요", "note": "qǐng zuò (칭 쭈어)"}], "quiz": [{"q": "친구가 생일 선물을 줬어요. 뭐라고 말할까요?", "choices": ["对不起", "没关系", "谢谢", "请进"], "answer": 2, "explain": "고마울 때는 谢谢(xièxie)라고 해요."}, {"q": "친구가 '谢谢！'라고 했어요. 알맞은 대답은 무엇일까요?", "choices": ["不客气！", "对不起！", "请坐！", "谢谢！"], "answer": 0, "explain": "'고마워'에는 不客气(천만에)라고 대답해요."}, {"q": "对不起의 뜻은 무엇일까요?", "choices": ["고마워요", "괜찮아요", "들어오세요", "미안해요"], "answer": 3, "explain": "对不起(duìbuqǐ, 뚜이부치)는 '미안해요'예요."}, {"q": "친구가 '对不起！'라고 사과했어요. '괜찮아!'라고 대답하려면?", "choices": ["谢谢！", "没关系！", "不用谢！", "请进！"], "answer": 1, "explain": "사과에는 没关系(méi guānxi, 괜찮아)라고 대답해요."}, {"q": "집에 온 손님에게 '앉으세요'라고 할 때 알맞은 말은 무엇일까요?", "choices": ["请坐", "请进", "没事", "谢谢"], "answer": 0, "explain": "请坐(qǐng zuò)는 '앉으세요', 请进(qǐng jìn)은 '들어오세요'예요."}], "summary": ["고마울 때는 谢谢(xièxie), 대답은 不客气(bú kèqi)나 不用谢(bú yòng xiè)예요.", "미안할 때는 对不起(duìbuqǐ), 대답은 没关系(méi guānxi)나 没事(méi shì)예요.", "请(qǐng)을 행동 앞에 붙이면 请进, 请坐처럼 공손하게 권하는 말이 돼요."], "parent_tip": "'谢谢-不客气', '对不起-没关系'를 짝으로 외우게 하면 헷갈리지 않습니다. 집에서 물건을 건네줄 때마다 谢谢와 不客气를 주고받아 보세요. 谢谢의 xiè 소리를 한국어 '셰'가 아니라 '씨에'처럼 내는지 들어 봐 주세요."}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','고마워요·미안해요',9,'c3-09' where not exists (select 1 from public.topics where lesson_slug='c3-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c3-10','3~4','중국어','이름 말하기 我叫','중국어로 내 이름을 소개해 볼까?','assets/img/l_c3-10.jpg',$j${"intro": "새 친구를 사귀려면 인사 다음에 이름을 말해야겠지요? 我叫(wǒ jiào, 워 쟈오) 한 마디면 중국어로 내 이름을 소개할 수 있어요.", "sections": [{"heading": "我叫…로 이름을 말해요", "paras": ["我(wǒ)는 '나', 叫(jiào)는 '~라고 부르다'라는 뜻이에요. 그래서 我叫… 뒤에 이름을 붙이면 '나는 …라고 해요'가 돼요.", "중국 친구 왕샤오밍은 我叫王小明(wǒ jiào Wáng Xiǎomíng, 워 쟈오 왕 샤오밍)이라고 소개해요.", "우리는 我叫 뒤에 한국 이름을 그대로 말해도 돼요. 예를 들어 '我叫 민준'처럼요."], "example": "我叫王小明。(wǒ jiào Wáng Xiǎomíng, 워 쟈오 왕 샤오밍) 나는 왕샤오밍이라고 해.", "figure": "아이가 가슴에 손을 얹고 웃으며 자기 이름을 말하는 모습"}, {"heading": "친구 이름을 물어봐요", "paras": ["친구 이름을 물을 때는 你叫什么名字？(nǐ jiào shénme míngzi, 니 쟈오 선머 밍쯔)라고 해요.", "什么(shénme)는 '무엇', 名字(míngzi)는 '이름'이에요. 그래서 '너는 이름이 뭐라고 해?'라는 뜻이 돼요.", "내 이름을 말한 뒤 친구에게 되물을 때는 짧게 你呢？(nǐ ne, 니 너) '너는?'이라고 하면 돼요."], "example": "A: 你叫什么名字？ 이름이 뭐야? / B: 我叫王小明。你呢？ 나는 왕샤오밍이야. 너는?", "figure": "두 아이가 이름표를 가리키며 서로 묻고 대답하는 모습"}, {"heading": "성만 말할 때는 我姓…", "paras": ["성(김, 이, 박 같은 집안 이름)만 말할 때는 我姓…(wǒ xìng…, 워 싱…)이라고 해요. 姓(xìng)은 '성'이에요.", "우리나라 성도 한자로 쓰면 중국어로 읽을 수 있어요. 김(金)은 Jīn(진), 이(李)는 Lǐ(리), 박(朴)은 Piáo(퍄오), 최(崔)는 Cuī(추이)예요.", "王小明에서 王(Wáng)이 성이고, 小明(Xiǎomíng)이 이름이에요. 중국어도 우리말처럼 성을 먼저 말해요."], "example": "我姓金。(wǒ xìng Jīn, 워 싱 진) 내 성은 김이에요. / 我姓李。(wǒ xìng Lǐ, 워 싱 리) 내 성은 이예요.", "figure": "김, 이, 박, 최 성씨 한자 카드가 책상 위에 펼쳐진 모습"}, {"heading": "자기소개를 완성해요", "paras": ["어느 나라 사람인지는 我是…人(wǒ shì…rén)으로 말해요. 한국 사람은 我是韩国人(wǒ shì Hánguórén, 워 스 한궈런), 중국 사람은 我是中国人(wǒ shì Zhōngguórén, 워 스 중궈런)이에요.", "소개가 끝나면 认识你很高兴(rènshi nǐ hěn gāoxìng, 런스 니 헌 까오싱) '만나서 반가워'라고 말해요.", "인사 → 이름 → 나라 → 반가워 순서로 말하면 멋진 자기소개가 돼요."], "example": "你好！我叫王小明。我是中国人。认识你很高兴！ 안녕! 나는 왕샤오밍이야. 나는 중국 사람이야. 만나서 반가워!", "figure": "교실 앞에서 한 아이가 친구들 앞에 서서 자기소개를 하는 모습"}], "keywords": [{"word": "我叫…", "meaning": "wǒ jiào(워 쟈오). 나는 …라고 해요"}, {"word": "名字", "meaning": "míngzi(밍쯔). 이름"}, {"word": "什么", "meaning": "shénme(선머). 무엇"}, {"word": "姓", "meaning": "xìng(싱). 성(집안 이름)"}, {"word": "认识你很高兴", "meaning": "rènshi nǐ hěn gāoxìng. 만나서 반가워요"}], "expressions": [{"en": "我叫王小明", "ko": "나는 왕샤오밍이라고 해요", "note": "wǒ jiào Wáng Xiǎomíng (워 쟈오 왕 샤오밍)"}, {"en": "你叫什么名字？", "ko": "이름이 뭐예요?", "note": "nǐ jiào shénme míngzi? (니 쟈오 선머 밍쯔)"}, {"en": "名字", "ko": "이름", "note": "míngzi (밍쯔)"}, {"en": "什么", "ko": "무엇", "note": "shénme (선머)"}, {"en": "你呢？", "ko": "너는?", "note": "nǐ ne? (니 너)"}, {"en": "我姓金", "ko": "내 성은 김이에요", "note": "wǒ xìng Jīn (워 싱 진)"}, {"en": "你姓什么？", "ko": "성이 뭐예요?", "note": "nǐ xìng shénme? (니 싱 선머)"}, {"en": "我是韩国人", "ko": "나는 한국 사람이에요", "note": "wǒ shì Hánguórén (워 스 한궈런)"}, {"en": "我是中国人", "ko": "나는 중국 사람이에요", "note": "wǒ shì Zhōngguórén (워 스 중궈런)"}, {"en": "认识你很高兴", "ko": "만나서 반가워요", "note": "rènshi nǐ hěn gāoxìng (런스 니 헌 까오싱)"}], "quiz": [{"q": "'나는 왕샤오밍이라고 해요.'를 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["我是王小明人。", "我叫王小明。", "你叫王小明。", "我姓小明。"], "answer": 1, "explain": "我叫(나는 …라고 해요) 뒤에 이름을 붙여 我叫王小明。이라고 해요."}, {"q": "你叫什么名字？는 무엇을 묻는 말일까요?", "choices": ["나이", "나라", "이름", "좋아하는 색"], "answer": 2, "explain": "名字(míngzi)는 '이름'이라서 이름을 묻는 말이에요."}, {"q": "'내 성은 김이에요.'를 중국어로 바르게 쓴 것은 무엇일까요?", "choices": ["我姓金。", "我叫金。", "我是金人。", "你姓金。"], "answer": 0, "explain": "성만 말할 때는 我姓…을 써요. 金은 Jīn(진)이라고 읽어요."}, {"q": "我是韩国人의 뜻은 무엇일까요?", "choices": ["나는 중국 사람이에요.", "만나서 반가워요.", "이름이 뭐예요?", "나는 한국 사람이에요."], "answer": 3, "explain": "韩国人(Hánguórén)은 '한국 사람'이에요."}, {"q": "내 이름을 말한 뒤 '너는?' 하고 되물을 때 쓰는 말은 무엇일까요?", "choices": ["你好？", "你呢？", "什么？", "谢谢？"], "answer": 1, "explain": "你呢？(nǐ ne)는 '너는?'이라고 되묻는 말이에요."}], "summary": ["我叫…(wǒ jiào)로 이름을, 我姓…(wǒ xìng)으로 성을 말해요.", "이름은 你叫什么名字？(nǐ jiào shénme míngzi)로 묻고, 你呢？로 되물어요.", "我是韩国人(나는 한국 사람)과 认识你很高兴(만나서 반가워)으로 자기소개를 마무리해요."], "parent_tip": "아이와 함께 우리 가족 성씨의 한자와 중국어 소리(김 Jīn, 이 Lǐ, 박 Piáo, 최 Cuī 등)를 찾아보면 아이가 아주 흥미로워합니다. 부모님이 중국 친구 역할을 맡아 '你叫什么名字？'라고 묻고 아이가 인사부터 반가워까지 이어서 대답하는 역할놀이를 해 보세요."}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','중국어','이름 말하기 我叫',10,'c3-10' where not exists (select 1 from public.topics where lesson_slug='c3-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-01','5~6','중국어','자기소개 我是','중국어로 나를 소개해 볼까요?','assets/img/l_c5-01.jpg',$j${"intro": "중국에서 온 새 친구를 만났어요! 반갑게 인사하고 내 이름을 말해 주고 싶다면 어떻게 할까요? 오늘은 중국어로 나를 소개하는 방법을 처음부터 배워요.", "sections": [{"heading": "인사는 你好(nǐ hǎo)로 시작해요", "paras": ["중국어로 '안녕'은 你好(nǐ hǎo, 니하오)예요. 你(nǐ)는 '너', 好(hǎo)는 '좋다'라는 뜻이에요.", "알파벳 위의 작은 표시는 성조예요. 성조는 소리의 높낮이인데, 높낮이가 달라지면 뜻도 달라져요. ā는 높고 평평하게, á는 쭉 올리고, ǎ는 내렸다가 올리고, à는 뚝 떨어뜨려 읽어요.", "헤어질 때는 再见(zàijiàn, 짜이지엔)이라고 말해요. 선생님께는 老师好(lǎoshī hǎo, 라오스 하오)라고 인사해요."], "example": "你好！(nǐ hǎo, 니하오) → 안녕! / 再见！(zàijiàn, 짜이지엔) → 잘 가!", "figure": "두 아이가 교실 앞에서 웃으며 손을 흔들어 인사하는 모습"}, {"heading": "我是(wǒ shì)로 '나는 ~이에요'를 말해요", "paras": ["我(wǒ, 워)는 '나', 是(shì, 스)는 '~이다'라는 뜻이에요. 我是 뒤에 나를 나타내는 말을 붙이면 '나는 ~이에요'가 돼요.", "我是学生(wǒ shì xuésheng, 워 스 쉐셩)은 '나는 학생이에요', 我是韩国人(wǒ shì Hánguórén, 워 스 한궈런)은 '나는 한국 사람이에요'예요. 중국어는 우리말과 달리 '나는 - 이다 - 학생' 순서로 말해요."], "example": "我 + 是 + 学生 → 我是学生。(나는 학생이에요.)", "figure": "'나 - 이다 - 학생' 순서로 놓인 낱말 카드 세 장 그림"}, {"heading": "이름은 我叫(wǒ jiào)로 말해요", "paras": ["이름을 말할 때는 我叫(wǒ jiào, 워 지아오) 뒤에 이름을 붙여요. 叫는 '(이름을) 부르다'라는 뜻이에요.", "이름을 물을 때는 你叫什么名字？(nǐ jiào shénme míngzi, 니 지아오 선머 밍쯔)라고 해요. 什么(shénme)는 '무엇', 名字(míngzi)는 '이름'이에요.", "我是敏浩(wǒ shì Mǐnhào, 워 스 민하오)처럼 我是 뒤에 이름을 붙여도 '나는 민호야'라는 뜻이 돼요."], "example": "A: 你叫什么名字？(이름이 뭐야?)  B: 我叫敏浩。(wǒ jiào Mǐnhào, 워 지아오 민하오 → 나는 민호라고 해.)", "figure": "이름표를 가슴에 단 아이가 친구에게 자기 이름을 말하는 모습"}, {"heading": "吗(ma)로 묻고, 不是(bú shì)로 아니라고 해요", "paras": ["문장 끝에 吗(ma, 마)를 붙이면 묻는 말이 돼요. 你是中国人吗？(nǐ shì Zhōngguórén ma, 니 스 중궈런 마)는 '너는 중국 사람이니?'예요.", "'아니에요'라고 할 때는 是 앞에 不를 붙여 不是(bú shì, 부 스)라고 해요. 不는 원래 bù(뿌)인데, 是처럼 뚝 떨어지는 소리(4성) 앞에서는 bú(부)로 올려 읽어요.", "처음 만난 친구에게는 认识你很高兴(rènshi nǐ hěn gāoxìng, 런스 니 헌 가오싱), '만나서 반가워'라고 말해 보세요."], "example": "A: 你是中国人吗？ B: 我不是中国人，我是韩国人。(나는 중국 사람이 아니야. 한국 사람이야.)", "figure": "한국 국기와 중국 국기를 각각 든 두 아이가 마주 보고 이야기하는 모습"}], "keywords": [{"word": "병음", "meaning": "중국어 소리를 알파벳으로 적은 것 (예: nǐ hǎo)"}, {"word": "성조", "meaning": "소리의 높낮이. 1성(ā)·2성(á)·3성(ǎ)·4성(à) 네 가지가 있어요"}, {"word": "我是 (wǒ shì)", "meaning": "나는 ~이에요"}, {"word": "我叫 (wǒ jiào)", "meaning": "내 이름은 ~이에요"}, {"word": "吗 (ma)", "meaning": "문장 끝에 붙여 묻는 말을 만드는 글자"}], "expressions": [{"en": "你好！", "ko": "안녕! / 안녕하세요!", "note": "nǐ hǎo (니하오)"}, {"en": "我是学生。", "ko": "나는 학생이에요.", "note": "wǒ shì xuésheng (워 스 쉐셩)"}, {"en": "我是韩国人。", "ko": "나는 한국 사람이에요.", "note": "wǒ shì Hánguórén (워 스 한궈런)"}, {"en": "我叫敏浩。", "ko": "내 이름은 민호예요.", "note": "wǒ jiào Mǐnhào (워 지아오 민하오)"}, {"en": "你叫什么名字？", "ko": "이름이 뭐예요?", "note": "nǐ jiào shénme míngzi (니 지아오 선머 밍쯔)"}, {"en": "你是中国人吗？", "ko": "너는 중국 사람이니?", "note": "nǐ shì Zhōngguórén ma (니 스 중궈런 마)"}, {"en": "我不是中国人。", "ko": "나는 중국 사람이 아니에요.", "note": "wǒ bú shì Zhōngguórén (워 부 스 중궈런)"}, {"en": "认识你很高兴。", "ko": "만나서 반가워요.", "note": "rènshi nǐ hěn gāoxìng (런스 니 헌 가오싱)"}, {"en": "老师好！", "ko": "선생님, 안녕하세요!", "note": "lǎoshī hǎo (라오스 하오)"}, {"en": "再见！", "ko": "잘 가! / 안녕히 계세요!", "note": "zàijiàn (짜이지엔)"}], "quiz": [{"q": "我是学生。(wǒ shì xuésheng)의 뜻은 무엇일까요?", "choices": ["나는 선생님이에요.", "나는 학생이에요.", "너는 학생이니?", "나는 한국 사람이에요."], "answer": 1, "explain": "我는 '나', 是는 '~이다', 学生은 '학생'이에요."}, {"q": "친구의 이름을 물어볼 때 하는 말은?", "choices": ["你好！", "再见！", "你叫什么名字？", "我是韩国人。"], "answer": 2, "explain": "什么는 '무엇', 名字는 '이름'이라서 '이름이 뭐야?'라는 뜻이에요."}, {"q": "문장 끝에 붙이면 묻는 말이 되는 글자는?", "choices": ["吗 (ma)", "是 (shì)", "我 (wǒ)", "叫 (jiào)"], "answer": 0, "explain": "你是中国人吗？처럼 문장 끝에 吗를 붙이면 '~이니?' 하고 묻는 말이 돼요."}, {"q": "'나는 중국 사람이 아니에요.'를 중국어로 바르게 쓴 것은?", "choices": ["我是中国人。", "你是中国人吗？", "我叫中国人。", "我不是中国人。"], "answer": 3, "explain": "'아니다'는 是 앞에 不를 붙인 不是(bú shì)로 말해요."}, {"q": "처음 만난 친구에게 '만나서 반가워.'라고 할 때 알맞은 말은?", "choices": ["认识你很高兴。", "再见！", "老师好！", "我是学生。"], "answer": 0, "explain": "认识你很高兴(rènshi nǐ hěn gāoxìng)은 '너를 알게 되어 기뻐', 곧 '만나서 반가워'라는 뜻이에요."}], "summary": ["你好(nǐ hǎo)는 '안녕', 再见(zàijiàn)은 '잘 가'예요.", "我是 ~ (wǒ shì)는 '나는 ~이에요', 我叫 ~ (wǒ jiào)는 '내 이름은 ~이에요'예요.", "문장 끝에 吗(ma)를 붙이면 묻는 말, 是 앞에 不를 붙이면 '~이 아니에요'가 돼요."], "parent_tip": "중국어는 같은 소리라도 성조(높낮이)가 다르면 뜻이 달라지므로, 병음 위 표시를 보며 손으로 높낮이를 그려 가며 읽게 하면 좋습니다. 你好처럼 3성이 두 번 이어지면 실제로는 앞 글자를 2성처럼 올려 'ní hǎo'로 읽는데, 표기는 nǐ hǎo 그대로 둡니다. 저녁 식사 때 '你叫什么名字？'라고 물어 아이가 '我叫○○。'로 대답하는 놀이를 해 보세요."}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','자기소개 我是',1,'c5-01' where not exists (select 1 from public.topics where lesson_slug='c5-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-02','5~6','중국어','나이 묻기 你几岁','중국어로 몇 살인지 물어볼까요?','assets/img/l_c5-02.jpg',$j${"intro": "새 친구와 친해지면 '너 몇 살이야?' 하고 궁금해지지요. 오늘은 중국어 숫자를 익히고, 나이를 묻고 대답하는 말을 배워요.", "sections": [{"heading": "1부터 10까지 세어 봐요", "paras": ["중국어 숫자는 한자로 써요. 一(yī, 이) 1, 二(èr, 얼) 2, 三(sān, 싼) 3, 四(sì, 쓰) 4, 五(wǔ, 우) 5예요.", "六(liù, 리우) 6, 七(qī, 치) 7, 八(bā, 바) 8, 九(jiǔ, 지우) 9, 十(shí, 스) 10이에요. 손가락을 하나씩 접으며 소리 내어 세어 보세요."], "example": "一 yī, 二 èr, 三 sān, 四 sì, 五 wǔ, 六 liù, 七 qī, 八 bā, 九 jiǔ, 十 shí", "figure": "아이 두 손의 손가락을 하나씩 펴며 수를 세는 모습"}, {"heading": "11부터 99까지는 블록처럼 붙여요", "paras": ["11은 '열 + 하나'라서 十一(shíyī, 스이), 12는 十二(shí'èr, 스얼)이에요. 우리말 '십일, 십이'와 만드는 방법이 똑같아요.", "20은 '둘 + 열'이라서 二十(èrshí, 얼스), 25는 二十五(èrshíwǔ, 얼스우)예요. 이렇게 하면 99 九十九(jiǔshíjiǔ)까지 모두 말할 수 있어요."], "example": "十一 = 11 / 十二 = 12 / 二十 = 20 / 二十五 = 25 / 九十九 = 99", "figure": "숫자 블록을 이어 붙여 큰 수를 만드는 장난감 블록 사진"}, {"heading": "你几岁？(nǐ jǐ suì) — 몇 살이야?", "paras": ["几(jǐ, 지)는 '몇', 岁(suì, 쑤이)는 '살'이에요. 그래서 你几岁？(nǐ jǐ suì, 니 지 쑤이)는 '너 몇 살이야?'예요.", "대답은 我 + 숫자 + 岁로 해요. 我十二岁(wǒ shí'èr suì, 워 스얼 쑤이)는 '나는 열두 살이야'예요. 우리말처럼 '이에요'에 해당하는 是는 넣지 않아요.", "조심! 두 살은 二岁가 아니라 两岁(liǎng suì, 량 쑤이)라고 해요. 하지만 열두 살은 그대로 十二岁예요."], "example": "A: 你几岁？(너 몇 살이야?)  B: 我十二岁。(나는 열두 살이야.)", "figure": "생일 케이크 위에 꽂힌 초를 아이가 세어 보는 모습"}, {"heading": "你多大？와 你呢？도 알아 두어요", "paras": ["几岁는 주로 어린아이에게 나이를 물을 때 써요. 비슷한 또래 친구에게는 你多大？(nǐ duō dà, 니 둬 다)라고도 물어요.", "대답한 뒤 상대에게 되물을 때는 你呢？(nǐ ne, 니 너), '너는?'이라고 해요. 나이가 같다면 我也十二岁(wǒ yě shí'èr suì, 워 예 스얼 쑤이), '나도 열두 살이야'라고 해요. 也(yě)는 '~도'예요.", "가족 나이도 말할 수 있어요. 我弟弟八岁(wǒ dìdi bā suì)는 '내 남동생은 여덟 살이에요'예요."], "example": "A: 我十二岁，你呢？  B: 我也十二岁。", "figure": "같은 반 친구 두 명이 서로 손가락으로 나이를 보여 주며 웃는 모습"}], "keywords": [{"word": "几 (jǐ)", "meaning": "몇"}, {"word": "岁 (suì)", "meaning": "살(나이를 세는 말)"}, {"word": "两 (liǎng)", "meaning": "둘. 두 살, 두 개처럼 셀 때 쓰는 '2'"}, {"word": "也 (yě)", "meaning": "~도"}, {"word": "呢 (ne)", "meaning": "'~는?' 하고 되물을 때 붙이는 글자"}], "expressions": [{"en": "你几岁？", "ko": "너 몇 살이야?", "note": "nǐ jǐ suì (니 지 쑤이)"}, {"en": "我十二岁。", "ko": "나는 열두 살이에요.", "note": "wǒ shí'èr suì (워 스얼 쑤이)"}, {"en": "我十一岁。", "ko": "나는 열한 살이에요.", "note": "wǒ shíyī suì (워 스이 쑤이)"}, {"en": "你多大？", "ko": "너 몇 살이야? (또래에게)", "note": "nǐ duō dà (니 둬 다)"}, {"en": "你呢？", "ko": "너는?", "note": "nǐ ne (니 너)"}, {"en": "我也十二岁。", "ko": "나도 열두 살이에요.", "note": "wǒ yě shí'èr suì (워 예 스얼 쑤이)"}, {"en": "我弟弟八岁。", "ko": "내 남동생은 여덟 살이에요.", "note": "wǒ dìdi bā suì (워 디디 바 쑤이)"}, {"en": "我妹妹两岁。", "ko": "내 여동생은 두 살이에요.", "note": "wǒ mèimei liǎng suì (워 메이메이 량 쑤이)"}, {"en": "十", "ko": "10, 열", "note": "shí (스)"}, {"en": "二十", "ko": "20, 스물", "note": "èrshí (얼스)"}], "quiz": [{"q": "七(qī)은 숫자 몇일까요?", "choices": ["1", "4", "7", "9"], "answer": 2, "explain": "七(qī, 치)은 7이에요."}, {"q": "你几岁？(nǐ jǐ suì)의 뜻은?", "choices": ["너 몇 살이야?", "이름이 뭐야?", "너는 학생이니?", "몇 시야?"], "answer": 0, "explain": "几는 '몇', 岁는 '살'이라서 '몇 살이야?'예요."}, {"q": "'나는 열한 살이에요.'를 바르게 쓴 것은?", "choices": ["我是十一。", "我一十岁。", "我十一岁。", "我岁十一。"], "answer": 2, "explain": "나이는 我 + 숫자 + 岁 순서로 말하고, 11은 十一예요."}, {"q": "'두 살'을 중국어로 바르게 말한 것은?", "choices": ["二岁", "十二岁", "二十岁", "两岁"], "answer": 3, "explain": "두 살은 两岁(liǎng suì)라고 해요."}, {"q": "我十二岁，你呢？에서 你呢？의 뜻은?", "choices": ["너도?", "너는?", "몇 살?", "안녕?"], "answer": 1, "explain": "你呢？(nǐ ne)는 '너는?' 하고 되묻는 말이에요."}], "summary": ["숫자 1~10: 一 二 三 四 五 六 七 八 九 十, 11은 十一, 20은 二十예요.", "你几岁？(nǐ jǐ suì)로 묻고, 我 + 숫자 + 岁로 대답해요. 두 살은 两岁예요.", "你呢？는 '너는?', 也는 '~도'라는 뜻이에요."], "parent_tip": "중국어 나이 말하기에는 '是'가 들어가지 않는다는 점(我十二岁)과, 2살은 二岁가 아닌 两岁라는 점을 아이가 자주 헷갈립니다. 계단을 오르거나 물건을 셀 때 중국어 숫자로 함께 세어 보시고, 가족 한 사람씩 가리키며 '他几岁？'라고 물어 '○岁'로 답하는 놀이를 해 보세요."}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','나이 묻기 你几岁',2,'c5-02' where not exists (select 1 from public.topics where lesson_slug='c5-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-03','5~6','중국어','날짜와 요일','오늘은 몇 월 며칠, 무슨 요일일까요?','assets/img/l_c5-03.jpg',$j${"intro": "달력을 보며 '오늘이 며칠이지?' 하고 물어본 적 있지요? 중국어로도 날짜와 요일을 묻고 말할 수 있어요. 숫자만 알면 생각보다 아주 쉬워요!", "sections": [{"heading": "月(yuè)와 号(hào)로 날짜를 말해요", "paras": ["'몇 월'은 숫자 뒤에 月(yuè, 위에)를 붙여요. 一月(yī yuè)는 1월, 十二月(shí'èr yuè)는 12월이에요.", "'며칠'은 숫자 뒤에 号(hào, 하오)를 붙여요. 그래서 5월 5일은 五月五号(wǔ yuè wǔ hào, 우 위에 우 하오)예요. 글로 쓸 때는 号 대신 日(rì)를 쓰기도 해요.", "순서는 우리말과 같아요. 월 → 일 순서로 말하면 돼요."], "example": "三月一号 = 3월 1일 / 十月九号 = 10월 9일", "figure": "벽에 걸린 달력에서 아이가 손가락으로 날짜 한 칸을 가리키는 모습"}, {"heading": "今天几月几号？— 오늘은 몇 월 며칠이에요?", "paras": ["今天(jīntiān, 진티엔)은 '오늘'이에요. 几(jǐ)는 '몇'이니까, 今天几月几号？(jīntiān jǐ yuè jǐ hào, 진티엔 지 위에 지 하오)는 '오늘은 몇 월 며칠이에요?'예요.", "대답할 때는 几 자리에 숫자를 넣으면 돼요. 今天五月五号。는 '오늘은 5월 5일이에요.'예요.", "明天(míngtiān, 밍티엔)은 '내일', 昨天(zuótiān, 쭤티엔)은 '어제'예요."], "example": "A: 今天几月几号？  B: 今天十月九号。(오늘은 10월 9일이야.)", "figure": "어제·오늘·내일 세 칸으로 나뉜 달력 종이 그림"}, {"heading": "요일은 星期(xīngqī) + 숫자예요", "paras": ["요일은 星期(xīngqī, 싱치) 뒤에 숫자를 붙여요. 월요일이 星期一(xīngqīyī), 화요일이 星期二(xīngqī'èr), 수요일이 星期三(xīngqīsān)이에요.", "목요일 星期四(xīngqīsì), 금요일 星期五(xīngqīwǔ), 토요일 星期六(xīngqīliù)까지 숫자 차례예요. 일요일만 숫자가 아니라 星期天(xīngqītiān, 싱치티엔) 또는 星期日(xīngqīrì)라고 해요.", "무슨 요일인지 물을 때는 今天星期几？(jīntiān xīngqī jǐ, 진티엔 싱치 지)라고 해요."], "example": "星期一(월) 星期二(화) 星期三(수) 星期四(목) 星期五(금) 星期六(토) 星期天(일)", "figure": "일주일 일곱 칸이 그려진 시간표 종이와 색연필"}, {"heading": "내 생일을 말해 봐요", "paras": ["的(de, 더)는 '~의'라는 뜻이에요. 我的生日(wǒ de shēngrì, 워 더 셩르)는 '나의 생일'이에요.", "我的生日是三月十号。는 '내 생일은 3월 10일이에요.'예요. 친구에게는 你的生日是几月几号？라고 물어보세요.", "생일인 친구에게는 生日快乐！(shēngrì kuàilè, 셩르 콰이러), '생일 축하해!'라고 말해 줘요."], "example": "A: 你的生日是几月几号？  B: 我的生日是三月十号。", "figure": "포장된 선물 상자와 생일 고깔모자가 놓인 책상"}], "keywords": [{"word": "月 (yuè)", "meaning": "월(달)"}, {"word": "号 (hào)", "meaning": "일(날짜)"}, {"word": "星期 (xīngqī)", "meaning": "요일, 주"}, {"word": "今天 (jīntiān)", "meaning": "오늘"}, {"word": "生日 (shēngrì)", "meaning": "생일"}], "expressions": [{"en": "今天几月几号？", "ko": "오늘은 몇 월 며칠이에요?", "note": "jīntiān jǐ yuè jǐ hào (진티엔 지 위에 지 하오)"}, {"en": "今天五月五号。", "ko": "오늘은 5월 5일이에요.", "note": "jīntiān wǔ yuè wǔ hào (진티엔 우 위에 우 하오)"}, {"en": "今天星期几？", "ko": "오늘은 무슨 요일이에요?", "note": "jīntiān xīngqī jǐ (진티엔 싱치 지)"}, {"en": "今天星期一。", "ko": "오늘은 월요일이에요.", "note": "jīntiān xīngqīyī (진티엔 싱치이)"}, {"en": "明天星期六。", "ko": "내일은 토요일이에요.", "note": "míngtiān xīngqīliù (밍티엔 싱치리우)"}, {"en": "星期天", "ko": "일요일", "note": "xīngqītiān (싱치티엔)"}, {"en": "昨天", "ko": "어제", "note": "zuótiān (쭤티엔)"}, {"en": "我的生日是三月十号。", "ko": "내 생일은 3월 10일이에요.", "note": "wǒ de shēngrì shì sān yuè shí hào (워 더 셩르 스 싼 위에 스 하오)"}, {"en": "你的生日是几月几号？", "ko": "네 생일은 몇 월 며칠이야?", "note": "nǐ de shēngrì shì jǐ yuè jǐ hào (니 더 셩르 스 지 위에 지 하오)"}, {"en": "生日快乐！", "ko": "생일 축하해!", "note": "shēngrì kuàilè (셩르 콰이러)"}], "quiz": [{"q": "八月十五号는 며칠일까요?", "choices": ["8월 15일", "15월 8일", "8월 5일", "10월 8일"], "answer": 0, "explain": "八月는 8월, 十五号는 15일이에요."}, {"q": "'오늘은 무슨 요일이에요?'를 중국어로 한 것은?", "choices": ["今天几月几号？", "今天星期几？", "你几岁？", "生日快乐！"], "answer": 1, "explain": "요일은 星期를 쓰니까 今天星期几？예요."}, {"q": "星期五는 무슨 요일일까요?", "choices": ["월요일", "수요일", "토요일", "금요일"], "answer": 3, "explain": "星期 + 五(5)는 다섯째 날인 금요일이에요. 星期一가 월요일이에요."}, {"q": "일요일을 나타내는 말은?", "choices": ["星期七", "星期一", "星期天", "星期十"], "answer": 2, "explain": "일요일은 숫자 7을 쓰지 않고 星期天 또는 星期日라고 해요."}, {"q": "生日快乐！는 언제 하는 말일까요?", "choices": ["친구 생일에", "헤어질 때", "처음 만났을 때", "물건을 살 때"], "answer": 0, "explain": "生日快乐(shēngrì kuàilè)는 '생일 축하해!'예요."}], "summary": ["날짜는 숫자 + 月(월), 숫자 + 号(일) 순서로 말해요. 五月五号 = 5월 5일.", "요일은 星期 + 숫자(星期一 = 월요일)이고, 일요일은 星期天이에요.", "今天几月几号？(며칠?) / 今天星期几？(무슨 요일?)로 물어요."], "parent_tip": "아이들이 星期一를 '일요일'로 착각하는 일이 많습니다. 星期 뒤 숫자는 '월요일부터 센 순서'라는 점을 달력을 보며 짚어 주세요. 아침마다 '今天星期几？'라고 물어 보고, 가족 생일을 '○月○号'로 말해 보게 하면 숫자 복습도 함께 됩니다."}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','날짜와 요일',3,'c5-03' where not exists (select 1 from public.topics where lesson_slug='c5-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-04','5~6','중국어','시간 말하기','지금 몇 시예요? 중국어로 시간 말하기','assets/img/l_c5-04.jpg',$j${"intro": "학교 가는 시간, 학원 가는 시간, 잠자는 시간… 하루는 시간으로 가득해요. 오늘은 중국어로 '지금 몇 시야?'라고 묻고, 내 하루를 시간으로 소개해 봐요.", "sections": [{"heading": "'몇 시'는 숫자 + 点(diǎn)이에요", "paras": ["시계의 '시'는 点(diǎn, 디엔)이에요. 숫자 뒤에 点을 붙이면 돼요. 三点(sān diǎn, 싼 디엔)은 3시, 十二点(shí'èr diǎn)은 12시예요.", "조심! 2시는 二点이 아니라 两点(liǎng diǎn, 량 디엔)이라고 해요. 나이에서 두 살을 两岁라고 한 것과 같아요."], "example": "一点 1시 / 两点 2시 / 三点 3시 / 十点 10시 / 十二点 12시", "figure": "벽에 걸린 둥근 아날로그 시계와 그 앞에 서 있는 아이"}, {"heading": "'몇 분'은 分(fēn), '반'은 半(bàn)", "paras": ["'분'은 숫자 뒤에 分(fēn, 펀)을 붙여요. 八点十分(bā diǎn shí fēn, 바 디엔 스 펀)은 8시 10분, 七点二十分(qī diǎn èrshí fēn)은 7시 20분이에요.", "'30분'은 우리말처럼 '반'이라고 할 수 있어요. 半(bàn, 빤)을 点 뒤에 붙여 三点半(sān diǎn bàn, 싼 디엔 빤)이라고 하면 3시 반이에요."], "example": "八点十分 = 8시 10분 / 三点半 = 3시 반(3시 30분)", "figure": "긴바늘이 6을 가리키는 시계 두 개를 나란히 놓은 그림"}, {"heading": "现在几点？— 지금 몇 시예요?", "paras": ["现在(xiànzài, 시엔짜이)는 '지금', 几(jǐ)는 '몇'이에요. 그래서 现在几点？(xiànzài jǐ diǎn, 시엔짜이 지 디엔)은 '지금 몇 시예요?'예요.", "대답은 现在 + 시간으로 해요. 现在三点。(지금 3시예요.) 现在九点半。(지금 9시 반이에요.)", "아침·오후·저녁을 함께 말하면 더 정확해요. 早上(zǎoshang, 짜오샹) 아침, 下午(xiàwǔ, 시아우) 오후, 晚上(wǎnshang, 완샹) 저녁이에요. 이 말은 시간 앞에 붙여요."], "example": "A: 现在几点？  B: 现在下午四点。(지금 오후 4시야.)", "figure": "손목시계를 들여다보는 아이의 손목 사진"}, {"heading": "시간은 '무엇을 하다' 앞에 와요", "paras": ["중국어는 '언제'를 하는 일 앞에 말해요. 我七点起床。(wǒ qī diǎn qǐchuáng, 워 치 디엔 치촹)은 '나는 7시에 일어나요.'예요. 起床은 '일어나다'예요.", "我八点去学校。(wǒ bā diǎn qù xuéxiào)는 '나는 8시에 학교에 가요.', 我晚上十点睡觉。(wǒ wǎnshang shí diǎn shuìjiào)는 '나는 저녁 10시에 자요.'예요.", "순서를 기억해요. 我(나) → 시간 → 하는 일! 우리말 '나는 7시에 일어나요'와 순서가 비슷해서 쉬워요."], "example": "我 + 七点 + 起床 → 我七点起床。(나는 7시에 일어나요.)", "figure": "아침 햇살이 드는 방에서 알람시계 옆 침대에서 일어나는 아이"}], "keywords": [{"word": "点 (diǎn)", "meaning": "시(시각)"}, {"word": "分 (fēn)", "meaning": "분"}, {"word": "半 (bàn)", "meaning": "반(30분)"}, {"word": "现在 (xiànzài)", "meaning": "지금"}, {"word": "两点 (liǎng diǎn)", "meaning": "2시 (二点이라고 하지 않아요)"}], "expressions": [{"en": "现在几点？", "ko": "지금 몇 시예요?", "note": "xiànzài jǐ diǎn (시엔짜이 지 디엔)"}, {"en": "现在三点。", "ko": "지금 3시예요.", "note": "xiànzài sān diǎn (시엔짜이 싼 디엔)"}, {"en": "两点", "ko": "2시", "note": "liǎng diǎn (량 디엔)"}, {"en": "三点半", "ko": "3시 반", "note": "sān diǎn bàn (싼 디엔 빤)"}, {"en": "八点十分", "ko": "8시 10분", "note": "bā diǎn shí fēn (바 디엔 스 펀)"}, {"en": "我七点起床。", "ko": "나는 7시에 일어나요.", "note": "wǒ qī diǎn qǐchuáng (워 치 디엔 치촹)"}, {"en": "我八点去学校。", "ko": "나는 8시에 학교에 가요.", "note": "wǒ bā diǎn qù xuéxiào (워 바 디엔 취 쉐시아오)"}, {"en": "我晚上十点睡觉。", "ko": "나는 저녁 10시에 자요.", "note": "wǒ wǎnshang shí diǎn shuìjiào (워 완샹 스 디엔 수이지아오)"}, {"en": "早上", "ko": "아침", "note": "zǎoshang (짜오샹)"}, {"en": "下午", "ko": "오후", "note": "xiàwǔ (시아우)"}], "quiz": [{"q": "现在几点？(xiànzài jǐ diǎn)의 뜻은?", "choices": ["오늘은 며칠이에요?", "지금 몇 시예요?", "몇 살이에요?", "무슨 요일이에요?"], "answer": 1, "explain": "现在는 '지금', 几点은 '몇 시'예요."}, {"q": "'2시'를 중국어로 바르게 말한 것은?", "choices": ["二点", "十二点", "两点", "二分"], "answer": 2, "explain": "2시는 两点(liǎng diǎn)이라고 해요. 十二点은 12시예요."}, {"q": "六点半은 몇 시일까요?", "choices": ["6시 30분", "6시 5분", "5시 30분", "6시 반 전"], "answer": 0, "explain": "六点은 6시, 半은 30분(반)이라서 6시 30분이에요."}, {"q": "'나는 7시에 일어나요.'를 바른 순서로 쓴 것은?", "choices": ["我起床七点。", "七点起床我。", "起床我七点。", "我七点起床。"], "answer": 3, "explain": "중국어는 나 → 시간 → 하는 일 순서로 말해요."}, {"q": "晚上(wǎnshang)의 뜻은?", "choices": ["아침", "오후", "저녁", "지금"], "answer": 2, "explain": "早上은 아침, 下午는 오후, 晚上은 저녁이에요."}], "summary": ["'시'는 숫자 + 点, '분'은 숫자 + 分, '반'은 半이에요. 2시는 两点!", "现在几点？로 묻고, 现在 + 시간으로 대답해요.", "중국어는 '나 → 시간 → 하는 일' 순서로 말해요. 我七点起床。"], "parent_tip": "아이들이 2시를 二点으로 말하는 실수를 자주 합니다(정답: 两点). 또 '我起床七点'처럼 시간을 동사 뒤에 두기 쉬우니 '시간은 하는 일 앞'이라고 짚어 주세요. 집 시계를 가리키며 '现在几点？'라고 하루에 한두 번 물어보면 숫자와 시간 표현을 함께 복습할 수 있습니다."}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','시간 말하기',4,'c5-04' where not exists (select 1 from public.topics where lesson_slug='c5-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-05','5~6','중국어','좋아하는 것 我喜欢','중국어로 ''나는 ~을 좋아해!'' 말해 볼까요?','assets/img/l_c5-05.jpg',$j${"intro": "판다, 사과, 축구, 노래… 여러분은 무엇을 좋아하나요? 좋아하는 것을 이야기하면 친구와 금방 친해질 수 있어요. 오늘은 중국어로 좋아하는 것을 말하고 물어봐요.", "sections": [{"heading": "我喜欢(wǒ xǐhuan) + 좋아하는 것", "paras": ["喜欢(xǐhuan, 시환)은 '좋아하다'예요. 我喜欢 뒤에 좋아하는 것을 붙이면 '나는 ~을 좋아해요'가 돼요.", "我喜欢熊猫。(wǒ xǐhuan xióngmāo, 워 시환 슝마오)는 '나는 판다를 좋아해요.', 我喜欢苹果。(wǒ xǐhuan píngguǒ, 워 시환 핑궈)는 '나는 사과를 좋아해요.'예요.", "우리말은 '판다를 좋아해'처럼 좋아하는 것이 앞에 오지만, 중국어는 '좋아해 → 판다' 순서예요."], "example": "我 + 喜欢 + 熊猫 → 我喜欢熊猫。(나는 판다를 좋아해요.)", "figure": "대나무 잎을 먹는 판다 인형을 안고 있는 아이"}, {"heading": "좋아하는 '활동'도 말할 수 있어요", "paras": ["喜欢 뒤에는 하는 일도 올 수 있어요. 唱歌(chàng gē, 창꺼)는 '노래하다', 看书(kàn shū, 칸 수)는 '책을 읽다', 踢足球(tī zúqiú, 티 쭈치우)는 '축구를 하다'예요.", "我喜欢唱歌。는 '나는 노래하는 것을 좋아해요.', 我喜欢看书。는 '나는 책 읽는 것을 좋아해요.'예요."], "example": "我喜欢踢足球。(wǒ xǐhuan tī zúqiú) → 나는 축구하는 것을 좋아해요.", "figure": "운동장 잔디 위에 놓인 축구공과 책 한 권"}, {"heading": "묻고 대답하기 — 什么(shénme)와 吗(ma)", "paras": ["'무엇을 좋아해?'는 你喜欢什么？(nǐ xǐhuan shénme, 니 시환 선머)예요. 什么는 '무엇'이에요.", "'~을 좋아하니?'는 문장 끝에 吗를 붙여요. 你喜欢狗吗？(nǐ xǐhuan gǒu ma, 니 시환 거우 마)는 '너는 개를 좋아하니?'예요.", "좋아하면 喜欢！, 좋아하지 않으면 不喜欢(bù xǐhuan, 뿌 시환)이라고 대답해요. 喜 앞의 不는 원래 소리 bù(뿌)로 읽어요."], "example": "A: 你喜欢狗吗？  B: 喜欢！我很喜欢狗。 / 不喜欢，我喜欢猫。", "figure": "강아지와 고양이 인형을 양손에 하나씩 든 아이"}, {"heading": "很(hěn)과 也(yě)로 더 풍부하게", "paras": ["아주 좋아할 때는 喜欢 앞에 很(hěn, 헌)을 붙여 很喜欢이라고 해요. 我很喜欢熊猫。는 '나는 판다를 아주 좋아해요.'예요.", "친구와 좋아하는 것이 같다면 也(yě, 예)를 써요. 我也喜欢猫。(wǒ yě xǐhuan māo, 워 예 시환 마오)는 '나도 고양이를 좋아해.'예요. 也는 喜欢 앞에 놓아요.", "싫어하는 것도 말해 봐요. 我不喜欢牛奶。(wǒ bù xǐhuan niúnǎi)는 '나는 우유를 좋아하지 않아요.'예요."], "example": "A: 我喜欢猫。  B: 我也喜欢猫！(나도 고양이 좋아해!)", "figure": "두 친구가 고양이 사진이 담긴 책을 함께 보며 웃는 모습"}], "keywords": [{"word": "喜欢 (xǐhuan)", "meaning": "좋아하다"}, {"word": "什么 (shénme)", "meaning": "무엇"}, {"word": "不喜欢 (bù xǐhuan)", "meaning": "좋아하지 않다"}, {"word": "很 (hěn)", "meaning": "아주, 매우"}, {"word": "也 (yě)", "meaning": "~도"}], "expressions": [{"en": "我喜欢熊猫。", "ko": "나는 판다를 좋아해요.", "note": "wǒ xǐhuan xióngmāo (워 시환 슝마오)"}, {"en": "你喜欢什么？", "ko": "너는 무엇을 좋아해?", "note": "nǐ xǐhuan shénme (니 시환 선머)"}, {"en": "我喜欢苹果。", "ko": "나는 사과를 좋아해요.", "note": "wǒ xǐhuan píngguǒ (워 시환 핑궈)"}, {"en": "你喜欢狗吗？", "ko": "너는 개를 좋아하니?", "note": "nǐ xǐhuan gǒu ma (니 시환 거우 마)"}, {"en": "我不喜欢牛奶。", "ko": "나는 우유를 좋아하지 않아요.", "note": "wǒ bù xǐhuan niúnǎi (워 뿌 시환 니우나이)"}, {"en": "我很喜欢踢足球。", "ko": "나는 축구하는 것을 아주 좋아해요.", "note": "wǒ hěn xǐhuan tī zúqiú (워 헌 시환 티 쭈치우)"}, {"en": "我喜欢唱歌。", "ko": "나는 노래하는 것을 좋아해요.", "note": "wǒ xǐhuan chàng gē (워 시환 창 꺼)"}, {"en": "我也喜欢猫。", "ko": "나도 고양이를 좋아해요.", "note": "wǒ yě xǐhuan māo (워 예 시환 마오)"}, {"en": "看书", "ko": "책을 읽다", "note": "kàn shū (칸 수)"}, {"en": "熊猫", "ko": "판다", "note": "xióngmāo (슝마오)"}], "quiz": [{"q": "喜欢(xǐhuan)의 뜻은?", "choices": ["싫어하다", "좋아하다", "먹다", "보다"], "answer": 1, "explain": "喜欢은 '좋아하다'예요."}, {"q": "'너는 무엇을 좋아해?'를 중국어로 한 것은?", "choices": ["你喜欢什么？", "你叫什么名字？", "你几岁？", "你喜欢狗吗？"], "answer": 0, "explain": "喜欢(좋아하다) + 什么(무엇)로 물어요."}, {"q": "我不喜欢牛奶。의 뜻은?", "choices": ["나는 우유를 아주 좋아해요.", "나도 우유를 좋아해요.", "나는 우유를 좋아하지 않아요.", "너는 우유를 좋아하니?"], "answer": 2, "explain": "不喜欢은 '좋아하지 않다'예요."}, {"q": "친구가 我喜欢熊猫。라고 했어요. '나도 판다 좋아해!'라고 할 때 알맞은 말은?", "choices": ["我很喜欢熊猫。", "我不喜欢熊猫。", "你喜欢熊猫吗？", "我也喜欢熊猫。"], "answer": 3, "explain": "'~도'는 也(yě)이고, 喜欢 앞에 놓아요."}, {"q": "我喜欢唱歌。에서 唱歌의 뜻은?", "choices": ["책을 읽다", "노래하다", "축구를 하다", "그림을 그리다"], "answer": 1, "explain": "唱歌(chàng gē)는 '노래하다'예요."}], "summary": ["我喜欢 + 좋아하는 것: '나는 ~을 좋아해요.' (좋아하다 → 대상 순서)", "你喜欢什么？(무엇을 좋아해?) / 你喜欢 ~ 吗？(~을 좋아하니?)로 물어요.", "不喜欢은 '좋아하지 않다', 很喜欢은 '아주 좋아하다', 我也喜欢은 '나도 좋아해'예요."], "parent_tip": "우리말은 '사과를 좋아해'처럼 대상이 앞에 오지만 중국어는 '我喜欢苹果'처럼 동사가 먼저 나온다는 점을 아이가 헷갈려 합니다. 也를 문장 맨 앞(也我喜欢)에 두는 실수도 흔하니 '나 + 也 + 喜欢' 순서를 확인해 주세요. 가족끼리 '你喜欢什么？'를 돌아가며 묻고 답하는 놀이를 추천합니다."}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','좋아하는 것 我喜欢',5,'c5-05' where not exists (select 1 from public.topics where lesson_slug='c5-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-06','5~6','중국어','음식 주문 我要','식당에서 중국어로 주문해 볼까요?','assets/img/l_c5-06.jpg',$j${"intro": "중국 식당에 갔는데 메뉴를 주문해야 해요! 두근두근하지만 걱정 마세요. '我要(wǒ yào)' 한마디만 알면 먹고 싶은 음식을 시킬 수 있어요.", "sections": [{"heading": "我要(wǒ yào) — '~ 주세요'", "paras": ["要(yào, 야오)는 '원하다, 필요하다'예요. 我要 뒤에 음식 이름을 붙이면 '나는 ~을 원해요', 곧 '~ 주세요'가 돼요.", "我要饺子。(wǒ yào jiǎozi, 워 야오 지아오쯔)는 '만두 주세요.'예요. 식당에서 종업원을 부를 때는 服务员！(fúwùyuán, 푸우위엔)이라고 해요."], "example": "服务员！我要饺子。(저기요! 만두 주세요.)", "figure": "식당 테이블 위에 김이 나는 만두 접시와 젓가락이 놓인 모습"}, {"heading": "몇 개인지 말하기 — 세는 말(양사)", "paras": ["중국어는 수와 물건 사이에 '세는 말'을 넣어요. 우리말 '한 그릇, 한 잔, 한 개'와 비슷해요.", "个(ge, 거)는 '개', 碗(wǎn, 완)은 '그릇', 杯(bēi, 베이)는 '잔'이에요. 一个汉堡(yí ge hànbǎo)는 햄버거 한 개, 一碗面条(yì wǎn miàntiáo)는 국수 한 그릇, 一杯可乐(yì bēi kělè)는 콜라 한 잔이에요.", "一는 뒤 글자에 따라 yí, yì로 소리가 살짝 바뀌니 병음을 보고 읽어요. 두 개를 말할 때는 二이 아니라 两(liǎng)을 써요. 两个汉堡 = 햄버거 두 개!"], "example": "我要一碗面条。(국수 한 그릇 주세요.) / 我要两个汉堡。(햄버거 두 개 주세요.)", "figure": "국수 한 그릇, 콜라 한 잔, 햄버거 두 개가 나란히 놓인 쟁반"}, {"heading": "종업원이 묻는 말에 대답해요", "paras": ["종업원은 먼저 你要什么？(nǐ yào shénme, 니 야오 선머), '무엇을 드릴까요?'라고 물어요. 그러면 我要 ~ 로 대답해요.", "주문한 뒤에는 还要别的吗？(hái yào bié de ma, 하이 야오 비에 더 마), '다른 것도 필요하세요?'라고 물을 수 있어요.", "더 필요 없으면 不要了，谢谢。(bú yào le, xièxie, 부 야오 러 씨에시에), '이제 됐어요, 고마워요.'라고 해요. 종업원은 好的(hǎo de, 하오 더), '알겠습니다'라고 대답해요."], "example": "A: 还要别的吗？  B: 不要了，谢谢。  A: 好的。", "figure": "앞치마를 두른 종업원이 메모지를 들고 아이의 주문을 받는 모습"}, {"heading": "중국 음식 이름을 알아 두어요", "paras": ["饺子(jiǎozi, 지아오쯔) 만두, 面条(miàntiáo, 미엔티아오) 국수, 米饭(mǐfàn, 미판) 밥이에요.", "汉堡(hànbǎo, 한바오) 햄버거, 可乐(kělè, 커러) 콜라, 水(shuǐ, 수이) 물이에요. 좋아하는 음식 이름을 넣어 我要 ~ 로 연습해 보세요."], "example": "我要一碗米饭和一杯水。(밥 한 그릇과 물 한 잔 주세요.) — 和(hé)는 '~와/과'", "figure": "만두, 국수, 밥, 물컵이 각각 담긴 작은 그릇들"}], "keywords": [{"word": "要 (yào)", "meaning": "원하다, 필요하다 (我要 = ~ 주세요)"}, {"word": "个 (ge)", "meaning": "개 (물건을 세는 말)"}, {"word": "碗 (wǎn)", "meaning": "그릇 (그릇에 담긴 음식을 세는 말)"}, {"word": "杯 (bēi)", "meaning": "잔 (음료를 세는 말)"}, {"word": "服务员 (fúwùyuán)", "meaning": "종업원"}], "expressions": [{"en": "服务员！", "ko": "저기요! (종업원을 부를 때)", "note": "fúwùyuán (푸우위엔)"}, {"en": "你要什么？", "ko": "무엇을 드릴까요? / 뭐 먹을래?", "note": "nǐ yào shénme (니 야오 선머)"}, {"en": "我要一碗面条。", "ko": "국수 한 그릇 주세요.", "note": "wǒ yào yì wǎn miàntiáo (워 야오 이 완 미엔티아오)"}, {"en": "我要两个汉堡。", "ko": "햄버거 두 개 주세요.", "note": "wǒ yào liǎng ge hànbǎo (워 야오 량 거 한바오)"}, {"en": "我要一杯可乐。", "ko": "콜라 한 잔 주세요.", "note": "wǒ yào yì bēi kělè (워 야오 이 베이 커러)"}, {"en": "我要饺子。", "ko": "만두 주세요.", "note": "wǒ yào jiǎozi (워 야오 지아오쯔)"}, {"en": "还要别的吗？", "ko": "다른 것도 필요하세요?", "note": "hái yào bié de ma (하이 야오 비에 더 마)"}, {"en": "不要了，谢谢。", "ko": "이제 됐어요, 고마워요.", "note": "bú yào le, xièxie (부 야오 러, 씨에시에)"}, {"en": "好的。", "ko": "알겠습니다. / 좋아요.", "note": "hǎo de (하오 더)"}, {"en": "米饭", "ko": "밥", "note": "mǐfàn (미판)"}], "quiz": [{"q": "식당에서 我要饺子。라고 하면 무슨 뜻일까요?", "choices": ["만두를 좋아해요.", "만두 주세요.", "만두는 얼마예요?", "만두가 어디 있어요?"], "answer": 1, "explain": "我要 ~ 는 '~을 원해요', 곧 '~ 주세요'예요."}, {"q": "콜라 '한 잔'을 말할 때 알맞은 세는 말은?", "choices": ["个", "碗", "杯", "岁"], "answer": 2, "explain": "음료는 잔을 뜻하는 杯(bēi)로 세요."}, {"q": "'햄버거 두 개 주세요.'를 바르게 쓴 것은?", "choices": ["我要两个汉堡。", "我要二个汉堡。", "我要汉堡两个。", "我两个要汉堡。"], "answer": 0, "explain": "두 개는 两个이고, 我要 + 수 + 세는 말 + 음식 순서예요."}, {"q": "종업원이 还要别的吗？라고 물었어요. 더 필요 없을 때 대답은?", "choices": ["我要米饭。", "好的。", "你要什么？", "不要了，谢谢。"], "answer": 3, "explain": "不要了，谢谢。는 '이제 됐어요, 고마워요.'예요."}], "summary": ["我要 + 음식: '~ 주세요.' 종업원은 服务员！으로 불러요.", "수와 음식 사이에 세는 말을 넣어요: 一个(개), 一碗(그릇), 一杯(잔). 2는 两!", "你要什么？(무엇을 드릴까요?) / 还要别的吗？(더 필요하세요?) / 不要了，谢谢。(됐어요, 고마워요.)"], "parent_tip": "우리말은 '햄버거 두 개'처럼 음식 이름이 먼저 나오지만 중국어는 '两个汉堡'처럼 수와 세는 말이 앞에 온다는 점을 아이가 헷갈립니다. 一의 성조가 yí(一个)·yì(一碗, 一杯)로 바뀌는 것은 지금은 병음을 보고 읽는 정도로 충분합니다. 집에서 식사 때 '你要什么？'로 묻고 '我要一碗米饭。'으로 답하는 식당 놀이를 해 보세요."}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','음식 주문 我要',6,'c5-06' where not exists (select 1 from public.topics where lesson_slug='c5-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-07','5~6','중국어','값 묻기 多少钱','이거 얼마예요? 중국어로 물건 사기','assets/img/l_c5-07.jpg',$j${"intro": "중국 시장에서 예쁜 판다 열쇠고리를 발견했어요! 값이 궁금할 때는 뭐라고 물어야 할까요? 오늘은 값을 묻고, 깎아 달라고 하고, 물건을 사는 말을 배워요.", "sections": [{"heading": "这个多少钱？— 이거 얼마예요?", "paras": ["这个(zhège, 저거)는 '이것', 那个(nàge, 나거)는 '저것'이에요. 多少钱(duōshao qián, 둬사오 치엔)은 '얼마예요?'라는 뜻이에요.", "그래서 물건을 가리키며 这个多少钱？(zhège duōshao qián)이라고 하면 '이거 얼마예요?'가 돼요. 멀리 있는 물건은 那个多少钱？이라고 물어요."], "example": "这个多少钱？(이거 얼마예요?) / 那个多少钱？(저거 얼마예요?)", "figure": "시장 진열대 위의 판다 열쇠고리를 손가락으로 가리키는 아이"}, {"heading": "값은 숫자 + 块(kuài)로 말해요", "paras": ["중국 돈의 단위는 위안(元, yuán)이에요. 말할 때는 元 대신 块(kuài, 콰이)를 많이 써요.", "十块钱(shí kuài qián, 스 콰이 치엔)은 '10위안이에요', 二十五块(èrshíwǔ kuài)는 '25위안'이에요. 끝의 钱은 빼고 말해도 돼요.", "2위안은 两块(liǎng kuài), 100위안은 一百块(yìbǎi kuài, 이바이 콰이)예요. 2를 셀 때 两을 쓰는 규칙, 기억나지요?"], "example": "A: 这个多少钱？  B: 十五块。(15위안이에요.)", "figure": "작은 동전과 지폐 모양 장난감 돈이 지갑 옆에 놓인 모습"}, {"heading": "비싸요! 깎아 주세요!", "paras": ["너무 비쌀 때는 太贵了！(tài guì le, 타이 꾸이 러)라고 해요. 太 ~ 了는 '너무 ~하다'예요.", "싸다는 便宜(piányi, 피엔이)예요. 很便宜。는 '아주 싸요.'이고, 便宜一点儿吧。(piányi yìdiǎnr ba, 피엔이 이디얼 바)는 '조금 싸게 해 주세요.'예요."], "example": "A: 这个三十块。  B: 太贵了！便宜一点儿吧。", "figure": "가게 주인과 아이가 웃으며 물건값을 이야기하는 시장 풍경"}, {"heading": "사기로 했다면 — 我买这个 / 一共多少钱？", "paras": ["买(mǎi, 마이)는 '사다'예요. 我买这个。(wǒ mǎi zhège, 워 마이 저거)는 '이거 살게요.'예요.", "여러 개를 샀다면 一共多少钱？(yígòng duōshao qián, 이꽁 둬사오 치엔), '모두 얼마예요?'라고 물어요. 一共은 '모두 합해서'라는 뜻이에요.", "값을 더하는 건 수학 시간처럼 하면 돼요. 연필이 五块, 공책이 八块라면 一共十三块예요."], "example": "A: 一共多少钱？  B: 一共十三块。(모두 13위안이에요.)", "figure": "연필과 공책을 계산대 위에 올려놓은 아이의 손"}], "keywords": [{"word": "多少钱 (duōshao qián)", "meaning": "얼마예요?"}, {"word": "这个 / 那个 (zhège / nàge)", "meaning": "이것 / 저것"}, {"word": "块 (kuài)", "meaning": "위안(중국 돈 단위)을 말로 할 때 쓰는 말"}, {"word": "贵 / 便宜 (guì / piányi)", "meaning": "비싸다 / 싸다"}, {"word": "一共 (yígòng)", "meaning": "모두 합해서"}], "expressions": [{"en": "这个多少钱？", "ko": "이거 얼마예요?", "note": "zhège duōshao qián (저거 둬사오 치엔)"}, {"en": "那个多少钱？", "ko": "저거 얼마예요?", "note": "nàge duōshao qián (나거 둬사오 치엔)"}, {"en": "十块钱。", "ko": "10위안이에요.", "note": "shí kuài qián (스 콰이 치엔)"}, {"en": "两块", "ko": "2위안", "note": "liǎng kuài (량 콰이)"}, {"en": "一百块", "ko": "100위안", "note": "yìbǎi kuài (이바이 콰이)"}, {"en": "太贵了！", "ko": "너무 비싸요!", "note": "tài guì le (타이 꾸이 러)"}, {"en": "很便宜。", "ko": "아주 싸요.", "note": "hěn piányi (헌 피엔이)"}, {"en": "便宜一点儿吧。", "ko": "조금 싸게 해 주세요.", "note": "piányi yìdiǎnr ba (피엔이 이디얼 바)"}, {"en": "我买这个。", "ko": "이거 살게요.", "note": "wǒ mǎi zhège (워 마이 저거)"}, {"en": "一共多少钱？", "ko": "모두 얼마예요?", "note": "yígòng duōshao qián (이꽁 둬사오 치엔)"}], "quiz": [{"q": "这个多少钱？의 뜻은?", "choices": ["이거 얼마예요?", "이거 살게요.", "이거 뭐예요?", "이거 좋아요?"], "answer": 0, "explain": "这个는 '이것', 多少钱은 '얼마예요?'예요."}, {"q": "물건이 너무 비쌀 때 하는 말은?", "choices": ["很便宜。", "我买这个。", "太贵了！", "好的。"], "answer": 2, "explain": "太贵了！(tài guì le)는 '너무 비싸요!'예요."}, {"q": "二十块는 얼마일까요?", "choices": ["12위안", "20위안", "2위안", "200위안"], "answer": 1, "explain": "二十은 20이라서 20위안이에요."}, {"q": "여러 물건을 사고 '모두 얼마예요?'라고 물을 때 알맞은 말은?", "choices": ["那个多少钱？", "便宜一点儿吧。", "我买这个。", "一共多少钱？"], "answer": 3, "explain": "一共(모두 합해서) + 多少钱(얼마)이에요."}, {"q": "便宜(piányi)의 뜻은?", "choices": ["싸다", "비싸다", "사다", "크다"], "answer": 0, "explain": "便宜는 '싸다', 贵는 '비싸다'예요."}], "summary": ["这个多少钱？(이거 얼마예요?) / 那个多少钱？(저거 얼마예요?)", "값은 숫자 + 块로 말해요: 十块(10위안), 两块(2위안), 一百块(100위안).", "太贵了！(너무 비싸요!) / 便宜一点儿吧。(싸게 해 주세요.) / 一共多少钱？(모두 얼마예요?)"], "parent_tip": "중국 돈은 위안(元)이지만 일상 회화에서는 块를 주로 쓴다는 점, 2위안은 两块라는 점을 짚어 주세요. 장난감 돈과 집안 물건에 가격표를 붙여 '这个多少钱？—○块'로 가게 놀이를 하면, 숫자 복습과 더하기 연습(一共)을 함께 할 수 있습니다."}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','값 묻기 多少钱',7,'c5-07' where not exists (select 1 from public.topics where lesson_slug='c5-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-08','5~6','중국어','장소 묻기 在哪儿','화장실은 어디예요? 중국어로 장소 묻기','assets/img/l_c5-08.jpg',$j${"intro": "낯선 곳에서 화장실이나 도서관을 찾고 싶을 때가 있지요. 그럴 때 '어디예요?'라고 물을 수 있으면 아주 든든해요. 오늘은 중국어로 장소를 묻고 위치를 말하는 법을 배워요.", "sections": [{"heading": "___在哪儿？— ~은 어디에 있어요?", "paras": ["在(zài, 짜이)는 '~에 있다', 哪儿(nǎr, 날)은 '어디'예요. 찾는 장소 뒤에 在哪儿？을 붙이면 '~은 어디에 있어요?'가 돼요.", "洗手间在哪儿？(xǐshǒujiān zài nǎr, 시서우지엔 짜이 날)은 '화장실은 어디에 있어요?'예요. 洗手间은 '화장실'이에요.", "哪儿의 儿(r)은 혀끝을 살짝 말아 올려 'ㄹ' 받침처럼 소리 내요."], "example": "洗手间在哪儿？(화장실은 어디예요?) / 学校在哪儿？(학교는 어디예요?)", "figure": "건물 복도에서 두리번거리며 길을 찾는 아이"}, {"heading": "这儿(여기)·那儿(저기)으로 대답해요", "paras": ["这儿(zhèr, 절)은 '여기', 那儿(nàr, 날)은 '저기'예요. 대답은 在 + 장소로 해요. 在那儿。(zài nàr)은 '저기에 있어요.'예요.", "哪儿(nǎr, 어디)과 那儿(nàr, 저기)은 소리가 비슷해요! 哪儿은 내렸다 올리는 3성, 那儿은 뚝 떨어지는 4성이에요. 성조를 잘 들어 보세요."], "example": "A: 洗手间在哪儿？  B: 在那儿。(저기 있어요.)", "figure": "한 아이가 손가락으로 멀리 있는 문을 가리키는 모습"}, {"heading": "앞·뒤·옆으로 자세히 말해요", "paras": ["前边(qiánbian, 치엔비엔)은 '앞', 后边(hòubian, 허우비엔)은 '뒤', 旁边(pángbiān, 팡비엔)은 '옆'이에요.", "'A는 B의 옆에 있어요'는 A + 在 + B + 旁边이라고 해요. 超市在学校旁边。(chāoshì zài xuéxiào pángbiān)은 '마트는 학교 옆에 있어요.'예요.", "우리말 '학교 옆'과 순서가 같아서 쉬워요. 기준이 되는 장소 뒤에 위치 말을 붙이면 돼요."], "example": "图书馆在医院后边。(túshūguǎn zài yīyuàn hòubian) → 도서관은 병원 뒤에 있어요.", "figure": "학교 건물 옆에 작은 가게가 있는 동네 거리 모형"}, {"heading": "장소 낱말과 우리 집", "paras": ["学校(xuéxiào, 쉐시아오) 학교, 图书馆(túshūguǎn, 투수관) 도서관, 医院(yīyuàn, 이위엔) 병원, 超市(chāoshì, 차오스) 마트예요.", "家(jiā, 지아)는 '집'이에요. 你家在哪儿？(nǐ jiā zài nǎr)은 '너희 집은 어디야?'예요. 我家在首尔。(wǒ jiā zài Shǒu'ěr, 워 지아 짜이 서우얼)는 '우리 집은 서울에 있어.'예요."], "example": "A: 你家在哪儿？  B: 我家在首尔。", "figure": "언덕 위에서 내려다본 아파트와 학교가 있는 동네 풍경"}], "keywords": [{"word": "在 (zài)", "meaning": "~에 있다"}, {"word": "哪儿 (nǎr)", "meaning": "어디 (3성)"}, {"word": "这儿 / 那儿 (zhèr / nàr)", "meaning": "여기 / 저기"}, {"word": "旁边 (pángbiān)", "meaning": "옆"}, {"word": "洗手间 (xǐshǒujiān)", "meaning": "화장실"}], "expressions": [{"en": "洗手间在哪儿？", "ko": "화장실은 어디에 있어요?", "note": "xǐshǒujiān zài nǎr (시서우지엔 짜이 날)"}, {"en": "在那儿。", "ko": "저기에 있어요.", "note": "zài nàr (짜이 날)"}, {"en": "学校在这儿。", "ko": "학교는 여기에 있어요.", "note": "xuéxiào zài zhèr (쉐시아오 짜이 절)"}, {"en": "你家在哪儿？", "ko": "너희 집은 어디야?", "note": "nǐ jiā zài nǎr (니 지아 짜이 날)"}, {"en": "我家在首尔。", "ko": "우리 집은 서울에 있어요.", "note": "wǒ jiā zài Shǒu'ěr (워 지아 짜이 서우얼)"}, {"en": "超市在学校旁边。", "ko": "마트는 학교 옆에 있어요.", "note": "chāoshì zài xuéxiào pángbiān (차오스 짜이 쉐시아오 팡비엔)"}, {"en": "图书馆在医院后边。", "ko": "도서관은 병원 뒤에 있어요.", "note": "túshūguǎn zài yīyuàn hòubian (투수관 짜이 이위엔 허우비엔)"}, {"en": "前边", "ko": "앞", "note": "qiánbian (치엔비엔)"}, {"en": "后边", "ko": "뒤", "note": "hòubian (허우비엔)"}, {"en": "旁边", "ko": "옆", "note": "pángbiān (팡비엔)"}], "quiz": [{"q": "洗手间在哪儿？의 뜻은?", "choices": ["화장실은 어디에 있어요?", "학교는 어디에 있어요?", "화장실은 저기에 있어요.", "화장실에 가요."], "answer": 0, "explain": "洗手间은 '화장실', 在哪儿은 '어디에 있어요?'예요."}, {"q": "'저기'를 뜻하는 말은?", "choices": ["哪儿 (nǎr)", "这儿 (zhèr)", "那儿 (nàr)", "旁边 (pángbiān)"], "answer": 2, "explain": "那儿(nàr, 4성)이 '저기'예요. 哪儿(nǎr, 3성)은 '어디'예요."}, {"q": "超市在学校旁边。의 뜻은?", "choices": ["마트는 학교 앞에 있어요.", "학교는 마트 옆에 있어요.", "마트는 학교 뒤에 있어요.", "마트는 학교 옆에 있어요."], "answer": 3, "explain": "A + 在 + B + 旁边은 'A는 B 옆에 있어요'예요."}, {"q": "'우리 집은 서울에 있어요.'를 바르게 쓴 것은?", "choices": ["我家在首尔。", "首尔在我家。", "我家首尔在。", "我在家首尔。"], "answer": 0, "explain": "장소 주인공(我家) + 在 + 위치(首尔) 순서예요."}, {"q": "医院(yīyuàn)은 어떤 곳일까요?", "choices": ["도서관", "병원", "마트", "학교"], "answer": 1, "explain": "医院(이위엔)은 '병원'이에요."}], "summary": ["장소 + 在哪儿？: '~은 어디에 있어요?' (哪儿 nǎr = 어디)", "这儿(zhèr) 여기, 那儿(nàr) 저기. 哪儿(3성)과 那儿(4성)은 성조로 구별해요.", "A + 在 + B + 前边/后边/旁边: 'A는 B의 앞/뒤/옆에 있어요.'"], "parent_tip": "哪儿(nǎr, 어디)과 那儿(nàr, 저기)은 성조만 다르기 때문에 아이가 자주 헷갈립니다. 손으로 3성(✓ 모양)과 4성(↘)을 그리며 구별해 보세요. 집 안 물건을 숨겨 두고 '书在哪儿？(책은 어디에 있어?)'—'在桌子旁边(책상 옆에)' 같은 보물찾기 놀이를 하면 위치 말을 재미있게 익힐 수 있습니다."}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','장소 묻기 在哪儿',8,'c5-08' where not exists (select 1 from public.topics where lesson_slug='c5-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-09','5~6','중국어','할 수 있어요 会','중국어로 ''나는 ~할 수 있어요'' 말해 볼까요?','assets/img/l_c5-09.jpg',$j${"intro": "수영, 자전거, 피아노… 여러분이 배워서 할 수 있게 된 것은 무엇인가요? 오늘은 중국어로 '할 수 있어요', '못 해요'를 말하고 친구에게 물어보는 법을 배워요.", "sections": [{"heading": "我会(wǒ huì) + 하는 일", "paras": ["会(huì, 후이)는 '(배워서) ~할 줄 알다, ~할 수 있다'예요. 我会 뒤에 하는 일을 붙이면 '나는 ~할 수 있어요'가 돼요.", "我会游泳。(wǒ huì yóuyǒng, 워 후이 여우융)은 '나는 수영할 수 있어요.'예요. 游泳은 '수영하다'예요.", "会는 연습해서 익힌 솜씨에 써요. 수영, 자전거, 악기, 외국어처럼 배워야 할 수 있는 것들이지요."], "example": "我 + 会 + 游泳 → 我会游泳。(나는 수영할 수 있어요.)", "figure": "수영장 가장자리에서 물안경을 쓰고 있는 아이"}, {"heading": "못 할 때는 不会(bú huì)", "paras": ["아직 못 하면 会 앞에 不를 붙여 不会(bú huì, 부 후이)라고 해요. 我不会游泳。는 '나는 수영을 못 해요.'예요.", "不는 원래 bù인데, 会(huì)처럼 4성 앞에서는 bú(부)로 올려 읽어요. 是 앞에서 不是(bú shì)로 읽은 것과 같은 규칙이에요."], "example": "我会骑自行车，我不会游泳。(나는 자전거는 탈 수 있지만 수영은 못 해요.)", "figure": "자전거 옆에 서 있는 아이와 물가에서 망설이는 아이"}, {"heading": "묻고 대답하기", "paras": ["'~할 수 있니?'는 你会 ~ 吗？로 물어요. 你会弹钢琴吗？(nǐ huì tán gāngqín ma, 니 후이 탄 깡친 마)는 '너 피아노 칠 줄 알아?'예요.", "대답은 짧게 会！(할 수 있어!) 또는 不会。(못 해.)라고 하면 돼요.", "'너는 무엇을 할 수 있어?'는 你会做什么？(nǐ huì zuò shénme, 니 후이 쭤 선머)예요. 做는 '하다'예요."], "example": "A: 你会弹钢琴吗？  B: 会！我会弹钢琴。", "figure": "피아노 건반 위에 올려진 아이의 두 손"}, {"heading": "'중국어 할 줄 알아요?' — 언어 말하기", "paras": ["说(shuō, 숴)는 '말하다', 汉语(Hànyǔ, 한위)는 '중국어'예요. 你会说汉语吗？는 '너 중국어 할 줄 알아?'예요.", "조금 할 수 있다면 我会说一点儿汉语。(wǒ huì shuō yìdiǎnr Hànyǔ, 워 후이 숴 이디얼 한위), '나는 중국어를 조금 할 줄 알아요.'라고 해요. 一点儿은 '조금'이에요.", "英语(Yīngyǔ, 잉위)는 영어, 韩语(Hányǔ, 한위)는 한국어예요."], "example": "A: 你会说汉语吗？  B: 我会说一点儿汉语。", "figure": "세계 지도 앞에서 친구와 이야기하는 두 아이"}], "keywords": [{"word": "会 (huì)", "meaning": "(배워서) ~할 줄 알다, ~할 수 있다"}, {"word": "不会 (bú huì)", "meaning": "~할 줄 모르다, 못 하다"}, {"word": "说 (shuō)", "meaning": "말하다"}, {"word": "汉语 (Hànyǔ)", "meaning": "중국어"}, {"word": "一点儿 (yìdiǎnr)", "meaning": "조금"}], "expressions": [{"en": "我会游泳。", "ko": "나는 수영할 수 있어요.", "note": "wǒ huì yóuyǒng (워 후이 여우융)"}, {"en": "我不会游泳。", "ko": "나는 수영을 못 해요.", "note": "wǒ bú huì yóuyǒng (워 부 후이 여우융)"}, {"en": "你会说汉语吗？", "ko": "너 중국어 할 줄 알아?", "note": "nǐ huì shuō Hànyǔ ma (니 후이 숴 한위 마)"}, {"en": "我会说一点儿汉语。", "ko": "나는 중국어를 조금 할 줄 알아요.", "note": "wǒ huì shuō yìdiǎnr Hànyǔ (워 후이 숴 이디얼 한위)"}, {"en": "你会做什么？", "ko": "너는 무엇을 할 수 있어?", "note": "nǐ huì zuò shénme (니 후이 쭤 선머)"}, {"en": "我会弹钢琴。", "ko": "나는 피아노를 칠 수 있어요.", "note": "wǒ huì tán gāngqín (워 후이 탄 깡친)"}, {"en": "我会骑自行车。", "ko": "나는 자전거를 탈 수 있어요.", "note": "wǒ huì qí zìxíngchē (워 후이 치 쯔싱처)"}, {"en": "我会踢足球。", "ko": "나는 축구를 할 수 있어요.", "note": "wǒ huì tī zúqiú (워 후이 티 쭈치우)"}, {"en": "我会画画儿。", "ko": "나는 그림을 그릴 수 있어요.", "note": "wǒ huì huà huàr (워 후이 화 활)"}, {"en": "我会说英语。", "ko": "나는 영어를 할 줄 알아요.", "note": "wǒ huì shuō Yīngyǔ (워 후이 숴 잉위)"}], "quiz": [{"q": "我会游泳。의 뜻은?", "choices": ["나는 수영을 좋아해요.", "나는 수영할 수 있어요.", "나는 수영을 못 해요.", "너는 수영할 수 있니?"], "answer": 1, "explain": "会는 '할 수 있다', 游泳은 '수영하다'예요."}, {"q": "'나는 피아노를 못 쳐요.'를 바르게 쓴 것은?", "choices": ["我会弹钢琴。", "我不喜欢弹钢琴。", "我不会弹钢琴。", "你会弹钢琴吗？"], "answer": 2, "explain": "'못 하다'는 会 앞에 不를 붙인 不会예요."}, {"q": "不会에서 不는 어떻게 읽을까요?", "choices": ["bú (부)", "bù (뿌)", "bū", "bǔ"], "answer": 0, "explain": "会(huì)가 4성이라서 앞의 不는 bú(2성)로 올려 읽어요."}, {"q": "汉语(Hànyǔ)의 뜻은?", "choices": ["한국어", "영어", "일본어", "중국어"], "answer": 3, "explain": "汉语는 '중국어'예요. 한국어는 韩语(Hányǔ)예요."}, {"q": "A: 你会骑自行车吗？ — 자전거를 탈 줄 알 때 짧은 대답은?", "choices": ["会！", "不会。", "喜欢。", "在那儿。"], "answer": 0, "explain": "会！는 '할 수 있어!'라는 짧은 대답이에요."}], "summary": ["我会 + 하는 일: '나는 ~할 수 있어요.' (배워서 익힌 솜씨)", "못 할 때는 不会(bú huì): 我不会游泳。", "你会 ~ 吗？로 묻고 会！/ 不会。로 대답해요. 我会说一点儿汉语。= 중국어 조금 해요."], "parent_tip": "会는 '배워서 할 줄 아는 능력'에 쓰는 말이라 수영·자전거·악기·외국어 같은 표현과 잘 어울립니다. 아이가 喜欢(좋아하다)과 会(할 수 있다)를 섞어 쓰기 쉬우니 '좋아하는 것'과 '할 수 있는 것'을 나눠 말해 보게 해 주세요. 가족이 돌아가며 '你会○○吗？'로 묻고 '会/不会'로 답하는 놀이를 추천합니다."}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','할 수 있어요 会',9,'c5-09' where not exists (select 1 from public.topics where lesson_slug='c5-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('c5-10','5~6','중국어','날씨 말하기','오늘 날씨 어때요? 중국어로 날씨 말하기','assets/img/l_c5-10.jpg',$j${"intro": "아침에 창밖을 보면 '오늘은 덥나? 비가 오나?' 궁금하지요. 날씨는 누구와도 나눌 수 있는 좋은 이야깃거리예요. 오늘은 중국어로 날씨를 묻고 말해 봐요.", "sections": [{"heading": "今天天气怎么样？— 오늘 날씨 어때요?", "paras": ["天气(tiānqì, 티엔치)는 '날씨', 怎么样(zěnmeyàng, 쩐머양)은 '어때요?'예요.", "그래서 今天天气怎么样？(jīntiān tiānqì zěnmeyàng, 진티엔 티엔치 쩐머양)은 '오늘 날씨 어때요?'예요. 明天(내일)을 넣으면 내일 날씨도 물을 수 있어요."], "example": "今天天气怎么样？(오늘 날씨 어때?) / 明天天气怎么样？(내일 날씨 어때?)", "figure": "창문 밖 하늘을 바라보는 아이의 뒷모습"}, {"heading": "덥다·춥다는 很(hěn) + 날씨 말", "paras": ["热(rè, 러)는 '덥다', 冷(lěng, 렁)은 '춥다'예요. 날씨를 말할 때는 앞에 很(hěn)을 붙여 今天很热。(오늘은 더워요.), 今天很冷。(오늘은 추워요.)이라고 해요.", "조심! '덥다, 춥다' 같은 말 앞에는 是를 쓰지 않아요. 今天是热。가 아니라 今天很热。예요. 이때 很은 '아주'라는 뜻이 약해서 그냥 '더워요'로 생각하면 돼요.", "凉快(liángkuai, 량콰이)는 '시원하다', 暖和(nuǎnhuo, 놘훠)는 '따뜻하다'예요."], "example": "今天很热。(오늘은 더워요.) / 今天很冷。(오늘은 추워요.) / 今天很凉快。(오늘은 시원해요.)", "figure": "한쪽은 반팔에 부채, 다른 쪽은 목도리와 장갑을 낀 아이 그림"}, {"heading": "비·눈·바람 — 下雨了, 下雪了, 刮风了", "paras": ["下雨了(xià yǔ le, 시아 위 러)는 '비가 와요', 下雪了(xià xuě le, 시아 쉐 러)는 '눈이 와요', 刮风了(guā fēng le, 꽈 펑 러)는 '바람이 불어요'예요.", "끝의 了(le)는 '이제 막 그렇게 됐다'는 느낌을 더해요. 창밖을 보다가 '어, 비 온다!' 할 때 딱 맞는 말이에요.", "맑은 날은 晴天(qíngtiān, 칭티엔), 흐린 날은 阴天(yīntiān, 인티엔)이에요. 이건 '날'이라는 이름이라 今天是晴天。(오늘은 맑은 날이에요.)처럼 是를 써요."], "example": "A: 今天天气怎么样？  B: 下雨了。(비가 와.)", "figure": "창문 유리에 빗방울이 맺히고 우산이 옆에 세워진 모습"}, {"heading": "계절 날씨도 말해요", "paras": ["春天(chūntiān, 춘티엔) 봄, 夏天(xiàtiān, 시아티엔) 여름, 秋天(qiūtiān, 치우티엔) 가을, 冬天(dōngtiān, 똥티엔) 겨울이에요.", "夏天很热，冬天很冷。은 '여름은 덥고, 겨울은 추워요.'예요. 春天很暖和。(봄은 따뜻해요.) 秋天很凉快。(가을은 시원해요.)도 말해 보세요."], "example": "春天很暖和。/ 夏天很热。/ 秋天很凉快。/ 冬天很冷。", "figure": "벚꽃, 수박, 단풍잎, 눈사람이 네 칸에 나뉘어 놓인 계절 그림"}], "keywords": [{"word": "天气 (tiānqì)", "meaning": "날씨"}, {"word": "怎么样 (zěnmeyàng)", "meaning": "어때요?"}, {"word": "热 / 冷 (rè / lěng)", "meaning": "덥다 / 춥다"}, {"word": "下雨 / 下雪 (xià yǔ / xià xuě)", "meaning": "비가 오다 / 눈이 오다"}, {"word": "很 (hěn)", "meaning": "날씨 말 앞에 붙이는 말 (是 대신)"}], "expressions": [{"en": "今天天气怎么样？", "ko": "오늘 날씨 어때요?", "note": "jīntiān tiānqì zěnmeyàng (진티엔 티엔치 쩐머양)"}, {"en": "今天很热。", "ko": "오늘은 더워요.", "note": "jīntiān hěn rè (진티엔 헌 러)"}, {"en": "今天很冷。", "ko": "오늘은 추워요.", "note": "jīntiān hěn lěng (진티엔 헌 렁)"}, {"en": "下雨了。", "ko": "비가 와요.", "note": "xià yǔ le (시아 위 러)"}, {"en": "下雪了。", "ko": "눈이 와요.", "note": "xià xuě le (시아 쉐 러)"}, {"en": "刮风了。", "ko": "바람이 불어요.", "note": "guā fēng le (꽈 펑 러)"}, {"en": "今天是晴天。", "ko": "오늘은 맑은 날이에요.", "note": "jīntiān shì qíngtiān (진티엔 스 칭티엔)"}, {"en": "春天很暖和。", "ko": "봄은 따뜻해요.", "note": "chūntiān hěn nuǎnhuo (춘티엔 헌 놘훠)"}, {"en": "秋天很凉快。", "ko": "가을은 시원해요.", "note": "qiūtiān hěn liángkuai (치우티엔 헌 량콰이)"}, {"en": "明天下雨吗？", "ko": "내일 비가 와요?", "note": "míngtiān xià yǔ ma (밍티엔 시아 위 마)"}], "quiz": [{"q": "今天天气怎么样？의 뜻은?", "choices": ["오늘 날씨 어때요?", "오늘은 무슨 요일이에요?", "오늘은 몇 월 며칠이에요?", "지금 몇 시예요?"], "answer": 0, "explain": "天气는 '날씨', 怎么样은 '어때요?'예요."}, {"q": "'오늘은 추워요.'를 바르게 쓴 것은?", "choices": ["今天是冷。", "今天很热。", "今天很冷。", "今天冷很。"], "answer": 2, "explain": "춥다는 冷이고, 是 대신 很을 앞에 붙여요."}, {"q": "下雪了。의 뜻은?", "choices": ["비가 와요.", "바람이 불어요.", "맑아요.", "눈이 와요."], "answer": 3, "explain": "雪(xuě)는 '눈'이라서 下雪了는 '눈이 와요'예요."}, {"q": "夏天(xiàtiān)은 어느 계절일까요?", "choices": ["봄", "여름", "가을", "겨울"], "answer": 1, "explain": "春天 봄, 夏天 여름, 秋天 가을, 冬天 겨울이에요."}, {"q": "가을 날씨를 알맞게 말한 것은?", "choices": ["秋天很凉快。", "秋天下雪了。", "秋天是热。", "秋天很冷很热。"], "answer": 0, "explain": "秋天很凉快。는 '가을은 시원해요.'예요."}], "summary": ["今天天气怎么样？로 날씨를 물어요.", "덥다·춥다는 很 + 热/冷: 今天很热。(是는 쓰지 않아요!)", "下雨了(비), 下雪了(눈), 刮风了(바람), 晴天(맑은 날) / 계절: 春天·夏天·秋天·冬天"], "parent_tip": "'今天是热'처럼 형용사 앞에 是를 넣는 것이 가장 흔한 실수입니다. 날씨·기분을 나타내는 말 앞에는 是 대신 很을 쓴다고 짚어 주세요. 매일 아침 창밖을 보며 '今天天气怎么样？'라고 묻고 아이가 '今天很冷。/ 下雨了。'로 답하게 하면 자연스럽게 입에 붙습니다."}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','중국어','날씨 말하기',10,'c5-10' where not exists (select 1 from public.topics where lesson_slug='c5-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-01','1~2','영어','1단계 · 알파벳 A~M','A부터 M까지, 알파벳 친구를 만나 볼까?','assets/img/l_e1-01.jpg',$j${"intro": "영어에는 글자가 26개 있어요. 🔤 오늘은 앞의 13개를 만나요.", "sections": [{"heading": "알파벳은 영어 글자예요", "paras": ["알파벳은 영어 글자예요.", "모두 26개가 있어요.", "오늘은 A부터 M까지 배워요."], "example": "A B C D E F G H I J K L M", "figure": "책상 위에 A부터 M까지 차례로 놓인 나무 알파벳 블록"}, {"heading": "A부터 G까지 이름을 불러요", "paras": ["글자마다 이름이 있어요.", "A는 '에이'라고 불러요.", "🍎 apple은 A로 시작해요."], "example": "A 에이 · B 비 · C 씨 · D 디 · E 이 · F 에프 · G 지", "figure": "사과, 곰 인형, 고양이 인형이 나란히 놓인 책상"}, {"heading": "H부터 M까지 이름을 불러요", "paras": ["H는 '에이치'예요.", "🦁 lion은 L로 시작해요.", "🌙 moon은 M으로 시작해요."], "example": "H 에이치 · I 아이 · J 제이 · K 케이 · L 엘 · M 엠", "figure": "아이 손이 알파벳 카드를 한 장씩 집는 모습"}, {"heading": "노래로 외워요", "paras": ["알파벳 노래를 불러요. 🎵", "손가락으로 짚으며 불러요.", "차례를 쉽게 외울 수 있어요."], "example": "A B C D E F G, H I J K L M", "figure": "아이가 손가락으로 알파벳 카드 줄을 짚으며 노래하는 모습"}], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자. 모두 26개예요."}, {"word": "글자 이름", "meaning": "글자를 부르는 말. A는 '에이'예요."}, {"word": "차례", "meaning": "A, B, C처럼 글자가 놓이는 순서"}], "expressions": [{"en": "A", "ko": "에이", "note": "🍎 apple 의 첫 글자"}, {"en": "B", "ko": "비", "note": "🐻 bear 의 첫 글자"}, {"en": "C", "ko": "씨", "note": "🐱 cat 의 첫 글자"}, {"en": "D", "ko": "디", "note": "🐶 dog 의 첫 글자"}, {"en": "E", "ko": "이", "note": "🥚 egg 의 첫 글자"}, {"en": "F", "ko": "에프", "note": "🐟 fish 의 첫 글자"}, {"en": "G", "ko": "지", "note": "🍇 grapes 의 첫 글자"}, {"en": "H", "ko": "에이치", "note": "🎩 hat 의 첫 글자"}, {"en": "I", "ko": "아이", "note": "🍦 ice cream 의 첫 글자"}, {"en": "J", "ko": "제이", "note": "🧃 juice 의 첫 글자"}, {"en": "K", "ko": "케이", "note": "🪁 kite 의 첫 글자"}, {"en": "L, M", "ko": "엘, 엠", "note": "🦁 lion, 🌙 moon 의 첫 글자"}], "quiz": [{"q": "🍎 apple은 어떤 글자로 시작할까요?", "choices": ["B", "A", "C", "D"], "answer": 1, "explain": "apple은 A(에이)로 시작해요."}, {"q": "A 다음에 오는 글자는?", "choices": ["C", "D", "B", "M"], "answer": 2, "explain": "A, B, C 차례예요. A 다음은 B예요."}, {"q": "'엠'이라고 부르는 글자는?", "choices": ["M", "N", "H", "K"], "answer": 0, "explain": "M의 이름은 '엠'이에요. 🌙 moon의 첫 글자예요."}, {"q": "알파벳은 모두 몇 개일까요?", "choices": ["13개", "20개", "10개", "26개"], "answer": 3, "explain": "알파벳은 A부터 Z까지 26개예요. 오늘은 그중 13개를 배웠어요."}, {"q": "K 바로 앞 글자는?", "choices": ["L", "J", "I", "M"], "answer": 1, "explain": "I, J, K, L 차례예요. K 바로 앞은 J예요."}], "summary": ["알파벳은 영어 글자이고 26개예요.", "A부터 M까지 13개 글자의 이름을 배웠어요.", "노래로 부르면 차례를 쉽게 외워요."], "parent_tip": "이 단계에서는 글자 '이름'만 익히고, 글자 '소리'(파닉스)는 다음 단원에서 다룹니다. 알파벳 카드를 섞어 놓고 '에이 찾아볼까?'처럼 놀이로 한 글자씩 찾게 하시면 좋습니다. G(지)와 J(제이), I(아이)와 E(이)를 아이들이 자주 헷갈립니다.", "narr": {"cover": "assets/audio/n/e1-01_cover.mp3", "s0": "assets/audio/n/e1-01_s0.mp3", "s1": "assets/audio/n/e1-01_s1.mp3", "s2": "assets/audio/n/e1-01_s2.mp3", "s3": "assets/audio/n/e1-01_s3.mp3", "kw": "assets/audio/n/e1-01_kw.mp3", "q0": "assets/audio/n/e1-01_q0.mp3", "q1": "assets/audio/n/e1-01_q1.mp3", "q2": "assets/audio/n/e1-01_q2.mp3", "q3": "assets/audio/n/e1-01_q3.mp3", "q4": "assets/audio/n/e1-01_q4.mp3", "sum": "assets/audio/n/e1-01_sum.mp3"}}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','1단계 · 알파벳 A~M',1,'e1-01' where not exists (select 1 from public.topics where lesson_slug='e1-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-02','1~2','영어','1단계 · 알파벳 N~Z','N부터 Z까지, 알파벳 끝까지 가 볼까?','assets/img/l_e1-02.jpg',$j${"intro": "지난번에 A부터 M까지 배웠어요. 🔤 오늘은 나머지 13개를 만나요.", "sections": [{"heading": "알파벳 뒷부분이에요", "paras": ["M 다음은 N이에요.", "N부터 Z까지 13개예요.", "Z가 맨 마지막 글자예요."], "example": "N O P Q R S T U V W X Y Z", "figure": "책상 위에 N부터 Z까지 차례로 놓인 나무 알파벳 블록"}, {"heading": "N부터 T까지 이름을 불러요", "paras": ["R은 '알'이라고 불러요.", "🐷 pig는 P로 시작해요.", "☀️ sun은 S로 시작해요."], "example": "N 엔 · O 오 · P 피 · Q 큐 · R 알 · S 에스 · T 티", "figure": "돼지 인형과 호랑이 인형이 놓인 아이 책상"}, {"heading": "U부터 Z까지 이름을 불러요", "paras": ["W는 '더블유'예요. 이름이 길어요.", "🦓 zebra는 Z로 시작해요.", "X는 🦊 fox 끝에 있어요."], "example": "U 유 · V 브이 · W 더블유 · X 엑스 · Y 와이 · Z 지", "figure": "우산, 요요, 얼룩말 인형이 나란히 놓인 모습"}, {"heading": "A부터 Z까지 이어 불러요", "paras": ["알파벳 노래를 끝까지 불러요. 🎵", "LMNOP는 빨리 지나가요.", "천천히 한 글자씩 짚어요."], "example": "Q R S, T U V, W X, Y and Z", "figure": "아이가 바닥에 26개 알파벳 카드를 한 줄로 늘어놓은 모습"}], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자 26개"}, {"word": "마지막 글자", "meaning": "알파벳 맨 끝 글자 Z"}, {"word": "알파벳 노래", "meaning": "26개 글자를 차례대로 부르는 노래"}], "expressions": [{"en": "N", "ko": "엔", "note": "👃 nose 의 첫 글자"}, {"en": "O", "ko": "오", "note": "🐙 octopus 의 첫 글자"}, {"en": "P", "ko": "피", "note": "🐷 pig 의 첫 글자"}, {"en": "Q", "ko": "큐", "note": "👸 queen 의 첫 글자"}, {"en": "R", "ko": "알", "note": "🐰 rabbit 의 첫 글자"}, {"en": "S", "ko": "에스", "note": "☀️ sun 의 첫 글자"}, {"en": "T", "ko": "티", "note": "🐯 tiger 의 첫 글자"}, {"en": "U", "ko": "유", "note": "☂️ umbrella 의 첫 글자"}, {"en": "V", "ko": "브이", "note": "🎻 violin 의 첫 글자"}, {"en": "W", "ko": "더블유", "note": "⌚ watch 의 첫 글자"}, {"en": "X", "ko": "엑스", "note": "🦊 fox 의 끝 글자"}, {"en": "Y, Z", "ko": "와이, 지", "note": "🪀 yo-yo, 🦓 zebra 의 첫 글자"}], "quiz": [{"q": "🐷 pig는 어떤 글자로 시작할까요?", "choices": ["B", "D", "P", "Q"], "answer": 2, "explain": "pig는 P(피)로 시작해요."}, {"q": "Z 바로 앞 글자는?", "choices": ["Y", "X", "W", "V"], "answer": 0, "explain": "X, Y, Z 차례예요. Z 바로 앞은 Y예요."}, {"q": "'더블유'라고 부르는 글자는?", "choices": ["V", "M", "N", "W"], "answer": 3, "explain": "W의 이름은 '더블유'예요."}, {"q": "N 다음에 오는 글자는?", "choices": ["M", "O", "P", "Q"], "answer": 1, "explain": "M, N, O 차례예요. N 다음은 O예요."}, {"q": "알파벳 맨 마지막 글자는?", "choices": ["A", "X", "Z", "Y"], "answer": 2, "explain": "알파벳은 A로 시작해서 Z로 끝나요."}], "summary": ["N부터 Z까지 13개 글자를 배웠어요.", "R은 '알', W는 '더블유'라고 불러요.", "Z가 알파벳 맨 마지막 글자예요."], "parent_tip": "알파벳 노래에서 L-M-N-O-P를 한 덩어리 'elemeno'처럼 부르는 아이가 많으니 천천히 짚으며 불러 주세요. Z는 미국식 '지', 영국식 '제드'로 부르며 둘 다 맞습니다. A~M 카드와 합쳐 26장을 차례대로 늘어놓는 놀이를 해 보세요.", "narr": {"cover": "assets/audio/n/e1-02_cover.mp3", "s0": "assets/audio/n/e1-02_s0.mp3", "s1": "assets/audio/n/e1-02_s1.mp3", "s2": "assets/audio/n/e1-02_s2.mp3", "s3": "assets/audio/n/e1-02_s3.mp3", "kw": "assets/audio/n/e1-02_kw.mp3", "q0": "assets/audio/n/e1-02_q0.mp3", "q1": "assets/audio/n/e1-02_q1.mp3", "q2": "assets/audio/n/e1-02_q2.mp3", "q3": "assets/audio/n/e1-02_q3.mp3", "q4": "assets/audio/n/e1-02_q4.mp3", "sum": "assets/audio/n/e1-02_sum.mp3"}}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','1단계 · 알파벳 N~Z',2,'e1-02' where not exists (select 1 from public.topics where lesson_slug='e1-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-03','1~2','영어','1단계 · 대문자와 소문자','큰 글자 A와 작은 글자 a는 같은 친구일까?','assets/img/l_e1-03.jpg',$j${"intro": "알파벳은 모양이 두 가지예요. 🔠 큰 글자와 🔡 작은 글자를 만나요.", "sections": [{"heading": "글자마다 두 모양이 있어요", "paras": ["큰 글자는 대문자예요.", "작은 글자는 소문자예요.", "A와 a는 이름이 같아요. 둘 다 '에이'!"], "example": "A a · B b · C c · D d", "figure": "큰 나무 블록과 작은 나무 블록이 짝지어 놓인 책상"}, {"heading": "모양이 닮은 짝", "paras": ["크기만 다른 짝이 있어요.", "C와 c는 둘 다 동그라미 반쪽이에요. 🌙", "O와 o는 둘 다 동그라미예요. ⭕"], "example": "C c · O o · S s · U u · V v · W w · X x · Z z", "figure": "큰 공과 작은 공이 나란히 놓인 모습"}, {"heading": "모양이 다른 짝", "paras": ["모양이 많이 다른 짝도 있어요.", "이런 짝은 눈으로 자주 봐요. 👀"], "example": "A a · B b · D d · E e · G g · Q q · R r", "figure": "아이 손이 큰 글자 카드와 작은 글자 카드를 짝 맞추는 모습"}, {"heading": "헷갈리는 b와 d", "paras": ["b는 막대 오른쪽에 배가 있어요.", "d는 막대 왼쪽에 배가 있어요.", "p와 q도 조심해요."], "example": "b - 🐻 bear · d - 🐶 dog", "figure": "곰 인형과 강아지 인형이 마주 보고 앉은 모습"}], "keywords": [{"word": "대문자", "meaning": "알파벳의 큰 글자 (A, B, C)"}, {"word": "소문자", "meaning": "알파벳의 작은 글자 (a, b, c)"}, {"word": "짝", "meaning": "이름이 같은 대문자와 소문자 (A와 a)"}], "expressions": [{"en": "A a", "ko": "에이 (대문자 A, 소문자 a)", "note": "모양이 달라요"}, {"en": "B b", "ko": "비", "note": "b는 배가 오른쪽"}, {"en": "D d", "ko": "디", "note": "d는 배가 왼쪽"}, {"en": "E e", "ko": "이", "note": "모양이 달라요"}, {"en": "G g", "ko": "지", "note": "모양이 달라요"}, {"en": "Q q", "ko": "큐", "note": "q는 꼬리가 오른쪽 아래"}, {"en": "R r", "ko": "알", "note": "모양이 달라요"}, {"en": "C c", "ko": "씨", "note": "크기만 달라요"}, {"en": "O o", "ko": "오", "note": "크기만 달라요"}, {"en": "b - bear", "ko": "🐻 곰", "note": "b로 시작해요"}, {"en": "d - dog", "ko": "🐶 개", "note": "d로 시작해요"}], "quiz": [{"q": "대문자 B의 소문자는?", "choices": ["d", "b", "p", "q"], "answer": 1, "explain": "B의 짝은 b예요. 막대 오른쪽에 배가 있어요."}, {"q": "소문자 g의 대문자는?", "choices": ["Q", "C", "G", "J"], "answer": 2, "explain": "g의 짝은 G예요. 둘 다 '지'라고 불러요."}, {"q": "크기만 다르고 모양이 같은 짝은?", "choices": ["A a", "R r", "O o", "E e"], "answer": 2, "explain": "O와 o는 둘 다 동그라미예요."}, {"q": "🐶 dog의 첫 글자(소문자)는?", "choices": ["b", "p", "q", "d"], "answer": 3, "explain": "dog은 d로 시작해요. 배가 왼쪽에 있어요."}, {"q": "대문자와 소문자의 이름은 어떨까요?", "choices": ["같아요", "달라요", "대문자만 이름이 있어요", "소문자만 이름이 있어요"], "answer": 0, "explain": "A와 a는 둘 다 '에이'예요. 이름이 같아요."}], "summary": ["알파벳은 대문자와 소문자가 있어요.", "대문자와 소문자는 이름이 같아요.", "b와 d, p와 q는 방향을 잘 봐요."], "parent_tip": "b/d, p/q 좌우 바뀜은 이 나이에 매우 흔하며 시간이 지나면 대부분 자연스럽게 고쳐집니다. 'bed' 글자를 침대 모양(b 머리판, d 발판)으로 보여 주면 기억에 도움이 됩니다. 대문자 카드와 소문자 카드를 섞어 짝 맞추기 놀이를 해 보세요.", "narr": {"cover": "assets/audio/n/e1-03_cover.mp3", "s0": "assets/audio/n/e1-03_s0.mp3", "s1": "assets/audio/n/e1-03_s1.mp3", "s2": "assets/audio/n/e1-03_s2.mp3", "s3": "assets/audio/n/e1-03_s3.mp3", "kw": "assets/audio/n/e1-03_kw.mp3", "q0": "assets/audio/n/e1-03_q0.mp3", "q1": "assets/audio/n/e1-03_q1.mp3", "q2": "assets/audio/n/e1-03_q2.mp3", "q3": "assets/audio/n/e1-03_q3.mp3", "q4": "assets/audio/n/e1-03_q4.mp3", "sum": "assets/audio/n/e1-03_sum.mp3"}}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','1단계 · 대문자와 소문자',3,'e1-03' where not exists (select 1 from public.topics where lesson_slug='e1-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-04','1~2','영어','1단계 · 글자 소리 a~m (파닉스)','글자는 어떤 소리를 낼까? a부터 m까지','assets/img/l_e1-04.jpg',$j${"intro": "글자에는 이름도 있고 소리도 있어요. 👂 오늘은 a부터 m까지 소리를 들어 봐요.", "sections": [{"heading": "이름과 소리는 달라요", "paras": ["a의 이름은 '에이'예요.", "🍎 apple에서는 '애' 소리가 나요.", "이걸 글자 소리라고 해요."], "example": "a - apple · b - bear", "figure": "책상 위의 빨간 사과와 곰 인형"}, {"heading": "a부터 f까지 소리", "paras": ["낱말 첫소리를 잘 들어요.", "🐱 cat은 '크' 소리로 시작해요.", "🐟 fish는 윗니로 아랫입술을 살짝 물어요."], "example": "a - apple · b - bear · c - cat · d - dog · e - egg · f - fish", "figure": "사과, 곰 인형, 달걀, 물고기 장난감이 한 줄로 놓인 모습"}, {"heading": "g부터 m까지 소리", "paras": ["🎩 hat은 숨을 '흐' 내쉬어요.", "🦁 lion은 혀끝을 윗니 뒤에 대요.", "🌙 moon은 입을 다물고 '음' 해요."], "example": "g - grapes · h - hat · i - insect · j - juice · k - kite · l - lion · m - moon", "figure": "포도, 모자, 주스 팩, 연이 놓인 아이 방 바닥"}, {"heading": "c와 k는 같은 소리", "paras": ["🐱 cat과 🪁 kite는 둘 다 '크' 소리예요.", "글자는 달라도 소리가 같아요."], "example": "c - cat · k - kite", "figure": "고양이 인형 옆에 놓인 작은 연"}], "keywords": [{"word": "글자 소리", "meaning": "낱말 속에서 글자가 내는 소리 (apple의 a는 '애')"}, {"word": "첫소리", "meaning": "낱말을 말할 때 맨 처음 나는 소리"}, {"word": "파닉스", "meaning": "글자와 소리를 짝지어 배우는 방법"}], "expressions": [{"en": "a - apple", "ko": "🍎 사과", "note": "'애' 소리로 시작"}, {"en": "b - bear", "ko": "🐻 곰", "note": "입술을 붙였다 떼며 '브'"}, {"en": "c - cat", "ko": "🐱 고양이", "note": "'크' 소리"}, {"en": "d - dog", "ko": "🐶 개", "note": "'드' 소리"}, {"en": "e - egg", "ko": "🥚 달걀", "note": "'에' 소리"}, {"en": "f - fish", "ko": "🐟 물고기", "note": "윗니로 아랫입술을 물고 '프'"}, {"en": "g - grapes", "ko": "🍇 포도", "note": "목에서 '그'"}, {"en": "h - hat", "ko": "🎩 모자", "note": "숨을 내쉬며 '흐'"}, {"en": "i - insect", "ko": "🐛 곤충", "note": "짧게 '이'"}, {"en": "j - juice", "ko": "🧃 주스", "note": "'즈' 소리"}, {"en": "k - kite", "ko": "🪁 연", "note": "'크' 소리 (c와 같아요)"}, {"en": "l - lion, m - moon", "ko": "🦁 사자, 🌙 달", "note": "l은 혀끝을 윗니 뒤에, m은 입을 다물고 '음'"}], "quiz": [{"q": "🍎 apple의 첫소리를 내는 글자는?", "choices": ["e", "a", "i", "o"], "answer": 1, "explain": "apple은 a로 시작해요. '애' 소리가 나요."}, {"q": "🐶 dog은 어떤 글자 소리로 시작할까요?", "choices": ["g", "b", "h", "d"], "answer": 3, "explain": "dog은 '드' 소리, d로 시작해요."}, {"q": "🌙 moon과 첫소리가 같은 낱말은?", "choices": ["🦁 lion", "🎩 hat", "🐵 monkey", "🥚 egg"], "answer": 2, "explain": "moon과 monkey는 둘 다 m '음' 소리로 시작해요."}, {"q": "🐱 cat과 첫소리가 같은 낱말은?", "choices": ["🪁 kite", "🐟 fish", "🍇 grapes", "🧃 juice"], "answer": 0, "explain": "cat의 c와 kite의 k는 둘 다 '크' 소리예요."}, {"q": "글자 a에 대해 맞는 말은?", "choices": ["이름과 소리가 늘 같아요", "이름은 '에이', apple에서는 '애' 소리예요", "a는 소리가 없어요", "a는 '음' 소리가 나요"], "answer": 1, "explain": "글자 이름과 낱말 속 소리는 다를 수 있어요."}], "summary": ["글자에는 이름과 소리가 있어요.", "a부터 m까지 낱말 첫소리를 들어 봤어요.", "c와 k는 둘 다 '크' 소리가 나요."], "parent_tip": "한글로 적은 소리('크', '브')는 어디까지나 비슷한 소리이니 듣기 버튼으로 실제 소리를 꼭 들려주세요. 특히 '브', '드'처럼 뒤에 '으'를 길게 붙이지 않고 짧게 끊어 내는 것이 중요합니다. 집 안 물건을 가리키며 '이건 무슨 소리로 시작할까?' 하고 물어보세요.", "narr": {"cover": "assets/audio/n/e1-04_cover.mp3", "s0": "assets/audio/n/e1-04_s0.mp3", "s1": "assets/audio/n/e1-04_s1.mp3", "s2": "assets/audio/n/e1-04_s2.mp3", "s3": "assets/audio/n/e1-04_s3.mp3", "kw": "assets/audio/n/e1-04_kw.mp3", "q0": "assets/audio/n/e1-04_q0.mp3", "q1": "assets/audio/n/e1-04_q1.mp3", "q2": "assets/audio/n/e1-04_q2.mp3", "q3": "assets/audio/n/e1-04_q3.mp3", "q4": "assets/audio/n/e1-04_q4.mp3", "sum": "assets/audio/n/e1-04_sum.mp3"}}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','1단계 · 글자 소리 a~m (파닉스)',4,'e1-04' where not exists (select 1 from public.topics where lesson_slug='e1-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-05','1~2','영어','1단계 · 글자 소리 n~z (파닉스)','n부터 z까지, 글자 소리를 들어 볼까?','assets/img/l_e1-05.jpg',$j${"intro": "지난번에 a부터 m까지 소리를 배웠어요. 👂 오늘은 n부터 z까지 소리를 들어 봐요.", "sections": [{"heading": "n부터 r까지 소리", "paras": ["👃 nose는 콧소리 '은'으로 시작해요.", "🐷 pig는 입술을 붙였다 '프' 터뜨려요.", "q는 늘 u와 함께 다녀요. 👸 queen!"], "example": "n - nose · o - octopus · p - pig · q - queen · r - rabbit", "figure": "돼지 인형과 토끼 인형이 나란히 앉은 책상"}, {"heading": "s부터 v까지 소리", "paras": ["☀️ sun은 뱀 소리 '스'로 시작해요. 🐍", "☂️ umbrella는 짧게 '어' 해요.", "🎻 violin은 윗니로 아랫입술을 물어요."], "example": "s - sun · t - tiger · u - umbrella · v - violin", "figure": "노란 우산과 장난감 바이올린이 놓인 아이 방"}, {"heading": "w부터 z까지 소리", "paras": ["⌚ watch는 입술을 동그랗게 '우' 해요.", "x는 🦊 fox처럼 끝에서 '크스' 소리가 나요.", "🦓 zebra는 벌 소리 '즈'로 시작해요. 🐝"], "example": "w - watch · x - fox · y - yo-yo · z - zebra", "figure": "요요와 얼룩말 인형, 여우 인형이 놓인 책상"}, {"heading": "헷갈리는 소리 짝", "paras": ["v와 b는 달라요.", "v는 윗니가 입술에 닿고, b는 두 입술이 붙어요.", "s는 바람 소리, z는 벌 소리예요."], "example": "v - violin · b - bear · s - sun · z - zebra", "figure": "아이가 거울 앞에서 입 모양을 보는 모습"}], "keywords": [{"word": "첫소리", "meaning": "낱말을 말할 때 맨 처음 나는 소리"}, {"word": "끝소리", "meaning": "낱말 맨 끝에서 나는 소리 (fox의 x)"}, {"word": "입 모양", "meaning": "소리를 낼 때 입술·이·혀의 모양"}], "expressions": [{"en": "n - nose", "ko": "👃 코", "note": "콧소리 '은'"}, {"en": "o - octopus", "ko": "🐙 문어", "note": "입을 크게 벌려 '아'"}, {"en": "p - pig", "ko": "🐷 돼지", "note": "입술을 붙였다 '프' 터뜨려요"}, {"en": "q - queen", "ko": "👸 여왕", "note": "qu는 '크우' 소리"}, {"en": "r - rabbit", "ko": "🐰 토끼", "note": "입술을 동그랗게 '루'"}, {"en": "s - sun", "ko": "☀️ 해", "note": "뱀 소리 '스'"}, {"en": "t - tiger", "ko": "🐯 호랑이", "note": "'트' 소리"}, {"en": "u - umbrella", "ko": "☂️ 우산", "note": "짧게 '어'"}, {"en": "v - violin", "ko": "🎻 바이올린", "note": "윗니로 아랫입술을 물고 '브'"}, {"en": "w - watch", "ko": "⌚ 손목시계", "note": "입술을 동그랗게 '우'"}, {"en": "x - fox", "ko": "🦊 여우", "note": "x는 끝에서 '크스'"}, {"en": "y - yo-yo, z - zebra", "ko": "🪀 요요, 🦓 얼룩말", "note": "y는 '이으', z는 벌 소리 '즈'"}], "quiz": [{"q": "🐷 pig의 첫소리 글자는?", "choices": ["b", "p", "q", "d"], "answer": 1, "explain": "pig는 입술을 터뜨리는 '프' 소리, p로 시작해요."}, {"q": "☀️ sun과 첫소리가 같은 낱말은?", "choices": ["🐍 snake", "🦓 zebra", "🐯 tiger", "🐙 octopus"], "answer": 0, "explain": "sun과 snake는 둘 다 s '스' 소리로 시작해요."}, {"q": "🦊 fox에서 x 소리는 어디에 있을까요?", "choices": ["맨 앞", "가운데", "맨 끝", "없어요"], "answer": 2, "explain": "fox는 f-o-x예요. x는 맨 끝에서 '크스' 소리가 나요."}, {"q": "윗니로 아랫입술을 살짝 물고 내는 소리는?", "choices": ["🐷 pig의 p", "🐰 rabbit의 r", "🐯 tiger의 t", "🎻 violin의 v"], "answer": 3, "explain": "v는 윗니가 아랫입술에 닿아요."}, {"q": "☂️ umbrella의 첫 글자는?", "choices": ["a", "o", "u", "e"], "answer": 2, "explain": "umbrella는 짧은 '어' 소리, u로 시작해요."}], "summary": ["n부터 z까지 낱말 첫소리를 들어 봤어요.", "x는 fox처럼 낱말 끝에서 자주 소리 나요.", "v와 b, s와 z는 입 모양으로 구별해요."], "parent_tip": "r과 l, v와 b, f와 p는 우리말에 없는 구별이라 아이들이 어려워합니다. 거울 앞에서 입 모양(윗니가 입술에 닿는지)을 함께 보며 연습하면 좋습니다. 한글로 적은 소리는 참고용이니 듣기 버튼으로 실제 소리를 꼭 들려주세요.", "narr": {"cover": "assets/audio/n/e1-05_cover.mp3", "s0": "assets/audio/n/e1-05_s0.mp3", "s1": "assets/audio/n/e1-05_s1.mp3", "s2": "assets/audio/n/e1-05_s2.mp3", "s3": "assets/audio/n/e1-05_s3.mp3", "kw": "assets/audio/n/e1-05_kw.mp3", "q0": "assets/audio/n/e1-05_q0.mp3", "q1": "assets/audio/n/e1-05_q1.mp3", "q2": "assets/audio/n/e1-05_q2.mp3", "q3": "assets/audio/n/e1-05_q3.mp3", "q4": "assets/audio/n/e1-05_q4.mp3", "sum": "assets/audio/n/e1-05_sum.mp3"}}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','1단계 · 글자 소리 n~z (파닉스)',5,'e1-05' where not exists (select 1 from public.topics where lesson_slug='e1-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-06','1~2','영어','2단계 · 짧은 모음 낱말 (cat, dog)','c-a-t, 소리를 이으면 어떤 낱말이 될까?','assets/img/l_e1-06.jpg',$j${"intro": "글자 소리를 알면 낱말을 읽을 수 있어요. 🐱 소리를 이어서 cat을 읽어 봐요.", "sections": [{"heading": "소리를 이어 읽어요", "paras": ["글자 소리를 하나씩 내요.", "c, a, t → '크, 애, 트'.", "빨리 이으면 cat! 🐱"], "example": "c + a + t = cat · d + o + g = dog", "figure": "아이 손가락이 나무 글자 블록 세 개를 차례로 짚는 모습"}, {"heading": "가운데 모음이 중요해요", "paras": ["a e i o u 는 모음이에요.", "세 글자 낱말 가운데에 자주 와요.", "짧게 소리 내요."], "example": "a: cat 🐱 hat 🎩 · e: bed 🛏️ pen 🖊️ · i: pig 🐷 six · o: dog 🐶 box 📦 · u: sun ☀️ bus 🚌", "figure": "고양이 인형, 펜, 돼지 인형, 상자, 장난감 버스가 한 줄로 놓인 책상"}, {"heading": "첫 글자만 바꿔 봐요", "paras": ["cat의 c를 h로 바꾸면?", "hat 🎩 이 돼요!", "끝소리가 같은 낱말 가족이에요."], "example": "cat · hat · bat · mat", "figure": "고양이 인형 옆에 작은 모자와 매트가 놓인 모습"}, {"heading": "가운데만 바꿔 봐요", "paras": ["가운데 모음을 바꾸면 뜻이 바뀌어요.", "pen 🖊️ 의 e를 a로 바꾸면 pan 🍳 이에요."], "example": "pen → pan · pin → pen", "figure": "책상 위의 펜과 장난감 프라이팬"}], "keywords": [{"word": "모음", "meaning": "a, e, i, o, u 다섯 글자"}, {"word": "이어 읽기", "meaning": "글자 소리를 하나씩 낸 뒤 이어서 낱말로 읽기"}, {"word": "낱말 가족", "meaning": "끝소리가 같은 낱말들 (cat, hat, bat)"}], "expressions": [{"en": "c, a, t - cat", "ko": "🐱 고양이", "note": "소리를 하나씩 내고 이어 읽어요"}, {"en": "cat", "ko": "🐱 고양이", "note": "가운데 a '애'"}, {"en": "hat", "ko": "🎩 모자", "note": "가운데 a '애'"}, {"en": "bed", "ko": "🛏️ 침대", "note": "가운데 e '에'"}, {"en": "pen", "ko": "🖊️ 펜", "note": "가운데 e '에'"}, {"en": "pig", "ko": "🐷 돼지", "note": "가운데 i '이'"}, {"en": "six", "ko": "6 여섯", "note": "가운데 i '이'"}, {"en": "dog", "ko": "🐶 개", "note": "가운데 o '아'"}, {"en": "box", "ko": "📦 상자", "note": "가운데 o '아'"}, {"en": "sun", "ko": "☀️ 해", "note": "가운데 u '어'"}, {"en": "bus", "ko": "🚌 버스", "note": "가운데 u '어'"}, {"en": "pan", "ko": "🍳 프라이팬", "note": "pen과 가운데만 달라요"}], "quiz": [{"q": "🐶 그림에 맞는 낱말은?", "choices": ["dig", "dog", "bag", "pig"], "answer": 1, "explain": "d-o-g, '드-아-그'를 이으면 dog이에요."}, {"q": "c-a-t 를 이어 읽으면?", "choices": ["cut", "cot", "cat", "kit"], "answer": 2, "explain": "'크-애-트'를 이으면 cat 🐱 이에요."}, {"q": "cat 에서 c를 h로 바꾸면?", "choices": ["hot", "hut", "hit", "hat"], "answer": 3, "explain": "h-a-t, hat 🎩 이 돼요."}, {"q": "☀️ sun의 가운데 모음은?", "choices": ["u", "a", "o", "i"], "answer": 0, "explain": "s-u-n, 가운데는 짧은 '어' 소리 u예요."}, {"q": "pen의 가운데를 a로 바꾸면 어떤 그림일까요?", "choices": ["🍳 pan", "🐷 pig", "🛏️ bed", "🖊️ pen"], "answer": 0, "explain": "p-a-n, pan은 프라이팬이에요."}], "summary": ["글자 소리를 하나씩 낸 뒤 이으면 낱말이 돼요.", "가운데 모음 a e i o u 는 짧게 소리 내요.", "한 글자만 바꿔도 새 낱말이 돼요."], "parent_tip": "처음에는 '크-애-트'처럼 천천히 끊어 읽다가 점점 빠르게 이어 붙이도록 도와주세요. 이때 '크'를 길게 '크으'로 늘이면 이어 읽기가 어려워지니 짧게 끊어 주시면 좋습니다. 글자 카드 한 장만 바꿔 cat→hat→bat처럼 새 낱말을 만드는 놀이가 효과적입니다.", "narr": {"cover": "assets/audio/n/e1-06_cover.mp3", "s0": "assets/audio/n/e1-06_s0.mp3", "s1": "assets/audio/n/e1-06_s1.mp3", "s2": "assets/audio/n/e1-06_s2.mp3", "s3": "assets/audio/n/e1-06_s3.mp3", "kw": "assets/audio/n/e1-06_kw.mp3", "q0": "assets/audio/n/e1-06_q0.mp3", "q1": "assets/audio/n/e1-06_q1.mp3", "q2": "assets/audio/n/e1-06_q2.mp3", "q3": "assets/audio/n/e1-06_q3.mp3", "q4": "assets/audio/n/e1-06_q4.mp3", "sum": "assets/audio/n/e1-06_sum.mp3"}}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','2단계 · 짧은 모음 낱말 (cat, dog)',6,'e1-06' where not exists (select 1 from public.topics where lesson_slug='e1-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-07','1~2','영어','2단계 · 자주 보는 낱말 (I, you, the, a)','I, you, the, a — 책에 자꾸 나오는 낱말은 뭘까?','assets/img/l_e1-07.jpg',$j${"intro": "영어 책을 펴면 자꾸 보이는 낱말이 있어요. 📖 눈으로 보자마자 읽어 봐요.", "sections": [{"heading": "자주 보는 낱말이 있어요", "paras": ["책에 같은 낱말이 자꾸 나와요.", "I, you, the, a 예요.", "보자마자 바로 읽어요. 👀"], "example": "I · you · the · a", "figure": "펼쳐진 그림책 위에 아이 손가락이 놓인 모습"}, {"heading": "I는 나, you는 너", "paras": ["I는 '나'예요. 🙋", "I는 언제나 대문자로 써요.", "you는 '너'예요. 👉"], "example": "I like you. 나는 너를 좋아해.", "figure": "두 아이가 마주 보고 웃는 모습"}, {"heading": "a는 하나, the는 그", "paras": ["a는 '하나'라는 뜻이에요.", "a cat 🐱 은 고양이 한 마리예요.", "the는 '그'예요. 다 아는 것에 써요."], "example": "a dog 🐶 개 한 마리 · the sun ☀️ 해", "figure": "강아지 인형 한 개가 창가 햇빛 아래 놓인 모습"}, {"heading": "문장으로 읽어요", "paras": ["I see는 '나는 ~을 봐요'예요.", "뒤의 낱말만 바꿔 읽어요."], "example": "I see a cat. · I see the sun. · I see you.", "figure": "아이가 쌍안경으로 창밖을 보는 모습"}], "keywords": [{"word": "I", "meaning": "나. 언제나 대문자로 써요."}, {"word": "you", "meaning": "너"}, {"word": "a", "meaning": "하나의 (a cat 고양이 한 마리)"}, {"word": "the", "meaning": "그 (다 아는 것 앞에 써요)"}], "expressions": [{"en": "I", "ko": "나 🙋", "note": "아이. 언제나 대문자"}, {"en": "you", "ko": "너 👉", "note": "유"}, {"en": "the", "ko": "그", "note": "더"}, {"en": "a", "ko": "하나의", "note": "어. 낱말 앞에서 짧게"}, {"en": "a cat", "ko": "🐱 고양이 한 마리"}, {"en": "the sun", "ko": "☀️ 해"}, {"en": "I see a dog.", "ko": "나는 개 한 마리를 봐요. 🐶"}, {"en": "I see the sun.", "ko": "나는 해를 봐요. ☀️"}, {"en": "I see you.", "ko": "나는 너를 봐요. 👀"}, {"en": "I like you.", "ko": "나는 너를 좋아해요. 💛"}, {"en": "you and I", "ko": "너와 나"}], "quiz": [{"q": "🙋 '나'를 뜻하는 낱말은?", "choices": ["you", "I", "a", "the"], "answer": 1, "explain": "I는 '나'예요. 언제나 대문자로 써요."}, {"q": "👉 '너'를 뜻하는 낱말은?", "choices": ["I", "the", "you", "a"], "answer": 2, "explain": "you는 '너'예요."}, {"q": "🐱 '고양이 한 마리'는?", "choices": ["a cat", "I cat", "you cat", "cat a"], "answer": 0, "explain": "'하나'라는 뜻의 a를 cat 앞에 써요."}, {"q": "바르게 쓴 문장은?", "choices": ["i see a dog.", "i See a dog.", "see I a dog.", "I see a dog."], "answer": 3, "explain": "I는 대문자로 쓰고, 문장 맨 앞에 와요."}, {"q": "'I see the sun.'의 뜻은?", "choices": ["너는 해를 봐요.", "나는 달을 봐요.", "나는 해를 봐요.", "나는 해가 좋아요."], "answer": 2, "explain": "I 나는, see 봐요, the sun 해."}], "summary": ["I는 '나', you는 '너'예요.", "a는 '하나의', the는 '그'예요.", "I는 언제나 대문자로 써요."], "parent_tip": "I, you, the, a 같은 낱말은 소리로 풀어 읽기보다 통째로 눈에 익히는 '사이트 워드'입니다. 그림책을 함께 읽으며 이 낱말이 나올 때마다 손가락으로 짚게 해 보세요. a와 the의 차이는 이 단계에서 깊게 설명하지 않고 '하나', '그' 정도로만 알려 주셔도 충분합니다.", "narr": {"cover": "assets/audio/n/e1-07_cover.mp3", "s0": "assets/audio/n/e1-07_s0.mp3", "s1": "assets/audio/n/e1-07_s1.mp3", "s2": "assets/audio/n/e1-07_s2.mp3", "s3": "assets/audio/n/e1-07_s3.mp3", "kw": "assets/audio/n/e1-07_kw.mp3", "q0": "assets/audio/n/e1-07_q0.mp3", "q1": "assets/audio/n/e1-07_q1.mp3", "q2": "assets/audio/n/e1-07_q2.mp3", "q3": "assets/audio/n/e1-07_q3.mp3", "q4": "assets/audio/n/e1-07_q4.mp3", "sum": "assets/audio/n/e1-07_sum.mp3"}}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','2단계 · 자주 보는 낱말 (I, you, the, a)',7,'e1-07' where not exists (select 1 from public.topics where lesson_slug='e1-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-08','1~2','영어','2단계 · 숫자 1~10','영어로 하나, 둘, 셋 어떻게 셀까?','assets/img/l_e1-08.jpg',$j${"intro": "🍎 사과가 몇 개 있을까요? 오늘은 영어로 1부터 10까지 세어 봐요.", "sections": [{"heading": "1부터 5까지 세어요", "paras": ["1은 one, 2는 two예요.", "3은 three, 4는 four, 5는 five예요.", "손가락을 하나씩 펴며 말해 봐요. ✋"], "example": "🍎 one, 🍎🍎 two, 🍎🍎🍎 three, 🍎🍎🍎🍎 four, 🍎🍎🍎🍎🍎 five", "figure": "아이 손가락 다섯 개를 하나씩 펴는 모습"}, {"heading": "6부터 10까지 세어요", "paras": ["6은 six, 7은 seven이에요.", "8은 eight, 9는 nine이에요.", "10은 ten이에요. 손가락이 모두 펴졌어요! 🙌"], "example": "⭐ six, seven, eight, nine, ten!", "figure": "두 손을 활짝 편 아이의 손"}, {"heading": "숫자 글자를 살펴봐요", "paras": ["two는 w 소리가 안 나요. [투]라고 읽어요.", "eight도 gh 소리가 안 나요. [에잇]이라고 읽어요."], "example": "two [투], eight [에잇]", "figure": "책상 위에 놓인 숫자 블록 장난감"}, {"heading": "How many? 몇 개예요?", "paras": ["How many?는 \"몇 개예요?\"라는 뜻이에요.", "세어 보고 숫자로 대답해요."], "example": "How many? 🐶🐶🐶 → Three!", "figure": "강아지 인형 세 개를 손가락으로 세는 아이"}], "keywords": [{"word": "one ~ ten", "meaning": "영어로 1부터 10까지의 숫자"}, {"word": "How many?", "meaning": "몇 개예요? 하고 묻는 말"}, {"word": "세기", "meaning": "하나씩 짚으며 몇 개인지 알아보는 것"}], "expressions": [{"en": "one", "ko": "1, 하나", "note": "[원]"}, {"en": "two", "ko": "2, 둘", "note": "[투] w는 소리가 안 나요"}, {"en": "three", "ko": "3, 셋", "note": "[쓰리] 혀를 이 사이에 살짝"}, {"en": "four", "ko": "4, 넷", "note": "[포]"}, {"en": "five", "ko": "5, 다섯", "note": "[파이브]"}, {"en": "six", "ko": "6, 여섯", "note": "[식스]"}, {"en": "seven", "ko": "7, 일곱", "note": "[세븐]"}, {"en": "eight", "ko": "8, 여덟", "note": "[에잇] gh는 소리가 안 나요"}, {"en": "nine", "ko": "9, 아홉", "note": "[나인]"}, {"en": "ten", "ko": "10, 열", "note": "[텐]"}, {"en": "How many?", "ko": "몇 개예요?", "note": "개수를 물을 때"}], "quiz": [{"q": "🍎🍎🍎 사과는 몇 개? 영어로 고르세요.", "choices": ["two", "three", "four", "five"], "answer": 1, "explain": "사과가 3개예요. 3은 three예요."}, {"q": "ten은 몇일까요?", "choices": ["1", "6", "8", "10"], "answer": 3, "explain": "ten은 10이에요."}, {"q": "5를 영어로 하면?", "choices": ["four", "nine", "five", "six"], "answer": 2, "explain": "5는 five예요."}, {"q": "\"몇 개예요?\"를 영어로 하면?", "choices": ["How many?", "Hello!", "Thank you.", "Good bye."], "answer": 0, "explain": "개수를 물을 때 How many?라고 해요."}, {"q": "seven 다음 숫자는?", "choices": ["six", "nine", "ten", "eight"], "answer": 3, "explain": "7 다음은 8, eight예요."}], "summary": ["1~5는 one, two, three, four, five예요.", "6~10은 six, seven, eight, nine, ten이에요.", "How many?는 \"몇 개예요?\"라는 뜻이에요."], "parent_tip": "two와 eight처럼 글자와 소리가 다른 숫자를 아이가 가장 많이 헷갈립니다. 계단을 오르거나 간식을 나눌 때 영어로 함께 세어 보세요. \"How many cookies?\"라고 묻고 숫자로 대답하게 하면 자연스럽게 익힙니다.", "narr": {"cover": "assets/audio/n/e1-08_cover.mp3", "s0": "assets/audio/n/e1-08_s0.mp3", "s1": "assets/audio/n/e1-08_s1.mp3", "s2": "assets/audio/n/e1-08_s2.mp3", "s3": "assets/audio/n/e1-08_s3.mp3", "kw": "assets/audio/n/e1-08_kw.mp3", "q0": "assets/audio/n/e1-08_q0.mp3", "q1": "assets/audio/n/e1-08_q1.mp3", "q2": "assets/audio/n/e1-08_q2.mp3", "q3": "assets/audio/n/e1-08_q3.mp3", "q4": "assets/audio/n/e1-08_q4.mp3", "sum": "assets/audio/n/e1-08_sum.mp3"}}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','2단계 · 숫자 1~10',8,'e1-08' where not exists (select 1 from public.topics where lesson_slug='e1-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-09','1~2','영어','2단계 · 색깔과 모양','빨간 동그라미를 영어로 뭐라고 할까?','assets/img/l_e1-09.jpg',$j${"intro": "🍎 사과는 무슨 색이에요? 오늘은 색깔과 모양을 영어로 말해 봐요.", "sections": [{"heading": "여러 가지 색깔", "paras": ["빨강은 red, 파랑은 blue예요.", "노랑은 yellow, 초록은 green이에요.", "검정은 black, 하양은 white예요."], "example": "🍎 red, 💙 blue, 🍌 yellow, 🐸 green", "figure": "빨강, 파랑, 노랑, 초록 크레파스가 놓인 책상"}, {"heading": "여러 가지 모양", "paras": ["동그라미는 circle이에요. ⚪", "네모는 square예요. 🟥", "세모는 triangle, 별은 star예요. 🔺⭐"], "example": "⚪ circle, 🟥 square, 🔺 triangle, ⭐ star", "figure": "동그라미, 네모, 세모 모양 블록"}, {"heading": "색깔 + 모양을 함께 말해요", "paras": ["색깔을 먼저, 모양을 나중에 말해요.", "빨간 동그라미는 a red circle이에요."], "example": "🔴 a red circle, 🟦 a blue square", "figure": "빨간 공과 파란 네모 상자"}, {"heading": "What color? 무슨 색이에요?", "paras": ["What color?는 \"무슨 색이에요?\"라는 뜻이에요.", "색깔 낱말로 대답하면 돼요."], "example": "What color? 🐸 → Green!", "figure": "초록 개구리 인형을 들고 있는 아이 손"}], "keywords": [{"word": "color", "meaning": "색깔"}, {"word": "shape", "meaning": "모양"}, {"word": "What color?", "meaning": "무슨 색이에요? 하고 묻는 말"}], "expressions": [{"en": "red", "ko": "빨간색", "note": "[레드]"}, {"en": "blue", "ko": "파란색", "note": "[블루]"}, {"en": "yellow", "ko": "노란색", "note": "[옐로]"}, {"en": "green", "ko": "초록색", "note": "[그린]"}, {"en": "black", "ko": "검은색", "note": "[블랙]"}, {"en": "white", "ko": "하얀색", "note": "[와잇]"}, {"en": "circle", "ko": "동그라미", "note": "[써클]"}, {"en": "square", "ko": "네모(정사각형)", "note": "[스퀘어]"}, {"en": "triangle", "ko": "세모", "note": "[트라이앵글]"}, {"en": "star", "ko": "별", "note": "[스타]"}, {"en": "a red circle", "ko": "빨간 동그라미", "note": "색깔 먼저, 모양 나중"}, {"en": "What color?", "ko": "무슨 색이에요?", "note": "색깔을 물을 때"}], "quiz": [{"q": "🍌 바나나는 무슨 색? 영어로 고르세요.", "choices": ["red", "yellow", "blue", "black"], "answer": 1, "explain": "바나나는 노란색, yellow예요."}, {"q": "🔺 이 모양은?", "choices": ["circle", "star", "triangle", "square"], "answer": 2, "explain": "세모는 triangle이에요."}, {"q": "\"파란 네모\"를 영어로 하면?", "choices": ["a blue square", "a square blue", "a red circle", "a blue star"], "answer": 0, "explain": "색깔 blue를 먼저, 모양 square를 나중에 말해요."}, {"q": "What color?의 뜻은?", "choices": ["몇 개예요?", "이름이 뭐예요?", "어디 있어요?", "무슨 색이에요?"], "answer": 3, "explain": "color는 색깔이에요. What color?는 무슨 색이냐고 묻는 말이에요."}, {"q": "🐸 개구리는 무슨 색?", "choices": ["white", "red", "green", "yellow"], "answer": 2, "explain": "개구리는 초록색, green이에요."}], "summary": ["red, blue, yellow, green, black, white는 색깔이에요.", "circle, square, triangle, star는 모양이에요.", "색깔을 먼저 말해요: a red circle."], "parent_tip": "우리말은 '빨간 동그라미'처럼 색깔이 앞에 오듯 영어도 같은 순서라 아이가 쉽게 익힙니다. 다만 white를 [화이트]보다 [와잇]에 가깝게 들려주세요. 장난감이나 옷을 가리키며 \"What color?\"라고 물어보면 좋습니다.", "narr": {"cover": "assets/audio/n/e1-09_cover.mp3", "s0": "assets/audio/n/e1-09_s0.mp3", "s1": "assets/audio/n/e1-09_s1.mp3", "s2": "assets/audio/n/e1-09_s2.mp3", "s3": "assets/audio/n/e1-09_s3.mp3", "kw": "assets/audio/n/e1-09_kw.mp3", "q0": "assets/audio/n/e1-09_q0.mp3", "q1": "assets/audio/n/e1-09_q1.mp3", "q2": "assets/audio/n/e1-09_q2.mp3", "q3": "assets/audio/n/e1-09_q3.mp3", "q4": "assets/audio/n/e1-09_q4.mp3", "sum": "assets/audio/n/e1-09_sum.mp3"}}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','2단계 · 색깔과 모양',9,'e1-09' where not exists (select 1 from public.topics where lesson_slug='e1-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-10','1~2','영어','3단계 · 인사하기','영어로 어떻게 인사할까?','assets/img/l_e1-10.jpg',$j${"intro": "👋 친구를 만나면 \"안녕!\" 하고 인사하지요? 영어로도 반갑게 인사해 봐요.", "sections": [{"heading": "만났을 때 인사해요", "paras": ["만나면 Hello! 또는 Hi!라고 해요.", "Hi는 친구끼리 쓰는 짧은 인사예요."], "example": "👧 Hello! 👦 Hi!", "figure": "손을 흔들며 인사하는 두 아이"}, {"heading": "아침, 낮, 저녁 인사", "paras": ["🌅 아침에는 Good morning!", "☀️ 낮에는 Good afternoon!", "🌙 저녁에는 Good evening!"], "example": "아침에 선생님께: Good morning!", "figure": "아침 햇살이 비치는 창가의 식탁"}, {"heading": "안부를 물어요", "paras": ["How are you?는 \"잘 지내?\"라는 뜻이에요.", "I'm fine, thank you.로 대답해요.", "기분이 좋으면 I'm good!이라고 해도 돼요."], "example": "👩 How are you? 👦 I'm fine, thank you.", "figure": "웃으며 이야기하는 엄마와 아이"}, {"heading": "헤어질 때 인사해요", "paras": ["헤어질 때는 Goodbye! 또는 Bye!라고 해요.", "See you!는 \"또 만나!\"라는 뜻이에요."], "example": "👋 Bye! See you!", "figure": "학교 앞에서 손을 흔들며 헤어지는 아이들"}], "keywords": [{"word": "Hello / Hi", "meaning": "만났을 때 하는 인사"}, {"word": "How are you?", "meaning": "잘 지내? 하고 안부를 묻는 말"}, {"word": "Goodbye / Bye", "meaning": "헤어질 때 하는 인사"}], "expressions": [{"en": "Hello!", "ko": "안녕하세요! / 안녕!", "note": "만났을 때"}, {"en": "Hi!", "ko": "안녕!", "note": "친구끼리 짧게"}, {"en": "Good morning!", "ko": "좋은 아침이에요!", "note": "아침 인사"}, {"en": "Good afternoon!", "ko": "안녕하세요! (낮 인사)", "note": "점심 지나서"}, {"en": "Good evening!", "ko": "안녕하세요! (저녁 인사)", "note": "저녁에 만났을 때"}, {"en": "How are you?", "ko": "잘 지내? / 어떻게 지내?", "note": "안부를 물을 때"}, {"en": "I'm fine, thank you.", "ko": "잘 지내, 고마워.", "note": "How are you?에 대답"}, {"en": "I'm good!", "ko": "좋아!", "note": "기분이 좋을 때"}, {"en": "Goodbye!", "ko": "잘 가! / 안녕히 가세요!", "note": "헤어질 때"}, {"en": "Bye!", "ko": "안녕! (헤어질 때)", "note": "짧게"}, {"en": "See you!", "ko": "또 만나!", "note": "헤어질 때"}], "quiz": [{"q": "🌅 아침에 선생님을 만났어요. 뭐라고 할까요?", "choices": ["Good evening!", "Good morning!", "Goodbye!", "See you!"], "answer": 1, "explain": "아침 인사는 Good morning!이에요."}, {"q": "친구가 How are you?라고 물었어요. 알맞은 대답은?", "choices": ["I'm fine, thank you.", "Goodbye!", "Good morning!", "Hello!"], "answer": 0, "explain": "안부를 물으면 I'm fine, thank you.라고 대답해요."}, {"q": "👋 집에 갈 때 친구에게 하는 말은?", "choices": ["Hi!", "Good morning!", "How are you?", "Bye!"], "answer": 3, "explain": "헤어질 때는 Bye!라고 해요."}, {"q": "See you!의 뜻은?", "choices": ["잘 지내?", "고마워.", "또 만나!", "좋은 아침!"], "answer": 2, "explain": "See you!는 또 만나자는 인사예요."}, {"q": "🌙 저녁에 만난 이웃에게 하는 인사는?", "choices": ["Good afternoon!", "Good morning!", "Bye!", "Good evening!"], "answer": 3, "explain": "저녁에 만나면 Good evening!이라고 해요."}], "summary": ["만나면 Hello! / Hi!라고 해요.", "How are you?에는 I'm fine, thank you.로 대답해요.", "헤어질 때는 Goodbye! / Bye! / See you!라고 해요."], "parent_tip": "Good night!은 만날 때가 아니라 잠자리에 들거나 밤에 헤어질 때 쓰는 말이라 Good evening!과 헷갈리기 쉽습니다. 아침에 일어나면 \"Good morning!\", 등원할 때 \"Bye! See you!\"처럼 하루 생활 속에서 짧게 주고받아 보세요.", "narr": {"cover": "assets/audio/n/e1-10_cover.mp3", "s0": "assets/audio/n/e1-10_s0.mp3", "s1": "assets/audio/n/e1-10_s1.mp3", "s2": "assets/audio/n/e1-10_s2.mp3", "s3": "assets/audio/n/e1-10_s3.mp3", "kw": "assets/audio/n/e1-10_kw.mp3", "q0": "assets/audio/n/e1-10_q0.mp3", "q1": "assets/audio/n/e1-10_q1.mp3", "q2": "assets/audio/n/e1-10_q2.mp3", "q3": "assets/audio/n/e1-10_q3.mp3", "q4": "assets/audio/n/e1-10_q4.mp3", "sum": "assets/audio/n/e1-10_sum.mp3"}}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','3단계 · 인사하기',10,'e1-10' where not exists (select 1 from public.topics where lesson_slug='e1-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-11','1~2','영어','3단계 · This is ~ 소개하기','This is my mom! 어떻게 소개할까?','assets/img/l_e1-11.jpg',$j${"intro": "👩 친구에게 우리 엄마를 소개하고 싶어요. 영어로는 어떻게 말할까요?", "sections": [{"heading": "This is ~는 \"이 사람은 ~야\"", "paras": ["가까이 있는 사람을 소개할 때 This is ~라고 해요.", "This is 다음에 소개할 사람을 말해요."], "example": "This is my mom. (이분은 우리 엄마야.)", "figure": "아이가 엄마 옆에 서서 친구에게 손으로 가리키는 모습"}, {"heading": "가족을 소개해요", "paras": ["my는 \"나의\"라는 뜻이에요.", "👨 my dad, 👩 my mom이에요.", "👧 my sister, 👦 my brother도 있어요."], "example": "This is my dad. This is my sister.", "figure": "가족사진 액자가 놓인 책상"}, {"heading": "친구를 소개해요", "paras": ["친구는 friend예요.", "이름을 넣어서 소개할 수도 있어요."], "example": "This is my friend, Mina. (얘는 내 친구 미나야.)", "figure": "나란히 서서 웃는 두 친구"}, {"heading": "소개받으면 이렇게 말해요", "paras": ["Nice to meet you.는 \"만나서 반가워.\"예요.", "상대도 Nice to meet you, too.라고 대답해요."], "example": "👧 Nice to meet you. 👦 Nice to meet you, too.", "figure": "악수하는 두 아이의 손"}], "keywords": [{"word": "This is ~", "meaning": "이 사람은(이것은) ~야, 하고 소개하는 말"}, {"word": "my", "meaning": "나의"}, {"word": "Nice to meet you.", "meaning": "만나서 반가워."}], "expressions": [{"en": "This is my mom.", "ko": "이분은 우리 엄마야.", "note": "가족 소개"}, {"en": "This is my dad.", "ko": "이분은 우리 아빠야."}, {"en": "This is my sister.", "ko": "얘는 내 언니(누나, 여동생)야.", "note": "sister는 여자 형제"}, {"en": "This is my brother.", "ko": "얘는 내 오빠(형, 남동생)야.", "note": "brother는 남자 형제"}, {"en": "This is my friend.", "ko": "얘는 내 친구야."}, {"en": "This is my friend, Mina.", "ko": "얘는 내 친구 미나야.", "note": "이름을 넣어 소개"}, {"en": "Nice to meet you.", "ko": "만나서 반가워.", "note": "처음 만났을 때"}, {"en": "Nice to meet you, too.", "ko": "나도 만나서 반가워.", "note": "대답할 때"}, {"en": "mom", "ko": "엄마", "note": "[맘]"}, {"en": "dad", "ko": "아빠", "note": "[대드]"}], "quiz": [{"q": "👨 아빠를 소개할 때 알맞은 말은?", "choices": ["This is my mom.", "This is my dad.", "This is my friend.", "Nice to meet you."], "answer": 1, "explain": "아빠는 dad예요. This is my dad.라고 해요."}, {"q": "my의 뜻은?", "choices": ["나의", "너의", "이것", "친구"], "answer": 0, "explain": "my는 \"나의\"라는 뜻이에요."}, {"q": "처음 만난 친구에게 하는 말은?", "choices": ["Goodbye!", "This is my dad.", "How many?", "Nice to meet you."], "answer": 3, "explain": "처음 만나면 Nice to meet you.라고 해요."}, {"q": "Nice to meet you.에 알맞은 대답은?", "choices": ["I'm fine.", "Bye!", "Nice to meet you, too.", "This is my mom."], "answer": 2, "explain": "\"나도 반가워\"는 Nice to meet you, too.예요."}, {"q": "👦 남자 형제를 소개해요. This is my ____.", "choices": ["sister", "mom", "brother", "friend"], "answer": 2, "explain": "남자 형제는 brother예요."}], "summary": ["This is ~로 사람을 소개해요.", "my는 \"나의\": my mom, my dad, my friend.", "소개받으면 Nice to meet you.라고 해요."], "parent_tip": "영어는 형·오빠·남동생을 모두 brother, 언니·누나·여동생을 모두 sister라고 해서 아이가 신기해합니다. 인형이나 가족사진을 가리키며 \"This is my ~.\"로 소개 놀이를 해 보세요. 소개를 받으면 \"Nice to meet you.\"라고 답하도록 역할을 바꿔 주면 좋습니다.", "narr": {"cover": "assets/audio/n/e1-11_cover.mp3", "s0": "assets/audio/n/e1-11_s0.mp3", "s1": "assets/audio/n/e1-11_s1.mp3", "s2": "assets/audio/n/e1-11_s2.mp3", "s3": "assets/audio/n/e1-11_s3.mp3", "kw": "assets/audio/n/e1-11_kw.mp3", "q0": "assets/audio/n/e1-11_q0.mp3", "q1": "assets/audio/n/e1-11_q1.mp3", "q2": "assets/audio/n/e1-11_q2.mp3", "q3": "assets/audio/n/e1-11_q3.mp3", "q4": "assets/audio/n/e1-11_q4.mp3", "sum": "assets/audio/n/e1-11_sum.mp3"}}$j$::jsonb,11) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
