insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-12','1~2','영어','3단계 · I like ~ 좋아하는 것','내가 좋아하는 것을 영어로 말해 볼까?','assets/img/l_e1-12.jpg',$j${"intro": "🍕 피자를 좋아하나요? 오늘은 좋아하는 것을 영어로 말해 봐요.", "sections": [{"heading": "I like ~는 \"나는 ~을 좋아해\"", "paras": ["I는 \"나는\", like는 \"좋아해\"예요.", "I like 다음에 좋아하는 것을 말해요."], "example": "🍎 I like apples. (나는 사과를 좋아해.)", "figure": "사과를 들고 웃는 아이의 손"}, {"heading": "여러 가지를 좋아해요", "paras": ["동물도, 음식도, 색깔도 말할 수 있어요.", "🐶 I like dogs. 🍕 I like pizza.", "💙 I like blue."], "example": "I like cats. I like milk.", "figure": "강아지 인형과 우유 컵이 놓인 책상"}, {"heading": "좋아하지 않을 때", "paras": ["싫으면 I don't like ~라고 해요.", "don't는 \"~하지 않아\"라는 뜻이에요."], "example": "🥕 I don't like carrots. (나는 당근을 안 좋아해.)", "figure": "접시 위 당근을 밀어내는 아이 손"}, {"heading": "친구에게 물어봐요", "paras": ["Do you like ~?는 \"너는 ~을 좋아하니?\"예요.", "좋으면 Yes, I do. 싫으면 No, I don't."], "example": "Do you like dogs? → Yes, I do! 🐶", "figure": "마주 앉아 이야기하는 두 아이"}], "keywords": [{"word": "like", "meaning": "좋아하다"}, {"word": "I like ~.", "meaning": "나는 ~을 좋아해."}, {"word": "I don't like ~.", "meaning": "나는 ~을 좋아하지 않아."}, {"word": "Do you like ~?", "meaning": "너는 ~을 좋아하니?"}], "expressions": [{"en": "I like apples.", "ko": "나는 사과를 좋아해."}, {"en": "I like dogs.", "ko": "나는 개를 좋아해."}, {"en": "I like cats.", "ko": "나는 고양이를 좋아해."}, {"en": "I like pizza.", "ko": "나는 피자를 좋아해."}, {"en": "I like blue.", "ko": "나는 파란색을 좋아해."}, {"en": "I don't like carrots.", "ko": "나는 당근을 좋아하지 않아.", "note": "싫을 때"}, {"en": "Do you like dogs?", "ko": "너는 개를 좋아하니?", "note": "물어볼 때"}, {"en": "Yes, I do.", "ko": "응, 좋아해.", "note": "좋아할 때 대답"}, {"en": "No, I don't.", "ko": "아니, 안 좋아해.", "note": "싫을 때 대답"}, {"en": "like", "ko": "좋아하다", "note": "[라이크]"}], "quiz": [{"q": "\"나는 고양이를 좋아해.\"를 영어로 하면? 🐱", "choices": ["I like dogs.", "I like cats.", "I don't like cats.", "Do you like cats?"], "answer": 1, "explain": "고양이는 cats. I like cats.예요."}, {"q": "I don't like milk.의 뜻은?", "choices": ["나는 우유를 좋아해.", "너는 우유를 좋아하니?", "나는 우유를 좋아하지 않아.", "우유 주세요."], "answer": 2, "explain": "don't가 있으면 \"좋아하지 않아\"예요."}, {"q": "Do you like pizza? 피자를 좋아하면 뭐라고 대답할까요? 🍕", "choices": ["Yes, I do.", "No, I don't.", "Goodbye!", "This is pizza."], "answer": 0, "explain": "좋아하면 Yes, I do.라고 대답해요."}, {"q": "like의 뜻은?", "choices": ["싫어하다", "먹다", "보다", "좋아하다"], "answer": 3, "explain": "like는 좋아한다는 뜻이에요."}, {"q": "\"너는 개를 좋아하니?\"를 영어로 하면? 🐶", "choices": ["I like dogs.", "No, I don't.", "Do you like dogs?", "This is my dog."], "answer": 2, "explain": "물어볼 때는 Do you like ~?를 써요."}], "summary": ["I like ~. = 나는 ~을 좋아해.", "I don't like ~. = 나는 ~을 좋아하지 않아.", "Do you like ~?에는 Yes, I do. / No, I don't.로 대답해요."], "parent_tip": "영어에서는 동물이나 과일처럼 셀 수 있는 것을 좋아한다고 할 때 dogs, apples처럼 끝에 s를 붙입니다. 1~2학년 단계에서는 문법 설명보다 통째로 따라 말하게 해 주세요. 식사 시간에 \"Do you like carrots?\" 하고 묻고 Yes, I do. / No, I don't.로 답하는 놀이가 효과적입니다.", "narr": {"cover": "assets/audio/n/e1-12_cover.mp3", "s0": "assets/audio/n/e1-12_s0.mp3", "s1": "assets/audio/n/e1-12_s1.mp3", "s2": "assets/audio/n/e1-12_s2.mp3", "s3": "assets/audio/n/e1-12_s3.mp3", "kw": "assets/audio/n/e1-12_kw.mp3", "q0": "assets/audio/n/e1-12_q0.mp3", "q1": "assets/audio/n/e1-12_q1.mp3", "q2": "assets/audio/n/e1-12_q2.mp3", "q3": "assets/audio/n/e1-12_q3.mp3", "q4": "assets/audio/n/e1-12_q4.mp3", "sum": "assets/audio/n/e1-12_sum.mp3"}}$j$::jsonb,12) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','3단계 · I like ~ 좋아하는 것',12,'e1-12' where not exists (select 1 from public.topics where lesson_slug='e1-12');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-13','1~2','영어','3단계 · Can I ~? 부탁하기','"~해도 돼요?" 영어로 어떻게 부탁할까?','assets/img/l_e1-13.jpg',$j${"intro": "💧 목이 말라요. 물을 마셔도 되는지 영어로 물어볼까요?", "sections": [{"heading": "Can I ~?는 \"~해도 돼요?\"", "paras": ["무엇을 해도 되는지 물을 때 Can I ~?라고 해요.", "Can I 다음에 하고 싶은 일을 말해요."], "example": "Can I go out? (나가도 돼요?)", "figure": "문 앞에서 엄마를 바라보는 아이"}, {"heading": "이럴 때 써요", "paras": ["🚻 Can I go to the bathroom? 화장실 가도 돼요?", "🪑 Can I sit here? 여기 앉아도 돼요?", "🍪 Can I have a cookie? 쿠키 먹어도 돼요?"], "example": "Can I have some water? (물 좀 마셔도 돼요?)", "figure": "책상 위의 물컵과 쿠키 한 개"}, {"heading": "대답하는 방법", "paras": ["괜찮으면 Sure! 또는 Yes, you can.이라고 해요.", "안 되면 Sorry, you can't.라고 해요."], "example": "Can I sit here? → Sure! 😊", "figure": "고개를 끄덕이며 웃는 선생님"}, {"heading": "예쁘게 부탁해요", "paras": ["끝에 please를 붙이면 더 공손해요.", "들어주면 Thank you!라고 말해요."], "example": "Can I have some water, please? → Sure! → Thank you!", "figure": "물컵을 건네받는 아이 손"}], "keywords": [{"word": "Can I ~?", "meaning": "~해도 돼요? 하고 허락을 구하는 말"}, {"word": "Sure!", "meaning": "그럼! 물론이지!"}, {"word": "please", "meaning": "부탁할 때 붙이는 공손한 말"}], "expressions": [{"en": "Can I go out?", "ko": "나가도 돼요?"}, {"en": "Can I go to the bathroom?", "ko": "화장실에 가도 돼요?"}, {"en": "Can I sit here?", "ko": "여기 앉아도 돼요?"}, {"en": "Can I have a cookie?", "ko": "쿠키 하나 먹어도 돼요?"}, {"en": "Can I have some water, please?", "ko": "물 좀 마셔도 될까요?", "note": "please로 공손하게"}, {"en": "Sure!", "ko": "그럼! / 물론이지!", "note": "허락할 때"}, {"en": "Yes, you can.", "ko": "응, 해도 돼.", "note": "허락할 때"}, {"en": "Sorry, you can't.", "ko": "미안, 안 돼.", "note": "안 될 때"}, {"en": "please", "ko": "부탁해요(공손하게)", "note": "[플리즈]"}, {"en": "Thank you!", "ko": "고맙습니다!", "note": "들어주었을 때"}], "quiz": [{"q": "🚻 화장실에 가고 싶어요. 선생님께 뭐라고 할까요?", "choices": ["Can I sit here?", "Can I go to the bathroom?", "I like the bathroom.", "Goodbye!"], "answer": 1, "explain": "화장실은 bathroom이에요. Can I go to the bathroom?이라고 물어요."}, {"q": "Can I sit here?의 뜻은?", "choices": ["여기 앉아도 돼요?", "나가도 돼요?", "물 마셔도 돼요?", "여기 있어요."], "answer": 0, "explain": "sit은 앉다, here는 여기예요."}, {"q": "허락할 때 하는 대답은?", "choices": ["Sorry, you can't.", "No, I don't.", "Bye!", "Sure!"], "answer": 3, "explain": "Sure!는 \"그럼, 물론이지!\"라는 허락의 말이에요."}, {"q": "더 공손하게 부탁할 때 붙이는 말은?", "choices": ["please", "sorry", "hello", "bye"], "answer": 0, "explain": "please를 붙이면 공손한 부탁이 돼요."}, {"q": "🍪 엄마가 쿠키를 먹어도 된다고 했어요. 내가 할 말은?", "choices": ["Sorry.", "Can I?", "Thank you!", "Hello!"], "answer": 2, "explain": "부탁을 들어주면 Thank you!라고 해요."}], "summary": ["Can I ~?는 \"~해도 돼요?\"예요.", "허락은 Sure! / Yes, you can., 거절은 Sorry, you can't.", "please를 붙이고, 들어주면 Thank you!"], "parent_tip": "Can I ~?는 학교 영어 시간과 실제 생활에서 가장 많이 쓰는 표현 중 하나입니다. 간식이나 TV 시간처럼 아이가 무언가를 원할 때 \"Can I ~, please?\"로 부탁하게 하고 Sure! / Sorry, you can't.로 답해 주세요. 허락을 받으면 Thank you!까지 말하도록 이끌어 주시면 좋습니다.", "narr": {"cover": "assets/audio/n/e1-13_cover.mp3", "s0": "assets/audio/n/e1-13_s0.mp3", "s1": "assets/audio/n/e1-13_s1.mp3", "s2": "assets/audio/n/e1-13_s2.mp3", "s3": "assets/audio/n/e1-13_s3.mp3", "kw": "assets/audio/n/e1-13_kw.mp3", "q0": "assets/audio/n/e1-13_q0.mp3", "q1": "assets/audio/n/e1-13_q1.mp3", "q2": "assets/audio/n/e1-13_q2.mp3", "q3": "assets/audio/n/e1-13_q3.mp3", "q4": "assets/audio/n/e1-13_q4.mp3", "sum": "assets/audio/n/e1-13_sum.mp3"}}$j$::jsonb,13) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','3단계 · Can I ~? 부탁하기',13,'e1-13' where not exists (select 1 from public.topics where lesson_slug='e1-13');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e1-14','1~2','영어','3단계 · 짧은 이야기 읽기','영어 이야기를 혼자 읽어 볼까?','assets/img/l_e1-14.jpg',$j${"intro": "📖 짧은 영어 이야기를 읽어 봐요. 배운 낱말이 많이 나와요!", "sections": [{"heading": "이야기를 읽어요: My Cat", "paras": ["손가락으로 낱말을 짚으며 천천히 읽어요.", "듣기 버튼으로 먼저 들어도 좋아요. 🔊"], "example": "I have a cat. 🐱 My cat is big. It is black. It can run. I like my cat!", "figure": "책상 위에 펼친 그림책과 검은 고양이 인형"}, {"heading": "문장 하나씩 뜻을 알아봐요", "paras": ["I have a cat. 나는 고양이가 있어요.", "My cat is big. 내 고양이는 커요.", "It is black. 그것은 까매요."], "example": "It can run. 그것은 달릴 수 있어요. I like my cat! 나는 내 고양이가 좋아요!", "figure": "커다란 검은 고양이가 달리는 모습"}, {"heading": "It은 누구일까요?", "paras": ["It은 \"그것\"이라는 뜻이에요.", "이야기에서 It은 앞에 나온 고양이예요. 🐱", "같은 말을 또 하지 않으려고 It을 써요."], "example": "My cat is big. It is black. → It = my cat", "figure": "고양이를 가리키는 아이 손가락"}, {"heading": "읽고 나서 생각해요", "paras": ["누가 나왔나요? 어떤 모습인가요?", "이야기 속 낱말에 동그라미를 쳐 봐요."], "example": "Who? 🐱 a cat / What color? black / Big or small? big", "figure": "연필로 낱말에 동그라미를 치는 아이 손"}], "keywords": [{"word": "I have ~.", "meaning": "나는 ~이 있어요(가지고 있어요)."}, {"word": "It", "meaning": "그것. 앞에 나온 것을 다시 가리키는 말"}, {"word": "can", "meaning": "~할 수 있다"}, {"word": "big / small", "meaning": "큰 / 작은"}], "expressions": [{"en": "I have a cat.", "ko": "나는 고양이가 있어요."}, {"en": "My cat is big.", "ko": "내 고양이는 커요."}, {"en": "It is black.", "ko": "그것은 까매요."}, {"en": "It can run.", "ko": "그것은 달릴 수 있어요."}, {"en": "I like my cat!", "ko": "나는 내 고양이가 좋아요!"}, {"en": "big", "ko": "큰", "note": "[빅]"}, {"en": "small", "ko": "작은", "note": "[스몰]"}, {"en": "run", "ko": "달리다", "note": "[런]"}, {"en": "It", "ko": "그것", "note": "[잇]"}, {"en": "have", "ko": "가지고 있다", "note": "[해브]"}], "quiz": [{"q": "이야기에 나오는 동물은?", "choices": ["🐶 dog", "🐱 cat", "🐟 fish", "🐰 rabbit"], "answer": 1, "explain": "I have a cat.이라고 했어요. 고양이예요."}, {"q": "고양이는 무슨 색인가요?", "choices": ["white", "yellow", "black", "red"], "answer": 2, "explain": "It is black.이라고 했어요."}, {"q": "My cat is big.의 뜻은?", "choices": ["내 고양이는 작아요.", "내 고양이는 까매요.", "내 고양이는 달려요.", "내 고양이는 커요."], "answer": 3, "explain": "big은 \"큰\"이에요."}, {"q": "이야기에서 It은 무엇을 가리키나요?", "choices": ["고양이", "나", "엄마", "공"], "answer": 0, "explain": "It은 앞에 나온 my cat을 다시 가리켜요."}, {"q": "고양이가 할 수 있는 것은?", "choices": ["swim 수영하기", "run 달리기", "fly 날기", "sing 노래하기"], "answer": 1, "explain": "It can run.이라고 했어요."}], "summary": ["낱말을 짚으며 천천히 소리 내어 읽어요.", "It은 앞에 나온 것을 다시 가리키는 \"그것\"이에요.", "읽고 나서 누가, 어떤 모습인지 생각해요."], "parent_tip": "처음에는 듣기 버튼이나 부모님 목소리로 이야기를 들려준 뒤, 아이가 손가락으로 짚으며 따라 읽게 해 주세요. 다 읽으면 \"What color is the cat?\"처럼 쉬운 질문을 하고, 아이가 키우고 싶은 동물로 \"I have a dog. It is small.\"처럼 이야기를 바꿔 지어 보게 하면 좋습니다.", "narr": {"cover": "assets/audio/n/e1-14_cover.mp3", "s0": "assets/audio/n/e1-14_s0.mp3", "s1": "assets/audio/n/e1-14_s1.mp3", "s2": "assets/audio/n/e1-14_s2.mp3", "s3": "assets/audio/n/e1-14_s3.mp3", "kw": "assets/audio/n/e1-14_kw.mp3", "q0": "assets/audio/n/e1-14_q0.mp3", "q1": "assets/audio/n/e1-14_q1.mp3", "q2": "assets/audio/n/e1-14_q2.mp3", "q3": "assets/audio/n/e1-14_q3.mp3", "q4": "assets/audio/n/e1-14_q4.mp3", "sum": "assets/audio/n/e1-14_sum.mp3"}}$j$::jsonb,14) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','영어','3단계 · 짧은 이야기 읽기',14,'e1-14' where not exists (select 1 from public.topics where lesson_slug='e1-14');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-01','3~4','일본어','일본어 글자 세 가지','일본어는 왜 글자가 세 가지나 있을까?','assets/img/l_j3-01.jpg',$j${"intro": "일본 그림책을 펼쳐 보면 동글동글한 글자, 뾰족뾰족 각진 글자, 복잡한 네모 글자가 섞여 있어요. 일본어에는 글자가 세 가지나 있거든요! 오늘은 세 글자가 각각 어떤 일을 하는지 알아봐요.", "sections": [{"heading": "동글동글 기본 글자, 히라가나", "paras": ["일본 아이들이 가장 먼저 배우는 글자는 히라가나(ひらがな, hiragana, 히라가나)예요. 모양이 둥글둥글하고 부드러워요.", "한글 '가'가 한 소리를 내는 것처럼, 히라가나도 한 글자가 한 소리를 내요. 예를 들어 あ는 '아', ね는 '네', こ는 '코' 소리예요.", "히라가나는 기본 글자가 46개예요. 일본어 낱말과 문장의 뼈대가 되는 글자라서 우리도 히라가나부터 배워요."], "example": "🐱 ねこ(neko, 네코) = 고양이 / ⛰️ やま(yama, 야마) = 산", "figure": "둥글둥글한 히라가나 글자 카드 あ, ね, こ 가 책상 위에 놓여 있는 모습"}, {"heading": "뾰족뾰족 각진 글자, 가타카나", "paras": ["두 번째 글자는 가타카나(カタカナ, katakana, 카타카나)예요. 직선이 많아서 각지고 뾰족해 보여요.", "가타카나는 주로 다른 나라에서 들어온 말을 쓸 때 써요. 빵, 텔레비전, 바나나 같은 낱말이에요.", "히라가나와 가타카나는 소리가 같고 모양만 달라요. 히라가나 あ와 가타카나 ア는 둘 다 '아' 소리예요."], "example": "🍞 パン(pan, 팡) = 빵 — 아주 옛날 포르투갈 말에서 들어온 낱말이라 가타카나로 써요.", "figure": "왼쪽에는 둥근 히라가나 あ, 오른쪽에는 각진 가타카나 ア 카드가 나란히 놓인 모습"}, {"heading": "뜻을 담은 글자, 한자", "paras": ["세 번째 글자는 한자(かんじ, kanji, 칸지)예요. 아주 옛날 중국에서 들어온 글자로, 글자 하나하나에 뜻이 들어 있어요.", "예를 들어 山이라는 한자는 '산'이라는 뜻이고, 일본어로 やま(yama, 야마)라고 읽어요.", "한자는 어려워서 어린이 책에서는 한자 위에 작은 히라가나를 붙여 읽는 법을 알려 줘요. 이 작은 글자를 '후리가나'라고 해요."], "example": "山 위에 작게 やま → '야마'라고 읽어요. 뜻은 '산' ⛰️", "figure": "한자 山 위에 작은 히라가나 やま 가 붙어 있는 그림책 한 쪽"}, {"heading": "세 글자가 한 문장에 함께 나와요", "paras": ["일본어 문장에는 세 글자가 섞여서 나와요. 한자로 뜻을 보여 주고, 히라가나로 문장을 이어 주고, 가타카나로 외국에서 온 말을 써요.", "우리말은 한글 한 가지로 쓰지만, 일본어는 세 가지를 함께 써요. 처음엔 어려워 보여도 히라가나부터 차근차근 익히면 괜찮아요."], "example": "山で パンを たべます。(야마데 팡오 타베마스) = 산에서 빵을 먹어요. → 山(한자), パン(가타카나), で・を・たべます(히라가나)", "figure": "한 문장의 글자들이 한자는 빨강, 히라가나는 파랑, 가타카나는 초록 색연필로 동그라미 쳐진 공책"}], "keywords": [{"word": "히라가나", "meaning": "둥글둥글한 일본어 기본 글자. 일본 아이들이 가장 먼저 배워요."}, {"word": "가타카나", "meaning": "각진 일본어 글자. 다른 나라에서 들어온 말을 쓸 때 주로 써요."}, {"word": "한자", "meaning": "옛날 중국에서 들어온 글자. 글자마다 뜻이 있어요."}, {"word": "후리가나", "meaning": "한자 위에 작게 써서 읽는 법을 알려 주는 히라가나."}], "expressions": [{"en": "ひらがな", "ko": "히라가나 (동글동글한 기본 글자)", "note": "hiragana (히라가나)"}, {"en": "カタカナ", "ko": "가타카나 (각진 글자)", "note": "katakana (카타카나)"}, {"en": "かんじ", "ko": "한자 (뜻을 담은 글자)", "note": "kanji (칸지)"}, {"en": "にほんご", "ko": "일본어", "note": "nihongo (니홍고)"}, {"en": "あ", "ko": "히라가나 '아'", "note": "a (아)"}, {"en": "ア", "ko": "가타카나 '아' (あ와 소리가 같아요)", "note": "a (아)"}, {"en": "ねこ", "ko": "고양이 🐱", "note": "neko (네코)"}, {"en": "やま", "ko": "산 ⛰️ (한자로 山)", "note": "yama (야마)"}, {"en": "パン", "ko": "빵 🍞", "note": "pan (팡)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (콘니치와)"}], "quiz": [{"q": "일본 아이들이 가장 먼저 배우는 동글동글한 글자는 무엇일까요?", "choices": ["가타카나", "히라가나", "한자", "알파벳"], "answer": 1, "explain": "히라가나는 둥글둥글한 기본 글자로, 일본 아이들이 가장 먼저 배워요."}, {"q": "🍞 '빵'을 뜻하는 パン은 어떤 글자로 썼을까요?", "choices": ["히라가나", "한자", "가타카나", "한글"], "answer": 2, "explain": "パン은 다른 나라에서 들어온 말이라서 각진 글자인 가타카나로 써요."}, {"q": "글자 하나하나에 뜻이 들어 있는 글자는 무엇일까요?", "choices": ["한자", "히라가나", "가타카나", "후리가나"], "answer": 0, "explain": "한자는 山(산)처럼 글자마다 뜻이 있어요."}, {"q": "히라가나 あ와 가타카나 ア를 바르게 설명한 것은 무엇일까요?", "choices": ["모양도 소리도 같아요.", "모양도 소리도 달라요.", "모양은 같고 소리가 달라요.", "모양은 다르고 소리는 같아요."], "answer": 3, "explain": "あ와 ア는 모양은 다르지만 둘 다 '아' 소리예요."}, {"q": "한자 위에 작게 써서 읽는 법을 알려 주는 히라가나를 무엇이라고 할까요?", "choices": ["가타카나", "후리가나", "알파벳", "받침"], "answer": 1, "explain": "한자 위에 붙는 작은 히라가나를 후리가나라고 해요."}], "summary": ["일본어 글자는 히라가나, 가타카나, 한자 세 가지예요.", "히라가나는 기본 글자, 가타카나는 외국에서 온 말, 한자는 뜻을 담은 글자예요.", "히라가나와 가타카나는 소리가 같고 모양만 달라서, 히라가나부터 배우면 돼요."], "parent_tip": "부모님께: 아이가 세 글자를 한꺼번에 외우려 하면 부담을 느낍니다. 오늘은 '글자가 세 종류 있고 하는 일이 다르다'는 것만 알아도 충분합니다. 집에 있는 일본 과자 봉지나 장난감 상자를 보며 '이건 둥근 글자일까, 각진 글자일까?' 하고 찾아보는 놀이를 해 보세요."}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','일본어 글자 세 가지',1,'j3-01' where not exists (select 1 from public.topics where lesson_slug='j3-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-02','3~4','일본어','히라가나 あ행·か행','あいうえお, かきくけこ는 어떻게 읽을까?','assets/img/l_j3-02.jpg',$j${"intro": "한글을 배울 때 '가나다라'부터 배웠지요? 일본어 히라가나는 'あいうえお(아이우에오)'부터 시작해요. 오늘은 첫 두 줄인 あ행과 か행 열 글자를 익혀 봐요.", "sections": [{"heading": "일본어의 기본 소리 다섯 개, あ행", "paras": ["あ행은 あ(a, 아), い(i, 이), う(u, 우), え(e, 에), お(o, 오) 다섯 글자예요. 일본어 글자 소리는 거의 모두 이 다섯 소리(모음)로 끝나요.", "우리말 ㅏ, ㅣ, ㅜ, ㅔ, ㅗ와 거의 같아요. 다만 う는 입술을 앞으로 쭉 내밀지 않고 편하게 '우' 하고 소리 내요.", "순서는 꼭 あ, い, う, え, お예요. '아이우에오' 하고 노래처럼 외워 두면 다음 줄도 쉽게 익힐 수 있어요."], "example": "あ(아) い(이) う(우) え(에) お(오)", "figure": "히라가나 あ, い, う, え, お 카드 다섯 장이 한 줄로 놓여 있고, 아이 손가락이 차례로 짚는 모습"}, {"heading": "k 소리를 붙이면 か행", "paras": ["か행은 あ행 소리 앞에 k(ㅋ) 소리를 붙인 줄이에요. か(ka, 카), き(ki, 키), く(ku, 쿠), け(ke, 케), こ(ko, 코)예요.", "낱말 첫머리에서는 '카'에 가깝게, 낱말 가운데에서는 '까'처럼 살짝 세게 들리기도 해요. 둘 다 같은 か 소리예요.", "한글에서 ㅋ과 ㅏ를 합치면 '카'가 되는 것과 비슷해요. 다만 히라가나는 글자 하나가 통째로 '카' 소리를 나타내요."], "example": "k + a → か(카) / k + i → き(키) / k + u → く(쿠) / k + e → け(케) / k + o → こ(코)", "figure": "あいうえお 줄 아래에 かきくけこ 줄이 표처럼 나란히 적힌 공책 한 쪽"}, {"heading": "헷갈리는 글자 구별하기", "paras": ["あ와 お는 아주 비슷해요. お는 오른쪽 위에 작은 점 같은 획이 하나 더 붙어 있어요. 이 점이 있으면 '오'예요.", "い와 こ도 헷갈려요. い는 세로로 두 줄, こ는 가로로 두 줄이에요. '이'는 서 있고, '코'는 누워 있다고 기억해요.", "く는 한 획으로 꺾어 쓰는 글자로, '<' 모양처럼 생겼어요. 입을 벌린 새 부리를 떠올려 보세요."], "example": "あ(아) ↔ お(오): 오른쪽 위 점 확인! / い(이) 세로 두 줄 ↔ こ(코) 가로 두 줄", "figure": "あ와 お, い와 こ 카드를 두 장씩 나란히 놓고 다른 부분에 빨간 동그라미를 친 모습"}, {"heading": "열 글자로 낱말을 읽어요", "paras": ["あ행과 か행만 알아도 읽을 수 있는 낱말이 많아요. 글자를 하나씩 읽고 이어서 말해 보세요.", "いえ는 い(이)와 え(에)를 이어서 '이에', 뜻은 '집'이에요. かお는 '카오', 뜻은 '얼굴'이에요."], "example": "🏠 いえ(ie, 이에) 집 / 😊 かお(kao, 카오) 얼굴 / 🔴 あか(aka, 아카) 빨강 / 🦑 いか(ika, 이카) 오징어 / 🍁 あき(aki, 아키) 가을", "figure": "집, 얼굴, 빨간 사과, 오징어, 단풍잎 그림 카드 아래에 히라가나 낱말이 적힌 모습"}], "keywords": [{"word": "あ행", "meaning": "あ, い, う, え, お 다섯 글자. 일본어의 기본 소리(모음)예요."}, {"word": "か행", "meaning": "か, き, く, け, こ 다섯 글자. あ행 소리에 k(ㅋ) 소리를 붙였어요."}, {"word": "모음", "meaning": "아, 이, 우, 에, 오처럼 목에서 막힘 없이 나오는 소리."}, {"word": "오십음도", "meaning": "히라가나를 あ행, か행… 순서대로 표처럼 늘어놓은 것."}], "expressions": [{"en": "あいうえお", "ko": "あ행 다섯 글자", "note": "a i u e o (아 이 우 에 오)"}, {"en": "かきくけこ", "ko": "か행 다섯 글자", "note": "ka ki ku ke ko (카 키 쿠 케 코)"}, {"en": "いえ", "ko": "집 🏠", "note": "ie (이에)"}, {"en": "かお", "ko": "얼굴 😊", "note": "kao (카오)"}, {"en": "あか", "ko": "빨강 🔴", "note": "aka (아카)"}, {"en": "あお", "ko": "파랑 🔵", "note": "ao (아오)"}, {"en": "いか", "ko": "오징어 🦑", "note": "ika (이카)"}, {"en": "かき", "ko": "감 🟠", "note": "kaki (카키)"}, {"en": "あき", "ko": "가을 🍁", "note": "aki (아키)"}, {"en": "えき", "ko": "역(기차역) 🚉", "note": "eki (에키)"}, {"en": "こえ", "ko": "목소리 🗣️", "note": "koe (코에)"}], "quiz": [{"q": "あ행 글자의 순서로 알맞은 것은 무엇일까요?", "choices": ["あ い う え お", "あ う い お え", "あ い え う お", "お え う い あ"], "answer": 0, "explain": "あ행은 あ(아), い(이), う(우), え(에), お(오) 순서예요."}, {"q": "'코' 소리를 나타내는 히라가나는 무엇일까요?", "choices": ["い", "く", "こ", "け"], "answer": 2, "explain": "こ는 가로 두 줄로 쓰는 글자로 '코'라고 읽어요. 세로 두 줄인 い는 '이'예요."}, {"q": "😊 '얼굴'을 뜻하는 낱말은 무엇일까요?", "choices": ["いえ", "あか", "えき", "かお"], "answer": 3, "explain": "かお(kao, 카오)는 얼굴이에요. いえ는 집, あか는 빨강, えき는 역이에요."}, {"q": "あ와 お를 구별하는 방법으로 알맞은 것은 무엇일까요?", "choices": ["お는 오른쪽 위에 점 같은 획이 하나 더 있어요.", "あ가 お보다 획이 더 많아요.", "お는 세로 두 줄로 써요.", "둘은 소리가 같아요."], "answer": 0, "explain": "お는 오른쪽 위에 작은 획이 하나 더 있고 '오'라고 읽어요."}, {"q": "いか는 어떻게 읽을까요?", "choices": ["이카", "이코", "아카", "코카"], "answer": 0, "explain": "い(이) + か(카) = いか(이카), 뜻은 오징어 🦑 예요."}], "summary": ["あ행은 あ(아) い(이) う(우) え(에) お(오), 일본어의 기본 소리예요.", "か행은 k 소리를 붙인 か(카) き(키) く(쿠) け(케) こ(코)예요.", "あ와 お, い와 こ처럼 닮은 글자는 다른 부분을 찾아 구별해요."], "parent_tip": "부모님께: 아이들은 あ/お, い/こ를 자주 헷갈립니다. 글자 카드를 만들어 부모님이 소리를 말하면 아이가 카드를 고르는 놀이를 해 보세요. 'いえ(집)', 'かお(얼굴)'처럼 아는 물건을 가리키며 일본어로 말해 보면 오래 기억합니다."}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','히라가나 あ행·か행',2,'j3-02' where not exists (select 1 from public.topics where lesson_slug='j3-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-03','3~4','일본어','히라가나 さ행·た행·な행','すし, ねこ, いぬ를 히라가나로 읽어 볼까?','assets/img/l_j3-03.jpg',$j${"intro": "초밥을 일본어로 すし(스시)라고 해요. 오늘 배울 さ행·た행·な행 글자를 알면 すし, ねこ(고양이), いぬ(개)도 혼자 읽을 수 있어요!", "sections": [{"heading": "s 소리 줄, さ행", "paras": ["さ행은 さ(sa, 사), し(shi, 시), す(su, 스), せ(se, 세), そ(so, 소)예요.", "し는 로마자로 si가 아니라 shi라고 써요. 소리는 우리말 '시'와 거의 같아요.", "す는 '수'보다는 입술을 덜 내밀어 '스'에 가깝게 소리 내요."], "example": "🍣 すし(sushi, 스시) 초밥 / 🪑 いす(isu, 이스) 의자 / 🐄 うし(ushi, 우시) 소", "figure": "초밥 접시, 작은 의자, 소 인형 옆에 히라가나 카드가 놓인 모습"}, {"heading": "t 소리 줄, た행 — ち와 つ를 조심해요", "paras": ["た행은 た(ta, 타), ち(chi, 치), つ(tsu, 츠), て(te, 테), と(to, 토)예요.", "ち는 ti가 아니라 chi로 '치' 소리예요. つ는 tsu로, 혀끝을 윗니 뒤에 댔다가 떼며 '츠' 하고 소리 내요. 우리말에 딱 맞는 소리가 없어서 연습이 필요해요.", "さ와 ち는 거울에 비친 것처럼 닮았어요. さ의 아랫부분은 영어 c처럼 왼쪽으로 둥글고, ち의 아랫부분은 숫자 5의 아래처럼 오른쪽으로 둥글어요."], "example": "🐙 たこ(tako, 타코) 문어 / 👟 くつ(kutsu, 쿠츠) 신발 / ☀️ なつ(natsu, 나츠) 여름", "figure": "문어 인형과 운동화 한 켤레가 나란히 놓이고, さ와 ち 카드를 마주 놓아 모양을 비교하는 모습"}, {"heading": "n 소리 줄, な행", "paras": ["な행은 な(na, 나), に(ni, 니), ぬ(nu, 누), ね(ne, 네), の(no, 노)예요. 우리말과 소리가 거의 같아서 쉬워요.", "ぬ는 끝에 작은 고리가 있어요. ね도 끝에 고리가 있지만 왼쪽에 세로 막대가 하나 있어요.", "の는 한 번에 빙글 돌려 쓰는 글자예요. '~의'라는 뜻으로 아주 자주 나와요."], "example": "🐶 いぬ(inu, 이누) 개 / 🐱 ねこ(neko, 네코) 고양이 / 🍆 なす(nasu, 나스) 가지", "figure": "강아지와 고양이 인형 앞에 히라가나 いぬ, ねこ 카드가 놓여 있는 모습"}, {"heading": "배운 글자로 낱말 읽기", "paras": ["이제 あ행부터 な행까지 25글자를 배웠어요. 읽을 수 있는 낱말이 훨씬 많아졌어요.", "さかな는 さ(사)+か(카)+な(나)로 '사카나', 뜻은 물고기예요. つくえ는 '츠쿠에', 뜻은 책상이에요."], "example": "🐟 さかな(sakana, 사카나) 물고기 / 📚 つくえ(tsukue, 츠쿠에) 책상 / ☂️ かさ(kasa, 카사) 우산", "figure": "책상 위에 물고기 그림 카드와 접힌 우산이 놓여 있는 장면"}], "keywords": [{"word": "さ행", "meaning": "さ, し, す, せ, そ. s 소리 줄인데 し만 shi(시)예요."}, {"word": "た행", "meaning": "た, ち, つ, て, と. ち는 chi(치), つ는 tsu(츠)예요."}, {"word": "な행", "meaning": "な, に, ぬ, ね, の. 우리말 '나니누네노'와 소리가 비슷해요."}, {"word": "로마자", "meaning": "일본어 소리를 알파벳으로 적은 것. 예: すし → sushi."}], "expressions": [{"en": "さしすせそ", "ko": "さ행 다섯 글자", "note": "sa shi su se so (사 시 스 세 소)"}, {"en": "たちつてと", "ko": "た행 다섯 글자", "note": "ta chi tsu te to (타 치 츠 테 토)"}, {"en": "なにぬねの", "ko": "な행 다섯 글자", "note": "na ni nu ne no (나 니 누 네 노)"}, {"en": "すし", "ko": "초밥 🍣", "note": "sushi (스시)"}, {"en": "いぬ", "ko": "개 🐶", "note": "inu (이누)"}, {"en": "ねこ", "ko": "고양이 🐱", "note": "neko (네코)"}, {"en": "さかな", "ko": "물고기 🐟", "note": "sakana (사카나)"}, {"en": "たこ", "ko": "문어 🐙", "note": "tako (타코)"}, {"en": "くつ", "ko": "신발 👟", "note": "kutsu (쿠츠)"}, {"en": "なつ", "ko": "여름 ☀️", "note": "natsu (나츠)"}, {"en": "つくえ", "ko": "책상", "note": "tsukue (츠쿠에)"}], "quiz": [{"q": "し를 로마자로 바르게 쓴 것은 무엇일까요?", "choices": ["si", "shi", "chi", "tsu"], "answer": 1, "explain": "し는 si가 아니라 shi라고 쓰고 '시'라고 읽어요."}, {"q": "'츠' 소리를 나타내는 히라가나는 무엇일까요?", "choices": ["ち", "て", "つ", "す"], "answer": 2, "explain": "つ(tsu)는 '츠' 소리예요. ち는 '치', て는 '테', す는 '스'예요."}, {"q": "🐶 '개'를 뜻하는 낱말은 무엇일까요?", "choices": ["ねこ", "いぬ", "たこ", "うし"], "answer": 1, "explain": "いぬ(inu, 이누)가 개예요. ねこ는 고양이, たこ는 문어, うし는 소예요."}, {"q": "さかな는 어떻게 읽을까요?", "choices": ["사카나", "사타나", "치카나", "사카네"], "answer": 0, "explain": "さ(사) + か(카) + な(나) = さかな(사카나), 물고기예요."}, {"q": "な행 글자의 순서로 알맞은 것은 무엇일까요?", "choices": ["な ぬ に ね の", "な に ね ぬ の", "の ね ぬ に な", "な に ぬ ね の"], "answer": 3, "explain": "な행은 な(나) に(니) ぬ(누) ね(네) の(노) 순서예요."}], "summary": ["さ행은 さ し す せ そ(사 시 스 세 소), し는 shi예요.", "た행은 た ち つ て と(타 치 츠 테 토), ち는 chi, つ는 tsu예요.", "な행은 な に ぬ ね の(나 니 누 네 노)로 우리말과 소리가 비슷해요."], "parent_tip": "부모님께: し(shi), ち(chi), つ(tsu)는 로마자가 규칙과 달라 아이들이 자주 틀립니다. 또 さ/ち, ぬ/ね는 모양이 닮아 헷갈리기 쉽습니다. 'すし', 'いぬ', 'ねこ'처럼 좋아하는 음식과 동물 이름을 종이에 써서 냉장고에 붙여 두고 오가며 읽어 보게 해 주세요."}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','히라가나 さ행·た행·な행',3,'j3-03' where not exists (select 1 from public.topics where lesson_slug='j3-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-04','3~4','일본어','히라가나 は행·ま행','はな, ほし, みみ는 무슨 뜻일까?','assets/img/l_j3-04.jpg',$j${"intro": "봄에 피는 꽃을 일본어로 はな(하나), 밤하늘의 별을 ほし(호시)라고 해요. 오늘은 は행과 ま행 열 글자를 배워서 꽃, 별, 귀 같은 낱말을 읽어 봐요.", "sections": [{"heading": "h 소리 줄, は행 — ふ를 조심해요", "paras": ["は행은 は(ha, 하), ひ(hi, 히), ふ(fu, 후), へ(he, 헤), ほ(ho, 호)예요.", "ふ는 로마자로 fu라고 써요. 윗니로 아랫입술을 무는 영어 f가 아니라, 입술을 살짝 오므리고 바람을 내보내며 '후' 하고 소리 내요.", "へ는 산 모양 '^'처럼 생긴 쉬운 글자예요. 가타카나 ヘ도 거의 똑같이 생겼어요."], "example": "🌸 はな(hana, 하나) 꽃 / 🧍 ひと(hito, 히토) 사람 / 🚢 ふね(fune, 후네) 배 / ⭐ ほし(hoshi, 호시) 별", "figure": "꽃 한 송이, 작은 장난감 배, 별 모양 스티커가 책상 위에 놓인 모습"}, {"heading": "は와 ほ를 구별해요", "paras": ["は와 ほ는 아주 닮았어요. ほ는 오른쪽 위에 가로줄이 하나 더 있어서 위쪽이 막혀 있어요.", "위가 열려 있으면 は(하), 위가 막혀 있으면 ほ(호)예요. 손가락으로 오른쪽 윗부분을 짚어 보며 확인해요."], "example": "は(하) — 오른쪽 위가 열려 있어요 / ほ(호) — 오른쪽 위에 가로줄이 하나 더 있어요", "figure": "は 카드와 ほ 카드를 나란히 놓고 ほ의 맨 위 가로줄에 빨간 동그라미를 친 모습"}, {"heading": "m 소리 줄, ま행", "paras": ["ま행은 ま(ma, 마), み(mi, 미), む(mu, 무), め(me, 메), も(mo, 모)예요. 우리말 '마미무메모'와 소리가 거의 같아요.", "め와 지난 시간에 배운 ぬ는 쌍둥이처럼 닮았어요. ぬ는 끝에 작은 고리가 있고, め는 고리 없이 끝나요.", "め는 혼자서 '눈 👁️'이라는 뜻의 낱말도 돼요. 글자 하나짜리 낱말이에요."], "example": "👂 みみ(mimi, 미미) 귀 / 🍑 もも(momo, 모모) 복숭아 / 🐛 むし(mushi, 무시) 벌레 / 👁️ め(me, 메) 눈", "figure": "복숭아 두 개와 돋보기로 작은 벌레 장난감을 보는 아이 손"}, {"heading": "알아 두면 좋은 것: は를 '와'로 읽을 때", "paras": ["は는 보통 '하'로 읽지만, 문장에서 '~은/는'이라는 뜻으로 쓰일 때는 '와(wa)'로 읽어요.", "그래서 인사말 こんにちは도 끝의 は를 '와'로 읽어 '콘니치와'가 돼요. 지금은 '이럴 때도 있구나' 하고 알아 두기만 하면 돼요."], "example": "はな(하나) 꽃 → は를 '하'로 읽어요 / こんにちは(콘니치와) → 끝의 は를 '와'로 읽어요", "figure": "공책에 はな와 こんにちは를 쓰고 は 글자 아래에 각각 '하', '와'라고 작게 적은 모습"}], "keywords": [{"word": "は행", "meaning": "は, ひ, ふ, へ, ほ. h 소리 줄인데 ふ만 fu(후)예요."}, {"word": "ま행", "meaning": "ま, み, む, め, も. 우리말 '마미무메모'와 소리가 비슷해요."}, {"word": "조사 は", "meaning": "'~은/는'이라는 뜻으로 쓰는 は. 이때는 '와(wa)'로 읽어요."}], "expressions": [{"en": "はひふへほ", "ko": "は행 다섯 글자", "note": "ha hi fu he ho (하 히 후 헤 호)"}, {"en": "まみむめも", "ko": "ま행 다섯 글자", "note": "ma mi mu me mo (마 미 무 메 모)"}, {"en": "はな", "ko": "꽃 🌸 (코라는 뜻도 있어요)", "note": "hana (하나)"}, {"en": "ほし", "ko": "별 ⭐", "note": "hoshi (호시)"}, {"en": "ふね", "ko": "배 🚢", "note": "fune (후네)"}, {"en": "ひと", "ko": "사람 🧍", "note": "hito (히토)"}, {"en": "みみ", "ko": "귀 👂", "note": "mimi (미미)"}, {"en": "もも", "ko": "복숭아 🍑", "note": "momo (모모)"}, {"en": "むし", "ko": "벌레 🐛", "note": "mushi (무시)"}, {"en": "め", "ko": "눈 👁️", "note": "me (메)"}, {"en": "あたま", "ko": "머리", "note": "atama (아타마)"}], "quiz": [{"q": "ふ를 로마자로 바르게 쓴 것은 무엇일까요?", "choices": ["hu", "pu", "fu", "bu"], "answer": 2, "explain": "ふ는 fu라고 쓰고, 입술을 살짝 오므려 '후'라고 읽어요."}, {"q": "ほ와 は를 구별하는 방법으로 알맞은 것은 무엇일까요?", "choices": ["ほ는 오른쪽 위에 가로줄이 하나 더 있어요.", "は가 ほ보다 획이 더 많아요.", "ほ는 끝에 고리가 없어요.", "둘은 소리가 같아요."], "answer": 0, "explain": "ほ(호)는 오른쪽 위에 가로줄이 하나 더 있어 위가 막혀 있어요."}, {"q": "👂 '귀'를 뜻하는 낱말은 무엇일까요?", "choices": ["もも", "むし", "はな", "みみ"], "answer": 3, "explain": "みみ(mimi, 미미)는 귀예요. もも는 복숭아, むし는 벌레, はな는 꽃이에요."}, {"q": "끝에 작은 고리가 __없는__ 글자는 무엇일까요?", "choices": ["ぬ", "め", "ね", "ま"], "answer": 1, "explain": "め(메)는 고리 없이 끝나요. ぬ, ね, ま는 끝에 고리가 있어요."}, {"q": "こんにちは의 끝 글자 は는 어떻게 읽을까요?", "choices": ["하", "호", "와", "바"], "answer": 2, "explain": "'~은/는'에서 온 は라서 '와(wa)'로 읽어 '콘니치와'가 돼요."}], "summary": ["は행은 は ひ ふ へ ほ(하 히 후 헤 호), ふ는 fu예요.", "ま행은 ま み む め も(마 미 무 메 모)예요.", "は/ほ, ぬ/め는 닮은 글자라서 다른 부분을 찾아 구별해요."], "parent_tip": "부모님께: 아이들은 は/ほ, ぬ/め를 자주 헷갈립니다. 두 글자를 크게 써서 '다른 곳 찾기' 놀이를 해 보세요. 또 は를 '와'로 읽는 경우는 지금 깊이 설명하지 않아도 됩니다. 'みみ(귀)', 'め(눈)', 'あたま(머리)'처럼 몸을 가리키며 말해 보는 놀이도 좋습니다."}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','히라가나 は행·ま행',4,'j3-04' where not exists (select 1 from public.topics where lesson_slug='j3-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-05','3~4','일본어','히라가나 や행·ら행·わ행·ん','히라가나 마지막 글자 ん까지 다 읽어 볼까?','assets/img/l_j3-05.jpg',$j${"intro": "드디어 히라가나 46글자의 마지막 부분이에요! や행, ら행, わ행과 특별한 글자 ん을 배우면 기본 히라가나를 모두 읽을 수 있어요.", "sections": [{"heading": "세 글자뿐인 や행", "paras": ["や행은 や(ya, 야), ゆ(yu, 유), よ(yo, 요) 세 글자예요. 다른 줄과 달리 다섯 글자가 아니라 세 글자뿐이에요.", "오십음도 표에서 や행의 い 자리와 え 자리는 비어 있어요. 그 자리에 쓰던 글자는 오늘날 쓰지 않거든요."], "example": "⛰️ やま(yama, 야마) 산 / ❄️ ゆき(yuki, 유키) 눈 / 🌙 よる(yoru, 요루) 밤", "figure": "창밖으로 눈 덮인 산과 밤하늘의 달이 보이는 창가 책상 풍경"}, {"heading": "r 소리 줄, ら행", "paras": ["ら행은 ら(ra, 라), り(ri, 리), る(ru, 루), れ(re, 레), ろ(ro, 로)예요. 로마자는 r이지만 소리는 우리말 'ㄹ'과 거의 같아요.", "る와 ろ는 닮았어요. る는 아래에 작은 고리가 있고, ろ는 고리 없이 끝나요.", "れ, わ, ね는 왼쪽에 세로 막대가 있는 삼총사예요. 끝을 보고 구별해요. れ는 끝이 바깥으로 툭 튀어나가고, わ는 둥글게 감싸고, ね는 작은 고리로 끝나요."], "example": "🐿️ りす(risu, 리스) 다람쥐 / 🐒 さる(saru, 사루) 원숭이 / 🚗 くるま(kuruma, 쿠루마) 자동차 / ☁️ そら(sora, 소라) 하늘", "figure": "れ, わ, ね 카드 세 장을 나란히 놓고 끝부분에 서로 다른 색 동그라미를 친 모습"}, {"heading": "わ, を 그리고 특별한 글자 ん", "paras": ["わ행에는 わ(wa, 와)와 を(o, 오) 두 글자가 있어요. を는 お와 똑같이 '오'라고 읽지만, 문장에서 '~을/를'이라는 뜻으로만 써요.", "ん(n, 응)은 혼자서 한 박자를 차지하는 특별한 글자예요. 우리말 받침처럼 앞 글자에 붙어서 소리 나고, 낱말 맨 앞에는 절대 오지 않아요.", "ん은 뒤에 오는 소리에 따라 'ㄴ', 'ㅁ', 'ㅇ' 받침처럼 들려요. 낱말 끝에 오면 콧소리 'ㅇ'에 가깝게 들려요."], "example": "📖 ほん(hon, 홍) 책 / 🍊 みかん(mikan, 미캉) 귤 / 📖 ほんを よみます(hon o yomimasu, 홍오 요미마스) 책을 읽어요", "figure": "펼친 그림책 옆에 귤 두 개가 놓인 책상"}, {"heading": "히라가나 46글자를 다 배웠어요", "paras": ["あ행부터 ん까지 기본 히라가나 46글자를 모두 배웠어요. 이제 어떤 히라가나 낱말이든 한 글자씩 읽어 낼 수 있어요.", "헷갈리는 글자가 있으면 오십음도 표를 보며 다시 확인해요. 매일 다섯 글자씩 소리 내어 읽으면 금방 익숙해져요."], "example": "🐊 わに(wani, 와니) 악어 / 🙋 わたし(watashi, 와타시) 나 / 💭 ゆめ(yume, 유메) 꿈", "figure": "벽에 붙은 히라가나 오십음도 표 앞에서 아이가 손가락으로 글자를 짚는 모습(글자는 흐리게)"}], "keywords": [{"word": "や행", "meaning": "や, ゆ, よ 세 글자뿐인 줄."}, {"word": "ら행", "meaning": "ら, り, る, れ, ろ. 우리말 'ㄹ' 소리와 비슷해요."}, {"word": "を", "meaning": "'오'로 읽고, 문장에서 '~을/를'이라는 뜻으로만 쓰는 글자."}, {"word": "ん", "meaning": "받침처럼 앞 글자에 붙어 소리 나는 글자. 낱말 맨 앞에는 오지 않아요."}, {"word": "오십음도", "meaning": "히라가나를 줄과 칸에 맞춰 늘어놓은 표."}], "expressions": [{"en": "やゆよ", "ko": "や행 세 글자", "note": "ya yu yo (야 유 요)"}, {"en": "らりるれろ", "ko": "ら행 다섯 글자", "note": "ra ri ru re ro (라 리 루 레 로)"}, {"en": "わをん", "ko": "わ, を, ん", "note": "wa o n (와 오 응)"}, {"en": "ゆき", "ko": "눈(하늘에서 내리는 눈) ❄️", "note": "yuki (유키)"}, {"en": "よる", "ko": "밤 🌙", "note": "yoru (요루)"}, {"en": "そら", "ko": "하늘 ☁️", "note": "sora (소라)"}, {"en": "さる", "ko": "원숭이 🐒", "note": "saru (사루)"}, {"en": "くるま", "ko": "자동차 🚗", "note": "kuruma (쿠루마)"}, {"en": "わに", "ko": "악어 🐊", "note": "wani (와니)"}, {"en": "ほん", "ko": "책 📖", "note": "hon (홍)"}, {"en": "みかん", "ko": "귤 🍊", "note": "mikan (미캉)"}, {"en": "ほんを よみます", "ko": "책을 읽어요", "note": "hon o yomimasu (홍오 요미마스)"}], "quiz": [{"q": "や행에 들어 있는 글자가 __아닌__ 것은 무엇일까요?", "choices": ["や", "ゆ", "よ", "わ"], "answer": 3, "explain": "や행은 や, ゆ, よ 세 글자예요. わ는 わ행 글자예요."}, {"q": "아래에 작은 고리가 있는 글자는 무엇일까요?", "choices": ["ろ", "る", "ら", "り"], "answer": 1, "explain": "る(루)는 아래에 고리가 있고, ろ(로)는 고리 없이 끝나요."}, {"q": "を에 대한 설명으로 알맞은 것은 무엇일까요?", "choices": ["'워'라고 읽어요.", "낱말 맨 앞에 자주 와요.", "'오'라고 읽고 '~을/를'이라는 뜻으로 써요.", "'응'이라고 읽어요."], "answer": 2, "explain": "を는 お와 같이 '오'로 읽고, '~을/를'이라는 뜻으로만 써요."}, {"q": "🍊 みかん은 어떻게 읽을까요?", "choices": ["미캉", "미카", "무캉", "미칸나"], "answer": 0, "explain": "み(미) + か(카) + ん(받침) = 미캉, 뜻은 귤이에요."}, {"q": "ん에 대한 설명으로 알맞은 것은 무엇일까요?", "choices": ["낱말 맨 앞에 와요.", "받침처럼 앞 글자에 붙어 소리 나요.", "'와'라고 읽어요.", "ら행 글자예요."], "answer": 1, "explain": "ん은 받침처럼 앞 글자에 붙어 소리 나고, 낱말 맨 앞에는 오지 않아요."}], "summary": ["や행은 や ゆ よ 세 글자, ら행은 ら り る れ ろ(라 리 루 레 로)예요.", "わ행의 を는 '오'로 읽고 '~을/를'이라는 뜻으로만 써요.", "ん은 받침처럼 소리 나는 글자이고, 이제 기본 히라가나 46글자를 모두 배웠어요."], "parent_tip": "부모님께: れ/わ/ね, る/ろ는 히라가나에서 가장 많이 헷갈리는 글자입니다. 또 ん을 '응'으로 한 글자처럼 따로 읽어 '호응'이라고 하는 실수가 많으니, 앞 글자에 붙여 '홍'처럼 읽도록 도와주세요. 오늘로 기본 히라가나를 다 배웠으니 오십음도 표를 함께 소리 내어 읽어 보며 축하해 주세요."}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','히라가나 や행·ら행·わ행·ん',5,'j3-05' where not exists (select 1 from public.topics where lesson_slug='j3-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-06','3~4','일본어','탁음과 반탁음','점 두 개와 동그라미 하나로 소리가 바뀐다고?','assets/img/l_j3-06.jpg',$j${"intro": "かき(카키)는 '감'인데, き 옆에 작은 점 두 개를 찍으면 かぎ(카기), '열쇠'가 돼요! 오늘은 글자에 점이나 동그라미를 붙여 새 소리를 만드는 방법을 배워요.", "sections": [{"heading": "점 두 개 ゛를 붙이면 탁음", "paras": ["글자 오른쪽 위에 붙이는 작은 점 두 개(゛)를 '탁점'이라고 해요. 탁점이 붙은 글자를 '탁음'이라고 해요.", "탁점은 か행, さ행, た행, は행 네 줄에만 붙어요. 탁점을 붙이면 목이 살짝 울리는 부드러운 소리가 돼요.", "か(카)에 탁점을 붙이면 が(가), さ(사)는 ざ(자), た(타)는 だ(다), は(하)는 ば(바)가 돼요."], "example": "か → が(ga, 가) / さ → ざ(za, 자) / た → だ(da, 다) / は → ば(ba, 바)", "figure": "か 카드 옆에 작은 점 두 개 스티커를 붙여 が로 바꾸는 아이 손"}, {"heading": "탁음 네 줄 읽기", "paras": ["が행은 が(가) ぎ(기) ぐ(구) げ(게) ご(고), ざ행은 ざ(자) じ(지) ず(즈) ぜ(제) ぞ(조)예요.", "だ행은 だ(다) ぢ(지) づ(즈) で(데) ど(도), ば행은 ば(바) び(비) ぶ(부) べ(베) ぼ(보)예요.", "ぢ와 づ는 じ, ず와 소리가 같아요. 쓰이는 낱말이 아주 적어서, '지'와 '즈'는 보통 じ와 ず로 써요."], "example": "🍚 ごはん(gohan, 고항) 밥 / 💧 みず(mizu, 미즈) 물 / 🪟 まど(mado, 마도) 창문 / 🐷 ぶた(buta, 부타) 돼지", "figure": "밥 한 그릇과 물컵이 창가 식탁 위에 놓인 모습"}, {"heading": "동그라미 ゜를 붙이면 반탁음", "paras": ["글자 오른쪽 위에 붙이는 작은 동그라미(゜)를 '반탁점'이라고 해요. 반탁점이 붙은 글자를 '반탁음'이라고 해요.", "반탁점은 は행에만 붙어요. ぱ(pa, 파) ぴ(pi, 피) ぷ(pu, 푸) ぺ(pe, 페) ぽ(po, 포)가 돼요.", "は행에는 탁점도 반탁점도 붙을 수 있어요. は(하), ば(바), ぱ(파) 세 소리를 비교해 보세요."], "example": "✏️ えんぴつ(enpitsu, 엠피츠) 연필 / 🌼 たんぽぽ(tanpopo, 탐포포) 민들레 / 🚶 さんぽ(sanpo, 삼포) 산책", "figure": "연필 한 자루와 노란 민들레 한 송이가 공책 위에 놓인 모습"}, {"heading": "점 하나로 뜻이 달라져요", "paras": ["탁점이 있고 없고에 따라 낱말의 뜻이 완전히 바뀌기도 해요. 그래서 점과 동그라미를 빠뜨리지 않고 써야 해요.", "かき(카키)는 감, かぎ(카기)는 열쇠예요. ふた(후타)는 뚜껑, ぶた(부타)는 돼지예요."], "example": "🟠 かき(감) ↔ 🔑 かぎ(열쇠) / 🫙 ふた(뚜껑) ↔ 🐷 ぶた(돼지)", "figure": "감과 열쇠, 병뚜껑과 돼지 인형을 두 줄로 짝지어 놓은 모습"}], "keywords": [{"word": "탁점", "meaning": "글자 오른쪽 위에 붙이는 점 두 개(゛). か・さ・た・は행에 붙어요."}, {"word": "탁음", "meaning": "탁점이 붙은 글자. が, ざ, だ, ば 줄이에요."}, {"word": "반탁점", "meaning": "글자 오른쪽 위에 붙이는 작은 동그라미(゜). は행에만 붙어요."}, {"word": "반탁음", "meaning": "반탁점이 붙은 글자. ぱ, ぴ, ぷ, ぺ, ぽ예요."}], "expressions": [{"en": "がぎぐげご", "ko": "が행 (か행 + 탁점)", "note": "ga gi gu ge go (가 기 구 게 고)"}, {"en": "ざじずぜぞ", "ko": "ざ행 (さ행 + 탁점)", "note": "za ji zu ze zo (자 지 즈 제 조)"}, {"en": "だぢづでど", "ko": "だ행 (た행 + 탁점)", "note": "da ji zu de do (다 지 즈 데 도)"}, {"en": "ばびぶべぼ", "ko": "ば행 (は행 + 탁점)", "note": "ba bi bu be bo (바 비 부 베 보)"}, {"en": "ぱぴぷぺぽ", "ko": "ぱ행 (は행 + 반탁점)", "note": "pa pi pu pe po (파 피 푸 페 포)"}, {"en": "かぎ", "ko": "열쇠 🔑", "note": "kagi (카기)"}, {"en": "ごはん", "ko": "밥 🍚", "note": "gohan (고항)"}, {"en": "みず", "ko": "물 💧", "note": "mizu (미즈)"}, {"en": "ぶた", "ko": "돼지 🐷", "note": "buta (부타)"}, {"en": "かばん", "ko": "가방 🎒", "note": "kaban (카방)"}, {"en": "えんぴつ", "ko": "연필 ✏️", "note": "enpitsu (엠피츠)"}, {"en": "たんぽぽ", "ko": "민들레 🌼", "note": "tanpopo (탐포포)"}], "quiz": [{"q": "か에 탁점(゛)을 붙이면 어떤 글자가 될까요?", "choices": ["ぱ", "が", "ざ", "だ"], "answer": 1, "explain": "か(카)에 탁점을 붙이면 が(가)가 돼요."}, {"q": "반탁점(゜)이 붙을 수 있는 줄은 어디일까요?", "choices": ["か행", "さ행", "た행", "は행"], "answer": 3, "explain": "반탁점은 は행에만 붙어서 ぱ ぴ ぷ ぺ ぽ가 돼요."}, {"q": "🔑 '열쇠'를 뜻하는 낱말은 무엇일까요?", "choices": ["かぎ", "かき", "かさ", "かお"], "answer": 0, "explain": "かぎ(카기)가 열쇠예요. 점이 없는 かき(카키)는 감이에요."}, {"q": "ぶ는 어떻게 읽을까요?", "choices": ["후", "푸", "부", "구"], "answer": 2, "explain": "ふ(후)에 탁점을 붙인 ぶ는 '부'라고 읽어요. ぷ는 '푸'예요."}, {"q": "다음 중 じ와 소리가 같은 글자는 무엇일까요?", "choices": ["ぢ", "ず", "ぎ", "び"], "answer": 0, "explain": "ぢ는 じ와 같은 '지' 소리예요. 보통은 じ를 더 많이 써요."}], "summary": ["탁점(゛)은 か・さ・た・は행에 붙어 が・ざ・だ・ば행이 돼요.", "반탁점(゜)은 は행에만 붙어 ぱ ぴ ぷ ぺ ぽ(파 피 푸 페 포)가 돼요.", "かき(감)와 かぎ(열쇠)처럼 점 하나로 뜻이 바뀌니 꼭 챙겨 써요."], "parent_tip": "부모님께: 이 단원부터는 か(카)와 が(가), た(타)와 だ(다)처럼 거센소리와 예사소리로 구분해 읽으면 아이가 쉽게 익힙니다. 아이가 글자를 쓸 때 탁점과 반탁점을 자주 빠뜨리니 '점 확인!' 하고 함께 점검해 주세요. 'かき와 かぎ', 'ふた와 ぶた'처럼 뜻이 바뀌는 짝을 퀴즈로 내 보면 재미있어합니다."}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','탁음과 반탁음',6,'j3-06' where not exists (select 1 from public.topics where lesson_slug='j3-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-07','3~4','일본어','인사하기 こんにちは','일본 친구를 만나면 어떻게 인사할까?','assets/img/l_j3-07.jpg',$j${"intro": "우리말에 '안녕하세요', '고마워요', '잘 자'가 있듯이 일본어에도 때에 맞는 인사말이 있어요. 히라가나로 인사말을 읽고, 소리 내어 따라 해 봐요.", "sections": [{"heading": "아침, 낮, 저녁 인사가 달라요", "paras": ["일본어는 시간에 따라 인사말이 달라요. 아침에는 おはようございます(오하요- 고자이마스), 낮에는 こんにちは(콘니치와), 저녁에는 こんばんは(콤방와)라고 해요.", "친구나 가족에게 아침 인사를 할 때는 짧게 おはよう(오하요-)라고만 해도 돼요.", "こんにちは와 こんばんは의 끝 글자 は는 '하'가 아니라 '와'로 읽어요. 꼭 기억해 두세요!"], "example": "🌅 아침: おはようございます(ohayou gozaimasu, 오하요- 고자이마스) / ☀️ 낮: こんにちは(konnichiwa, 콘니치와) / 🌙 저녁: こんばんは(konbanwa, 콤방와)", "figure": "아침 해, 한낮의 해, 저녁 달이 그려진 세 장의 그림 카드가 나란히 놓인 모습"}, {"heading": "う는 앞 소리를 길게 늘여요", "paras": ["おはよう는 '오하요우'라고 또박또박 읽지 않고 '오하요-' 하고 よ를 길게 늘여 읽어요. 이렇게 う가 앞 소리를 길게 만드는 경우가 많아요.", "ありがとう(아리가토-), さようなら(사요-나라)도 마찬가지예요. 이 책에서는 길게 읽는 곳을 '-'로 표시했어요."], "example": "おはよう → 오하요- / ありがとう → 아리가토- / さようなら → 사요-나라", "figure": "고무줄을 길게 늘이는 아이 손 그림 옆에 '요-' 소리를 길게 늘이는 모습을 표현한 그림"}, {"heading": "헤어질 때, 잘 때", "paras": ["헤어질 때는 さようなら(사요-나라)라고 해요. 친구끼리는 またね(마타네, 또 만나)를 더 자주 써요.", "밤에 잠자리에 들 때는 おやすみなさい(오야스미나사이, 안녕히 주무세요)라고 해요."], "example": "👋 またね(matane, 마타네) 또 봐 / 😴 おやすみなさい(oyasuminasai, 오야스미나사이) 잘 자요", "figure": "학교 앞에서 손을 흔들며 헤어지는 두 아이의 뒷모습"}, {"heading": "고마워요, 미안해요, 잘 먹겠습니다", "paras": ["고마울 때는 ありがとう(아리가토-), 더 공손하게는 ありがとうございます(아리가토- 고자이마스)라고 해요. 친구끼리는 짧게 どうも(도-모)라고도 해요. 대답으로는 どういたしまして(도-이타시마시테, 천만에요)라고 해요.", "미안할 때나 '저기요' 하고 부를 때는 すみません(스미마셍)이라고 해요.", "처음 만난 사람에게는 はじめまして(하지메마시테, 처음 뵙겠습니다)라고 해요. 밥 먹기 전에는 いただきます(이타다키마스), 다 먹은 뒤에는 ごちそうさまでした(고치소-사마데시타)라고 해요. 일본 사람들은 인사할 때 고개를 숙이는 '오지기'를 함께 해요."], "example": "🙏 ありがとう(arigatou, 아리가토-) 고마워 / 🍚 いただきます(itadakimasu, 이타다키마스) 잘 먹겠습니다", "figure": "식탁 앞에서 두 손을 모으고 고개를 살짝 숙이는 아이"}], "keywords": [{"word": "인사말", "meaning": "만나고 헤어질 때, 고마울 때 주고받는 말."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. おはよう의 よう는 '요-'로 길게 읽어요."}, {"word": "오지기", "meaning": "일본에서 인사할 때 고개와 허리를 숙이는 몸짓."}], "expressions": [{"en": "おはようございます", "ko": "안녕하세요 (아침 인사)", "note": "ohayou gozaimasu (오하요- 고자이마스)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (콘니치와) — 끝의 は는 '와'"}, {"en": "こんばんは", "ko": "안녕하세요 (저녁 인사)", "note": "konbanwa (콤방와) — 끝의 は는 '와'"}, {"en": "さようなら", "ko": "안녕히 가세요", "note": "sayounara (사요-나라)"}, {"en": "またね", "ko": "또 봐 (친구끼리)", "note": "matane (마타네)"}, {"en": "おやすみなさい", "ko": "안녕히 주무세요, 잘 자요", "note": "oyasuminasai (오야스미나사이)"}, {"en": "ありがとう", "ko": "고마워", "note": "arigatou (아리가토-)"}, {"en": "どういたしまして", "ko": "천만에요", "note": "douitashimashite (도-이타시마시테)"}, {"en": "すみません", "ko": "미안해요 / 저기요", "note": "sumimasen (스미마셍)"}, {"en": "はじめまして", "ko": "처음 뵙겠습니다", "note": "hajimemashite (하지메마시테)"}, {"en": "いただきます", "ko": "잘 먹겠습니다", "note": "itadakimasu (이타다키마스)"}, {"en": "ごちそうさまでした", "ko": "잘 먹었습니다", "note": "gochisousama deshita (고치소-사마데시타)"}], "quiz": [{"q": "🌙 저녁에 만난 사람에게 하는 인사는 무엇일까요?", "choices": ["おはようございます", "こんにちは", "こんばんは", "おやすみなさい"], "answer": 2, "explain": "저녁 인사는 こんばんは(콤방와)예요. おやすみなさい는 잘 때 하는 인사예요."}, {"q": "こんにちは는 어떻게 읽을까요?", "choices": ["콘니치하", "콘니치와", "곤니치히", "콘니치호"], "answer": 1, "explain": "끝의 は는 '와'로 읽어서 '콘니치와'예요."}, {"q": "친구가 선물을 줬을 때 할 말은 무엇일까요?", "choices": ["ありがとう", "すみません", "さようなら", "いただきます"], "answer": 0, "explain": "고마울 때는 ありがとう(아리가토-)라고 해요."}, {"q": "🍚 밥을 다 먹은 뒤에 하는 인사는 무엇일까요?", "choices": ["いただきます", "はじめまして", "またね", "ごちそうさまでした"], "answer": 3, "explain": "다 먹은 뒤에는 ごちそうさまでした(고치소-사마데시타), 먹기 전에는 いただきます라고 해요."}, {"q": "처음 만난 친구에게 하는 인사는 무엇일까요?", "choices": ["おやすみなさい", "はじめまして", "どういたしまして", "ごちそうさまでした"], "answer": 1, "explain": "처음 만났을 때는 はじめまして(하지메마시테)라고 해요."}], "summary": ["아침 おはようございます, 낮 こんにちは, 저녁 こんばんは로 때에 맞게 인사해요.", "こんにちは, こんばんは의 끝 は는 '와'로 읽고, おはよう의 よう는 '요-'로 길게 읽어요.", "ありがとう(고마워), すみません(미안해요), いただきます(잘 먹겠습니다)도 함께 익혀요."], "parent_tip": "부모님께: 인사말은 외우기보다 생활에서 써 보는 것이 가장 좋습니다. 오늘 하루는 아침에 'おはよう', 식사 때 'いただきます', 잘 때 'おやすみなさい'를 가족이 함께 일본어로 말해 보세요. 아이가 こんにちは를 '콘니치하'로 읽으면 끝의 は는 '와'로 읽는다는 점을 다시 짚어 주세요."}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','인사하기 こんにちは',7,'j3-07' where not exists (select 1 from public.topics where lesson_slug='j3-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-08','3~4','일본어','숫자 1~10','いち, に, さん! 일본어로 10까지 세어 볼까?','assets/img/l_j3-08.jpg',$j${"intro": "숨바꼭질할 때 '하나, 둘, 셋' 하고 세지요? 일본 아이들은 'いち, に, さん(이치, 니, 상)' 하고 세어요. 오늘은 일본어로 1부터 10까지 세는 법을 배워요.", "sections": [{"heading": "1부터 5까지", "paras": ["1은 いち(ichi, 이치), 2는 に(ni, 니), 3은 さん(san, 상), 4는 よん(yon, 욘), 5는 ご(go, 고)예요.", "に는 한 글자, ご도 한 글자라서 짧아요. 짧은 숫자일수록 또렷하게 말해요.", "さん의 ん은 받침처럼 앞 글자에 붙어서 한 번에 '상' 하고 소리 내요."], "example": "1️⃣ いち(이치) 2️⃣ に(니) 3️⃣ さん(상) 4️⃣ よん(욘) 5️⃣ ご(고)", "figure": "아이 손가락 다섯 개를 하나씩 펴며 수를 세는 모습"}, {"heading": "6부터 10까지와 작은 ゅ", "paras": ["6은 ろく(roku, 로쿠), 7은 なな(nana, 나나), 8은 はち(hachi, 하치), 9는 きゅう(kyuu, 큐-), 10은 じゅう(juu, 주-)예요.", "きゅう와 じゅう에는 작은 ゅ가 들어 있어요. 작은 ゅ는 앞 글자와 합쳐서 한 소리가 돼요. き(키)+ゅ(유)는 '키유'가 아니라 '큐', じ(지)+ゅ(유)는 '주'예요.", "끝의 う는 앞 소리를 길게 늘여요. 그래서 '큐-', '주-' 하고 길게 읽어요."], "example": "6️⃣ ろく(로쿠) 7️⃣ なな(나나) 8️⃣ はち(하치) 9️⃣ きゅう(큐-) 🔟 じゅう(주-)", "figure": "큰 글자 き 옆에 작은 글자 ゅ 카드를 붙여 놓은 모습"}, {"heading": "읽는 법이 두 가지인 숫자", "paras": ["4, 7, 9는 읽는 법이 두 가지예요. 4는 よん 또는 し(시), 7은 なな 또는 しち(시치), 9는 きゅう 또는 く(쿠)예요.", "보통 수를 셀 때는 よん, なな, きゅう를 더 많이 써요. 이 단원에서도 이 세 가지로 익혀요."], "example": "4 = よん(욘) / し(시) · 7 = なな(나나) / しち(시치) · 9 = きゅう(큐-) / く(쿠)", "figure": "숫자 카드 4, 7, 9 아래에 읽는 법 카드가 두 장씩 놓여 있는 모습"}, {"heading": "숫자로 놀아 봐요", "paras": ["일본어 숫자를 알면 간단한 계산도 일본어로 말할 수 있어요. さん たす よん は なな(상 타스 욘 와 나나)는 '3 더하기 4는 7'이라는 뜻이에요.", "10보다 큰 수는 じゅう 뒤에 숫자를 붙여요. 11은 じゅういち(주-이치), 12는 じゅうに(주-니)예요."], "example": "🍎🍎🍎 + 🍎🍎🍎🍎 → さん たす よん は なな (3 + 4 = 7) / じゅう + いち → じゅういち(11)", "figure": "사과 세 개와 사과 네 개를 모아 일곱 개를 만드는 아이 손"}], "keywords": [{"word": "작은 ゅ", "meaning": "앞 글자와 합쳐져 한 소리가 되는 작은 글자. きゅ(큐), じゅ(주)."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. きゅう는 '큐-'로 읽어요."}, {"word": "たす", "meaning": "'더하기'라는 뜻의 말. 타스라고 읽어요."}], "expressions": [{"en": "いち", "ko": "1, 하나", "note": "ichi (이치)"}, {"en": "に", "ko": "2, 둘", "note": "ni (니)"}, {"en": "さん", "ko": "3, 셋", "note": "san (상)"}, {"en": "よん", "ko": "4, 넷 (し라고도 읽어요)", "note": "yon (욘)"}, {"en": "ご", "ko": "5, 다섯", "note": "go (고)"}, {"en": "ろく", "ko": "6, 여섯", "note": "roku (로쿠)"}, {"en": "なな", "ko": "7, 일곱 (しち라고도 읽어요)", "note": "nana (나나)"}, {"en": "はち", "ko": "8, 여덟", "note": "hachi (하치)"}, {"en": "きゅう", "ko": "9, 아홉 (く라고도 읽어요)", "note": "kyuu (큐-)"}, {"en": "じゅう", "ko": "10, 열", "note": "juu (주-)"}, {"en": "じゅういち", "ko": "11, 열하나", "note": "juuichi (주-이치)"}], "quiz": [{"q": "일본어로 3은 무엇일까요?", "choices": ["いち", "さん", "ご", "に"], "answer": 1, "explain": "3은 さん(상)이에요. いち는 1, ご는 5, に는 2예요."}, {"q": "はち는 숫자 몇일까요?", "choices": ["6", "7", "8", "9"], "answer": 2, "explain": "はち(하치)는 8이에요."}, {"q": "きゅう는 어떻게 읽을까요?", "choices": ["키우", "큐-", "기유", "쿠"], "answer": 1, "explain": "き와 작은 ゅ가 합쳐져 '큐', 끝의 う로 길게 늘여 '큐-'라고 읽어요."}, {"q": "🍎🍎 + 🍎🍎🍎 = ? 일본어로 알맞은 것은 무엇일까요?", "choices": ["よん", "ろく", "なな", "ご"], "answer": 3, "explain": "2 + 3 = 5이고, 5는 ご(고)예요."}, {"q": "다음 중 7을 읽는 법으로 알맞은 것은 무엇일까요?", "choices": ["なな", "はち", "よん", "じゅう"], "answer": 0, "explain": "7은 なな(나나)예요. しち(시치)라고도 읽어요."}], "summary": ["1~5는 いち, に, さん, よん, ご(이치, 니, 상, 욘, 고)예요.", "6~10은 ろく, なな, はち, きゅう, じゅう(로쿠, 나나, 하치, 큐-, 주-)예요.", "작은 ゅ는 앞 글자와 합쳐 한 소리가 되고, 4·7·9는 읽는 법이 두 가지예요."], "parent_tip": "부모님께: 계단을 오르거나 줄넘기를 할 때 일본어로 수를 세어 보세요. 몸을 움직이며 세면 빨리 외웁니다. きゅう를 '키유-'처럼 두 소리로 나누어 읽는 실수가 많으니, 작은 ゅ는 앞 글자와 한 소리로 합쳐진다는 점을 짚어 주세요. 4·7·9의 다른 읽기(し, しち, く)는 들어 본 정도로 충분합니다."}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','숫자 1~10',8,'j3-08' where not exists (select 1 from public.topics where lesson_slug='j3-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-09','3~4','일본어','가족과 물건 이름','엄마, 아빠, 연필, 가방은 일본어로 뭐라고 할까?','assets/img/l_j3-09.jpg',$j${"intro": "일본 만화에서 'おかあさん(오카-상)!' 하고 엄마를 부르는 소리를 들어 본 적 있나요? 오늘은 가족을 부르는 말과 책상 위 물건 이름을 배우고, '이것은 ~예요'라고 말해 봐요.", "sections": [{"heading": "우리 가족을 불러요", "paras": ["엄마는 おかあさん(okaasan, 오카-상), 아빠는 おとうさん(otousan, 오토-상)이에요. 가족은 かぞく(kazoku, 카조쿠)라고 해요.", "형이나 오빠는 おにいさん(oniisan, 오니-상), 누나나 언니는 おねえさん(oneesan, 오네-상)이에요. 남동생은 おとうと(otouto, 오토-토), 여동생은 いもうと(imouto, 이모-토)예요.", "나 자신은 わたし(watashi, 와타시)라고 해요. 남자아이든 여자아이든 쓸 수 있어요."], "example": "👩 おかあさん(오카-상) 엄마 / 👨 おとうさん(오토-상) 아빠 / 👦 おにいさん(오니-상) 형·오빠 / 👧 おねえさん(오네-상) 누나·언니", "figure": "식탁에 둘러앉은 가족 다섯 명의 뒷모습과 손이 보이는 따뜻한 저녁 장면"}, {"heading": "길게 읽느냐에 따라 뜻이 달라져요", "paras": ["할머니는 おばあさん(obaasan, 오바-상), 할아버지는 おじいさん(ojiisan, 오지-상)이에요. ば와 じ를 길게 늘여 읽어요.", "그런데 길게 읽지 않으면 뜻이 바뀌어요! おばさん(오바상)은 '아주머니·이모·고모', おじさん(오지상)은 '아저씨·삼촌'이에요.", "그래서 긴소리를 만드는 あ, い 같은 글자를 빠뜨리지 않고 쓰고, 길게 소리 내는 것이 중요해요."], "example": "👵 おばあさん(오바-상) 할머니 ↔ おばさん(오바상) 아주머니 / 👴 おじいさん(오지-상) 할아버지 ↔ おじさん(오지상) 아저씨", "figure": "할머니와 아주머니, 할아버지와 아저씨가 짝지어 서 있는 모습을 그린 그림 카드 네 장"}, {"heading": "책상 위 물건 이름", "paras": ["책은 ほん(hon, 홍), 연필은 えんぴつ(enpitsu, 엠피츠), 가방은 かばん(kaban, 카방)이에요.", "책상은 つくえ(tsukue, 츠쿠에), 의자는 いす(isu, 이스), 우산은 かさ(kasa, 카사), 시계는 とけい(tokei, 토케-)예요.", "とけい의 けい는 '케이'보다 '케-'처럼 길게 들려요."], "example": "📖 ほん(홍) 책 / ✏️ えんぴつ(엠피츠) 연필 / 🎒 かばん(카방) 가방 / ⏰ とけい(토케-) 시계", "figure": "책상 위에 책, 연필, 가방, 탁상시계가 가지런히 놓여 있는 모습"}, {"heading": "'이것은 ~예요' 말하기", "paras": ["물건을 가리키며 'これは ~です(코레와 ~데스)'라고 하면 '이것은 ~예요'라는 뜻이 돼요. 여기서도 は는 '와'로 읽어요.", "'나의 ~'라고 할 때는 の(노)를 써요. わたしの かばん(와타시노 카방)은 '나의 가방', 곧 '내 가방'이에요."], "example": "これは ほんです。(코레와 혼데스) 이것은 책이에요. / これは わたしの かばんです。(코레와 와타시노 카반데스) 이것은 내 가방이에요.", "figure": "아이가 손가락으로 책을 가리키고 있는 모습"}], "keywords": [{"word": "かぞく", "meaning": "가족. 카조쿠라고 읽어요."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. おばあさん의 ばあ는 '바-'로 길게 읽어요."}, {"word": "これは ~です", "meaning": "'이것은 ~예요'라는 문장. は는 '와'로 읽어요."}, {"word": "の", "meaning": "'~의'라는 뜻. わたしの는 '나의'예요."}], "expressions": [{"en": "かぞく", "ko": "가족 👨‍👩‍👧‍👦", "note": "kazoku (카조쿠)"}, {"en": "おかあさん", "ko": "엄마, 어머니 👩", "note": "okaasan (오카-상)"}, {"en": "おとうさん", "ko": "아빠, 아버지 👨", "note": "otousan (오토-상)"}, {"en": "おにいさん", "ko": "형, 오빠 👦", "note": "oniisan (오니-상)"}, {"en": "おねえさん", "ko": "누나, 언니 👧", "note": "oneesan (오네-상)"}, {"en": "おばあさん", "ko": "할머니 👵", "note": "obaasan (오바-상)"}, {"en": "おじいさん", "ko": "할아버지 👴", "note": "ojiisan (오지-상)"}, {"en": "わたし", "ko": "나, 저", "note": "watashi (와타시)"}, {"en": "えんぴつ", "ko": "연필 ✏️", "note": "enpitsu (엠피츠)"}, {"en": "かばん", "ko": "가방 🎒", "note": "kaban (카방)"}, {"en": "とけい", "ko": "시계 ⏰", "note": "tokei (토케-)"}, {"en": "これは ほんです", "ko": "이것은 책이에요.", "note": "kore wa hon desu (코레와 혼데스)"}], "quiz": [{"q": "👩 '엄마'를 뜻하는 낱말은 무엇일까요?", "choices": ["おとうさん", "おかあさん", "おねえさん", "おばさん"], "answer": 1, "explain": "엄마는 おかあさん(오카-상)이에요. おとうさん은 아빠예요."}, {"q": "👴 '할아버지'를 뜻하는 낱말은 무엇일까요?", "choices": ["おじさん", "おにいさん", "おじいさん", "おとうと"], "answer": 2, "explain": "할아버지는 じ를 길게 읽는 おじいさん(오지-상)이에요. おじさん(오지상)은 아저씨예요."}, {"q": "✏️ えんぴつ는 무슨 뜻일까요?", "choices": ["연필", "가방", "책", "시계"], "answer": 0, "explain": "えんぴつ(엠피츠)는 연필이에요."}, {"q": "'이것은 책이에요.'를 일본어로 바르게 쓴 것은 무엇일까요?", "choices": ["これは かばんです。", "これは とけいです。", "わたしは ほんです。", "これは ほんです。"], "answer": 3, "explain": "'이것은 ~예요'는 これは ~です, 책은 ほん이라서 これは ほんです예요."}, {"q": "わたしの かばん은 무슨 뜻일까요?", "choices": ["엄마의 가방", "내 가방", "새 가방", "가방 속 책"], "answer": 1, "explain": "わたし는 '나', の는 '~의'라서 '나의 가방(내 가방)'이에요."}], "summary": ["엄마 おかあさん, 아빠 おとうさん, 형·오빠 おにいさん, 누나·언니 おねえさん이에요.", "おばあさん(할머니)과 おばさん(아주머니)처럼 길게 읽느냐에 따라 뜻이 달라져요.", "これは ~です(코레와 ~데스)로 '이것은 ~예요'라고 말할 수 있어요."], "parent_tip": "부모님께: 일본어에서는 남의 가족을 부를 때와 내 가족을 남에게 말할 때 쓰는 말이 다르지만(예: はは, ちち), 이 단계에서는 집에서 부르는 말(おかあさん 등)만 익혀도 충분합니다. 집 안 물건을 가리키며 'これは なんですか?(이건 뭐예요?)'라고 묻고 아이가 'これは ~です'로 답하는 놀이를 해 보세요."}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','가족과 물건 이름',9,'j3-09' where not exists (select 1 from public.topics where lesson_slug='j3-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j3-10','3~4','일본어','가타카나 맛보기','바나나, 케이크를 가타카나로 써 볼까?','assets/img/l_j3-10.jpg',$j${"intro": "일본 편의점에 가면 バナナ(바나나), ケーキ(케-키)처럼 각진 글자가 가득해요. 다른 나라에서 온 말을 쓰는 글자, 가타카나를 맛보기로 배워 봐요.", "sections": [{"heading": "가타카나는 언제 쓸까?", "paras": ["가타카나는 히라가나와 소리가 똑같고 모양만 각진 글자예요. 히라가나 あいうえお를 가타카나로는 アイウエオ(아 이 우 에 오)라고 써요.", "가타카나는 주로 다른 나라에서 들어온 말을 쓸 때 써요. 바나나, 텔레비전, 피아노 같은 낱말이에요.", "외국 사람 이름이나 다른 나라 지명도 가타카나로 써요. 우리나라 서울은 ソウル(소우루), 김치는 キムチ(키무치)라고 써요."], "example": "🍌 バナナ(banana, 바나나) / 🍅 トマト(tomato, 토마토) / 📺 テレビ(terebi, 테레비) 텔레비전 / 🎹 ピアノ(piano, 피아노)", "figure": "바나나, 토마토, 장난감 피아노가 책상 위에 나란히 놓여 있는 모습"}, {"heading": "히라가나와 닮은 가타카나", "paras": ["어떤 가타카나는 히라가나와 아주 닮아서 금방 외울 수 있어요. か와 カ(카), き와 キ(키), り와 リ(리), も와 モ(모), や와 ヤ(야)가 그래요.", "へ와 ヘ(헤)는 거의 똑같이 생겼어요. 히라가나를 잘 알면 가타카나도 쉽게 익힐 수 있어요.", "탁점(゛)과 반탁점(゜)도 히라가나와 똑같이 붙여요. ハ(하)에 붙이면 バ(바), パ(파)가 돼요."], "example": "か → カ / き → キ / へ → ヘ / り → リ / も → モ / や → ヤ", "figure": "왼쪽 줄에 히라가나 카드, 오른쪽 줄에 닮은 가타카나 카드를 짝지어 놓은 모습"}, {"heading": "シ와 ツ, ソ와 ン을 구별해요", "paras": ["가타카나에서 가장 헷갈리는 짝은 シ(시)와 ツ(츠), ソ(소)와 ン(응)이에요.", "シ와 ン은 마지막 획을 아래에서 위로 올려 써요. ツ와 ソ는 마지막 획을 위에서 아래로 내려 써요.", "그래서 シ의 점들은 왼쪽에 세로로 놓이고, ツ의 점들은 위쪽에 가로로 놓여요. 획의 방향을 보면 구별할 수 있어요."], "example": "シ(시) ↗ 아래에서 위로 / ツ(츠) ↙ 위에서 아래로 / ン(응) ↗ 아래에서 위로 / ソ(소) ↙ 위에서 아래로", "figure": "シ, ツ, ソ, ン 카드 위에 마지막 획 방향을 화살표로 그린 모습"}, {"heading": "길게 늘이는 막대 ー", "paras": ["가타카나 낱말에서 소리를 길게 늘일 때는 막대 'ー'를 써요. 히라가나에서 う나 あ를 덧붙여 길게 했던 것과 같은 역할이에요.", "ケーキ(케-키)는 ケ를 길게, ゲーム(게-무)는 ゲ를 길게 읽어요. ー를 빼먹으면 다른 소리가 되니 꼭 써 주세요."], "example": "🍰 ケーキ(keeki, 케-키) 케이크 / 🎮 ゲーム(geemu, 게-무) 게임 / 🍦 アイス(aisu, 아이스) 아이스크림", "figure": "생일 케이크 한 조각과 게임기가 놓인 책상"}], "keywords": [{"word": "가타카나", "meaning": "히라가나와 소리가 같고 모양이 각진 글자. 외국에서 온 말을 쓸 때 써요."}, {"word": "외래어", "meaning": "다른 나라에서 들어와 쓰이게 된 말. 예: バナナ, テレビ."}, {"word": "긴소리 표시 ー", "meaning": "가타카나에서 앞 소리를 길게 늘이라는 막대 표시."}], "expressions": [{"en": "カタカナ", "ko": "가타카나", "note": "katakana (카타카나)"}, {"en": "アイウエオ", "ko": "가타카나 ア행", "note": "a i u e o (아 이 우 에 오)"}, {"en": "バナナ", "ko": "바나나 🍌", "note": "banana (바나나)"}, {"en": "トマト", "ko": "토마토 🍅", "note": "tomato (토마토)"}, {"en": "テレビ", "ko": "텔레비전 📺", "note": "terebi (테레비)"}, {"en": "ピアノ", "ko": "피아노 🎹", "note": "piano (피아노)"}, {"en": "カメラ", "ko": "카메라 📷", "note": "kamera (카메라)"}, {"en": "ケーキ", "ko": "케이크 🍰", "note": "keeki (케-키)"}, {"en": "ゲーム", "ko": "게임 🎮", "note": "geemu (게-무)"}, {"en": "アイス", "ko": "아이스크림 🍦", "note": "aisu (아이스)"}, {"en": "ソウル", "ko": "서울 🇰🇷", "note": "souru (소우루)"}, {"en": "キムチ", "ko": "김치", "note": "kimuchi (키무치)"}], "quiz": [{"q": "가타카나를 주로 쓰는 때는 언제일까요?", "choices": ["다른 나라에서 들어온 말을 쓸 때", "'~을/를'을 쓸 때", "뜻을 담은 글자를 쓸 때", "인사말을 쓸 때"], "answer": 0, "explain": "가타카나는 주로 바나나, 텔레비전처럼 다른 나라에서 들어온 말을 쓸 때 써요."}, {"q": "🍌 '바나나'를 가타카나로 바르게 쓴 것은 무엇일까요?", "choices": ["ばなな", "バナナ", "パナナ", "バナメ"], "answer": 1, "explain": "바나나는 가타카나로 バナナ라고 써요. ばなな는 히라가나예요."}, {"q": "'츠' 소리를 나타내는 가타카나는 무엇일까요?", "choices": ["シ", "ソ", "ン", "ツ"], "answer": 3, "explain": "ツ(츠)는 마지막 획을 위에서 아래로 내려 써요. シ는 '시'예요."}, {"q": "ケーキ의 ー는 무슨 표시일까요?", "choices": ["소리를 멈추는 표시", "소리를 길게 늘이는 표시", "문장이 끝났다는 표시", "탁점과 같은 표시"], "answer": 1, "explain": "ー는 앞 소리를 길게 늘이라는 표시예요. ケーキ는 '케-키'라고 읽어요."}, {"q": "히라가나 へ와 거의 똑같이 생긴 가타카나는 무엇일까요?", "choices": ["ヘ", "ホ", "ハ", "ヒ"], "answer": 0, "explain": "히라가나 へ와 가타카나 ヘ는 둘 다 '헤'이고 모양도 거의 같아요."}], "summary": ["가타카나는 히라가나와 소리가 같고, 다른 나라에서 온 말이나 외국 이름을 쓸 때 써요.", "カ・キ・ヘ・リ・モ・ヤ처럼 히라가나와 닮은 글자부터 익히면 쉬워요.", "シ/ツ, ソ/ン은 획 방향으로 구별하고, ー는 소리를 길게 늘이는 표시예요."], "parent_tip": "부모님께: 가타카나는 이번 단원에서 '맛보기'로 소개하는 정도라 46자를 모두 외우지 않아도 됩니다. 대신 마트의 일본 과자나 장난감 포장에서 アイス, ケーキ처럼 아는 가타카나 낱말을 찾아보는 놀이를 해 보세요. 아이 이름을 가타카나로 써 보는 것도 큰 흥미를 줍니다."}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','일본어','가타카나 맛보기',10,'j3-10' where not exists (select 1 from public.topics where lesson_slug='j3-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-01','5~6','일본어','자기소개 わたしは~です','일본어로 내 이름을 어떻게 소개할까?','assets/img/l_j5-01.jpg',$j${"intro": "일본 친구를 처음 만났어요. 웃으면서 \"안녕, 나는 ○○야!\"라고 일본어로 말할 수 있다면 정말 멋지겠죠? 오늘은 일본어를 하나도 몰라도 바로 쓸 수 있는 자기소개를 배워요.", "sections": [{"heading": "일본어 글자는 세 가지예요", "paras": ["일본어에는 히라가나, 가타카나, 한자 세 가지 글자가 있어요. 히라가나는 일본어의 기본 글자이고, 가타카나는 외국에서 온 말이나 외국 사람 이름을 쓸 때 주로 써요.", "처음에는 글자를 다 외우지 않아도 괜찮아요. 이 단원에서는 일본어 옆에 로마자와 한글 소리를 함께 적어 두었으니, 소리를 듣고 따라 말해 보세요."], "example": "히라가나: あ(a, 아) い(i, 이) う(u, 우) え(e, 에) お(o, 오) / 가타카나: ア イ ウ エ オ (소리는 똑같아요)", "figure": "히라가나 あいうえお 와 가타카나 アイウエオ 를 나란히 적은 글자 카드"}, {"heading": "처음 만나면 はじめまして", "paras": ["처음 만난 사람에게는 はじめまして(hajimemashite, 하지메마시테)라고 인사해요. '처음 뵙겠습니다'라는 뜻이에요.", "낮에 만나면 こんにちは(konnichiwa, 곤니치와)도 함께 쓸 수 있어요. こんにちは의 마지막 글자 は는 이 인사말에서 '와'로 읽어요."], "example": "はじめまして。(hajimemashite, 하지메마시테) → 처음 뵙겠습니다.", "figure": "두 아이가 손을 흔들며 처음 인사하는 모습"}, {"heading": "わたしは ~です 로 이름을 말해요", "paras": ["'저는 ○○예요'는 わたしは ○○です(watashi wa ○○ desu, 와타시와 ○○데스)라고 해요. わたし는 '나, 저', です는 '~예요/이에요'라는 뜻이에요.", "여기서 は는 글자 이름은 '하'지만, '~은/는'이라는 뜻으로 쓸 때는 '와(wa)'라고 읽어요. 아주 중요한 규칙이에요!", "です의 す는 아주 약하게 소리 나서 '데스'처럼 들려요. 한국 이름은 보통 가타카나로 써요. 예를 들어 '미나'는 ミナ(mina, 미나)예요."], "example": "わたしは ミナです。(watashi wa mina desu, 와타시와 미나데스) → 저는 미나예요.", "figure": "가슴에 손을 얹고 자기 이름을 말하는 아이"}, {"heading": "어느 나라 사람인지, 몇 학년인지도 말해요", "paras": ["나라 이름 뒤에 じん(jin, 진)을 붙이면 '○○ 사람'이 돼요. 한국 사람은 かんこくじん(kankokujin, 캉코쿠진), 일본 사람은 にほんじん(nihonjin, 니혼진)이에요.", "초등학생은 しょうがくせい(shougakusei, 쇼-가쿠세이)라고 해요. 앞에서 배운 です를 붙이면 바로 문장이 돼요."], "example": "かんこくじんです。(kankokujin desu, 캉코쿠진데스) → 한국 사람이에요.", "figure": "한국과 일본 국기를 든 두 아이"}, {"heading": "마지막은 よろしくおねがいします", "paras": ["자기소개가 끝나면 よろしくおねがいします(yoroshiku onegaishimasu, 요로시쿠 오네가이시마스)라고 말하고 고개를 살짝 숙여요. '잘 부탁합니다'라는 뜻이에요.", "친구 이름을 부를 때는 이름 뒤에 さん(san, 상)을 붙여요. 'ミナさん'처럼요. 하지만 내 이름에는 さん을 붙이지 않아요."], "example": "はじめまして。わたしは ミナです。かんこくじんです。よろしくおねがいします。", "figure": "고개를 살짝 숙여 인사하는 아이"}], "keywords": [{"word": "히라가나", "meaning": "일본어의 기본 글자. あ, い, う 같은 글자"}, {"word": "가타카나", "meaning": "외국에서 온 말이나 외국 사람 이름을 쓰는 글자. ア, イ, ウ 같은 글자"}, {"word": "わたし", "meaning": "나, 저 (watashi, 와타시)"}, {"word": "です", "meaning": "~예요, ~이에요 (desu, 데스)"}, {"word": "は(와)", "meaning": "'~은/는'이라는 뜻일 때는 '와(wa)'로 읽어요"}], "expressions": [{"en": "はじめまして", "ko": "처음 뵙겠습니다", "note": "hajimemashite (하지메마시테)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (곤니치와)"}, {"en": "わたし", "ko": "나, 저", "note": "watashi (와타시)"}, {"en": "わたしは ミナです。", "ko": "저는 미나예요.", "note": "watashi wa mina desu (와타시와 미나데스)"}, {"en": "おなまえは？", "ko": "이름이 뭐예요?", "note": "onamae wa? (오나마에와?)"}, {"en": "かんこくじんです。", "ko": "한국 사람이에요.", "note": "kankokujin desu (캉코쿠진데스)"}, {"en": "にほんじん", "ko": "일본 사람", "note": "nihonjin (니혼진)"}, {"en": "しょうがくせいです。", "ko": "초등학생이에요.", "note": "shougakusei desu (쇼-가쿠세이데스)"}, {"en": "よろしくおねがいします。", "ko": "잘 부탁합니다.", "note": "yoroshiku onegaishimasu (요로시쿠 오네가이시마스)"}, {"en": "ミナさん", "ko": "미나 씨 (다른 사람 이름 뒤에 붙여요)", "note": "mina san (미나상)"}], "quiz": [{"q": "처음 만난 사람에게 하는 인사는 무엇일까요?", "choices": ["はじめまして", "おやすみ", "ありがとう", "さようなら"], "answer": 0, "explain": "はじめまして(하지메마시테)는 '처음 뵙겠습니다'라는 뜻이에요."}, {"q": "わたしは ジュンです。 에서 は는 어떻게 읽을까요?", "choices": ["하(ha)", "와(wa)", "아(a)", "바(ba)"], "answer": 1, "explain": "'~은/는'이라는 뜻으로 쓰인 は는 '와(wa)'로 읽어요."}, {"q": "'한국 사람이에요.'를 일본어로 바르게 말한 것은?", "choices": ["にほんじんです。", "しょうがくせいです。", "かんこくじんです。", "よろしくおねがいします。"], "answer": 2, "explain": "かんこく(한국) + じん(사람) + です = かんこくじんです예요."}, {"q": "자기소개를 마치며 '잘 부탁합니다'라고 할 때 쓰는 말은?", "choices": ["こんにちは", "はじめまして", "わたしは", "よろしくおねがいします"], "answer": 3, "explain": "よろしくおねがいします(요로시쿠 오네가이시마스)는 '잘 부탁합니다'예요."}, {"q": "さん을 붙이면 __어색한__ 것은 무엇일까요?", "choices": ["친구 이름 ミナ", "선생님 이름 たなか", "내 이름", "새로 만난 사람 이름"], "answer": 2, "explain": "さん은 다른 사람을 높여 부르는 말이라 내 이름에는 붙이지 않아요."}], "summary": ["처음 만나면 はじめまして(하지메마시테)라고 인사해요.", "わたしは ○○です(와타시와 ○○데스)로 이름을 말해요. 이때 は는 '와'로 읽어요.", "마지막에는 よろしくおねがいします(요로시쿠 오네가이시마스)로 마무리해요."], "parent_tip": "부모님께: 아이들이 가장 많이 헷갈리는 것은 '~은/는'으로 쓰인 は를 '와'로 읽는 규칙입니다. 듣기 버튼으로 소리를 먼저 들려준 뒤, 부모님이 일본 친구 역할을 맡아 \"おなまえは？\"라고 묻고 아이가 세 문장으로 자기소개를 하게 해 보세요. 글자를 외우는 것보다 소리 내어 말해 보는 경험이 먼저입니다."}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','자기소개 わたしは~です',1,'j5-01' where not exists (select 1 from public.topics where lesson_slug='j5-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-02','5~6','일본어','이것·그것·저것','''이것'', ''그것'', ''저것''은 일본어로 뭐라고 할까?','assets/img/l_j5-02.jpg',$j${"intro": "일본 문구점에서 귀여운 물건을 발견했어요. 손으로 가리키며 \"이건 뭐예요?\"라고 묻고 싶다면 어떻게 말할까요? 오늘은 물건을 가리키는 말 これ・それ・あれ를 배워요.", "sections": [{"heading": "これ・それ・あれ・どれ", "paras": ["내 가까이에 있는 물건은 これ(kore, 코레) '이것', 듣는 사람 가까이에 있는 물건은 それ(sore, 소레) '그것'이에요.", "둘 다에게서 멀리 있는 물건은 あれ(are, 아레) '저것'이고, '어느 것'을 물을 때는 どれ(dore, 도레)를 써요.", "앞 글자만 보면 こ(이)・そ(그)・あ(저)・ど(어느)예요. 한국어 '이・그・저・어느'와 똑같이 짝지어 외우면 쉬워요."], "example": "これ(코레) 이것 / それ(소레) 그것 / あれ(아레) 저것 / どれ(도레) 어느 것", "figure": "책상 위 물건, 친구 손의 물건, 멀리 창밖 물건을 가리키는 세 장면"}, {"heading": "これは なんですか? 로 물어요", "paras": ["'이것은 무엇이에요?'는 これは なんですか(kore wa nan desu ka, 코레와 난데스카)예요. なん은 '무엇', か는 문장 끝에 붙어서 질문을 만들어요.", "일본어는 질문 끝에도 보통 물음표 대신 마침표(。)를 찍어요. 말할 때는 끝을 살짝 올려요.", "여기서도 は는 '와'로 읽는다는 것, 잊지 않았죠?"], "example": "これは なんですか。(kore wa nan desu ka, 코레와 난데스카) → 이것은 무엇이에요?", "figure": "아이가 신기한 물건을 들고 고개를 갸웃하는 모습"}, {"heading": "それは ~です 로 대답해요", "paras": ["친구가 내 손의 물건을 가리키며 それ(그것)라고 물으면, 그 물건은 내 가까이에 있으니 나는 これは ~です로 대답해요. 반대로 친구가 자기 손의 물건을 これ라고 물으면, 나는 それは ~です라고 해요.", "물건 이름은 ほん(hon, 혼) 책, かばん(kaban, 카방) 가방, えんぴつ(enpitsu, 엠피츠) 연필, ペン(pen, 펜) 펜 등이 있어요. ペン처럼 외국에서 온 말은 가타카나로 써요."], "example": "A: それは なんですか。 B: これは えんぴつです。 (그건 뭐예요? / 이건 연필이에요.)", "figure": "연필, 책, 가방, 펜이 놓인 책상"}, {"heading": "はい・いいえ 로 대답해요", "paras": ["'이것은 펜이에요?'처럼 '예/아니요'로 답하는 질문도 있어요. 맞으면 はい、そうです(hai, sou desu, 하이 소-데스) '네, 그래요.'라고 해요.", "틀리면 いいえ、ちがいます(iie, chigaimasu, 이-에 치가이마스) '아니요, 달라요.'라고 해요."], "example": "A: これは ペンですか。 B: いいえ、ちがいます。えんぴつです。", "figure": "고개를 끄덕이는 아이와 고개를 젓는 아이"}, {"heading": "この・その・あの + 물건", "paras": ["물건 이름 앞에 붙여서 '이 ○○, 그 ○○, 저 ○○'라고 할 때는 この(kono, 코노)・その(sono, 소노)・あの(ano, 아노)를 써요.", "このほん은 '이 책', あのいぬ는 '저 개'예요. これ・それ・あれ는 혼자 쓰고, この・その・あの는 꼭 뒤에 물건 이름이 와요."], "example": "このかばんは わたしの かばんです。 (이 가방은 내 가방이에요.)", "figure": ""}], "keywords": [{"word": "これ", "meaning": "이것 — 말하는 사람 가까이 (kore, 코레)"}, {"word": "それ", "meaning": "그것 — 듣는 사람 가까이 (sore, 소레)"}, {"word": "あれ", "meaning": "저것 — 둘 다에게서 멀리 (are, 아레)"}, {"word": "どれ", "meaning": "어느 것 (dore, 도레)"}, {"word": "なん", "meaning": "무엇 (nan, 난)"}, {"word": "か", "meaning": "문장 끝에 붙여 질문을 만드는 말 (ka, 카)"}], "expressions": [{"en": "これ", "ko": "이것", "note": "kore (코레)"}, {"en": "それ", "ko": "그것", "note": "sore (소레)"}, {"en": "あれ", "ko": "저것", "note": "are (아레)"}, {"en": "どれ", "ko": "어느 것", "note": "dore (도레)"}, {"en": "これは なんですか。", "ko": "이것은 무엇이에요?", "note": "kore wa nan desu ka (코레와 난데스카)"}, {"en": "それは ほんです。", "ko": "그것은 책이에요.", "note": "sore wa hon desu (소레와 혼데스)"}, {"en": "あれは ねこです。", "ko": "저것은 고양이예요.", "note": "are wa neko desu (아레와 네코데스)"}, {"en": "はい、そうです。", "ko": "네, 그래요.", "note": "hai, sou desu (하이, 소-데스)"}, {"en": "いいえ、ちがいます。", "ko": "아니요, 달라요.", "note": "iie, chigaimasu (이-에, 치가이마스)"}, {"en": "えんぴつ", "ko": "연필", "note": "enpitsu (엠피츠)"}, {"en": "かばん", "ko": "가방", "note": "kaban (카방)"}, {"en": "このほん", "ko": "이 책", "note": "kono hon (코노 혼)"}], "quiz": [{"q": "내 손에 들고 있는 물건을 가리킬 때 쓰는 말은?", "choices": ["これ", "それ", "あれ", "どれ"], "answer": 0, "explain": "말하는 사람 가까이에 있는 물건은 これ(이것)예요."}, {"q": "これは なんですか。 의 뜻은?", "choices": ["이것은 연필이에요.", "이것은 무엇이에요?", "저것은 어느 것이에요?", "그것은 책이에요?"], "answer": 1, "explain": "なん은 '무엇', か는 질문이에요. '이것은 무엇이에요?'라는 뜻이에요."}, {"q": "멀리 하늘을 나는 새를 가리키며 '저것'이라고 할 때 쓰는 말은?", "choices": ["これ", "それ", "あれ", "この"], "answer": 2, "explain": "나와 친구 모두에게서 멀리 있으면 あれ(저것)예요."}, {"q": "A: これは ペンですか。 B: (펜이 아니라 연필이에요.) 알맞은 대답은?", "choices": ["はい、そうです。", "これは ペンです。", "はい、ペンです。", "いいえ、ちがいます。"], "answer": 3, "explain": "펜이 아니니까 いいえ、ちがいます(아니요, 달라요)라고 해요."}, {"q": "'이 책'을 일본어로 바르게 쓴 것은?", "choices": ["これほん", "このほん", "それほん", "あのほん"], "answer": 1, "explain": "물건 이름 앞에는 この를 붙여요. このほん은 '이 책', あのほん은 '저 책'이에요."}], "summary": ["これ(이것)・それ(그것)・あれ(저것)・どれ(어느 것)는 거리에 따라 골라 써요.", "これは なんですか(코레와 난데스카)로 묻고, ~は ~です로 대답해요.", "맞으면 はい、そうです, 아니면 いいえ、ちがいます라고 해요."], "parent_tip": "부모님께: 한국어의 '이・그・저・어느'와 일본어의 こ・そ・あ・ど가 거의 그대로 대응해서 한국 아이들이 쉽게 익히는 부분입니다. 다만 상대가 これ로 물으면 나는 それ로 답하는 '시점 바꾸기'를 헷갈려합니다. 집 안 물건을 아이 손, 부모님 손, 멀리 놓고 \"これは なんですか。\" 놀이를 해 보세요."}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','이것·그것·저것',2,'j5-02' where not exists (select 1 from public.topics where lesson_slug='j5-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-03','5~6','일본어','나이 묻기 なんさい','일본어로 몇 살인지 어떻게 묻고 답할까?','assets/img/l_j5-03.jpg',$j${"intro": "새로 사귄 일본 친구가 나와 동갑인지 궁금해요. \"몇 살이야?\"라고 일본어로 물어볼 수 있다면 금방 더 친해질 수 있겠죠? 오늘은 숫자와 함께 나이를 묻고 답하는 법을 배워요.", "sections": [{"heading": "1부터 10까지 세어 봐요", "paras": ["일본어 숫자는 いち(ichi, 이치) 1, に(ni, 니) 2, さん(san, 상) 3, よん(yon, 용) 4, ご(go, 고) 5예요.", "이어서 ろく(roku, 로쿠) 6, なな(nana, 나나) 7, はち(hachi, 하치) 8, きゅう(kyuu, 큐-) 9, じゅう(juu, 주-) 10이에요. 4는 し, 7은 しち라고도 하지만 오늘은 よん과 なな를 써요.", "11은 じゅういち(10+1), 12는 じゅうに(10+2)처럼 10 뒤에 숫자를 붙이면 돼요."], "example": "1 いち · 2 に · 3 さん · 4 よん · 5 ご · 6 ろく · 7 なな · 8 はち · 9 きゅう · 10 じゅう", "figure": "손가락으로 1부터 10까지 세는 두 손"}, {"heading": "なんさいですか? 몇 살이에요?", "paras": ["나이를 셀 때는 숫자 뒤에 さい(sai, 사이)를 붙여요. '몇 살'은 なんさい(nansai, 난사이)예요.", "'몇 살이에요?'는 なんさいですか(nansai desu ka, 난사이데스카)라고 물어요. 친구 이름을 넣어 ユナさんは なんさいですか。라고 물을 수도 있어요."], "example": "なんさいですか。(nansai desu ka, 난사이데스카) → 몇 살이에요?", "figure": "생일 케이크 앞에서 촛불을 세는 아이"}, {"heading": "작은 っ 가 들어가는 나이", "paras": ["몇몇 나이는 소리가 조금 바뀌어요. 1살은 いっさい(issai, 잇사이), 8살은 はっさい(hassai, 핫사이), 10살은 じゅっさい(jussai, 줏사이)예요.", "작게 쓴 っ는 '잠깐 멈추는 소리'예요. 한국어 받침 'ㅅ'처럼 짧게 끊었다가 다음 글자를 읽어요.", "그래서 11살은 じゅういっさい(juuissai, 주-잇사이), 12살은 じゅうにさい(juunisai, 주-니사이)예요."], "example": "11さい じゅういっさい(주-잇사이) / 12さい じゅうにさい(주-니사이)", "figure": ""}, {"heading": "じゅういっさいです 로 대답해요", "paras": ["대답은 나이 뒤에 です를 붙이면 돼요. 11살이면 じゅういっさいです(주-잇사이데스), 12살이면 じゅうにさいです(주-니사이데스)예요.", "학년을 말하고 싶으면 숫자 뒤에 ねんせい(nensei, 넨세이)를 붙여요. 5학년은 ごねんせい(gonensei, 고넨세이), 6학년은 ろくねんせい(rokunensei, 로쿠넨세이)예요."], "example": "A: なんさいですか。 B: じゅうにさいです。ろくねんせいです。 (12살이에요. 6학년이에요.)", "figure": "가방을 멘 초등학생 두 명이 이야기하는 모습"}], "keywords": [{"word": "さい", "meaning": "나이를 셀 때 숫자 뒤에 붙이는 말 (sai, 사이) — '~살'"}, {"word": "なんさい", "meaning": "몇 살 (nansai, 난사이)"}, {"word": "작은 っ", "meaning": "잠깐 멈추는 소리. いっさい(잇사이)처럼 읽어요"}, {"word": "ねんせい", "meaning": "~학년 (nensei, 넨세이)"}], "expressions": [{"en": "なんさいですか。", "ko": "몇 살이에요?", "note": "nansai desu ka (난사이데스카)"}, {"en": "じゅういっさいです。", "ko": "11살이에요.", "note": "juuissai desu (주-잇사이데스)"}, {"en": "じゅうにさいです。", "ko": "12살이에요.", "note": "juunisai desu (주-니사이데스)"}, {"en": "いっさい", "ko": "1살", "note": "issai (잇사이)"}, {"en": "はっさい", "ko": "8살", "note": "hassai (핫사이)"}, {"en": "じゅっさい", "ko": "10살", "note": "jussai (줏사이)"}, {"en": "ごねんせいです。", "ko": "5학년이에요.", "note": "gonensei desu (고넨세이데스)"}, {"en": "ろくねんせいです。", "ko": "6학년이에요.", "note": "rokunensei desu (로쿠넨세이데스)"}, {"en": "いち、に、さん、よん、ご", "ko": "1, 2, 3, 4, 5", "note": "ichi, ni, san, yon, go (이치, 니, 상, 용, 고)"}, {"en": "ろく、なな、はち、きゅう、じゅう", "ko": "6, 7, 8, 9, 10", "note": "roku, nana, hachi, kyuu, juu (로쿠, 나나, 하치, 큐-, 주-)"}], "quiz": [{"q": "일본어 숫자 ご(go, 고)는 얼마일까요?", "choices": ["5", "2", "9", "7"], "answer": 0, "explain": "いち・に・さん・よん・ご, 다섯 번째인 ご가 5예요."}, {"q": "なんさいですか。는 무엇을 묻는 말일까요?", "choices": ["이름", "나이", "학년", "사는 곳"], "answer": 1, "explain": "さい는 '~살'이에요. なんさい는 '몇 살'이에요."}, {"q": "'11살이에요.'를 일본어로 바르게 말한 것은?", "choices": ["じゅういちさいです。", "いちじゅうさいです。", "じゅういっさいです。", "じゅうさいです。"], "answer": 2, "explain": "11살은 소리가 바뀌어 じゅういっさい(주-잇사이)예요."}, {"q": "'6학년이에요.'를 일본어로 바르게 말한 것은?", "choices": ["ろくさいです。", "ごねんせいです。", "なんねんせいですか。", "ろくねんせいです。"], "answer": 3, "explain": "학년은 숫자 + ねんせい예요. 6은 ろく니까 ろくねんせいです예요."}], "summary": ["일본어 숫자: いち・に・さん・よん・ご・ろく・なな・はち・きゅう・じゅう", "나이는 숫자 + さい, 묻는 말은 なんさいですか(난사이데스카)예요.", "1살 いっさい, 8살 はっさい, 10살 じゅっさい, 11살 じゅういっさい처럼 작은 っ가 들어가는 나이를 조심해요."], "parent_tip": "부모님께: 숫자 자체보다 1・8・10살처럼 작은 っ(촉음)가 생기는 소리 변화를 아이가 어려워합니다. 가족의 나이를 하나씩 일본어로 말해 보는 놀이가 좋습니다. 다만 어른 나이(예: 40살 よんじゅっさい)는 숫자가 길어지니, 아이 또래 나이와 학년 중심으로 연습해 주세요."}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','나이 묻기 なんさい',3,'j5-03' where not exists (select 1 from public.topics where lesson_slug='j5-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-04','5~6','일본어','좋아해요 すきです','''좋아해요''는 일본어로 어떻게 말할까?','assets/img/l_j5-04.jpg',$j${"intro": "일본 친구와 좋아하는 것이 같다면 금방 친해질 수 있어요. \"나는 고양이를 좋아해!\", \"너는 뭘 좋아해?\" 오늘은 좋아하는 것을 묻고 답하는 말 すきです를 배워요.", "sections": [{"heading": "~が すきです 좋아해요", "paras": ["'○○을 좋아해요'는 ○○が すきです(ga suki desu, 가 스키데스)라고 해요. すき는 '좋아함', が는 좋아하는 대상 뒤에 붙어요.", "한국어는 '고양이를 좋아해요'라고 '을/를'을 쓰지만, 일본어는 を가 아니라 が를 쓰는 것이 특징이에요.", "すき의 す는 약하게 소리 나서 '스키'처럼 들려요."], "example": "ねこが すきです。(neko ga suki desu, 네코가 스키데스) → 고양이를 좋아해요.", "figure": "고양이를 꼭 안고 웃는 아이"}, {"heading": "좋아하는 것을 말해 봐요", "paras": ["음식: すし(sushi, 스시) 초밥, りんご(ringo, 링고) 사과, アイスクリーム(aisukuriimu, 아이스쿠리-무) 아이스크림", "활동: サッカー(sakkaa, 삭카-) 축구, ゲーム(geemu, 게-무) 게임, おんがく(ongaku, 옹가쿠) 음악", "가타카나 낱말에 있는 ー는 앞 소리를 길게 늘이라는 표시예요. サッカー는 '삭카아'처럼 끝을 길게 읽어요."], "example": "サッカーが すきです。(sakkaa ga suki desu, 삭카-가 스키데스) → 축구를 좋아해요.", "figure": "축구공, 사과, 게임기, 아이스크림이 놓인 테이블"}, {"heading": "なにが すきですか? 뭘 좋아해요?", "paras": ["상대에게 묻고 싶으면 なにが すきですか(nani ga suki desu ka, 나니가 스키데스카)라고 해요. なに는 '무엇'이에요.", "친구가 나와 같은 것을 좋아한다면 わたしも すきです(watashi mo suki desu, 와타시모 스키데스) '나도 좋아해요'라고 말해요. も는 '~도'라는 뜻이에요."], "example": "A: なにが すきですか。 B: ゲームが すきです。 A: わたしも すきです！", "figure": "두 아이가 하이파이브하는 모습"}, {"heading": "아주 좋아하면 だいすき, 별로면 すきじゃない", "paras": ["정말 정말 좋아하면 だいすきです(daisuki desu, 다이스키데스) '아주 좋아해요'라고 해요.", "별로 좋아하지 않을 때는 あまり すきじゃないです(amari suki ja nai desu, 아마리 스키자나이데스) '별로 안 좋아해요'라고 해요.", "きらいです(kirai desu, 키라이데스)는 '싫어해요'라는 뜻인데, 조금 강하게 들릴 수 있어서 친구에게는 あまり すきじゃないです가 더 부드러워요."], "example": "りんごが だいすきです。 (사과를 아주 좋아해요.)", "figure": "하트를 그린 손과 고개를 젓는 손"}], "keywords": [{"word": "すき", "meaning": "좋아함 (suki, 스키)"}, {"word": "が", "meaning": "좋아하는 대상 뒤에 붙는 말 (ga, 가). '~을/를'처럼 해석해요"}, {"word": "なに", "meaning": "무엇 (nani, 나니)"}, {"word": "も", "meaning": "~도 (mo, 모)"}, {"word": "ー", "meaning": "가타카나에서 앞 소리를 길게 늘이는 표시"}], "expressions": [{"en": "すきです。", "ko": "좋아해요.", "note": "suki desu (스키데스)"}, {"en": "ねこが すきです。", "ko": "고양이를 좋아해요.", "note": "neko ga suki desu (네코가 스키데스)"}, {"en": "なにが すきですか。", "ko": "무엇을 좋아해요?", "note": "nani ga suki desu ka (나니가 스키데스카)"}, {"en": "わたしも すきです。", "ko": "나도 좋아해요.", "note": "watashi mo suki desu (와타시모 스키데스)"}, {"en": "だいすきです。", "ko": "아주 좋아해요.", "note": "daisuki desu (다이스키데스)"}, {"en": "あまり すきじゃないです。", "ko": "별로 안 좋아해요.", "note": "amari suki ja nai desu (아마리 스키자나이데스)"}, {"en": "きらいです。", "ko": "싫어해요.", "note": "kirai desu (키라이데스)"}, {"en": "サッカー", "ko": "축구", "note": "sakkaa (삭카-)"}, {"en": "ゲーム", "ko": "게임", "note": "geemu (게-무)"}, {"en": "すし", "ko": "초밥", "note": "sushi (스시)"}, {"en": "りんご", "ko": "사과", "note": "ringo (링고)"}, {"en": "アイスクリーム", "ko": "아이스크림", "note": "aisukuriimu (아이스쿠리-무)"}], "quiz": [{"q": "すきです。의 뜻은?", "choices": ["좋아해요.", "싫어해요.", "먹어요.", "몰라요."], "answer": 0, "explain": "すき는 '좋아함', です는 '~해요'예요."}, {"q": "'고양이를 좋아해요.'에서 ねこ 뒤에 들어갈 말은?\nねこ[  ] すきです。", "choices": ["を", "が", "は", "も"], "answer": 1, "explain": "좋아하는 대상 뒤에는 が를 붙여요. ねこが すきです예요."}, {"q": "친구가 \"なにが すきですか。\"라고 물었어요. 알맞은 대답은?", "choices": ["じゅうにさいです。", "はじめまして。", "サッカーが すきです。", "これは ほんです。"], "answer": 2, "explain": "무엇을 좋아하는지 물었으니 '○○が すきです'로 대답해요."}, {"q": "'나도 좋아해요.'를 일본어로 바르게 쓴 것은?", "choices": ["わたしは すきです。", "わたしが すきです。", "だいすきです。", "わたしも すきです。"], "answer": 3, "explain": "'~도'는 も예요. わたしも すきです예요."}, {"q": "사과를 '아주' 좋아할 때 알맞은 말은?", "choices": ["りんごが きらいです。", "りんごが だいすきです。", "りんごが あまり すきじゃないです。", "りんごは なんですか。"], "answer": 1, "explain": "だいすき는 '아주 좋아함'이에요."}], "summary": ["'○○을 좋아해요'는 ○○が すきです(가 스키데스)예요. を가 아니라 が를 써요.", "なにが すきですか(나니가 스키데스카)로 묻고, 같으면 わたしも すきです라고 해요.", "아주 좋아하면 だいすきです, 별로면 あまり すきじゃないです라고 해요."], "parent_tip": "부모님께: 한국어 '~을 좋아해요'에 끌려 아이들이 を를 쓰기 쉬운데, すき 앞에는 が를 씁니다. 아이가 좋아하는 음식·놀이를 가타카나 낱말과 함께 말해 보게 하고, 부모님이 \"なにが すきですか。\"라고 묻고 아이가 답하는 놀이를 해 보세요. 가타카나의 장음 표시 ー를 길게 읽는지도 들어 봐 주세요."}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','좋아해요 すきです',4,'j5-04' where not exists (select 1 from public.topics where lesson_slug='j5-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-05','5~6','일본어','시간과 요일','지금 몇 시? 오늘은 무슨 요일? 일본어로 말해 볼까?','assets/img/l_j5-05.jpg',$j${"intro": "일본 친구와 놀기로 약속했어요. \"몇 시에 만날까?\", \"토요일 어때?\" 시간과 요일을 말할 수 있어야 약속을 잡을 수 있겠죠? 오늘은 일본어로 시간과 요일을 말하는 법을 배워요.", "sections": [{"heading": "いま なんじですか? 지금 몇 시예요?", "paras": ["시간을 말할 때는 숫자 뒤에 じ(ji, 지)를 붙여요. 1시는 いちじ(ichiji, 이치지), 3시는 さんじ(sanji, 산지)예요.", "'지금 몇 시예요?'는 いま なんじですか(ima nanji desu ka, 이마 난지데스카)예요. いま는 '지금', なんじ는 '몇 시'예요."], "example": "A: いま なんじですか。 B: さんじです。 (지금 몇 시예요? / 3시예요.)", "figure": "벽시계가 3시를 가리키는 거실"}, {"heading": "조심해야 할 시간 세 개", "paras": ["대부분은 숫자 + じ지만, 세 개는 특별해요. 4시는 よじ(yoji, 요지), 7시는 しちじ(shichiji, 시치지), 9시는 くじ(kuji, 쿠지)예요.", "'반', 즉 30분은 はん(han, 한)이에요. 3시 반은 さんじはん(sanjihan, 산지한)이에요."], "example": "4시 よじ · 7시 しちじ · 9시 くじ / 7시 반 しちじはん", "figure": "아침 7시 반을 가리키는 알람시계"}, {"heading": "요일은 한국어와 똑같은 순서!", "paras": ["일본어 요일 이름은 한국어처럼 '월・화・수・목・금・토・일'을 뜻하는 한자를 써요. 뒤에 ようび(youbi, 요-비)를 붙이면 '요일'이에요.", "月(げつ) 월요일 げつようび(getsuyoubi, 게츠요-비), 火(か) 화요일 かようび(kayoubi, 카요-비), 水(すい) 수요일 すいようび(suiyoubi, 스이요-비), 木(もく) 목요일 もくようび(mokuyoubi, 모쿠요-비)", "金(きん) 금요일 きんようび(kin'youbi, 킨요-비), 土(ど) 토요일 どようび(doyoubi, 도요-비), 日(にち) 일요일 にちようび(nichiyoubi, 니치요-비)예요."], "example": "月(げつ)・火(か)・水(すい)・木(もく)・金(きん)・土(ど)・日(にち) + ようび", "figure": "월요일부터 일요일까지 칸이 있는 달력 한 줄"}, {"heading": "きょうは なんようびですか? 오늘은 무슨 요일이에요?", "paras": ["きょう(kyou, 쿄-)는 '오늘', あした(ashita, 아시타)는 '내일', きのう(kinou, 키노-)는 '어제'예요.", "'무슨 요일'은 なんようび(nan'youbi, 난요-비)예요. 대답은 요일 뒤에 です를 붙이면 돼요."], "example": "A: きょうは なんようびですか。 B: きんようびです。 (오늘은 무슨 요일이에요? / 금요일이에요.)", "figure": "금요일에 동그라미를 친 달력"}], "keywords": [{"word": "じ", "meaning": "~시 (ji, 지)"}, {"word": "はん", "meaning": "반, 30분 (han, 한)"}, {"word": "ようび", "meaning": "요일 (youbi, 요-비)"}, {"word": "いま", "meaning": "지금 (ima, 이마)"}, {"word": "きょう・あした・きのう", "meaning": "오늘・내일・어제"}], "expressions": [{"en": "いま なんじですか。", "ko": "지금 몇 시예요?", "note": "ima nanji desu ka (이마 난지데스카)"}, {"en": "さんじです。", "ko": "3시예요.", "note": "sanji desu (산지데스)"}, {"en": "よじ", "ko": "4시", "note": "yoji (요지)"}, {"en": "しちじはん", "ko": "7시 반", "note": "shichijihan (시치지한)"}, {"en": "くじ", "ko": "9시", "note": "kuji (쿠지)"}, {"en": "きょうは なんようびですか。", "ko": "오늘은 무슨 요일이에요?", "note": "kyou wa nan'youbi desu ka (쿄-와 난요-비데스카)"}, {"en": "げつようび", "ko": "월요일", "note": "getsuyoubi (게츠요-비)"}, {"en": "すいようび", "ko": "수요일", "note": "suiyoubi (스이요-비)"}, {"en": "きんようび", "ko": "금요일", "note": "kin'youbi (킨요-비)"}, {"en": "どようび", "ko": "토요일", "note": "doyoubi (도요-비)"}, {"en": "にちようび", "ko": "일요일", "note": "nichiyoubi (니치요-비)"}, {"en": "あした", "ko": "내일", "note": "ashita (아시타)"}], "quiz": [{"q": "いま なんじですか。의 뜻은?", "choices": ["지금 몇 시예요?", "오늘은 무슨 요일이에요?", "몇 살이에요?", "지금 어디예요?"], "answer": 0, "explain": "いま는 '지금', なんじ는 '몇 시'예요."}, {"q": "'4시'를 일본어로 바르게 말한 것은?", "choices": ["よんじ", "よじ", "しじ", "よっじ"], "answer": 1, "explain": "4시는 특별하게 よじ(요지)라고 해요."}, {"q": "すいようび는 무슨 요일일까요?", "choices": ["월요일", "화요일", "수요일", "목요일"], "answer": 2, "explain": "水(すい)는 '물 수' 자, すいようび는 수요일이에요."}, {"q": "'7시 반'을 일본어로 바르게 말한 것은?", "choices": ["ななじはん", "しちじ", "はんしちじ", "しちじはん"], "answer": 3, "explain": "7시는 しちじ, 반은 はん이에요. 그래서 しちじはん이에요."}, {"q": "오늘이 금요일이면, あした(내일)는 무슨 요일일까요?", "choices": ["にちようび", "どようび", "もくようび", "げつようび"], "answer": 1, "explain": "금요일 다음 날은 토요일, どようび예요."}], "summary": ["시간은 숫자 + じ. 4시 よじ, 7시 しちじ, 9시 くじ는 특별해요. 30분은 はん이에요.", "요일은 月(げつ)・火(か)・水(すい)・木(もく)・金(きん)・土(ど)・日(にち) + ようび, 한국어와 순서가 같아요.", "いま なんじですか(몇 시?), きょうは なんようびですか(무슨 요일?)로 물어요."], "parent_tip": "부모님께: 요일은 한자 뜻이 한국어와 같아 아이들이 금방 익힙니다. 반대로 4시(よじ)・7시(しちじ)・9시(くじ)는 숫자 읽기와 달라 자주 틀리니, 집 시계를 보며 하루에 한두 번 \"いま なんじですか。\"라고 물어봐 주세요. 이 단원에서는 '몇 분'은 다루지 않고 정각과 반(はん)만 연습합니다."}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','시간과 요일',5,'j5-05' where not exists (select 1 from public.topics where lesson_slug='j5-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-06','5~6','일본어','음식 주문 ~をください','일본 식당에서 음식을 어떻게 주문할까?','assets/img/l_j5-06.jpg',$j${"intro": "일본 여행 중 라멘 가게에 들어갔어요. 맛있는 라멘을 먹으려면 주문을 해야겠죠? 오늘은 \"○○ 주세요!\"라고 말하는 ~を ください를 배워요.", "sections": [{"heading": "가게에 들어가면 いらっしゃいませ", "paras": ["일본 가게에 들어가면 직원이 いらっしゃいませ(irasshaimase, 이랏샤이마세)라고 말해요. '어서 오세요'라는 뜻이에요.", "직원을 부를 때는 손을 살짝 들고 すみません(sumimasen, 스미마센)이라고 해요. '저기요'라는 뜻으로 쓸 수 있어요."], "example": "てんいん(직원): いらっしゃいませ。 / わたし: すみません、メニューを ください。", "figure": "식당 입구에서 인사하는 직원과 손을 든 아이"}, {"heading": "~を ください ○○ 주세요", "paras": ["'○○ 주세요'는 ○○を ください(o kudasai, 오 쿠다사이)라고 해요. ください는 '주세요'예요.", "を는 글자 이름이 '오'이고, 소리도 お와 똑같이 '오(o)'예요. 물건 뒤에 붙여서 '~을/를'이라는 뜻이 돼요."], "example": "ラーメンを ください。(raamen o kudasai, 라-멘오 쿠다사이) → 라멘 주세요.", "figure": "김이 나는 라멘 한 그릇"}, {"heading": "메뉴 이름을 알아봐요", "paras": ["음식: ラーメン(raamen, 라-멘) 라멘, うどん(udon, 우동) 우동, カレー(karee, 카레-) 카레, おにぎり(onigiri, 오니기리) 주먹밥", "마실 것: おみず(omizu, 오미즈) 물, おちゃ(ocha, 오차) 차, ジュース(juusu, 주-스) 주스", "두 가지를 함께 시킬 때는 と(to, 토) '~와/과'로 이어요. うどんと おちゃを ください는 '우동과 차 주세요'예요."], "example": "カレーと ジュースを ください。 (카레와 주스 주세요.)", "figure": "우동, 카레, 주먹밥, 주스가 놓인 식탁"}, {"heading": "몇 개인지도 말해요", "paras": ["개수를 말할 때는 ひとつ(hitotsu, 히토츠) 한 개, ふたつ(futatsu, 후타츠) 두 개, みっつ(mittsu, 밋츠) 세 개를 써요.", "개수는 ください 바로 앞에 넣어요. 'ラーメンを ふたつ ください'는 '라멘 두 개 주세요'예요."], "example": "おにぎりを みっつ ください。(onigiri o mittsu kudasai, 오니기리오 밋츠 쿠다사이) → 주먹밥 세 개 주세요.", "figure": "주먹밥 세 개가 놓인 접시"}, {"heading": "먹기 전과 먹은 뒤의 인사", "paras": ["먹기 전에는 두 손을 모으고 いただきます(itadakimasu, 이타다키마스) '잘 먹겠습니다'라고 해요.", "다 먹은 뒤에는 ごちそうさまでした(gochisousama deshita, 고치소-사마데시타) '잘 먹었습니다'라고 해요. 맛있으면 おいしい(oishii, 오이시-) '맛있다'라고 말해 봐요!"], "example": "いただきます。 → (냠냠) おいしい！ → ごちそうさまでした。", "figure": "두 손을 모으고 식사 인사를 하는 아이"}], "keywords": [{"word": "ください", "meaning": "주세요 (kudasai, 쿠다사이)"}, {"word": "を", "meaning": "'~을/를'. 소리는 お와 같은 '오(o)'"}, {"word": "と", "meaning": "'~와/과' (to, 토). 두 가지를 이어요"}, {"word": "ひとつ・ふたつ・みっつ", "meaning": "한 개・두 개・세 개"}, {"word": "いただきます", "meaning": "잘 먹겠습니다 (먹기 전 인사)"}], "expressions": [{"en": "いらっしゃいませ。", "ko": "어서 오세요. (가게 직원이 하는 말)", "note": "irasshaimase (이랏샤이마세)"}, {"en": "すみません。", "ko": "저기요. / 죄송합니다.", "note": "sumimasen (스미마센)"}, {"en": "ラーメンを ください。", "ko": "라멘 주세요.", "note": "raamen o kudasai (라-멘오 쿠다사이)"}, {"en": "おみずを ください。", "ko": "물 주세요.", "note": "omizu o kudasai (오미즈오 쿠다사이)"}, {"en": "うどんと おちゃを ください。", "ko": "우동과 차 주세요.", "note": "udon to ocha o kudasai (우동토 오차오 쿠다사이)"}, {"en": "ひとつ", "ko": "한 개", "note": "hitotsu (히토츠)"}, {"en": "ふたつ", "ko": "두 개", "note": "futatsu (후타츠)"}, {"en": "みっつ", "ko": "세 개", "note": "mittsu (밋츠)"}, {"en": "いただきます。", "ko": "잘 먹겠습니다.", "note": "itadakimasu (이타다키마스)"}, {"en": "ごちそうさまでした。", "ko": "잘 먹었습니다.", "note": "gochisousama deshita (고치소-사마데시타)"}, {"en": "おいしい！", "ko": "맛있다!", "note": "oishii (오이시-)"}], "quiz": [{"q": "'라멘 주세요.'를 일본어로 바르게 말한 것은?", "choices": ["ラーメンを ください。", "ラーメンが すきです。", "ラーメンは なんですか。", "ラーメンです。"], "answer": 0, "explain": "'○○ 주세요'는 ○○を ください예요."}, {"q": "가게 직원이 손님에게 하는 いらっしゃいませ의 뜻은?", "choices": ["잘 먹었습니다.", "어서 오세요.", "얼마예요?", "맛있어요."], "answer": 1, "explain": "いらっしゃいませ는 '어서 오세요'예요."}, {"q": "'우동과 차'에서 '~과'에 해당하는 말은?\nうどん[  ] おちゃ", "choices": ["を", "が", "と", "も"], "answer": 2, "explain": "두 가지를 이을 때는 と를 써요."}, {"q": "밥을 먹기 __전에__ 하는 인사는?", "choices": ["ごちそうさまでした", "すみません", "いらっしゃいませ", "いただきます"], "answer": 3, "explain": "먹기 전에는 いただきます, 먹은 뒤에는 ごちそうさまでした예요."}, {"q": "おにぎりを ふたつ ください。는 무슨 뜻일까요?", "choices": ["주먹밥 세 개 주세요.", "주먹밥 두 개 주세요.", "주먹밥 한 개 주세요.", "주먹밥을 좋아해요."], "answer": 1, "explain": "ふたつ는 '두 개'예요."}], "summary": ["'○○ 주세요'는 ○○を ください(오 쿠다사이)예요. を는 '오'로 읽어요.", "두 가지는 と로 잇고, 개수 ひとつ・ふたつ・みっつ는 ください 앞에 넣어요.", "먹기 전 いただきます, 먹은 뒤 ごちそうさまでした라고 인사해요."], "parent_tip": "부모님께: を는 '워'가 아니라 お와 같은 '오' 소리로 읽습니다. 집에서 식사할 때 아이가 \"おみずを ください。\"로 물을 달라고 하거나, 식사 전후 인사를 일본어로 해 보는 것만으로도 금방 익숙해집니다. 숫자 ひとつ・ふたつ・みっつ는 앞에서 배운 いち・に・さん과 다른 '개수 세기'라는 점을 짚어 주세요."}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','음식 주문 ~をください',6,'j5-06' where not exists (select 1 from public.topics where lesson_slug='j5-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-07','5~6','일본어','값 묻기 いくら','일본 가게에서 ''얼마예요?''는 어떻게 물을까?','assets/img/l_j5-07.jpg',$j${"intro": "일본 문구점에서 귀여운 지우개를 발견했어요. 값이 얼마인지 궁금할 때는 어떻게 물어볼까요? 오늘은 값을 묻는 いくら와 일본 돈 えん(엔)을 세는 법을 배워요.", "sections": [{"heading": "これは いくらですか? 이건 얼마예요?", "paras": ["값을 물을 때는 いくらですか(ikura desu ka, 이쿠라데스카)라고 해요. いくら는 '얼마'라는 뜻이에요.", "물건을 가리키며 これは いくらですか(코레와 이쿠라데스카)라고 하면 '이것은 얼마예요?'가 돼요. 앞에서 배운 これ・それ・あれ를 함께 써 보세요."], "example": "これは いくらですか。(kore wa ikura desu ka, 코레와 이쿠라데스카) → 이것은 얼마예요?", "figure": "지우개를 들고 직원에게 묻는 아이"}, {"heading": "일본 돈은 えん(엔)", "paras": ["일본 돈의 단위는 えん(en, 엔)이에요. 숫자 뒤에 えん을 붙여요.", "100은 ひゃく(hyaku, 햐쿠), 1000은 せん(sen, 센)이에요. 그래서 100엔은 ひゃくえん(햐쿠엔), 1000엔은 せんえん(센엔)이에요."], "example": "ひゃくえん(100엔) · ごひゃくえん(500엔) · せんえん(1000엔)", "figure": "동전과 지폐가 놓인 작은 접시"}, {"heading": "100 단위 숫자, 소리가 바뀌는 것 조심!", "paras": ["200 にひゃく(nihyaku, 니햐쿠), 400 よんひゃく(yonhyaku, 용햐쿠), 500 ごひゃく(gohyaku, 고햐쿠), 700 ななひゃく(nanahyaku, 나나햐쿠), 900 きゅうひゃく(kyuuhyaku, 큐-햐쿠)는 숫자 + ひゃく예요.", "하지만 300은 さんびゃく(sanbyaku, 삼뱌쿠), 600은 ろっぴゃく(roppyaku, 롯퍄쿠), 800은 はっぴゃく(happyaku, 핫퍄쿠)로 소리가 바뀌어요.", "150처럼 10 단위가 붙으면 뒤에 이어 말해요. 50은 ごじゅう(gojuu, 고주-)니까 150엔은 ひゃくごじゅうえん(햐쿠고주-엔)이에요."], "example": "300 さんびゃく · 600 ろっぴゃく · 800 はっぴゃく / 150えん ひゃくごじゅうえん", "figure": ""}, {"heading": "대답을 듣고 사기", "paras": ["직원은 ○○えんです라고 대답해요. 사고 싶으면 앞에서 배운 ~を ください를 써서 これを ください(코레오 쿠다사이) '이거 주세요'라고 해요.", "값이 비싸면 たかい(takai, 타카이), 싸면 やすい(yasui, 야스이)라고 해요. 여러 개를 사면 ぜんぶで いくらですか(zenbu de ikura desu ka, 젬부데 이쿠라데스카) '전부 얼마예요?'라고 물어요."], "example": "A: これは いくらですか。 B: ひゃくえんです。 A: やすい！ これを ください。", "figure": "계산대 위에 지우개와 연필이 놓인 문구점"}], "keywords": [{"word": "いくら", "meaning": "얼마 (ikura, 이쿠라)"}, {"word": "えん", "meaning": "일본 돈의 단위, 엔 (en)"}, {"word": "ひゃく・せん", "meaning": "100(hyaku, 햐쿠)・1000(sen, 센)"}, {"word": "たかい・やすい", "meaning": "비싸다(takai, 타카이)・싸다(yasui, 야스이)"}, {"word": "ぜんぶで", "meaning": "전부 해서, 모두 합쳐서 (zenbu de, 젬부데)"}], "expressions": [{"en": "いくらですか。", "ko": "얼마예요?", "note": "ikura desu ka (이쿠라데스카)"}, {"en": "これは いくらですか。", "ko": "이것은 얼마예요?", "note": "kore wa ikura desu ka (코레와 이쿠라데스카)"}, {"en": "ひゃくえんです。", "ko": "100엔이에요.", "note": "hyakuen desu (햐쿠엔데스)"}, {"en": "さんびゃくえん", "ko": "300엔", "note": "sanbyakuen (삼뱌쿠엔)"}, {"en": "ろっぴゃくえん", "ko": "600엔", "note": "roppyakuen (롯퍄쿠엔)"}, {"en": "はっぴゃくえん", "ko": "800엔", "note": "happyakuen (핫퍄쿠엔)"}, {"en": "せんえん", "ko": "1000엔", "note": "sen'en (센엔)"}, {"en": "ひゃくごじゅうえん", "ko": "150엔", "note": "hyakugojuuen (햐쿠고주-엔)"}, {"en": "これを ください。", "ko": "이거 주세요.", "note": "kore o kudasai (코레오 쿠다사이)"}, {"en": "たかい", "ko": "비싸다", "note": "takai (타카이)"}, {"en": "やすい", "ko": "싸다", "note": "yasui (야스이)"}, {"en": "ぜんぶで いくらですか。", "ko": "전부 얼마예요?", "note": "zenbu de ikura desu ka (젬부데 이쿠라데스카)"}], "quiz": [{"q": "いくらですか。의 뜻은?", "choices": ["얼마예요?", "몇 살이에요?", "몇 시예요?", "무엇이에요?"], "answer": 0, "explain": "いくら는 '얼마'예요."}, {"q": "ごひゃくえん은 얼마일까요?", "choices": ["50엔", "500엔", "5000엔", "150엔"], "answer": 1, "explain": "ご(5) + ひゃく(100) = 500, ごひゃくえん은 500엔이에요."}, {"q": "'300엔'을 일본어로 바르게 말한 것은?", "choices": ["さんひゃくえん", "さんぜんえん", "さんびゃくえん", "さんじゅうえん"], "answer": 2, "explain": "300은 소리가 바뀌어 さんびゃく예요."}, {"q": "물건이 너무 비쌀 때 하는 말은?", "choices": ["やすい", "おいしい", "すき", "たかい"], "answer": 3, "explain": "たかい는 '비싸다', やすい는 '싸다'예요."}, {"q": "100엔짜리 지우개 2개를 샀어요. 전부 얼마일까요?", "choices": ["ひゃくえん", "にひゃくえん", "さんびゃくえん", "せんえん"], "answer": 1, "explain": "100 × 2 = 200, にひゃくえん이에요."}], "summary": ["값은 いくらですか(이쿠라데스카)로 묻고, ○○えんです로 대답해요.", "100은 ひゃく, 1000은 せん. 300 さんびゃく, 600 ろっぴゃく, 800 はっぴゃく는 소리가 바뀌어요.", "사고 싶으면 これを ください, 비싸면 たかい, 싸면 やすい라고 해요."], "parent_tip": "부모님께: 100 단위의 소리 변화(さんびゃく・ろっぴゃく・はっぴゃく)는 일본 아이들도 따로 외우는 부분이니 천천히 반복해 주세요. 집에 있는 물건에 100엔, 300엔처럼 가격표를 붙이고 가게 놀이를 하면 いくらですか → ○○えんです → これを ください 흐름을 자연스럽게 연습할 수 있습니다. 환율은 자주 바뀌므로 원화 환산은 다루지 않았습니다."}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','값 묻기 いくら',7,'j5-07' where not exists (select 1 from public.topics where lesson_slug='j5-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-08','5~6','일본어','장소 묻기 どこ','''화장실이 어디예요?''는 일본어로 어떻게 물을까?','assets/img/l_j5-08.jpg',$j${"intro": "일본 여행 중 화장실이 급해졌어요! 이럴 때 \"화장실이 어디예요?\"라고 물을 수 있다면 정말 든든하겠죠? 오늘은 장소를 묻는 どこ와 위치를 말하는 법을 배워요.", "sections": [{"heading": "ここ・そこ・あそこ・どこ", "paras": ["앞에서 배운 これ・それ・あれ・どれ 기억나요? 장소를 말할 때는 ここ(koko, 코코) '여기', そこ(soko, 소코) '거기', あそこ(asoko, 아소코) '저기', どこ(doko, 도코) '어디'를 써요.", "こ・そ・あ・ど 규칙은 똑같아요. 저기만 あこ가 아니라 あそこ라는 것을 조심해요."], "example": "ここ(여기) · そこ(거기) · あそこ(저기) · どこ(어디)", "figure": "아이가 가까운 곳, 친구 쪽, 먼 곳을 차례로 가리키는 모습"}, {"heading": "~は どこですか? ~은 어디예요?", "paras": ["'○○은 어디예요?'는 ○○は どこですか(wa doko desu ka, 와 도코데스카)라고 해요.", "길을 물을 때는 먼저 すみません(스미마센) '실례합니다'라고 말을 걸면 예의 바르게 들려요."], "example": "すみません、トイレは どこですか。(sumimasen, toire wa doko desu ka, 스미마센 토이레와 도코데스카) → 실례합니다, 화장실은 어디예요?", "figure": "길에서 어른에게 공손하게 길을 묻는 아이"}, {"heading": "장소 이름을 알아봐요", "paras": ["トイレ(toire, 토이레) 화장실, えき(eki, 에키) 역, がっこう(gakkou, 각코-) 학교, コンビニ(konbini, 콤비니) 편의점, こうえん(kouen, 코-엔) 공원, びょういん(byouin, 뵤-인) 병원", "びょういん(byouin, 뵤-인) 병원과 びよういん(biyouin, 비요-인) 미용실은 아주 비슷해요. 작은 ょ인지 큰 よ인지 잘 봐요!"], "example": "えきは あそこです。(eki wa asoko desu, 에키와 아소코데스) → 역은 저기예요.", "figure": "역, 공원, 편의점이 보이는 거리 풍경"}, {"heading": "위・아래・안・옆", "paras": ["물건이 어디 있는지 말할 때는 ○○の うえ(no ue, 노 우에) '○○ 위', ○○の した(shita, 시타) '아래', ○○の なか(naka, 나카) '안', ○○の となり(tonari, 토나리) '옆'을 써요.", "の는 '~의'라는 뜻이에요. つくえの うえ는 '책상의 위', 즉 '책상 위'예요."], "example": "A: ねこは どこですか。 B: つくえの したです。 (고양이는 어디예요? / 책상 아래예요.)", "figure": "책상 아래에 숨은 고양이"}, {"heading": "みぎ・ひだり 그리고 고맙습니다", "paras": ["방향은 みぎ(migi, 미기) '오른쪽', ひだり(hidari, 히다리) '왼쪽'이에요. トイレは みぎです는 '화장실은 오른쪽이에요'예요.", "길을 알려 주면 ありがとうございます(arigatou gozaimasu, 아리가토- 고자이마스) '고맙습니다'라고 꼭 인사해요."], "example": "A: コンビニは どこですか。 B: ひだりです。 A: ありがとうございます。", "figure": ""}], "keywords": [{"word": "どこ", "meaning": "어디 (doko, 도코)"}, {"word": "ここ・そこ・あそこ", "meaning": "여기・거기・저기"}, {"word": "の", "meaning": "~의 (no, 노). つくえの うえ = 책상 위"}, {"word": "うえ・した・なか・となり", "meaning": "위・아래・안・옆"}, {"word": "みぎ・ひだり", "meaning": "오른쪽・왼쪽"}], "expressions": [{"en": "どこですか。", "ko": "어디예요?", "note": "doko desu ka (도코데스카)"}, {"en": "トイレは どこですか。", "ko": "화장실은 어디예요?", "note": "toire wa doko desu ka (토이레와 도코데스카)"}, {"en": "えきは あそこです。", "ko": "역은 저기예요.", "note": "eki wa asoko desu (에키와 아소코데스)"}, {"en": "ここ", "ko": "여기", "note": "koko (코코)"}, {"en": "そこ", "ko": "거기", "note": "soko (소코)"}, {"en": "あそこ", "ko": "저기", "note": "asoko (아소코)"}, {"en": "つくえの うえ", "ko": "책상 위", "note": "tsukue no ue (츠쿠에노 우에)"}, {"en": "みぎ", "ko": "오른쪽", "note": "migi (미기)"}, {"en": "ひだり", "ko": "왼쪽", "note": "hidari (히다리)"}, {"en": "コンビニ", "ko": "편의점", "note": "konbini (콤비니)"}, {"en": "びょういん", "ko": "병원", "note": "byouin (뵤-인)"}, {"en": "ありがとうございます。", "ko": "고맙습니다.", "note": "arigatou gozaimasu (아리가토- 고자이마스)"}], "quiz": [{"q": "どこですか。의 뜻은?", "choices": ["어디예요?", "얼마예요?", "몇 시예요?", "무엇이에요?"], "answer": 0, "explain": "どこ는 '어디'예요."}, {"q": "'저기'를 일본어로 바르게 쓴 것은?", "choices": ["あこ", "あそこ", "あれ", "あの"], "answer": 1, "explain": "장소 '저기'는 あそこ예요. あれ는 '저것'이에요."}, {"q": "'역은 어디예요?'를 일본어로 바르게 말한 것은?", "choices": ["えきは なんですか。", "えきは いくらですか。", "えきは どこですか。", "えきが すきです。"], "answer": 2, "explain": "장소를 물을 때는 ~は どこですか예요."}, {"q": "つくえの うえ는 어디일까요?", "choices": ["책상 아래", "책상 안", "책상 옆", "책상 위"], "answer": 3, "explain": "うえ는 '위'예요. の는 '~의'예요."}, {"q": "びょういん(byouin)은 어떤 곳일까요?", "choices": ["병원", "미용실", "공원", "학교"], "answer": 0, "explain": "びょういん은 병원이에요. 미용실 びよういん과 헷갈리지 않게 조심해요."}], "summary": ["장소는 ここ(여기)・そこ(거기)・あそこ(저기)・どこ(어디)로 말해요.", "'○○은 어디예요?'는 ○○は どこですか(와 도코데스카)예요.", "위치는 ○○の うえ/した/なか/となり, 방향은 みぎ・ひだり로 말해요."], "parent_tip": "부모님께: これ・それ・あれ・どれ(물건)와 ここ・そこ・あそこ・どこ(장소)를 짝지어 보여 주면 아이가 규칙을 금방 찾습니다. 집 안에서 장난감을 숨기고 \"○○は どこですか。\"라고 물으면 아이가 \"つくえの したです。\"처럼 위치로 답하는 놀이를 해 보세요. 실제 여행에서는 'トイレは どこですか。' 한 문장만 알아도 큰 도움이 됩니다."}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','장소 묻기 どこ',8,'j5-08' where not exists (select 1 from public.topics where lesson_slug='j5-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-09','5~6','일본어','동사 ~ます','''먹어요, 가요, 봐요''는 일본어로 어떻게 말할까?','assets/img/l_j5-09.jpg',$j${"intro": "\"나는 빵을 먹어요.\", \"학교에 가요.\" 내가 하는 일을 말하려면 움직임을 나타내는 말(동사)이 필요해요. 오늘은 일본어 동사를 공손하게 말하는 ~ます를 배워요.", "sections": [{"heading": "~ます 는 '~해요'", "paras": ["일본어 동사를 공손하게 말할 때는 끝이 ~ます(masu, 마스)로 끝나요. 한국어의 '~해요'와 비슷해요.", "たべます(tabemasu, 타베마스) 먹어요, のみます(nomimasu, 노미마스) 마셔요, いきます(ikimasu, 이키마스) 가요, みます(mimasu, 미마스) 봐요.", "ます의 す는 약하게 소리 나서 '마스'처럼 들려요."], "example": "たべます 먹어요 · のみます 마셔요 · いきます 가요 · みます 봐요", "figure": "빵을 먹는 아이, 우유를 마시는 아이, 걸어가는 아이"}, {"heading": "하루 생활을 말해 봐요", "paras": ["おきます(okimasu, 오키마스) 일어나요, ねます(nemasu, 네마스) 자요, あそびます(asobimasu, 아소비마스) 놀아요, べんきょうします(benkyou shimasu, 벵쿄- 시마스) 공부해요.", "시간 뒤에 に(ni, 니)를 붙이면 '~시에'가 돼요. しちじに おきます는 '7시에 일어나요'예요."], "example": "しちじに おきます。(shichiji ni okimasu, 시치지니 오키마스) → 7시에 일어나요.", "figure": "아침에 알람시계를 끄며 일어나는 아이"}, {"heading": "を・に・で 짝꿍 글자", "paras": ["무엇을 하는지는 を(o, 오): パンを たべます(팡오 타베마스) '빵을 먹어요'.", "어디로 가는지는 に(ni, 니): がっこうに いきます(각코-니 이키마스) '학교에 가요'.", "어디에서 하는지는 で(de, 데): こうえんで あそびます(코-엔데 아소비마스) '공원에서 놀아요'."], "example": "テレビを みます。(terebi o mimasu, 테레비오 미마스) → 텔레비전을 봐요.", "figure": "공원에서 공놀이하는 아이들"}, {"heading": "안 해요는 ~ません, 했어요는 ~ました", "paras": ["ます를 ません(masen, 마센)으로 바꾸면 '안 해요'가 돼요. たべません은 '안 먹어요'예요.", "ます를 ました(mashita, 마시타)로 바꾸면 '했어요'가 돼요. たべました는 '먹었어요'예요.", "질문은 끝에 か를 붙여요. なにを たべますか(나니오 타베마스카)는 '무엇을 먹어요?'예요."], "example": "たべます(먹어요) → たべません(안 먹어요) → たべました(먹었어요)", "figure": ""}], "keywords": [{"word": "~ます", "meaning": "동사를 공손하게 말하는 끝 '~해요' (masu, 마스)"}, {"word": "~ません", "meaning": "'~안 해요' (masen, 마센)"}, {"word": "~ました", "meaning": "'~했어요' (mashita, 마시타)"}, {"word": "を", "meaning": "무엇을 하는지 (o, 오)"}, {"word": "に", "meaning": "어디로 가는지, 몇 시에 (ni, 니)"}, {"word": "で", "meaning": "어디에서 하는지 (de, 데)"}], "expressions": [{"en": "たべます。", "ko": "먹어요.", "note": "tabemasu (타베마스)"}, {"en": "のみます。", "ko": "마셔요.", "note": "nomimasu (노미마스)"}, {"en": "いきます。", "ko": "가요.", "note": "ikimasu (이키마스)"}, {"en": "みます。", "ko": "봐요.", "note": "mimasu (미마스)"}, {"en": "おきます。", "ko": "일어나요.", "note": "okimasu (오키마스)"}, {"en": "ねます。", "ko": "자요.", "note": "nemasu (네마스)"}, {"en": "べんきょうします。", "ko": "공부해요.", "note": "benkyou shimasu (벵쿄- 시마스)"}, {"en": "パンを たべます。", "ko": "빵을 먹어요.", "note": "pan o tabemasu (팡오 타베마스)"}, {"en": "がっこうに いきます。", "ko": "학교에 가요.", "note": "gakkou ni ikimasu (각코-니 이키마스)"}, {"en": "こうえんで あそびます。", "ko": "공원에서 놀아요.", "note": "kouen de asobimasu (코-엔데 아소비마스)"}, {"en": "たべません。", "ko": "안 먹어요.", "note": "tabemasen (타베마센)"}, {"en": "たべました。", "ko": "먹었어요.", "note": "tabemashita (타베마시타)"}], "quiz": [{"q": "たべます。의 뜻은?", "choices": ["먹어요.", "마셔요.", "가요.", "자요."], "answer": 0, "explain": "たべます는 '먹어요'예요."}, {"q": "'학교에 가요.'에서 빈칸에 알맞은 글자는?\nがっこう[  ] いきます。", "choices": ["を", "に", "で", "が"], "answer": 1, "explain": "가는 곳 뒤에는 に를 붙여요."}, {"q": "'공원에서 놀아요.'를 바르게 말한 것은?", "choices": ["こうえんを あそびます。", "こうえんに あそびます。", "こうえんで あそびます。", "こうえんが あそびます。"], "answer": 2, "explain": "무엇을 하는 장소 뒤에는 で를 붙여요."}, {"q": "みません。의 뜻은?", "choices": ["봐요.", "봤어요.", "볼까요?", "안 봐요."], "answer": 3, "explain": "ます를 ません으로 바꾸면 '안 해요'예요. みません은 '안 봐요'예요."}, {"q": "'먹었어요'를 일본어로 바르게 쓴 것은?", "choices": ["たべます", "たべました", "たべません", "たべますか"], "answer": 1, "explain": "ます → ました로 바꾸면 '했어요'가 돼요."}], "summary": ["동사를 공손하게 말할 때는 ~ます(마스): たべます, いきます, みます", "무엇을 → を, 어디로・몇 시에 → に, 어디에서 → で", "안 해요는 ~ません, 했어요는 ~ました, 질문은 끝에 か를 붙여요."], "parent_tip": "부모님께: 아이들이 가장 헷갈리는 것은 に(가는 곳)와 で(하는 곳)의 구분입니다. '학교에 가요'는 に, '학교에서 공부해요'는 で라는 짝을 반복해 주세요. 하루 일과를 시간 순서대로 \"しちじに おきます。 パンを たべます。 がっこうに いきます。\"처럼 말해 보는 '나의 하루 말하기'가 좋은 연습이 됩니다."}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','동사 ~ます',9,'j5-09' where not exists (select 1 from public.topics where lesson_slug='j5-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('j5-10','5~6','일본어','날씨와 형용사','''오늘은 더워요''는 일본어로 어떻게 말할까?','assets/img/l_j5-10.jpg',$j${"intro": "일본 사람들은 만나면 날씨 이야기로 인사를 자주 나눠요. \"날씨 좋네요!\", \"오늘 덥네요!\" 오늘은 날씨를 말하는 낱말과 '덥다, 춥다' 같은 꾸미는 말(형용사)을 배워요.", "sections": [{"heading": "맑음・흐림・비・눈", "paras": ["날씨 낱말은 はれ(hare, 하레) 맑음, くもり(kumori, 쿠모리) 흐림, あめ(ame, 아메) 비, ゆき(yuki, 유키) 눈이에요.", "'오늘은 ○○예요'는 きょうは ○○です라고 해요. 앞에서 배운 きょう(오늘)를 기억하죠?"], "example": "きょうは あめです。(kyou wa ame desu, 쿄-와 아메데스) → 오늘은 비가 와요.", "figure": "창밖으로 비가 내리고 우산이 세워진 현관"}, {"heading": "いい てんきですね 날씨 좋네요", "paras": ["てんき(tenki, 텡키)는 '날씨', いい(ii, 이-)는 '좋다'예요. いい てんきですね(ii tenki desu ne, 이- 텡키데스네)는 '날씨가 좋네요'라는 인사예요.", "문장 끝의 ね(ne, 네)는 '~네요'처럼 상대에게 맞장구를 구하는 말이에요. 대답은 そうですね(sou desu ne, 소-데스네) '그렇네요'라고 해요."], "example": "A: いい てんきですね。 B: そうですね。", "figure": "맑은 하늘 아래 두 사람이 인사하는 모습"}, {"heading": "あつい・さむい 덥다・춥다", "paras": ["あつい(atsui, 아츠이) 덥다, さむい(samui, 사무이) 춥다, あたたかい(atatakai, 아타타카이) 따뜻하다, すずしい(suzushii, 스즈시-) 시원하다.", "이 낱말들은 모두 끝이 い로 끝나요. 이런 형용사를 'い형용사'라고 불러요. 뒤에 です를 붙이면 공손한 말이 돼요.", "계절과 짝지어 외워 봐요. はる(haru, 하루) 봄은 あたたかい, なつ(natsu, 나츠) 여름은 あつい, あき(aki, 아키) 가을은 すずしい, ふゆ(fuyu, 후유) 겨울은 さむい."], "example": "なつは あついです。(natsu wa atsui desu, 나츠와 아츠이데스) → 여름은 더워요.", "figure": "봄꽃, 여름 바다, 가을 낙엽, 겨울 눈사람 네 장면"}, {"heading": "안 추워요는 さむくないです", "paras": ["'안 ~해요'라고 말할 때는 끝의 い를 빼고 くない를 붙여요. さむい → さむくないです(samukunai desu, 사무쿠나이데스) '안 추워요'.", "あつい → あつくないです(아츠쿠나이데스) '안 더워요'. 단, いい(좋다)는 특별해서 よくないです(yokunai desu, 요쿠나이데스) '안 좋아요'라고 해요."], "example": "きょうは さむくないです。 (오늘은 안 추워요.)", "figure": ""}, {"heading": "날씨 말고도 쓰는 い형용사", "paras": ["おおきい(ookii, 오-키-) 크다, ちいさい(chiisai, 치-사이) 작다, たのしい(tanoshii, 타노시-) 즐겁다도 い형용사예요.", "형용사를 낱말 앞에 두면 꾸며 줄 수 있어요. おおきい いぬ는 '큰 개', たのしい なつ는 '즐거운 여름'이에요."], "example": "ゆきの ひは たのしいです。 (눈 오는 날은 즐거워요.)", "figure": "눈사람을 만들며 웃는 아이들"}], "keywords": [{"word": "てんき", "meaning": "날씨 (tenki, 텡키)"}, {"word": "はれ・くもり・あめ・ゆき", "meaning": "맑음・흐림・비・눈"}, {"word": "い형용사", "meaning": "あつい, さむい처럼 끝이 い로 끝나는 꾸미는 말"}, {"word": "~くないです", "meaning": "'안 ~해요' (い를 빼고 붙여요)"}, {"word": "ね", "meaning": "'~네요'처럼 맞장구를 구하는 말 (ne, 네)"}], "expressions": [{"en": "いい てんきですね。", "ko": "날씨가 좋네요.", "note": "ii tenki desu ne (이- 텡키데스네)"}, {"en": "そうですね。", "ko": "그렇네요.", "note": "sou desu ne (소-데스네)"}, {"en": "はれ", "ko": "맑음", "note": "hare (하레)"}, {"en": "くもり", "ko": "흐림", "note": "kumori (쿠모리)"}, {"en": "あめ", "ko": "비", "note": "ame (아메)"}, {"en": "ゆき", "ko": "눈", "note": "yuki (유키)"}, {"en": "あついです。", "ko": "더워요.", "note": "atsui desu (아츠이데스)"}, {"en": "さむいです。", "ko": "추워요.", "note": "samui desu (사무이데스)"}, {"en": "あたたかいです。", "ko": "따뜻해요.", "note": "atatakai desu (아타타카이데스)"}, {"en": "すずしいです。", "ko": "시원해요.", "note": "suzushii desu (스즈시-데스)"}, {"en": "さむくないです。", "ko": "안 추워요.", "note": "samukunai desu (사무쿠나이데스)"}, {"en": "きょうは あめです。", "ko": "오늘은 비가 와요.", "note": "kyou wa ame desu (쿄-와 아메데스)"}], "quiz": [{"q": "あついです。의 뜻은?", "choices": ["더워요.", "추워요.", "시원해요.", "따뜻해요."], "answer": 0, "explain": "あつい는 '덥다'예요."}, {"q": "'오늘은 눈이 와요.'를 바르게 말한 것은?", "choices": ["きょうは あめです。", "きょうは ゆきです。", "きょうは はれです。", "きょうは くもりです。"], "answer": 1, "explain": "ゆき는 '눈'이에요."}, {"q": "いい てんきですね。라는 말을 들었을 때 알맞은 대답은?", "choices": ["いただきます。", "はじめまして。", "そうですね。", "いくらですか。"], "answer": 2, "explain": "そうですね(그렇네요)로 맞장구를 쳐요."}, {"q": "'안 추워요.'를 바르게 말한 것은?", "choices": ["さむいです。", "さむいないです。", "さむいくないです。", "さむくないです。"], "answer": 3, "explain": "い를 빼고 くない를 붙여요. さむ + くないです."}, {"q": "가을(あき)과 가장 잘 어울리는 말은?", "choices": ["すずしい", "あつい", "さむい", "ゆき"], "answer": 0, "explain": "가을은 시원해요. すずしい(시원하다)예요."}], "summary": ["날씨: はれ(맑음)・くもり(흐림)・あめ(비)・ゆき(눈), '오늘은 ~예요'는 きょうは ~です.", "あつい(덥다)・さむい(춥다)・あたたかい(따뜻하다)・すずしい(시원하다)는 い형용사예요.", "'안 ~해요'는 い를 빼고 くないです. いい는 よくないです로 특별하게 바뀌어요."], "parent_tip": "부모님께: い형용사의 부정형은 끝의 い를 떼고 くない를 붙이는데, 아이들은 'さむいないです'처럼 い를 남기는 실수를 자주 합니다. 매일 아침 창밖을 보며 \"きょうは はれです。 さむいです。\"처럼 날씨 두 문장을 말하는 습관을 들이면 좋습니다. いい→よくない는 예외라는 점도 함께 짚어 주세요."}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','일본어','날씨와 형용사',10,'j5-10' where not exists (select 1 from public.topics where lesson_slug='j5-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-01','1~2','국어','1단계 · 모음 ㅏ ㅓ ㅗ ㅜ ㅡ ㅣ','입 모양을 바꾸면 어떤 소리가 날까?','assets/img/l_k1-01.jpg',$j${"intro": "😮 입을 크게 벌리고 \"아~\" 해 봐요. 😗 이번엔 입을 동그랗게 \"오~\". 소리가 달라졌지요? 오늘은 이렇게 입 모양으로 내는 글자, 모음을 만나요.", "sections": [{"heading": "모음은 입 모양 소리예요", "paras": ["모음은 혼자서도 소리가 나요.", "입 모양이 바뀌면 소리도 바뀌어요.", "오늘은 모음 여섯 개를 배워요."], "example": "ㅏ ㅓ ㅗ ㅜ ㅡ ㅣ", "figure": "거울 앞에서 아이가 입을 크게 벌리고 '아' 소리를 내는 모습"}, {"heading": "서 있는 모음 ㅏ ㅓ ㅣ", "paras": ["ㅏ는 막대 오른쪽에 짧은 줄이 있어요.", "ㅓ는 짧은 줄이 왼쪽에 있어요.", "ㅣ는 막대 하나뿐이에요."], "example": "😮 아 · 😯 어 · 😁 이", "figure": "세로 막대 세 개에 짧은 줄 위치가 다른 그림(ㅏ ㅓ ㅣ)"}, {"heading": "누워 있는 모음 ㅗ ㅜ ㅡ", "paras": ["ㅗ는 짧은 줄이 위에 있어요.", "ㅜ는 짧은 줄이 아래에 있어요.", "ㅡ는 누운 막대 하나예요."], "example": "😗 오 · 😙 우 · 😬 으", "figure": "가로 막대 세 개에 짧은 줄 위치가 다른 그림(ㅗ ㅜ ㅡ)"}, {"heading": "ㅇ과 함께 글자로 써요", "paras": ["모음을 글자로 쓸 때는 ㅇ을 앞에 붙여요.", "맨 앞의 ㅇ은 소리가 없어요.", "모음 두 개로 낱말도 만들 수 있어요."], "example": "👶 아이 · 🥒 오이 · 🦷 이", "figure": "책상 위에 놓인 오이와 아기 사진 카드"}], "keywords": [{"word": "모음", "meaning": "입 모양으로 내는 소리 글자예요. 혼자서도 소리가 나요."}, {"word": "ㅇ(이응)", "meaning": "모음 앞에 붙는 자리 글자예요. 맨 앞에서는 소리가 없어요."}, {"word": "입 모양", "meaning": "입을 벌리고, 오므리고, 옆으로 펴는 모양이에요."}], "expressions": [{"en": "아", "ko": "ㅇ + ㅏ", "note": "입을 크게 벌려요"}, {"en": "어", "ko": "ㅇ + ㅓ", "note": "입을 조금 덜 벌려요"}, {"en": "오", "ko": "ㅇ + ㅗ", "note": "입을 동그랗게 해요"}, {"en": "우", "ko": "ㅇ + ㅜ", "note": "입을 앞으로 쭉 내밀어요"}, {"en": "으", "ko": "ㅇ + ㅡ", "note": "입을 옆으로 살짝 펴요"}, {"en": "이", "ko": "ㅇ + ㅣ", "note": "입을 옆으로 쭉 펴요"}, {"en": "아이", "ko": "👶 어린 사람"}, {"en": "오이", "ko": "🥒 길쭉한 초록 채소"}, {"en": "아 어 오 우 으 이", "ko": "오늘 배운 모음 여섯 개를 차례로 읽어요"}], "quiz": [{"q": "😮 입을 크게 벌리면 나는 소리는?", "choices": ["아", "우", "이", "으"], "answer": 0, "explain": "입을 크게 벌리면 '아' 소리가 나요."}, {"q": "🥒 그림에 맞는 낱말은?", "choices": ["아이", "오이", "우이", "이이"], "answer": 1, "explain": "길쭉한 초록 채소는 '오이'예요."}, {"q": "짧은 줄이 아래에 있는 모음은?", "choices": ["ㅗ", "ㅡ", "ㅜ", "ㅏ"], "answer": 2, "explain": "ㅜ는 누운 막대 아래에 짧은 줄이 있어요."}, {"q": "글자 맨 앞에 붙은 ㅇ은 어떤 소리가 날까요?", "choices": ["ㄱ 소리", "응 소리", "아 소리", "소리가 없어요"], "answer": 3, "explain": "맨 앞의 ㅇ은 자리만 채우고 소리는 없어요."}, {"q": "막대 왼쪽에 짧은 줄이 있는 모음은?", "choices": ["ㅓ", "ㅏ", "ㅣ", "ㅗ"], "answer": 0, "explain": "ㅓ는 짧은 줄이 왼쪽에 있어요."}], "summary": ["모음은 입 모양으로 내는 소리예요.", "서 있는 모음은 ㅏ ㅓ ㅣ, 누워 있는 모음은 ㅗ ㅜ ㅡ예요.", "글자로 쓸 때는 ㅇ을 붙여요: 아 어 오 우 으 이."], "parent_tip": "부모님께: 아이가 ㅏ와 ㅓ, ㅗ와 ㅜ의 짧은 줄 방향을 자주 헷갈립니다. 거울 앞에서 함께 입 모양을 만들어 보며 '해님이 오른쪽에 있으면 ㅏ'처럼 이야기로 기억하게 해 주세요. \"'오이'의 '오'는 입이 어떤 모양이야?\" 하고 물어보면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-01_cover.mp3", "s0": "assets/audio/n/k1-01_s0.mp3", "s1": "assets/audio/n/k1-01_s1.mp3", "s2": "assets/audio/n/k1-01_s2.mp3", "s3": "assets/audio/n/k1-01_s3.mp3", "kw": "assets/audio/n/k1-01_kw.mp3", "q0": "assets/audio/n/k1-01_q0.mp3", "q1": "assets/audio/n/k1-01_q1.mp3", "q2": "assets/audio/n/k1-01_q2.mp3", "q3": "assets/audio/n/k1-01_q3.mp3", "q4": "assets/audio/n/k1-01_q4.mp3", "sum": "assets/audio/n/k1-01_sum.mp3"}}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','1단계 · 모음 ㅏ ㅓ ㅗ ㅜ ㅡ ㅣ',1,'k1-01' where not exists (select 1 from public.topics where lesson_slug='k1-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-02','1~2','국어','1단계 · 모음 ㅑ ㅕ ㅛ ㅠ','짧은 줄이 두 개면 어떤 소리가 날까?','assets/img/l_k1-02.jpg',$j${"intro": "🦊 \"여우\"와 🥛 \"우유\"를 소리 내 읽어 봐요. 지난번 모음에 짧은 줄을 하나 더 그으면 새 소리가 생겨요!", "sections": [{"heading": "짧은 줄을 하나 더!", "paras": ["ㅏ에 짧은 줄을 더 그으면 ㅑ예요.", "ㅓ에 하나 더 그으면 ㅕ예요."], "example": "ㅏ → ㅑ (아 → 야) · ㅓ → ㅕ (어 → 여)", "figure": "ㅏ 옆에 짧은 줄이 하나 더해져 ㅑ가 되는 그림"}, {"heading": "누운 모음도 두 줄", "paras": ["ㅗ에 짧은 줄을 더하면 ㅛ예요.", "ㅜ에 하나 더하면 ㅠ예요."], "example": "ㅗ → ㅛ (오 → 요) · ㅜ → ㅠ (우 → 유)", "figure": "ㅗ와 ㅛ, ㅜ와 ㅠ를 나란히 놓은 그림"}, {"heading": "'이'를 살짝 붙인 소리", "paras": ["\"이\"와 \"아\"를 빨리 이어 말해 봐요.", "\"야\" 소리가 나지요?", "ㅑ ㅕ ㅛ ㅠ는 이렇게 생긴 소리예요."], "example": "이+아 → 야 · 이+어 → 여 · 이+오 → 요 · 이+우 → 유", "figure": "아이가 손가락 두 개를 펴서 줄 두 개를 표현하는 모습"}, {"heading": "낱말을 읽어요", "paras": ["배운 모음으로 낱말을 읽어요.", "모음 열 개를 차례로 외워 봐요."], "example": "🦊 여우 · 🥛 우유 · 🪀 요요 · 🤕 아야!", "figure": "책상 위의 우유 한 잔과 요요 장난감"}], "keywords": [{"word": "ㅑ ㅕ ㅛ ㅠ", "meaning": "짧은 줄이 두 개인 모음이에요."}, {"word": "모음 순서", "meaning": "ㅏ ㅑ ㅓ ㅕ ㅗ ㅛ ㅜ ㅠ ㅡ ㅣ, 모두 열 개예요."}, {"word": "짧은 줄", "meaning": "막대에 붙은 작은 줄이에요. 개수와 방향으로 모음이 달라져요."}], "expressions": [{"en": "야", "ko": "ㅇ + ㅑ", "note": "이+아를 빨리"}, {"en": "여", "ko": "ㅇ + ㅕ", "note": "이+어를 빨리"}, {"en": "요", "ko": "ㅇ + ㅛ", "note": "이+오를 빨리"}, {"en": "유", "ko": "ㅇ + ㅠ", "note": "이+우를 빨리"}, {"en": "여우", "ko": "🦊 꼬리가 긴 동물"}, {"en": "우유", "ko": "🥛 소에서 얻는 하얀 음료"}, {"en": "요요", "ko": "🪀 줄을 감았다 풀며 노는 장난감"}, {"en": "아야", "ko": "🤕 아플 때 내는 소리"}, {"en": "아 야 어 여 오 요 우 유 으 이", "ko": "모음 열 개를 차례로 읽어요"}], "quiz": [{"q": "ㅏ에 짧은 줄을 하나 더 그으면?", "choices": ["ㅓ", "ㅑ", "ㅕ", "ㅛ"], "answer": 1, "explain": "ㅏ에 짧은 줄을 더하면 ㅑ가 돼요."}, {"q": "🦊 그림에 맞는 낱말은?", "choices": ["여우", "요우", "야우", "유우"], "answer": 0, "explain": "꼬리가 긴 동물은 '여우'예요."}, {"q": "🥛 그림에 맞는 낱말은?", "choices": ["오유", "요요", "이유", "우유"], "answer": 3, "explain": "하얀 음료는 '우유'예요."}, {"q": "\"이\"와 \"오\"를 빨리 이어 말하면?", "choices": ["야", "여", "요", "유"], "answer": 2, "explain": "이+오를 빨리 말하면 '요'가 돼요."}, {"q": "모음 순서에서 빈 곳은?  아 야 어 ( ) 오", "choices": ["요", "여", "유", "우"], "answer": 1, "explain": "아 야 어 여 오 순서예요."}], "summary": ["ㅑ ㅕ ㅛ ㅠ는 짧은 줄이 두 개예요.", "'이'를 살짝 붙여 빨리 읽으면 야 여 요 유 소리가 나요.", "모음 열 개: 아 야 어 여 오 요 우 유 으 이."], "parent_tip": "부모님께: ㅕ와 ㅑ, ㅛ와 ㅠ처럼 줄 방향이 다른 짝을 아이가 자주 바꿔 읽습니다. 손가락 두 개를 펴서 방향을 함께 만들어 보세요. \"'우유'의 '유'는 줄이 위에 있을까, 아래에 있을까?\" 하고 물어보면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-02_cover.mp3", "s0": "assets/audio/n/k1-02_s0.mp3", "s1": "assets/audio/n/k1-02_s1.mp3", "s2": "assets/audio/n/k1-02_s2.mp3", "s3": "assets/audio/n/k1-02_s3.mp3", "kw": "assets/audio/n/k1-02_kw.mp3", "q0": "assets/audio/n/k1-02_q0.mp3", "q1": "assets/audio/n/k1-02_q1.mp3", "q2": "assets/audio/n/k1-02_q2.mp3", "q3": "assets/audio/n/k1-02_q3.mp3", "q4": "assets/audio/n/k1-02_q4.mp3", "sum": "assets/audio/n/k1-02_sum.mp3"}}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','1단계 · 모음 ㅑ ㅕ ㅛ ㅠ',2,'k1-02' where not exists (select 1 from public.topics where lesson_slug='k1-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-03','1~2','국어','1단계 · 자음 ㄱ ㄴ ㄷ ㄹ','ㄱ ㄴ ㄷ ㄹ, 이름이 뭘까?','assets/img/l_k1-03.jpg',$j${"intro": "🦆 \"오리\"를 읽어 봐요. '리'에는 모음 말고 다른 글자가 있어요. 오늘은 모음과 짝을 이루는 자음 네 개를 만나요.", "sections": [{"heading": "자음은 모음의 짝꿍", "paras": ["자음은 모음과 만나 글자가 돼요.", "ㅇ 자리에 자음을 넣어 보세요.", "자음마다 이름이 있어요."], "example": "ㅇ+ㅏ=아 → ㄱ+ㅏ=가", "figure": "'아' 카드의 ㅇ 자리에 ㄱ 카드를 끼워 넣는 그림"}, {"heading": "ㄱ 기역, ㄴ 니은", "paras": ["ㄱ의 이름은 '기역'이에요.", "ㄴ의 이름은 '니은'이에요.", "ㄱ은 아래로 꺾이고, ㄴ은 위에서 내려와 옆으로 가요."], "example": "ㄱ+ㅏ=가 · ㄴ+ㅏ=나", "figure": "ㄱ과 ㄴ의 꺾이는 방향을 화살표로 보여 주는 그림"}, {"heading": "ㄷ 디귿, ㄹ 리을", "paras": ["ㄷ의 이름은 '디귿'이에요.", "ㄴ 위에 줄을 하나 그으면 ㄷ이에요.", "ㄹ의 이름은 '리을'이에요. 꼬불꼬불해요."], "example": "ㄷ+ㅏ=다 · ㄹ+ㅏ=라", "figure": "ㄴ 위에 가로줄을 더해 ㄷ이 되는 그림, 꼬불꼬불한 ㄹ"}, {"heading": "낱말을 읽어요", "paras": ["배운 자음과 모음으로 낱말을 읽어요.", "글자를 하나씩 천천히 읽어 봐요."], "example": "🦆 오리 · 🦵 다리 · 🍖 고기 · 👞 구두 · 📻 라디오", "figure": "책상 위의 오리 인형과 작은 구두"}], "keywords": [{"word": "자음", "meaning": "모음과 만나야 소리가 나는 글자예요."}, {"word": "기역 · 니은", "meaning": "ㄱ과 ㄴ의 이름이에요."}, {"word": "디귿 · 리을", "meaning": "ㄷ과 ㄹ의 이름이에요."}, {"word": "글자 만들기", "meaning": "자음 + 모음 = 글자 (ㄱ+ㅏ=가)."}], "expressions": [{"en": "기역", "ko": "자음 ㄱ의 이름"}, {"en": "니은", "ko": "자음 ㄴ의 이름"}, {"en": "디귿", "ko": "자음 ㄷ의 이름", "note": "[디귿]"}, {"en": "리을", "ko": "자음 ㄹ의 이름"}, {"en": "가 나 다 라", "ko": "ㄱ ㄴ ㄷ ㄹ에 ㅏ를 붙인 글자"}, {"en": "고기", "ko": "🍖 먹는 고기"}, {"en": "오리", "ko": "🦆 꽥꽥 우는 새"}, {"en": "다리", "ko": "🦵 몸의 다리, 또는 강을 건너는 다리"}, {"en": "구두", "ko": "👞 가죽으로 만든 신"}, {"en": "라디오", "ko": "📻 소리를 듣는 기계"}], "quiz": [{"q": "ㄱ의 이름은?", "choices": ["기역", "니은", "디귿", "리을"], "answer": 0, "explain": "ㄱ은 '기역'이라고 불러요."}, {"q": "🦆 그림에 맞는 낱말은?", "choices": ["오기", "오니", "오리", "오두"], "answer": 2, "explain": "꽥꽥 우는 새는 '오리'예요."}, {"q": "ㄴ 위에 줄을 하나 그으면 어떤 자음?", "choices": ["ㄱ", "ㄹ", "ㅇ", "ㄷ"], "answer": 3, "explain": "ㄴ 위에 줄을 더하면 ㄷ이 돼요."}, {"q": "ㄷ과 ㅏ가 만나면?", "choices": ["가", "다", "나", "라"], "answer": 1, "explain": "ㄷ+ㅏ=다예요."}, {"q": "'리을'은 어떤 자음의 이름?", "choices": ["ㄹ", "ㄷ", "ㄴ", "ㄱ"], "answer": 0, "explain": "꼬불꼬불한 ㄹ의 이름이 '리을'이에요."}], "summary": ["자음은 모음과 만나 글자가 돼요.", "ㄱ 기역, ㄴ 니은, ㄷ 디귿, ㄹ 리을.", "가 나 다 라처럼 자음 + 모음으로 글자를 만들어요."], "parent_tip": "부모님께: 아이가 ㄱ과 ㄴ의 방향을 거꾸로 쓰는 일이 많습니다. 손가락으로 공중에 크게 써 보게 해 주세요. 자음 이름(기역·디귿)은 소리와 달라 어려워하니 \"가나다라\" 노래로 먼저 익힌 뒤 이름을 붙이면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-03_cover.mp3", "s0": "assets/audio/n/k1-03_s0.mp3", "s1": "assets/audio/n/k1-03_s1.mp3", "s2": "assets/audio/n/k1-03_s2.mp3", "s3": "assets/audio/n/k1-03_s3.mp3", "kw": "assets/audio/n/k1-03_kw.mp3", "q0": "assets/audio/n/k1-03_q0.mp3", "q1": "assets/audio/n/k1-03_q1.mp3", "q2": "assets/audio/n/k1-03_q2.mp3", "q3": "assets/audio/n/k1-03_q3.mp3", "q4": "assets/audio/n/k1-03_q4.mp3", "sum": "assets/audio/n/k1-03_sum.mp3"}}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','1단계 · 자음 ㄱ ㄴ ㄷ ㄹ',3,'k1-03' where not exists (select 1 from public.topics where lesson_slug='k1-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-04','1~2','국어','1단계 · 자음 ㅁ ㅂ ㅅ ㅇ','네모 ㅁ, 동그라미 ㅇ은 어떤 소리일까?','assets/img/l_k1-04.jpg',$j${"intro": "🦋 \"나비\"와 🌳 \"나무\"를 읽어 봐요. 지난번에 배운 ㄴ 말고도 새 자음이 숨어 있어요. 오늘은 ㅁ ㅂ ㅅ ㅇ을 만나요.", "sections": [{"heading": "ㅁ 미음, ㅂ 비읍", "paras": ["ㅁ은 네모 모양이에요. 이름은 '미음'이에요.", "ㅁ 위로 줄 두 개를 세우면 ㅂ이에요. 이름은 '비읍'이에요.", "둘 다 입술을 붙였다 떼며 소리 내요."], "example": "ㅁ+ㅏ=마 · ㅂ+ㅏ=바", "figure": "네모 ㅁ 위에 짧은 기둥 두 개가 생겨 ㅂ이 되는 그림"}, {"heading": "ㅅ 시옷", "paras": ["ㅅ은 사람이 걸어가는 모양 같아요.", "이름은 '시옷'이에요.", "이 사이로 바람을 '스~' 내보내요."], "example": "ㅅ+ㅏ=사 · ㅅ+ㅗ=소 🐮", "figure": "두 다리를 벌리고 선 사람과 ㅅ을 나란히 놓은 그림"}, {"heading": "ㅇ 이응", "paras": ["ㅇ은 동그라미예요. 이름은 '이응'이에요.", "글자 맨 앞의 ㅇ은 소리가 없어요.", "그래서 '아'는 모음 소리만 나요."], "example": "ㅇ+ㅏ=아 · ㅇ+ㅣ=이", "figure": "동그란 ㅇ과 동그란 단추를 나란히 놓은 그림"}, {"heading": "낱말을 읽어요", "paras": ["지금까지 배운 자음 여덟 개로 낱말을 읽어요.", "한 글자씩 천천히 읽어 봐요."], "example": "🌳 나무 · 🦋 나비 · 🌊 바다 · 🚌 버스 · 🦟 모기 · 🍠 고구마", "figure": "책상 위에 놓인 비누와 작은 장난감 버스"}], "keywords": [{"word": "미음 · 비읍", "meaning": "ㅁ과 ㅂ의 이름이에요. 입술을 붙였다 떼며 내요."}, {"word": "시옷", "meaning": "ㅅ의 이름이에요. 이 사이로 바람이 나와요."}, {"word": "이응", "meaning": "ㅇ의 이름이에요. 글자 맨 앞에서는 소리가 없어요."}], "expressions": [{"en": "미음", "ko": "자음 ㅁ의 이름"}, {"en": "비읍", "ko": "자음 ㅂ의 이름"}, {"en": "시옷", "ko": "자음 ㅅ의 이름", "note": "[시옫]"}, {"en": "이응", "ko": "자음 ㅇ의 이름"}, {"en": "마 바 사 아", "ko": "ㅁ ㅂ ㅅ ㅇ에 ㅏ를 붙인 글자"}, {"en": "나무", "ko": "🌳 땅에 뿌리를 내린 큰 식물"}, {"en": "나비", "ko": "🦋 날개가 예쁜 곤충"}, {"en": "바다", "ko": "🌊 넓고 짠 물"}, {"en": "버스", "ko": "🚌 많은 사람이 타는 차"}, {"en": "모기", "ko": "🦟 피를 빠는 작은 곤충"}, {"en": "고구마", "ko": "🍠 땅속에서 자라는 달콤한 먹을거리"}], "quiz": [{"q": "ㅂ의 이름은?", "choices": ["미음", "비읍", "시옷", "이응"], "answer": 1, "explain": "ㅂ은 '비읍'이라고 불러요."}, {"q": "🦋 그림에 맞는 낱말은?", "choices": ["나비", "나미", "다비", "바비"], "answer": 0, "explain": "날개가 예쁜 곤충은 '나비'예요."}, {"q": "입술을 붙였다 떼며 \"마\" 소리를 내는 자음은?", "choices": ["ㅅ", "ㅇ", "ㅁ", "ㄹ"], "answer": 2, "explain": "ㅁ은 입술을 붙였다 떼며 소리 내요."}, {"q": "🌊 그림에 맞는 낱말은?", "choices": ["마다", "사다", "나다", "바다"], "answer": 3, "explain": "넓고 짠 물은 '바다'예요."}, {"q": "'이응'은 어떤 자음의 이름?", "choices": ["ㅁ", "ㅇ", "ㅂ", "ㅅ"], "answer": 1, "explain": "동그라미 ㅇ의 이름이 '이응'이에요."}], "summary": ["ㅁ 미음, ㅂ 비읍, ㅅ 시옷, ㅇ 이응.", "ㅁ 위로 줄 두 개를 세우면 ㅂ이 돼요.", "글자 맨 앞의 ㅇ은 소리가 없어요."], "parent_tip": "부모님께: 아이가 ㅁ과 ㅂ을 쓸 때 획이 붙지 않거나 ㅂ의 기둥을 빼먹기 쉽습니다. '네모에 귀 두 개'처럼 말로 짚어 주세요. ㅇ이 앞에서 소리가 없다는 것을 \"'아'에서 ㅇ을 빼도 소리가 같지?\" 하고 확인하면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-04_cover.mp3", "s0": "assets/audio/n/k1-04_s0.mp3", "s1": "assets/audio/n/k1-04_s1.mp3", "s2": "assets/audio/n/k1-04_s2.mp3", "s3": "assets/audio/n/k1-04_s3.mp3", "kw": "assets/audio/n/k1-04_kw.mp3", "q0": "assets/audio/n/k1-04_q0.mp3", "q1": "assets/audio/n/k1-04_q1.mp3", "q2": "assets/audio/n/k1-04_q2.mp3", "q3": "assets/audio/n/k1-04_q3.mp3", "q4": "assets/audio/n/k1-04_q4.mp3", "sum": "assets/audio/n/k1-04_sum.mp3"}}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','1단계 · 자음 ㅁ ㅂ ㅅ ㅇ',4,'k1-04' where not exists (select 1 from public.topics where lesson_slug='k1-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-05','1~2','국어','1단계 · 자음 ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ','바람이 세게 나오는 자음은 무엇일까?','assets/img/l_k1-05.jpg',$j${"intro": "✋ 입 앞에 손바닥을 대고 \"가\", \"카\" 해 봐요. \"카\"를 할 때 바람이 더 세게 나오지요? 오늘은 남은 자음 여섯 개를 배워요.", "sections": [{"heading": "ㅈ 지읒, ㅊ 치읓", "paras": ["ㅈ의 이름은 '지읒'이에요.", "ㅈ 위에 꼭지를 하나 얹으면 ㅊ이에요.", "ㅊ의 이름은 '치읓'이에요."], "example": "ㅈ+ㅏ=자 📏 · ㅊ+ㅏ=차 🚗", "figure": "ㅈ 위에 작은 꼭지가 더해져 ㅊ이 되는 그림"}, {"heading": "ㅋ 키읔, ㅌ 티읕", "paras": ["ㄱ에 줄을 하나 더 그으면 ㅋ이에요. 이름은 '키읔'이에요.", "ㄷ에 줄을 하나 더 그으면 ㅌ이에요. 이름은 '티읕'이에요.", "줄이 늘면 바람이 세게 나와요."], "example": "가 → 카 · 다 → 타", "figure": "ㄱ과 ㅋ, ㄷ과 ㅌ을 나란히 놓고 더해진 줄을 색칠한 그림"}, {"heading": "ㅍ 피읖, ㅎ 히읗", "paras": ["ㅍ의 이름은 '피읖'이에요. ㅂ보다 바람이 세요.", "ㅎ의 이름은 '히읗'이에요.", "ㅎ은 입김을 '하~' 내뿜는 소리예요."], "example": "바 → 파 · ㅎ+ㅏ=하", "figure": "아이가 차가운 유리창에 '하~' 입김을 부는 모습"}, {"heading": "낱말을 읽어요", "paras": ["이제 자음 열네 개를 모두 배웠어요.", "새 자음이 들어간 낱말을 읽어 봐요."], "example": "🦁 사자 · 🚂 기차 · 🍕 피자 · 🍅 토마토 · 🍇 포도 · 🦛 하마 · 👃 코", "figure": "책상 위의 포도 한 송이와 토마토"}], "keywords": [{"word": "지읒 · 치읓", "meaning": "ㅈ과 ㅊ의 이름이에요."}, {"word": "키읔 · 티읕 · 피읖", "meaning": "ㅋ ㅌ ㅍ의 이름이에요. 바람이 세게 나와요."}, {"word": "히읗", "meaning": "ㅎ의 이름이에요. 입김 소리예요."}, {"word": "센 소리 짝", "meaning": "ㄱ-ㅋ, ㄷ-ㅌ, ㅂ-ㅍ, ㅈ-ㅊ처럼 바람이 세지는 짝이에요."}], "expressions": [{"en": "지읒", "ko": "자음 ㅈ의 이름", "note": "[지읃]"}, {"en": "치읓", "ko": "자음 ㅊ의 이름", "note": "[치읃]"}, {"en": "키읔", "ko": "자음 ㅋ의 이름", "note": "[키윽]"}, {"en": "티읕", "ko": "자음 ㅌ의 이름", "note": "[티읃]"}, {"en": "피읖", "ko": "자음 ㅍ의 이름", "note": "[피읍]"}, {"en": "히읗", "ko": "자음 ㅎ의 이름", "note": "[히읃]"}, {"en": "자 차 카 타 파 하", "ko": "ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ에 ㅏ를 붙인 글자"}, {"en": "기차", "ko": "🚂 철길을 달리는 탈것"}, {"en": "피자", "ko": "🍕 둥글고 납작한 음식"}, {"en": "토마토", "ko": "🍅 빨간 열매 채소"}, {"en": "포도", "ko": "🍇 알이 송알송알 달린 과일"}], "quiz": [{"q": "ㅊ의 이름은?", "choices": ["지읒", "치읓", "키읔", "히읗"], "answer": 1, "explain": "ㅊ은 '치읓'이라고 불러요."}, {"q": "🍕 그림에 맞는 낱말은?", "choices": ["비자", "피차", "피자", "피타"], "answer": 2, "explain": "둥글고 납작한 음식은 '피자'예요."}, {"q": "ㄱ에 줄을 하나 더 그으면 어떤 자음?", "choices": ["ㅋ", "ㅌ", "ㅊ", "ㅎ"], "answer": 0, "explain": "ㄱ에 줄을 더하면 ㅋ이 돼요."}, {"q": "🍇 그림에 맞는 낱말은?", "choices": ["보도", "포토", "호도", "포도"], "answer": 3, "explain": "알이 송알송알 달린 과일은 '포도'예요."}, {"q": "✋ 손을 입 앞에 대고 말할 때 바람이 더 세게 나오는 것은?", "choices": ["가", "카", "아", "나"], "answer": 1, "explain": "'카'의 ㅋ은 ㄱ보다 바람이 세게 나와요."}], "summary": ["ㅈ 지읒, ㅊ 치읓, ㅋ 키읔, ㅌ 티읕, ㅍ 피읖, ㅎ 히읗.", "ㄱ-ㅋ, ㄷ-ㅌ, ㅂ-ㅍ, ㅈ-ㅊ은 바람이 세지는 짝이에요.", "이제 자음 열네 개를 모두 배웠어요."], "parent_tip": "부모님께: 자음 이름의 받침(읒·읓·읔·읕·읖·읗)은 아이가 쓰기 어려워하므로 지금은 소리 내어 읽는 것만으로 충분합니다. 얇은 휴지를 입 앞에 들고 \"가/카\", \"바/파\"를 말해 보며 휴지가 더 많이 흔들리는 쪽을 찾게 하면 센 소리를 쉽게 느낍니다.", "narr": {"cover": "assets/audio/n/k1-05_cover.mp3", "s0": "assets/audio/n/k1-05_s0.mp3", "s1": "assets/audio/n/k1-05_s1.mp3", "s2": "assets/audio/n/k1-05_s2.mp3", "s3": "assets/audio/n/k1-05_s3.mp3", "kw": "assets/audio/n/k1-05_kw.mp3", "q0": "assets/audio/n/k1-05_q0.mp3", "q1": "assets/audio/n/k1-05_q1.mp3", "q2": "assets/audio/n/k1-05_q2.mp3", "q3": "assets/audio/n/k1-05_q3.mp3", "q4": "assets/audio/n/k1-05_q4.mp3", "sum": "assets/audio/n/k1-05_sum.mp3"}}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
