insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-06','1~2','국어','1단계 · 자음과 모음으로 글자 만들기','자음과 모음은 어디에 붙을까?','assets/img/l_k1-06.jpg',$j${"intro": "🧩 자음 14개, 모음 10개를 모두 배웠어요. 이제 퍼즐처럼 맞춰서 어떤 글자든 만들어 봐요!", "sections": [{"heading": "자음 + 모음 = 글자", "paras": ["글자는 자음과 모음이 만나 생겨요.", "자음은 앞에, 모음은 뒤에 읽어요."], "example": "ㄱ ㄴ ㄷ ㄹ ㅁ ㅂ ㅅ ㅇ ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ + ㅏ ㅑ ㅓ ㅕ ㅗ ㅛ ㅜ ㅠ ㅡ ㅣ", "figure": "자음 카드와 모음 카드를 퍼즐처럼 맞추는 그림"}, {"heading": "서 있는 모음은 오른쪽에", "paras": ["ㅏ ㅑ ㅓ ㅕ ㅣ는 서 있어요.", "그래서 자음의 오른쪽에 써요."], "example": "가 갸 거 겨 기", "figure": "ㄱ 오른쪽에 세로 모음이 붙는 화살표 그림"}, {"heading": "누워 있는 모음은 아래에", "paras": ["ㅗ ㅛ ㅜ ㅠ ㅡ는 누워 있어요.", "그래서 자음의 아래에 써요."], "example": "고 교 구 규 그", "figure": "ㄱ 아래에 가로 모음이 붙는 화살표 그림"}, {"heading": "글자를 모아 낱말", "paras": ["글자를 이어 붙이면 낱말이 돼요.", "가나다라 노래로 글자를 익혀요."], "example": "바+나+나 = 🍌 바나나 · 모+자 = 🧢 모자 · 너+구+리 = 🦝 너구리", "figure": "책상 위의 바나나 한 송이와 모자, 그 옆의 글자 카드"}], "keywords": [{"word": "글자", "meaning": "자음과 모음이 만나 소리 나는 한 덩어리예요."}, {"word": "오른쪽 모음", "meaning": "ㅏ ㅑ ㅓ ㅕ ㅣ. 자음 오른쪽에 써요."}, {"word": "아래쪽 모음", "meaning": "ㅗ ㅛ ㅜ ㅠ ㅡ. 자음 아래에 써요."}, {"word": "낱말", "meaning": "뜻이 있는 말이에요. 글자가 모여 만들어져요."}], "expressions": [{"en": "가 나 다 라 마 바 사 아 자 차 카 타 파 하", "ko": "자음 14개에 ㅏ를 붙인 노래"}, {"en": "가 갸 거 겨 고 교 구 규 그 기", "ko": "ㄱ에 모음 10개를 붙인 글자"}, {"en": "노", "ko": "ㄴ + ㅗ"}, {"en": "수", "ko": "ㅅ + ㅜ"}, {"en": "바나나", "ko": "🍌 길쭉한 노란 과일"}, {"en": "모자", "ko": "🧢 머리에 쓰는 것"}, {"en": "너구리", "ko": "🦝 눈가가 까만 동물"}, {"en": "마이크", "ko": "🎤 노래할 때 쓰는 것"}, {"en": "주스", "ko": "🧃 과일을 짜서 만든 음료"}, {"en": "고구마", "ko": "🍠 땅속에서 자라는 먹을거리"}], "quiz": [{"q": "ㄴ과 ㅗ로 만든 글자는?", "choices": ["노", "나", "누", "너"], "answer": 0, "explain": "ㄴ 아래에 ㅗ를 쓰면 '노'예요."}, {"q": "ㅗ는 자음의 어디에 쓸까요?", "choices": ["오른쪽", "아래", "왼쪽", "위"], "answer": 1, "explain": "누워 있는 모음 ㅗ는 자음 아래에 써요."}, {"q": "🍌 그림에 맞는 낱말은?", "choices": ["바나다", "마나나", "바나나", "파나나"], "answer": 2, "explain": "길쭉한 노란 과일은 '바나나'예요."}, {"q": "'모'를 자음과 모음으로 나누면?", "choices": ["ㅁ + ㅏ", "ㅂ + ㅗ", "ㅁ + ㅜ", "ㅁ + ㅗ"], "answer": 3, "explain": "'모'는 ㅁ과 ㅗ로 되어 있어요."}, {"q": "가 나 다 라 다음에 오는 글자는?", "choices": ["바", "마", "사", "아"], "answer": 1, "explain": "가 나 다 라 마 바 사 순서예요."}], "summary": ["자음과 모음이 만나 글자가 돼요.", "ㅏ ㅑ ㅓ ㅕ ㅣ는 자음 오른쪽, ㅗ ㅛ ㅜ ㅠ ㅡ는 자음 아래에 써요.", "글자를 이어 붙이면 낱말이 돼요."], "parent_tip": "부모님께: 자음 카드와 모음 카드를 따로 만들어 아이가 직접 맞춰 보게 하면 글자 원리를 빨리 익힙니다. 아이가 '고'를 'ㄱㅗ'처럼 옆으로 나란히 쓰면 누운 모음은 아래로 간다는 점을 다시 짚어 주세요. \"우리 가족 이름 첫 글자는 어떻게 만들까?\" 같은 놀이도 좋습니다.", "narr": {"cover": "assets/audio/n/k1-06_cover.mp3", "s0": "assets/audio/n/k1-06_s0.mp3", "s1": "assets/audio/n/k1-06_s1.mp3", "s2": "assets/audio/n/k1-06_s2.mp3", "s3": "assets/audio/n/k1-06_s3.mp3", "kw": "assets/audio/n/k1-06_kw.mp3", "q0": "assets/audio/n/k1-06_q0.mp3", "q1": "assets/audio/n/k1-06_q1.mp3", "q2": "assets/audio/n/k1-06_q2.mp3", "q3": "assets/audio/n/k1-06_q3.mp3", "q4": "assets/audio/n/k1-06_q4.mp3", "sum": "assets/audio/n/k1-06_sum.mp3"}}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','1단계 · 자음과 모음으로 글자 만들기',6,'k1-06' where not exists (select 1 from public.topics where lesson_slug='k1-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-07','1~2','국어','1단계 · 된소리 ㄲ ㄸ ㅃ ㅆ ㅉ','쌍둥이 자음은 어떤 소리가 날까?','assets/img/l_k1-07.jpg',$j${"intro": "🐰 \"토끼\"와 👨 \"아빠\"를 읽어 봐요. '끼'와 '빠'에는 같은 자음이 두 개씩 붙어 있어요. 오늘은 쌍둥이 자음, 된소리를 배워요.", "sections": [{"heading": "쌍둥이 자음", "paras": ["같은 자음 두 개를 나란히 쓰면 쌍둥이 자음이에요.", "이름 앞에 '쌍'을 붙여요."], "example": "ㄱ→ㄲ 쌍기역 · ㄷ→ㄸ 쌍디귿 · ㅂ→ㅃ 쌍비읍 · ㅅ→ㅆ 쌍시옷 · ㅈ→ㅉ 쌍지읒", "figure": "똑같은 자음 카드 두 장이 나란히 붙어 있는 그림"}, {"heading": "힘주어 단단하게", "paras": ["쌍둥이 자음은 목에 힘을 주어 단단하게 소리 내요.", "이런 소리를 된소리라고 해요."], "example": "가 → 까 · 다 → 따 · 바 → 빠 · 사 → 싸 · 자 → 짜", "figure": "아이가 주먹을 꼭 쥐고 힘주어 말하는 모습"}, {"heading": "가, 카, 까 소리 비교", "paras": ["\"가\"는 부드러운 소리예요.", "\"카\"는 바람이 세게 나와요.", "\"까\"는 바람은 적고 단단해요."], "example": "가 · 카 · 까 / 다 · 타 · 따 / 바 · 파 · 빠", "figure": "입 앞에 든 얇은 휴지가 '카'에서 크게 흔들리는 모습"}, {"heading": "낱말을 읽어요", "paras": ["된소리가 들어간 낱말을 읽어 봐요.", "쌍둥이 자음에서 힘을 꼭 줘요."], "example": "🐰 토끼 · 🐘 코끼리 · 🐦 까치 · 👨 아빠 · 😘 뽀뽀 · 🌱 씨 · 🧂 짜다", "figure": "책상 위의 토끼 인형과 작은 코끼리 인형"}], "keywords": [{"word": "된소리", "meaning": "힘을 주어 단단하게 내는 소리예요. ㄲ ㄸ ㅃ ㅆ ㅉ."}, {"word": "쌍", "meaning": "같은 것 두 개라는 뜻이에요. 쌍기역은 기역이 두 개예요."}, {"word": "소리 비교", "meaning": "가(부드럽게)·카(바람 세게)·까(단단하게)."}], "expressions": [{"en": "쌍기역", "ko": "자음 ㄲ의 이름"}, {"en": "쌍디귿", "ko": "자음 ㄸ의 이름"}, {"en": "쌍비읍", "ko": "자음 ㅃ의 이름"}, {"en": "쌍시옷", "ko": "자음 ㅆ의 이름", "note": "[쌍시옫]"}, {"en": "쌍지읒", "ko": "자음 ㅉ의 이름", "note": "[쌍지읃]"}, {"en": "가 카 까", "ko": "부드러운 소리, 바람 센 소리, 단단한 소리"}, {"en": "토끼", "ko": "🐰 귀가 긴 동물"}, {"en": "코끼리", "ko": "🐘 코가 긴 동물"}, {"en": "아빠", "ko": "👨 아버지를 다정하게 부르는 말"}, {"en": "뽀뽀", "ko": "😘 입을 맞추는 것"}, {"en": "아저씨", "ko": "🧑 어른 남자를 부르는 말"}, {"en": "짜다", "ko": "🧂 소금 맛이 나다"}], "quiz": [{"q": "ㄲ의 이름은?", "choices": ["쌍기역", "기역", "쌍디귿", "키읔"], "answer": 0, "explain": "ㄱ이 두 개라서 '쌍기역'이에요."}, {"q": "🐰 그림에 맞는 낱말은?", "choices": ["토기", "토키", "토끼", "도끼"], "answer": 2, "explain": "귀가 긴 동물은 '토끼'예요."}, {"q": "ㅂ을 두 개 나란히 쓰면?", "choices": ["ㅍ", "ㅃ", "ㅁ", "ㅉ"], "answer": 1, "explain": "ㅂ 두 개를 나란히 쓰면 ㅃ(쌍비읍)이에요."}, {"q": "힘을 주어 단단하게 내는 소리는?", "choices": ["다", "타", "아", "따"], "answer": 3, "explain": "'따'의 ㄸ은 된소리예요."}, {"q": "👨 그림에 맞는 낱말은?", "choices": ["아빠", "아바", "아파", "아마"], "answer": 0, "explain": "아버지를 다정하게 부르는 말은 '아빠'예요."}], "summary": ["같은 자음 두 개를 나란히 쓰면 된소리 자음이에요.", "ㄲ 쌍기역, ㄸ 쌍디귿, ㅃ 쌍비읍, ㅆ 쌍시옷, ㅉ 쌍지읒.", "가·카·까처럼 소리가 모두 달라요."], "parent_tip": "부모님께: 아이가 '아빠'를 '아바'로, '토끼'를 '토키'로 쓰는 일이 많습니다. 소리를 과장해서 들려주며 \"힘이 들어갔어, 바람이 나왔어?\" 하고 물어 구별하게 해 주세요. 가·카·까, 바·파·빠를 묶어 읽는 놀이가 효과적입니다.", "narr": {"cover": "assets/audio/n/k1-07_cover.mp3", "s0": "assets/audio/n/k1-07_s0.mp3", "s1": "assets/audio/n/k1-07_s1.mp3", "s2": "assets/audio/n/k1-07_s2.mp3", "s3": "assets/audio/n/k1-07_s3.mp3", "kw": "assets/audio/n/k1-07_kw.mp3", "q0": "assets/audio/n/k1-07_q0.mp3", "q1": "assets/audio/n/k1-07_q1.mp3", "q2": "assets/audio/n/k1-07_q2.mp3", "q3": "assets/audio/n/k1-07_q3.mp3", "q4": "assets/audio/n/k1-07_q4.mp3", "sum": "assets/audio/n/k1-07_sum.mp3"}}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','1단계 · 된소리 ㄲ ㄸ ㅃ ㅆ ㅉ',7,'k1-07' where not exists (select 1 from public.topics where lesson_slug='k1-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-08','1~2','국어','2단계 · 받침 ㄱ ㄴ ㅁ','글자 아래에 자음이 붙으면 어떻게 읽을까?','assets/img/l_k1-08.jpg',$j${"intro": "🐻 \"곰\"을 읽어 봐요. '고' 아래에 ㅁ이 하나 더 붙어 있지요? 글자 아래를 받치는 자음, 받침을 만나요.", "sections": [{"heading": "받침이 뭐예요?", "paras": ["글자 맨 아래에 붙는 자음을 받침이라고 해요.", "받침이 붙으면 소리가 끝에서 닫혀요."], "example": "가 → 각 · 가 → 간 · 가 → 감", "figure": "'가' 블록 아래에 자음 블록을 받쳐 끼우는 그림"}, {"heading": "받침 ㄱ [윽]", "paras": ["혀 뒤쪽을 올려 소리를 막아요.", "\"윽\" 하고 끝나는 느낌이에요."], "example": "🍲 국 · 💊 약 · 🍉 수박 · 🥁 북", "figure": "아이가 국그릇 앞에서 숟가락을 든 모습"}, {"heading": "받침 ㄴ [은]", "paras": ["혀끝을 윗잇몸에 대고 끝내요.", "콧소리가 \"은~\" 하고 나요."], "example": "👀 눈 · ⛰️ 산 · ✋ 손 · 🚪 문", "figure": "아이가 손바닥을 활짝 펴 보이는 모습"}, {"heading": "받침 ㅁ [음]", "paras": ["입술을 꼭 닫고 끝내요.", "\"음~\" 하고 입이 다물어져요."], "example": "🐻 곰 · 🌸 봄 · 🌰 밤 · 👩 엄마 · 🥔 감자", "figure": "책상 위의 곰 인형과 감자, 밤"}], "keywords": [{"word": "받침", "meaning": "글자 맨 아래에 붙는 자음이에요."}, {"word": "받침 ㄱ", "meaning": "혀 뒤로 소리를 막아요. 국, 약."}, {"word": "받침 ㄴ", "meaning": "혀끝을 윗잇몸에 대요. 눈, 산."}, {"word": "받침 ㅁ", "meaning": "입술을 꼭 닫아요. 곰, 봄."}], "expressions": [{"en": "각", "ko": "가 + 받침 ㄱ"}, {"en": "간", "ko": "가 + 받침 ㄴ"}, {"en": "감", "ko": "가 + 받침 ㅁ"}, {"en": "국", "ko": "🍲 그릇에 담아 먹는 국물 음식"}, {"en": "약", "ko": "💊 아플 때 먹는 것"}, {"en": "수박", "ko": "🍉 여름 과일"}, {"en": "눈", "ko": "👀 보는 곳, ⛄ 겨울에 내리는 눈"}, {"en": "산", "ko": "⛰️ 높이 솟은 땅"}, {"en": "손", "ko": "✋ 팔 끝의 손"}, {"en": "곰", "ko": "🐻 몸집이 큰 동물"}, {"en": "엄마", "ko": "👩 어머니를 다정하게 부르는 말"}, {"en": "감자", "ko": "🥔 땅속에서 자라는 채소"}], "quiz": [{"q": "글자 맨 아래에 붙는 자음을 무엇이라고 할까요?", "choices": ["모음", "받침", "낱말", "문장"], "answer": 1, "explain": "글자 아래를 받치는 자음을 '받침'이라고 해요."}, {"q": "🐻 그림에 맞는 낱말은?", "choices": ["고", "곡", "곤", "곰"], "answer": 3, "explain": "몸집이 큰 동물은 '곰'이에요. 받침 ㅁ이 있어요."}, {"q": "🍉 그림에 맞는 낱말은?", "choices": ["수박", "수바", "수반", "수밤"], "answer": 0, "explain": "여름 과일은 '수박'이에요. '박'에 받침 ㄱ이 있어요."}, {"q": "입술을 꼭 닫으며 끝나는 받침은?", "choices": ["ㄱ", "ㄴ", "ㅁ", "ㄹ"], "answer": 2, "explain": "받침 ㅁ은 입술을 닫으며 끝나요."}, {"q": "'손'에 들어 있는 받침은?", "choices": ["ㅅ", "ㄴ", "ㅗ", "ㅁ"], "answer": 1, "explain": "'손'은 ㅅ+ㅗ+받침 ㄴ이에요."}], "summary": ["받침은 글자 맨 아래에 붙는 자음이에요.", "받침 ㄱ은 혀 뒤, ㄴ은 혀끝, ㅁ은 입술을 닫으며 끝나요.", "가 → 각, 간, 감처럼 받침에 따라 소리와 뜻이 달라져요."], "parent_tip": "부모님께: 받침 낱말을 읽을 때 아이가 받침을 빼고 '고'처럼 읽거나 '고므'처럼 따로 떼어 읽기도 합니다. 받침 없는 글자(고)를 먼저 읽고 입을 닫으며 '곰'으로 이어 보게 해 주세요. '악어[아거]'처럼 받침이 뒤로 넘어가는 낱말은 다음 단계에서 다루므로 지금은 한 글자 낱말 위주로 연습하면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-08_cover.mp3", "s0": "assets/audio/n/k1-08_s0.mp3", "s1": "assets/audio/n/k1-08_s1.mp3", "s2": "assets/audio/n/k1-08_s2.mp3", "s3": "assets/audio/n/k1-08_s3.mp3", "kw": "assets/audio/n/k1-08_kw.mp3", "q0": "assets/audio/n/k1-08_q0.mp3", "q1": "assets/audio/n/k1-08_q1.mp3", "q2": "assets/audio/n/k1-08_q2.mp3", "q3": "assets/audio/n/k1-08_q3.mp3", "q4": "assets/audio/n/k1-08_q4.mp3", "sum": "assets/audio/n/k1-08_sum.mp3"}}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','2단계 · 받침 ㄱ ㄴ ㅁ',8,'k1-08' where not exists (select 1 from public.topics where lesson_slug='k1-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-09','1~2','국어','2단계 · 받침 ㄹ ㅂ ㅅ ㅇ','옷은 왜 [옫]으로 소리 날까?','assets/img/l_k1-09.jpg',$j${"intro": "🌙 \"달\", 🍚 \"밥\", 👕 \"옷\", ⚽ \"공\"을 읽어 봐요. 지난번 ㄱ ㄴ ㅁ에 이어, 오늘은 받침 네 개를 더 배워요.", "sections": [{"heading": "받침 ㄹ [을]", "paras": ["혀끝을 윗잇몸에 살짝 대고 끝내요.", "\"을~\" 하고 소리가 이어져요."], "example": "🌙 달 · 💧 물 · ⭐ 별 · 🦶 발 · 🍊 귤", "figure": "밤하늘에 뜬 둥근 달과 별"}, {"heading": "받침 ㅂ [읍]", "paras": ["입술을 꼭 닫고 짧게 끊어요.", "ㅁ 받침보다 짧고 단단해요."], "example": "🍚 밥 · 🏠 집 · 👄 입 · 🥤 컵", "figure": "책상 위에 놓인 밥그릇과 컵"}, {"heading": "받침 ㅅ은 [ㄷ] 소리", "paras": ["ㅅ이 받침이면 [ㄷ]처럼 소리 나요.", "글자는 ㅅ으로 쓰고, 소리는 [ㄷ]이에요."], "example": "👕 옷 [옫] · 🖌️ 붓 [붇] · 😋 맛 [맏]", "figure": "옷걸이에 걸린 작은 티셔츠와 붓"}, {"heading": "받침 ㅇ [응]", "paras": ["맨 앞의 ㅇ은 소리가 없었지요?", "받침 ㅇ은 \"응~\" 하고 콧소리가 나요."], "example": "⚽ 공 · 🍞 빵 · 🎒 가방 · 🏞️ 강", "figure": "책상 위의 작은 공과 빵, 가방"}], "keywords": [{"word": "받침 ㄹ", "meaning": "혀끝을 윗잇몸에 대고 '을' 하고 끝나요. 달, 물."}, {"word": "받침 ㅂ", "meaning": "입술을 닫고 짧게 끊어요. 밥, 집."}, {"word": "받침 ㅅ", "meaning": "쓸 때는 ㅅ, 소리는 [ㄷ]이에요. 옷[옫]."}, {"word": "받침 ㅇ", "meaning": "'응' 하는 콧소리예요. 공, 빵."}], "expressions": [{"en": "달", "ko": "🌙 밤하늘의 달"}, {"en": "물", "ko": "💧 마시는 물"}, {"en": "별", "ko": "⭐ 밤하늘에 반짝이는 별"}, {"en": "밥", "ko": "🍚 쌀로 지은 밥"}, {"en": "집", "ko": "🏠 사는 곳"}, {"en": "컵", "ko": "🥤 물을 담아 마시는 그릇"}, {"en": "옷", "ko": "👕 몸에 입는 것", "note": "[옫]"}, {"en": "맛", "ko": "😋 혀로 느끼는 맛", "note": "[맏]"}, {"en": "공", "ko": "⚽ 차고 던지는 공"}, {"en": "빵", "ko": "🍞 밀가루로 구운 음식"}, {"en": "가방", "ko": "🎒 물건을 넣어 메는 것"}, {"en": "갈 갑 갓 강", "ko": "'가'에 받침 ㄹ ㅂ ㅅ ㅇ을 붙인 글자", "note": "[갈 갑 갇 강]"}], "quiz": [{"q": "🌙 그림에 맞는 낱말은?", "choices": ["달", "다", "담", "단"], "answer": 0, "explain": "밤하늘의 달은 '달'이에요. 받침 ㄹ이 있어요."}, {"q": "👕 '옷'은 어떻게 소리 날까요?", "choices": ["[오]", "[옫]", "[온]", "[옥]"], "answer": 1, "explain": "받침 ㅅ은 [ㄷ]처럼 소리 나서 [옫]이에요."}, {"q": "받침 ㅇ은 어떤 소리가 날까요?", "choices": ["소리가 없어요", "[ㄷ] 소리", "'응' 하는 콧소리", "[ㄹ] 소리"], "answer": 2, "explain": "받침 ㅇ은 '응' 하는 콧소리가 나요."}, {"q": "🍚 그림에 맞는 낱말은?", "choices": ["바", "반", "발", "밥"], "answer": 3, "explain": "쌀로 지은 밥은 '밥'이에요. 받침 ㅂ이 있어요."}, {"q": "⚽ 그림에 맞는 낱말은?", "choices": ["곤", "공", "곱", "골"], "answer": 1, "explain": "차고 던지는 것은 '공'이에요."}], "summary": ["받침 ㄹ은 '을', ㅂ은 '읍', ㅇ은 '응' 소리로 끝나요.", "받침 ㅅ은 [ㄷ]처럼 소리 나요. 옷 → [옫].", "맨 앞의 ㅇ은 소리가 없고, 받침 ㅇ은 소리가 나요."], "parent_tip": "부모님께: 아이가 '옷'을 소리 나는 대로 '옫'이라고 쓰는 실수가 많습니다. \"소리는 [옫], 쓸 때는 ㅅ\"을 함께 말해 주세요. 또 ㅁ 받침(감)과 ㅂ 받침(갑)을 헷갈리면 ㅁ은 '음~' 길게, ㅂ은 '읍!' 짧게 끊는 차이를 들려주면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-09_cover.mp3", "s0": "assets/audio/n/k1-09_s0.mp3", "s1": "assets/audio/n/k1-09_s1.mp3", "s2": "assets/audio/n/k1-09_s2.mp3", "s3": "assets/audio/n/k1-09_s3.mp3", "kw": "assets/audio/n/k1-09_kw.mp3", "q0": "assets/audio/n/k1-09_q0.mp3", "q1": "assets/audio/n/k1-09_q1.mp3", "q2": "assets/audio/n/k1-09_q2.mp3", "q3": "assets/audio/n/k1-09_q3.mp3", "q4": "assets/audio/n/k1-09_q4.mp3", "sum": "assets/audio/n/k1-09_sum.mp3"}}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','2단계 · 받침 ㄹ ㅂ ㅅ ㅇ',9,'k1-09' where not exists (select 1 from public.topics where lesson_slug='k1-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-10','1~2','국어','2단계 · 복잡한 모음 ㅐ ㅔ ㅚ ㅟ ㅘ ㅝ ㅢ','모음 두 개가 만나면 어떤 소리가 날까?','assets/img/l_k1-10.jpg',$j${"intro": "모음 두 개가 만나면 새 모음이 돼요. 🦀 게, 🍎 사과 속에 숨어 있어요!", "sections": [{"heading": "ㅐ와 ㅔ는 쌍둥이 소리", "paras": ["ㅏ에 ㅣ를 붙이면 ㅐ예요.", "ㅓ에 ㅣ를 붙이면 ㅔ예요.", "둘은 소리가 거의 같아요. 낱말로 기억해요."], "example": "🐶 개 / 🦀 게", "figure": "개 인형과 게 장난감을 책상 위에 나란히 놓은 모습"}, {"heading": "ㅗ, ㅜ와 만나는 모음", "paras": ["ㅗ와 ㅏ가 만나면 ㅘ [와]예요.", "ㅜ와 ㅓ가 만나면 ㅝ [워]예요.", "ㅗ+ㅣ는 ㅚ, ㅜ+ㅣ는 ㅟ예요."], "example": "🍎 사과, 🐒 원숭이, 🍈 참외, 🐭 쥐", "figure": "사과와 참외가 담긴 바구니"}, {"heading": "ㅡ와 ㅣ가 만나면 ㅢ", "paras": ["ㅡ와 ㅣ를 붙이면 ㅢ예요.", "입을 옆으로 벌리고 [의] 해요."], "example": "🪑 의자, 👩‍⚕️ 의사", "figure": "작은 나무 의자 하나"}, {"heading": "빠르게 이어 읽어요", "paras": ["두 소리를 빠르게 이어 읽어요.", "오+아를 빨리 하면 [와]가 돼요."], "example": "오+아 → 와, 우+어 → 워, 우+이 → 위", "figure": "아이가 모음 카드 두 장을 겹쳐 드는 손"}], "keywords": [{"word": "모음", "meaning": "ㅏ, ㅓ, ㅗ처럼 소리를 내는 글자"}, {"word": "복잡한 모음", "meaning": "모음 두 개가 합쳐져 만든 모음(ㅐ, ㅘ, ㅢ 등)"}, {"word": "이어 읽기", "meaning": "두 소리를 끊지 않고 빠르게 붙여 읽는 것"}], "expressions": [{"en": "애", "ko": "ㅇ + ㅐ (ㅏ와 ㅣ가 만났어요)", "note": "[애]"}, {"en": "에", "ko": "ㅇ + ㅔ (ㅓ와 ㅣ가 만났어요)", "note": "[에] ㅐ와 소리가 거의 같아요"}, {"en": "와", "ko": "ㅇ + ㅘ (ㅗ와 ㅏ가 만났어요)", "note": "[와]"}, {"en": "워", "ko": "ㅇ + ㅝ (ㅜ와 ㅓ가 만났어요)", "note": "[워]"}, {"en": "외", "ko": "ㅇ + ㅚ (ㅗ와 ㅣ가 만났어요)", "note": "[외] 또는 [웨]"}, {"en": "위", "ko": "ㅇ + ㅟ (ㅜ와 ㅣ가 만났어요)", "note": "[위]"}, {"en": "의", "ko": "ㅇ + ㅢ (ㅡ와 ㅣ가 만났어요)", "note": "[의]"}, {"en": "개", "ko": "🐶 멍멍 짖는 동물", "note": "[개]"}, {"en": "게", "ko": "🦀 옆으로 걷는 바다 동물", "note": "[게]"}, {"en": "사과", "ko": "🍎 빨간 과일 (과 = ㄱ + ㅘ)", "note": "[사과]"}, {"en": "쥐", "ko": "🐭 찍찍 우는 작은 동물 (쥐 = ㅈ + ㅟ)", "note": "[쥐]"}, {"en": "의자", "ko": "🪑 앉는 물건", "note": "[의자]"}], "quiz": [{"q": "🦀 그림에 맞는 글자는?", "choices": ["개", "게", "계", "귀"], "answer": 1, "explain": "옆으로 걷는 🦀는 '게'예요. ㅔ를 써요."}, {"q": "ㅗ와 ㅏ가 만나면 어떤 모음이 될까요?", "choices": ["ㅝ", "ㅚ", "ㅘ", "ㅟ"], "answer": 2, "explain": "ㅗ와 ㅏ를 붙이면 ㅘ [와]가 돼요."}, {"q": "🪑 '의자'의 '의'에 들어 있는 모음은?", "choices": ["ㅢ", "ㅟ", "ㅚ", "ㅐ"], "answer": 0, "explain": "'의'는 ㅡ와 ㅣ가 만난 ㅢ를 써요."}, {"q": "🐭 그림에 맞는 낱말은?", "choices": ["줘", "재", "제", "쥐"], "answer": 3, "explain": "찍찍 우는 🐭는 '쥐'예요. ㅜ와 ㅣ가 만난 ㅟ를 써요."}, {"q": "🍎 '사과'의 '과'에 들어 있는 모음은?", "choices": ["ㅝ", "ㅘ", "ㅚ", "ㅐ"], "answer": 1, "explain": "'과'는 ㄱ과 ㅘ가 만나 만든 글자예요."}], "summary": ["모음 두 개가 만나 새 모음이 돼요.", "ㅐ와 ㅔ는 소리가 비슷해서 낱말로 기억해요.", "ㅘ, ㅝ, ㅚ, ㅟ, ㅢ는 두 소리를 빠르게 이어 읽어요."], "parent_tip": "부모님께: 요즘 말소리에서 ㅐ와 ㅔ는 거의 구별되지 않아 아이가 '개/게'를 헷갈리는 것이 자연스럽습니다. 소리보다 '🐶 개, 🦀 게'처럼 낱말 그림과 함께 기억하게 해 주세요. '오+아를 빨리 말하면?' 같은 놀이로 ㅘ, ㅝ를 익히면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-10_cover.mp3", "s0": "assets/audio/n/k1-10_s0.mp3", "s1": "assets/audio/n/k1-10_s1.mp3", "s2": "assets/audio/n/k1-10_s2.mp3", "s3": "assets/audio/n/k1-10_s3.mp3", "kw": "assets/audio/n/k1-10_kw.mp3", "q0": "assets/audio/n/k1-10_q0.mp3", "q1": "assets/audio/n/k1-10_q1.mp3", "q2": "assets/audio/n/k1-10_q2.mp3", "q3": "assets/audio/n/k1-10_q3.mp3", "q4": "assets/audio/n/k1-10_q4.mp3", "sum": "assets/audio/n/k1-10_sum.mp3"}}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','2단계 · 복잡한 모음 ㅐ ㅔ ㅚ ㅟ ㅘ ㅝ ㅢ',10,'k1-10' where not exists (select 1 from public.topics where lesson_slug='k1-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-11','1~2','국어','2단계 · 낱말 읽기(동물·과일·탈것)','동물, 과일, 탈것 이름을 읽어 볼까?','assets/img/l_k1-11.jpg',$j${"intro": "우리 주변의 모든 것에는 이름이 있어요. 그림을 보고 낱말을 소리 내어 읽어요.", "sections": [{"heading": "동물 이름을 읽어요", "paras": ["🐶 강아지, 🐱 고양이를 읽어요.", "한 글자씩 천천히 읽어요.", "그다음 이어서 한 번 더 읽어요."], "example": "강-아-지 → 강아지", "figure": "강아지, 고양이, 토끼 인형이 나란히 앉아 있는 모습"}, {"heading": "과일 이름을 읽어요", "paras": ["🍓 딸기, 🍉 수박에는 받침이 있어요.", "받침 소리를 또박또박 내요."], "example": "🍌 바나나, 🍇 포도, 🍓 딸기, 🍉 수박", "figure": "접시에 담긴 딸기, 바나나, 포도"}, {"heading": "탈것 이름을 읽어요", "paras": ["🚌 버스와 🚂 기차는 사람을 태워요.", "✈️ 비행기는 하늘을 날아요."], "example": "🚗 자동차, 🚲 자전거, ✈️ 비행기", "figure": "장난감 자동차와 기차가 놓인 책상"}, {"heading": "같은 무리끼리 모아요", "paras": ["동물, 과일, 탈것으로 나눠요.", "무리 지으면 더 잘 기억해요."], "example": "동물: 곰, 사자 / 과일: 사과, 포도 / 탈것: 버스, 기차", "figure": "세 개의 바구니에 동물·과일·탈것 장난감을 나눠 담는 아이 손"}], "keywords": [{"word": "낱말", "meaning": "뜻이 있는 말 한 덩어리"}, {"word": "동물", "meaning": "움직이며 사는 생물(강아지, 사자 등)"}, {"word": "과일", "meaning": "나무나 풀에 열리는 먹는 열매"}, {"word": "탈것", "meaning": "사람이나 짐을 태우고 움직이는 것"}], "expressions": [{"en": "강아지", "ko": "🐶 멍멍 짖는 어린 개"}, {"en": "고양이", "ko": "🐱 야옹 우는 동물"}, {"en": "토끼", "ko": "🐰 귀가 긴 동물"}, {"en": "사자", "ko": "🦁 어흥 하는 동물"}, {"en": "사과", "ko": "🍎 빨간 과일"}, {"en": "바나나", "ko": "🍌 노랗고 긴 과일"}, {"en": "딸기", "ko": "🍓 빨갛고 작은 과일"}, {"en": "수박", "ko": "🍉 크고 둥근 여름 과일"}, {"en": "자동차", "ko": "🚗 길을 달리는 탈것"}, {"en": "버스", "ko": "🚌 많은 사람이 타는 탈것"}, {"en": "자전거", "ko": "🚲 발로 굴려 타는 탈것"}, {"en": "비행기", "ko": "✈️ 하늘을 나는 탈것"}], "quiz": [{"q": "🐰 그림에 맞는 낱말은?", "choices": ["토끼", "고양이", "사자", "곰"], "answer": 0, "explain": "귀가 긴 🐰는 '토끼'예요."}, {"q": "🍓 그림에 맞는 낱말은?", "choices": ["수박", "포도", "딸기", "사과"], "answer": 2, "explain": "빨갛고 작은 🍓는 '딸기'예요."}, {"q": "탈것이 아닌 것은?", "choices": ["버스", "기차", "자전거", "포도"], "answer": 3, "explain": "포도는 먹는 과일이에요. 나머지는 타는 것이에요."}, {"q": "✈️ '비행기'는 어디로 다닐까요?", "choices": ["바다", "하늘", "땅속", "나무 위"], "answer": 1, "explain": "비행기는 하늘을 날아요."}, {"q": "동물끼리 모은 것은?", "choices": ["곰, 사자", "사과, 곰", "버스, 토끼", "포도, 수박"], "answer": 0, "explain": "곰과 사자는 둘 다 동물이에요."}], "summary": ["낱말은 한 글자씩 읽고, 다시 이어서 읽어요.", "받침이 있는 글자는 받침 소리를 또박또박 내요.", "동물, 과일, 탈것처럼 무리 지어 기억해요."], "parent_tip": "부모님께: 아이가 그림만 보고 낱말을 '짐작'해서 말하는지, 글자를 보고 읽는지 확인해 주세요. 이모지를 손으로 가리고 글자만 읽게 해 보면 좋습니다. 마트나 길에서 '저건 과일일까, 탈것일까?' 하고 무리 짓기 놀이를 해 보세요.", "narr": {"cover": "assets/audio/n/k1-11_cover.mp3", "s0": "assets/audio/n/k1-11_s0.mp3", "s1": "assets/audio/n/k1-11_s1.mp3", "s2": "assets/audio/n/k1-11_s2.mp3", "s3": "assets/audio/n/k1-11_s3.mp3", "kw": "assets/audio/n/k1-11_kw.mp3", "q0": "assets/audio/n/k1-11_q0.mp3", "q1": "assets/audio/n/k1-11_q1.mp3", "q2": "assets/audio/n/k1-11_q2.mp3", "q3": "assets/audio/n/k1-11_q3.mp3", "q4": "assets/audio/n/k1-11_q4.mp3", "sum": "assets/audio/n/k1-11_sum.mp3"}}$j$::jsonb,11) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','2단계 · 낱말 읽기(동물·과일·탈것)',11,'k1-11' where not exists (select 1 from public.topics where lesson_slug='k1-11');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-12','1~2','국어','2단계 · 소리와 글자가 다른 낱말','''음악''은 왜 [으막]이라고 읽을까?','assets/img/l_k1-12.jpg',$j${"intro": "글자와 다르게 소리 나는 낱말이 있어요. 왜 그런지 함께 알아봐요.", "sections": [{"heading": "받침이 뒤로 넘어가요", "paras": ["받침 뒤에 ㅇ이 오면 받침이 넘어가요.", "그래서 '음악'은 [으막]으로 읽어요."], "example": "🎵 음악 → [으막], 🎈 놀이 → [노리], 📕 책이 → [채기]", "figure": "글자 카드 '음'의 받침 카드를 옆 칸으로 옮기는 아이 손"}, {"heading": "소리가 세게 나요", "paras": ["어떤 낱말은 뒷소리가 세져요.", "'학교'는 [학꾜]로 소리 나요."], "example": "🏫 학교 → [학꾜], 🍜 국수 → [국쑤]", "figure": "책가방을 멘 아이가 학교 앞에 선 모습"}, {"heading": "ㅎ 소리가 숨어요", "paras": ["받침 ㅎ 뒤에 ㅇ이 오면 ㅎ 소리가 안 나요.", "'좋아요'는 [조아요]로 읽어요."], "example": "👍 좋아요 → [조아요], 많이 → [마니]", "figure": "엄지를 든 아이 손"}, {"heading": "쓸 때는 원래대로 써요", "paras": ["읽을 때는 소리 나는 대로 읽어요.", "쓸 때는 원래 글자로 써요."], "example": "✏️ [으막]이라고 들어도 '음악'이라고 써요.", "figure": "공책에 연필로 낱말을 쓰는 아이 손"}], "keywords": [{"word": "받침", "meaning": "글자 아래에 붙는 자음"}, {"word": "발음", "meaning": "말소리를 내는 것. [ ] 안에 써서 보여 줘요"}, {"word": "넘어가기", "meaning": "받침이 뒤 글자의 ㅇ 자리로 옮겨 가 소리 나는 것"}], "expressions": [{"en": "음악", "ko": "🎵 노래나 연주", "note": "[으막]"}, {"en": "놀이", "ko": "🎈 즐겁게 노는 일", "note": "[노리]"}, {"en": "국어", "ko": "📖 우리말을 배우는 과목", "note": "[구거]"}, {"en": "웃음", "ko": "😄 웃는 일", "note": "[우슴]"}, {"en": "목요일", "ko": "수요일 다음 날", "note": "[모교일]"}, {"en": "꽃이", "ko": "🌸 꽃 + 이", "note": "[꼬치]"}, {"en": "책이", "ko": "📕 책 + 이", "note": "[채기]"}, {"en": "학교", "ko": "🏫 공부하는 곳", "note": "[학꾜]"}, {"en": "국수", "ko": "🍜 길고 가는 면 음식", "note": "[국쑤]"}, {"en": "좋아요", "ko": "👍 마음에 들어요", "note": "[조아요]"}, {"en": "많이", "ko": "가득, 여러 개", "note": "[마니]"}], "quiz": [{"q": "🎵 '음악'은 어떻게 읽을까요?", "choices": ["[음악]", "[으막]", "[으낙]", "[음막]"], "answer": 1, "explain": "받침 ㅁ이 뒤로 넘어가 [으막]으로 읽어요."}, {"q": "🏫 '학교'는 어떻게 소리 날까요?", "choices": ["[학교]", "[하교]", "[학꾜]", "[항교]"], "answer": 2, "explain": "'교'가 세게 소리 나서 [학꾜]가 돼요."}, {"q": "[조아요]라고 들은 말을 바르게 쓴 것은?", "choices": ["조아요", "조와요", "좃아요", "좋아요"], "answer": 3, "explain": "소리는 [조아요]지만 쓸 때는 '좋아요'라고 써요."}, {"q": "받침이 뒤로 넘어가 소리 나는 낱말은?", "choices": ["놀이", "나무", "바다", "오이"], "answer": 0, "explain": "'놀이'는 받침 ㄹ이 넘어가 [노리]로 읽어요."}, {"q": "낱말을 쓸 때는 어떻게 써야 할까요?", "choices": ["소리 나는 대로", "원래 글자대로", "받침을 빼고", "마음대로"], "answer": 1, "explain": "읽을 때는 소리대로, 쓸 때는 원래 글자대로 써요."}], "summary": ["받침 뒤에 ㅇ이 오면 받침이 넘어가 소리 나요.", "'학교[학꾜]'처럼 소리가 세지는 낱말도 있어요.", "쓸 때는 소리가 아니라 원래 글자대로 써요."], "parent_tip": "부모님께: 이 시기 아이들은 '으막', '노리터'처럼 소리 나는 대로 쓰는 실수를 많이 합니다. 틀린 글자를 지적하기보다 '읽을 때는 [노리], 쓸 때는 놀이'처럼 두 가지를 나란히 보여 주세요. 받아쓰기 전에 낱말을 또박또박 끊어 읽어 주면 도움이 됩니다.", "narr": {"cover": "assets/audio/n/k1-12_cover.mp3", "s0": "assets/audio/n/k1-12_s0.mp3", "s1": "assets/audio/n/k1-12_s1.mp3", "s2": "assets/audio/n/k1-12_s2.mp3", "s3": "assets/audio/n/k1-12_s3.mp3", "kw": "assets/audio/n/k1-12_kw.mp3", "q0": "assets/audio/n/k1-12_q0.mp3", "q1": "assets/audio/n/k1-12_q1.mp3", "q2": "assets/audio/n/k1-12_q2.mp3", "q3": "assets/audio/n/k1-12_q3.mp3", "q4": "assets/audio/n/k1-12_q4.mp3", "sum": "assets/audio/n/k1-12_sum.mp3"}}$j$::jsonb,12) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','2단계 · 소리와 글자가 다른 낱말',12,'k1-12' where not exists (select 1 from public.topics where lesson_slug='k1-12');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-13','1~2','국어','3단계 · 띄어 읽고 띄어 쓰기','어디에서 띄어 쓰고, 어디에서 쉬어 읽을까?','assets/img/l_k1-13.jpg',$j${"intro": "'아버지가방에들어가신다'를 읽어 볼까요? 띄어 쓰지 않으면 뜻이 헷갈려요.", "sections": [{"heading": "낱말 사이를 띄어 써요", "paras": ["낱말과 낱말 사이는 한 칸 띄어 써요.", "띄어 쓰면 읽기가 쉬워요."], "example": "나는학교에가요. → 나는 학교에 가요.", "figure": "칸 공책에 한 칸씩 비워 가며 글씨를 쓰는 아이 손"}, {"heading": "작은 말은 붙여 써요", "paras": ["'가', '를', '는', '에' 같은 말은 붙여 써요.", "앞 낱말에 꼭 붙어 다녀요."], "example": "🐶 강아지가 / 🍎 사과를 / 🏫 학교에", "figure": ""}, {"heading": "띄어 쓰면 뜻이 바뀌어요", "paras": ["띄는 곳이 다르면 뜻도 달라요.", "그래서 띄어쓰기가 중요해요."], "example": "👨 아버지가 방에 들어가신다. / 👜 아버지 가방에 들어가신다.", "figure": "방문 앞에 선 아빠와 커다란 가방 그림"}, {"heading": "쉬어 읽어요", "paras": ["쉼표(,) 뒤에서는 조금 쉬어요. ∨로 표시해요.", "마침표(.) 뒤에서는 조금 더 쉬어요. ≫로 표시해요."], "example": "토끼야,∨같이 놀자.≫ 응,∨좋아.≫", "figure": "그림책을 소리 내어 읽는 아이"}], "keywords": [{"word": "띄어쓰기", "meaning": "낱말과 낱말 사이를 한 칸 비우고 쓰는 것"}, {"word": "띄어 읽기", "meaning": "알맞은 곳에서 쉬며 읽는 것"}, {"word": "쉼표", "meaning": "문장 중간에 쓰는 , 표시. 조금 쉬어 읽어요"}, {"word": "마침표", "meaning": "문장 끝에 쓰는 . 표시"}], "expressions": [{"en": "나는 학교에 가요.", "ko": "'나는', '학교에', '가요' 세 덩어리로 띄어 써요."}, {"en": "아버지가 방에 들어가신다.", "ko": "👨 아버지가 방 안으로 들어가요."}, {"en": "아버지 가방에 들어가신다.", "ko": "👜 아버지가 가방 속에 들어가요. (띄어쓰기로 뜻이 바뀌었어요)"}, {"en": "강아지가 멍멍 짖어요.", "ko": "🐶 '강아지가'는 붙여 써요.", "note": "[강아지가 멍멍 지저요]"}, {"en": "엄마가 사과를 깎아요.", "ko": "🍎 '사과를'은 붙여 써요.", "note": "[엄마가 사과를 까까요]"}, {"en": "토끼야, 같이 놀자.", "ko": "🐰 쉼표 뒤에서 조금 쉬어 읽어요.", "note": "[토끼야, 가치 놀자]"}, {"en": "오늘은 날씨가 맑아요.", "ko": "☀️ '오늘은', '날씨가'는 붙여 써요.", "note": "[오느른 날씨가 말가요]"}, {"en": "동생이 그림을 그려요.", "ko": "🖍️ '동생이', '그림을'은 붙여 써요.", "note": "[동생이 그리믈 그려요]"}], "quiz": [{"q": "바르게 띄어 쓴 것은?", "choices": ["나는학교에 가요.", "나는 학교에 가요.", "나 는 학교 에 가요.", "나는 학교에가요."], "answer": 1, "explain": "낱말 사이는 띄우고, '는', '에'는 앞말에 붙여 써요."}, {"q": "'가', '를' 같은 작은 말은 어떻게 쓸까요?", "choices": ["앞 낱말에 붙여 써요", "띄어 써요", "쓰지 않아요", "맨 뒤에 써요"], "answer": 0, "explain": "'가', '를'은 앞 낱말에 붙여 써요. 예: 강아지가, 사과를"}, {"q": "👜 아버지가 가방 속에 들어가는 뜻은?", "choices": ["아버지가 방에 들어가신다.", "아버지가방에 들어가신다.", "아버지가 방에들어가신다.", "아버지 가방에 들어가신다."], "answer": 3, "explain": "'아버지 가방에'로 띄어 쓰면 가방 속에 들어가는 뜻이 돼요."}, {"q": "∨ 표시는 무슨 뜻일까요?", "choices": ["크게 읽어요", "빨리 읽어요", "조금 쉬어 읽어요", "다시 읽어요"], "answer": 2, "explain": "∨는 조금 쉬어 읽으라는 표시예요."}, {"q": "마침표(.) 뒤에서는 어떻게 읽을까요?", "choices": ["∨보다 더 쉬어요", "쉬지 않아요", "노래하듯 읽어요", "크게 소리쳐요"], "answer": 0, "explain": "마침표 뒤에서는 ≫ 표시처럼 조금 더 쉬어 읽어요."}], "summary": ["낱말과 낱말 사이는 한 칸 띄어 써요.", "'가, 를, 는, 에' 같은 말은 앞 낱말에 붙여 써요.", "쉼표 뒤는 조금(∨), 마침표 뒤는 더(≫) 쉬어 읽어요."], "parent_tip": "부모님께: 1~2학년 아이들은 '이', '가', '를' 같은 조사를 띄어 쓰거나 모든 글자를 붙여 쓰는 실수를 자주 합니다. '아버지가 방에/아버지 가방에'처럼 띄어쓰기로 뜻이 바뀌는 문장을 함께 읽고 웃어 보면 띄어쓰기의 필요를 쉽게 느낍니다. 그림책을 읽을 때 쉼표와 마침표에서 손뼉을 한 번, 두 번 치며 쉬어 읽어 보세요.", "narr": {"cover": "assets/audio/n/k1-13_cover.mp3", "s0": "assets/audio/n/k1-13_s0.mp3", "s1": "assets/audio/n/k1-13_s1.mp3", "s2": "assets/audio/n/k1-13_s2.mp3", "s3": "assets/audio/n/k1-13_s3.mp3", "kw": "assets/audio/n/k1-13_kw.mp3", "q0": "assets/audio/n/k1-13_q0.mp3", "q1": "assets/audio/n/k1-13_q1.mp3", "q2": "assets/audio/n/k1-13_q2.mp3", "q3": "assets/audio/n/k1-13_q3.mp3", "q4": "assets/audio/n/k1-13_q4.mp3", "sum": "assets/audio/n/k1-13_sum.mp3"}}$j$::jsonb,13) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','3단계 · 띄어 읽고 띄어 쓰기',13,'k1-13' where not exists (select 1 from public.topics where lesson_slug='k1-13');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-14','1~2','국어','3단계 · 문장 부호 . ? !','마침표, 물음표, 느낌표는 언제 쓸까?','assets/img/l_k1-14.jpg',$j${"intro": "문장 끝에는 작은 표시가 붙어요. 표시에 따라 읽는 느낌이 달라져요.", "sections": [{"heading": "마침표( . )", "paras": ["무엇을 알려 주는 문장 끝에 써요.", "끝을 살짝 내려 읽어요."], "example": "나는 여덟 살이에요.", "figure": "공책 문장 끝에 점을 콕 찍는 연필"}, {"heading": "물음표( ? )", "paras": ["묻는 문장 끝에 써요.", "끝을 올려 읽어요."], "example": "🍚 밥 먹었니?", "figure": "고개를 갸웃하며 묻는 아이"}, {"heading": "느낌표( ! )", "paras": ["놀라거나 기쁜 마음일 때 써요.", "느낌을 살려 힘 있게 읽어요."], "example": "🌈 와, 무지개다!", "figure": "창밖 무지개를 보고 놀란 아이"}, {"heading": "부호가 바뀌면 뜻도 바뀌어요", "paras": ["같은 말도 부호에 따라 달라요.", "'밥 먹어요.'는 알려 주는 말이에요.", "'밥 먹어요?'는 묻는 말이에요."], "example": "밥 먹어요. / 밥 먹어요? / 밥 먹어요!", "figure": ""}], "keywords": [{"word": "문장 부호", "meaning": "문장에 쓰는 여러 가지 표시"}, {"word": "마침표", "meaning": "알려 주는 문장 끝에 쓰는 ."}, {"word": "물음표", "meaning": "묻는 문장 끝에 쓰는 ?"}, {"word": "느낌표", "meaning": "놀람이나 기쁨 같은 느낌을 나타낼 때 쓰는 !"}], "expressions": [{"en": "마침표", "ko": "알려 주는 문장 끝에 쓰는 ."}, {"en": "물음표", "ko": "묻는 문장 끝에 쓰는 ?", "note": "[무름표]"}, {"en": "느낌표", "ko": "느낌을 나타내는 !"}, {"en": "나는 여덟 살이에요.", "ko": "마침표 문장: 알려 주는 말", "note": "[나는 여덜 사리에요] 끝을 내려 읽어요"}, {"en": "오늘은 월요일이에요.", "ko": "마침표 문장: 알려 주는 말", "note": "[오느른 워료이리에요] 끝을 내려 읽어요"}, {"en": "이름이 뭐예요?", "ko": "물음표 문장: 묻는 말", "note": "[이르미 뭐예요] 끝을 올려 읽어요"}, {"en": "어디 가니?", "ko": "물음표 문장: 묻는 말", "note": "끝을 올려 읽어요"}, {"en": "와, 무지개다!", "ko": "🌈 느낌표 문장: 놀라고 기쁜 말", "note": "힘 있게 읽어요"}, {"en": "우아, 정말 멋지다!", "ko": "느낌표 문장: 감탄하는 말", "note": "[우아, 정말 먿찌다]"}, {"en": "밥 먹어요.", "ko": "🍚 알려 주는 말", "note": "[밤 머거요] 끝을 내려 읽어요"}, {"en": "밥 먹어요?", "ko": "🍚 묻는 말", "note": "[밤 머거요] 끝을 올려 읽어요"}], "quiz": [{"q": "묻는 문장 끝에 쓰는 부호는?", "choices": ["마침표 .", "물음표 ?", "느낌표 !", "쉼표 ,"], "answer": 1, "explain": "묻는 문장 끝에는 물음표(?)를 써요."}, {"q": "🌈 '와, 무지개다' 끝에 알맞은 부호는?", "choices": [".", "?", "!", ","], "answer": 2, "explain": "놀라고 기쁜 마음이니 느낌표(!)를 써요."}, {"q": "끝을 올려 읽는 문장은?", "choices": ["사과를 먹어요.", "사과가 맛있다!", "사과가 빨개요.", "사과를 먹어요?"], "answer": 3, "explain": "물음표가 있는 묻는 문장은 끝을 올려 읽어요."}, {"q": "마침표를 쓰기 알맞은 문장은?", "choices": ["나는 1학년이에요", "몇 살이니", "어디 가니", "누구세요"], "answer": 0, "explain": "'나는 1학년이에요'는 알려 주는 문장이라 마침표를 써요. 나머지는 묻는 문장이에요."}, {"q": "'밥 먹어요?'는 어떤 문장일까요?", "choices": ["알려 주는 문장", "묻는 문장", "놀란 문장", "부르는 문장"], "answer": 1, "explain": "물음표가 있으니 묻는 문장이에요."}], "summary": ["알려 주는 문장 끝에는 마침표(.)를 써요.", "묻는 문장 끝에는 물음표(?)를 쓰고 끝을 올려 읽어요.", "놀라거나 기쁜 느낌에는 느낌표(!)를 써요."], "parent_tip": "부모님께: 같은 문장을 '밥 먹어요. / 밥 먹어요? / 밥 먹어요!'처럼 부호만 바꿔 읽어 주면 아이가 차이를 금방 느낍니다. 그림책을 읽을 때 문장 끝 부호를 손가락으로 짚고 목소리를 바꿔 읽는 놀이를 해 보세요. 느낌표는 쓰는 사람의 마음에 따라 마침표로도 쓸 수 있으니 너무 엄격하게 정답을 강요하지 않으셔도 됩니다.", "narr": {"cover": "assets/audio/n/k1-14_cover.mp3", "s0": "assets/audio/n/k1-14_s0.mp3", "s1": "assets/audio/n/k1-14_s1.mp3", "s2": "assets/audio/n/k1-14_s2.mp3", "s3": "assets/audio/n/k1-14_s3.mp3", "kw": "assets/audio/n/k1-14_kw.mp3", "q0": "assets/audio/n/k1-14_q0.mp3", "q1": "assets/audio/n/k1-14_q1.mp3", "q2": "assets/audio/n/k1-14_q2.mp3", "q3": "assets/audio/n/k1-14_q3.mp3", "q4": "assets/audio/n/k1-14_q4.mp3", "sum": "assets/audio/n/k1-14_sum.mp3"}}$j$::jsonb,14) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','3단계 · 문장 부호 . ? !',14,'k1-14' where not exists (select 1 from public.topics where lesson_slug='k1-14');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-15','1~2','국어','3단계 · 꾸며 주는 말','''빨간'' 사과는 어떤 사과일까?','assets/img/l_k1-15.jpg',$j${"intro": "'사과'보다 '빨간 사과'가 더 잘 떠올라요. 꾸며 주는 말을 알아봐요.", "sections": [{"heading": "색깔과 크기를 꾸며요", "paras": ["'빨간', '노란'은 색깔을 알려 줘요.", "'큰', '작은'은 크기를 알려 줘요."], "example": "🍎 빨간 사과, 🐘 커다란 코끼리, 🐜 작은 개미", "figure": "빨간 사과와 작은 개미 모형이 놓인 책상"}, {"heading": "어떻게 하는지 꾸며요", "paras": ["'빨리', '천천히'는 움직임을 꾸며요.", "어떻게 하는지 알려 줘요."], "example": "🐇 토끼가 빨리 달려요. 🐢 거북이 천천히 걸어요.", "figure": "토끼와 거북 인형이 나란히 있는 모습"}, {"heading": "흉내 내는 말도 꾸며요", "paras": ["'엉금엉금', '반짝반짝'도 꾸며 주는 말이에요.", "모양이나 소리를 흉내 내요."], "example": "🐢 엉금엉금 기어가요. ⭐ 반짝반짝 빛나요.", "figure": "밤하늘의 별"}, {"heading": "문장이 생생해져요", "paras": ["꾸며 주는 말을 넣으면 문장이 생생해요.", "눈앞에 그림이 그려져요."], "example": "꽃이 피었어요. → 🌷 예쁜 꽃이 활짝 피었어요.", "figure": "화분에 활짝 핀 튤립"}], "keywords": [{"word": "꾸며 주는 말", "meaning": "다른 말의 색깔, 크기, 모양, 움직임을 자세히 알려 주는 말"}, {"word": "흉내 내는 말", "meaning": "소리나 모양을 흉내 낸 말(엉금엉금, 반짝반짝)"}, {"word": "생생하다", "meaning": "눈앞에 보이는 것처럼 또렷하다"}], "expressions": [{"en": "빨간 사과", "ko": "🍎 색깔을 꾸며요"}, {"en": "노란 바나나", "ko": "🍌 색깔을 꾸며요"}, {"en": "커다란 코끼리", "ko": "🐘 크기를 꾸며요"}, {"en": "작은 개미", "ko": "🐜 크기를 꾸며요", "note": "[자근 개미]"}, {"en": "귀여운 강아지", "ko": "🐶 모습을 꾸며요"}, {"en": "빨리 달려요", "ko": "🐇 움직임을 꾸며요"}, {"en": "천천히 걸어요", "ko": "🐢 움직임을 꾸며요", "note": "[천천히 거러요]"}, {"en": "엉금엉금 기어가요", "ko": "🐢 흉내 내는 말"}, {"en": "반짝반짝 빛나요", "ko": "⭐ 흉내 내는 말", "note": "[반짝빤짝 빈나요]"}, {"en": "예쁜 꽃이 활짝 피었어요.", "ko": "🌷 꾸며 주는 말이 두 개 들어간 문장", "note": "[예쁜 꼬치 활짝 피어써요]"}], "quiz": [{"q": "🍌 바나나를 꾸며 주기 알맞은 말은?", "choices": ["파란", "노란", "분홍", "네모난"], "answer": 1, "explain": "바나나는 노란색이라 '노란 바나나'가 알맞아요."}, {"q": "'귀여운 강아지'에서 꾸며 주는 말은?", "choices": ["귀여운", "강아지", "둘 다", "없어요"], "answer": 0, "explain": "'귀여운'이 강아지의 모습을 꾸며 줘요."}, {"q": "🐢 거북은 어떻게 걸을까요?", "choices": ["빨리", "쌩쌩", "천천히", "훨훨"], "answer": 2, "explain": "거북은 느리게 걸으니 '천천히'가 알맞아요."}, {"q": "⭐ 별이 ___ 빛나요. 알맞은 말은?", "choices": ["엉금엉금", "깡충깡충", "꿀꿀", "반짝반짝"], "answer": 3, "explain": "별이 빛나는 모양은 '반짝반짝'이에요."}, {"q": "더 생생한 문장은?", "choices": ["꽃이 피었어요.", "꽃이 있어요.", "예쁜 꽃이 활짝 피었어요.", "꽃이요."], "answer": 2, "explain": "'예쁜', '활짝'이 들어가서 꽃 모습이 더 잘 떠올라요."}], "summary": ["꾸며 주는 말은 색깔, 크기, 모양을 자세히 알려 줘요.", "'빨리', '천천히'처럼 움직임을 꾸미는 말도 있어요.", "꾸며 주는 말을 넣으면 문장이 생생해져요."], "parent_tip": "부모님께: 아이가 '꽃이 피었다'처럼 짧게 쓰면 '어떤 꽃이야? 어떻게 피었어?' 하고 물어 꾸며 주는 말을 끌어내 주세요. 산책하면서 보이는 사물에 꾸며 주는 말을 붙이는 놀이(빨간 자동차, 커다란 나무)를 해 보면 좋습니다. 맞고 틀림보다 다양한 표현을 칭찬해 주세요.", "narr": {"cover": "assets/audio/n/k1-15_cover.mp3", "s0": "assets/audio/n/k1-15_s0.mp3", "s1": "assets/audio/n/k1-15_s1.mp3", "s2": "assets/audio/n/k1-15_s2.mp3", "s3": "assets/audio/n/k1-15_s3.mp3", "kw": "assets/audio/n/k1-15_kw.mp3", "q0": "assets/audio/n/k1-15_q0.mp3", "q1": "assets/audio/n/k1-15_q1.mp3", "q2": "assets/audio/n/k1-15_q2.mp3", "q3": "assets/audio/n/k1-15_q3.mp3", "q4": "assets/audio/n/k1-15_q4.mp3", "sum": "assets/audio/n/k1-15_sum.mp3"}}$j$::jsonb,15) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','3단계 · 꾸며 주는 말',15,'k1-15' where not exists (select 1 from public.topics where lesson_slug='k1-15');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-16','1~2','국어','3단계 · 그림일기 쓰기','그림일기는 어떻게 쓸까?','assets/img/l_k1-16.jpg',$j${"intro": "오늘 있었던 일을 그림과 글로 남겨요. 그림일기를 함께 써 봐요.", "sections": [{"heading": "날짜와 날씨를 써요", "paras": ["맨 위에 날짜와 요일을 써요.", "날씨도 써요. ☀️ 맑음, 🌧️ 비처럼요."], "example": "10월 13일 화요일, 날씨: ☀️ 맑음", "figure": "그림일기 공책 윗부분의 날짜 칸을 가리키는 손가락"}, {"heading": "기억에 남는 일을 골라요", "paras": ["오늘 한 일 가운데 하나를 골라요.", "가장 기억에 남는 일이 좋아요."], "example": "🎈 동생과 공원에서 그네를 탄 일", "figure": "공원 그네를 타는 아이"}, {"heading": "그림을 그려요", "paras": ["고른 장면을 그림으로 그려요.", "누가, 어디에서, 무엇을 했는지 보이게 그려요."], "example": "🖍️ 그네를 타는 나와 웃는 동생", "figure": "크레파스로 그림을 그리는 아이 손"}, {"heading": "글을 써요", "paras": ["한 일을 차례대로 써요.", "마지막에 생각이나 느낌을 써요."], "example": "동생과 공원에 갔다. 그네를 탔다. 정말 재미있었다.", "figure": "그림 아래 줄 칸에 연필로 글을 쓰는 아이"}], "keywords": [{"word": "일기", "meaning": "날마다 겪은 일과 생각을 적는 글"}, {"word": "그림일기", "meaning": "그림과 짧은 글로 쓰는 일기"}, {"word": "날씨", "meaning": "맑음, 흐림, 비, 눈처럼 하늘의 모습"}, {"word": "느낌", "meaning": "일을 겪고 든 마음(재미있었다, 슬펐다)"}], "expressions": [{"en": "그림일기", "ko": "그림과 글로 쓰는 일기"}, {"en": "날씨", "ko": "하늘의 모습"}, {"en": "맑음", "ko": "☀️ 해가 쨍쨍한 날씨", "note": "[말금]"}, {"en": "흐림", "ko": "☁️ 구름이 많은 날씨"}, {"en": "비", "ko": "🌧️ 비가 오는 날씨"}, {"en": "눈", "ko": "❄️ 눈이 오는 날씨"}, {"en": "월요일", "ko": "한 주의 첫날", "note": "[워료일]"}, {"en": "오늘은 동생과 공원에 갔다.", "ko": "🎈 한 일: 누구와, 어디에", "note": "[오느른 동생과 공워네 갇따]"}, {"en": "그네를 탔다.", "ko": "한 일: 무엇을", "note": "[그네를 탇따]"}, {"en": "정말 재미있었다.", "ko": "😄 느낌", "note": "[정말 재미이썯따]"}], "quiz": [{"q": "그림일기 맨 위에 쓰는 것은?", "choices": ["날짜와 날씨", "친구 이름", "좋아하는 색", "내 키"], "answer": 0, "explain": "그림일기 맨 위에는 날짜, 요일, 날씨를 써요."}, {"q": "☁️ 그림에 맞는 날씨 말은?", "choices": ["맑음", "흐림", "눈", "비"], "answer": 1, "explain": "구름이 많은 날씨는 '흐림'이에요."}, {"q": "그림일기에 쓰기 알맞은 일은?", "choices": ["내년에 할 일", "동화책 줄거리", "오늘 기억에 남는 일", "친구의 비밀"], "answer": 2, "explain": "그림일기에는 오늘 겪은 일 가운데 기억에 남는 일을 써요."}, {"q": "느낌을 쓴 문장은?", "choices": ["공원에 갔다.", "그네를 탔다.", "동생과 갔다.", "정말 재미있었다."], "answer": 3, "explain": "'재미있었다'는 마음, 곧 느낌을 나타내요."}, {"q": "❄️ 그림에 맞는 날씨 말은?", "choices": ["비", "맑음", "눈", "바람"], "answer": 2, "explain": "하얀 ❄️가 내리는 날씨는 '눈'이에요."}], "summary": ["그림일기 맨 위에는 날짜, 요일, 날씨를 써요.", "기억에 남는 일 하나를 골라 그림으로 그려요.", "한 일을 차례대로 쓰고, 마지막에 느낌을 써요."], "parent_tip": "부모님께: 아이가 '아침에 일어났다. 밥을 먹었다…'처럼 하루를 다 나열하면 '오늘 가장 기억나는 일 하나만 골라 볼까?'라고 도와주세요. 글을 쓰기 전에 '누구랑, 어디서, 무엇을 했어? 기분은 어땠어?'를 말로 먼저 해 보게 하면 쓰기가 훨씬 쉬워집니다. 맞춤법보다 자기 생각을 쓴 것을 먼저 칭찬해 주세요.", "narr": {"cover": "assets/audio/n/k1-16_cover.mp3", "s0": "assets/audio/n/k1-16_s0.mp3", "s1": "assets/audio/n/k1-16_s1.mp3", "s2": "assets/audio/n/k1-16_s2.mp3", "s3": "assets/audio/n/k1-16_s3.mp3", "kw": "assets/audio/n/k1-16_kw.mp3", "q0": "assets/audio/n/k1-16_q0.mp3", "q1": "assets/audio/n/k1-16_q1.mp3", "q2": "assets/audio/n/k1-16_q2.mp3", "q3": "assets/audio/n/k1-16_q3.mp3", "q4": "assets/audio/n/k1-16_q4.mp3", "sum": "assets/audio/n/k1-16_sum.mp3"}}$j$::jsonb,16) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','3단계 · 그림일기 쓰기',16,'k1-16' where not exists (select 1 from public.topics where lesson_slug='k1-16');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-17','1~2','국어','3단계 · 이야기 순서 정리하기','이야기는 어떤 차례로 펼쳐질까?','assets/img/l_k1-17.jpg',$j${"intro": "이야기에는 처음, 가운데, 끝이 있어요. 차례를 알면 이야기가 쉬워져요.", "sections": [{"heading": "처음, 가운데, 끝", "paras": ["이야기는 처음에 시작해요.", "가운데에서 일이 생겨요.", "끝에서 이야기가 마무리돼요."], "example": "🌱 씨앗을 심었어요. → 🌿 싹이 났어요. → 🌻 꽃이 피었어요.", "figure": "화분 세 개에 씨앗, 싹, 꽃이 차례로 있는 모습"}, {"heading": "차례를 알려 주는 말", "paras": ["'먼저', '그다음에', '마지막으로'를 써요.", "이 말을 보면 차례를 알 수 있어요."], "example": "먼저 손을 씻어요. 그다음에 밥을 먹어요. 마지막으로 이를 닦아요.", "figure": "세면대에서 손을 씻는 아이"}, {"heading": "시간을 알려 주는 말", "paras": ["'아침', '점심', '저녁'도 차례를 알려 줘요.", "시간 차례대로 일이 일어나요."], "example": "☀️ 아침에 일어나요. 🍱 점심을 먹어요. 🌙 저녁에 자요.", "figure": "해가 뜨는 아침과 달이 뜬 밤 그림"}, {"heading": "이야기 차례 정리하기", "paras": ["일이 일어난 차례대로 정리해요.", "'토끼와 거북'으로 해 봐요."], "example": "🐇🐢 경주를 해요. → 🐇 토끼가 낮잠을 자요. → 🐢 거북이 이겨요.", "figure": "결승선을 지나는 거북 인형"}], "keywords": [{"word": "차례", "meaning": "먼저와 나중을 따라 늘어놓은 순서"}, {"word": "처음·가운데·끝", "meaning": "이야기가 시작하고, 일이 생기고, 마무리되는 부분"}, {"word": "차례를 나타내는 말", "meaning": "먼저, 그다음에, 마지막으로처럼 순서를 알려 주는 말"}], "expressions": [{"en": "처음", "ko": "이야기가 시작하는 부분"}, {"en": "가운데", "ko": "일이 생기는 부분"}, {"en": "끝", "ko": "이야기가 마무리되는 부분", "note": "[끋]"}, {"en": "먼저", "ko": "가장 앞에 하는 일"}, {"en": "그다음에", "ko": "먼저 한 일 바로 뒤에", "note": "[그다으메]"}, {"en": "마지막으로", "ko": "맨 끝에", "note": "[마지마그로]"}, {"en": "아침에", "ko": "☀️ 하루가 시작될 때", "note": "[아치메]"}, {"en": "저녁에", "ko": "🌙 해가 진 뒤", "note": "[저녀게]"}, {"en": "먼저 손을 씻어요.", "ko": "🧼 차례를 알려 주는 문장", "note": "[먼저 소늘 씨서요]"}, {"en": "토끼가 낮잠을 잤어요.", "ko": "🐇 이야기 가운데 부분", "note": "[토끼가 낟짜믈 자써요]"}, {"en": "거북이 경주에서 이겼어요.", "ko": "🐢 이야기 끝부분", "note": "[거부기 경주에서 이겨써요]"}], "quiz": [{"q": "🌱 → 🌿 → ? 다음에 올 것은?", "choices": ["🌻 꽃이 피어요", "🌰 씨앗을 심어요", "🌱 싹이 나요", "🪨 돌이 굴러요"], "answer": 0, "explain": "씨앗, 싹 다음에는 꽃이 피어요."}, {"q": "차례를 알려 주는 말이 아닌 것은?", "choices": ["먼저", "그다음에", "마지막으로", "빨간"], "answer": 3, "explain": "'빨간'은 색깔을 꾸며 주는 말이에요."}, {"q": "'토끼와 거북'에서 토끼는 경주 중에 무엇을 했나요?", "choices": ["노래를 불렀어요", "낮잠을 잤어요", "물을 마셨어요", "집에 갔어요"], "answer": 1, "explain": "토끼는 거북을 얕보고 낮잠을 잤어요."}, {"q": "하루의 차례로 맞는 것은?", "choices": ["저녁 → 아침 → 점심", "점심 → 저녁 → 아침", "아침 → 점심 → 저녁", "저녁 → 점심 → 아침"], "answer": 2, "explain": "하루는 아침, 점심, 저녁 차례로 지나가요."}, {"q": "이야기가 마무리되는 부분은?", "choices": ["처음", "가운데", "끝", "제목"], "answer": 2, "explain": "이야기는 끝부분에서 마무리돼요."}], "summary": ["이야기는 처음, 가운데, 끝으로 이어져요.", "'먼저, 그다음에, 마지막으로'는 차례를 알려 줘요.", "일이 일어난 차례대로 정리하면 이야기를 잘 이해할 수 있어요."], "parent_tip": "부모님께: 그림책을 읽은 뒤 '처음에 무슨 일이 있었지? 그다음엔? 마지막엔?' 하고 세 번만 물어보세요. 아이가 이야기를 차례대로 말하는 연습이 됩니다. 요리, 양치처럼 생활 속 일도 '먼저, 그다음에'로 말해 보게 하면 좋습니다.", "narr": {"cover": "assets/audio/n/k1-17_cover.mp3", "s0": "assets/audio/n/k1-17_s0.mp3", "s1": "assets/audio/n/k1-17_s1.mp3", "s2": "assets/audio/n/k1-17_s2.mp3", "s3": "assets/audio/n/k1-17_s3.mp3", "kw": "assets/audio/n/k1-17_kw.mp3", "q0": "assets/audio/n/k1-17_q0.mp3", "q1": "assets/audio/n/k1-17_q1.mp3", "q2": "assets/audio/n/k1-17_q2.mp3", "q3": "assets/audio/n/k1-17_q3.mp3", "q4": "assets/audio/n/k1-17_q4.mp3", "sum": "assets/audio/n/k1-17_sum.mp3"}}$j$::jsonb,17) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','3단계 · 이야기 순서 정리하기',17,'k1-17' where not exists (select 1 from public.topics where lesson_slug='k1-17');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k1-18','1~2','국어','3단계 · 인사말과 높임말','어른께는 어떻게 인사하고 말할까?','assets/img/l_k1-18.jpg',$j${"intro": "인사를 하면 마음이 따뜻해져요. 어른께는 높임말을 써요.", "sections": [{"heading": "때에 맞는 인사말", "paras": ["만나면 '안녕하세요.'라고 해요.", "밥 먹기 전에는 '잘 먹겠습니다.'라고 해요."], "example": "🌙 자기 전: 안녕히 주무세요. / 🎒 학교 갈 때: 다녀오겠습니다.", "figure": "현관에서 가족에게 인사하는 아이"}, {"heading": "가는 사람, 남는 사람", "paras": ["떠나는 사람에게는 '안녕히 가세요.'라고 해요.", "남는 사람에게는 '안녕히 계세요.'라고 해요."], "example": "🚪 손님이 가실 때: 안녕히 가세요.", "figure": "문 앞에서 손을 흔드는 아이"}, {"heading": "고마울 때, 미안할 때", "paras": ["고마우면 '고맙습니다.'라고 해요.", "잘못했으면 '죄송합니다.'라고 해요."], "example": "🎁 고맙습니다. / 🙇 죄송합니다.", "figure": "선물을 두 손으로 받는 아이"}, {"heading": "어른께 쓰는 높임말", "paras": ["어른께는 높이는 낱말을 써요.", "밥은 '진지', 집은 '댁'이라고 해요.", "말끝에 '-요'나 '-습니다'를 붙여요."], "example": "👵 할머니, 진지 드세요.", "figure": "할머니께 밥그릇을 두 손으로 드리는 아이"}], "keywords": [{"word": "인사말", "meaning": "만나거나 헤어질 때, 고마울 때 하는 말"}, {"word": "높임말", "meaning": "어른을 높여서 하는 말"}, {"word": "진지", "meaning": "'밥'의 높임말"}, {"word": "댁", "meaning": "'집'의 높임말"}, {"word": "연세", "meaning": "'나이'의 높임말"}], "expressions": [{"en": "안녕하세요", "ko": "만났을 때 하는 인사"}, {"en": "안녕히 주무세요", "ko": "🌙 자기 전에 어른께 하는 인사"}, {"en": "안녕히 가세요", "ko": "떠나는 사람에게 하는 인사"}, {"en": "안녕히 계세요", "ko": "남는 사람에게 하는 인사", "note": "[안녕히 게세요]"}, {"en": "잘 먹겠습니다", "ko": "🍚 밥 먹기 전 인사", "note": "[잘 먹껟씀니다]"}, {"en": "다녀오겠습니다", "ko": "🎒 집을 나설 때 인사", "note": "[다녀오겓씀니다]"}, {"en": "다녀왔습니다", "ko": "🏠 집에 돌아왔을 때 인사", "note": "[다녀왇씀니다]"}, {"en": "고맙습니다", "ko": "🎁 고마울 때 하는 말", "note": "[고맙씀니다]"}, {"en": "죄송합니다", "ko": "🙇 어른께 잘못을 빌 때 하는 말", "note": "[죄송함니다]"}, {"en": "진지 드세요", "ko": "'밥 먹어요'의 높임말"}, {"en": "할머니 댁", "ko": "'할머니 집'의 높임말"}, {"en": "연세", "ko": "'나이'의 높임말"}], "quiz": [{"q": "🌙 자기 전에 부모님께 하는 인사는?", "choices": ["안녕히 주무세요.", "잘 먹었습니다.", "다녀오겠습니다.", "안녕히 가세요."], "answer": 0, "explain": "잠자리에 들 때는 '안녕히 주무세요.'라고 해요."}, {"q": "친구 집에서 나올 때, 집에 남는 친구 어머니께 하는 인사는?", "choices": ["안녕히 가세요.", "안녕히 계세요.", "잘 먹겠습니다.", "안녕히 주무세요."], "answer": 1, "explain": "내가 떠나고 어머니는 남으시니 '안녕히 계세요.'라고 해요."}, {"q": "'밥'의 높임말은?", "choices": ["댁", "연세", "진지", "말씀"], "answer": 2, "explain": "어른께는 '밥' 대신 '진지'라고 해요."}, {"q": "할아버지께 알맞게 말한 것은?", "choices": ["할아버지, 밥 먹어.", "할아버지, 밥 먹자.", "할아버지, 빨리 와.", "할아버지, 진지 드세요."], "answer": 3, "explain": "'진지', '드세요'를 써서 할아버지를 높였어요."}, {"q": "🎒 학교에 가면서 가족에게 하는 인사는?", "choices": ["다녀왔습니다.", "다녀오겠습니다.", "안녕히 주무세요.", "잘 먹었습니다."], "answer": 1, "explain": "집을 나설 때는 '다녀오겠습니다.'라고 해요."}], "summary": ["때와 장소에 맞는 인사말을 해요.", "떠나는 사람에게는 '안녕히 가세요', 남는 사람에게는 '안녕히 계세요'예요.", "어른께는 진지, 댁, 연세 같은 높임말과 '-요, -습니다'를 써요."], "parent_tip": "부모님께: 아이들은 '안녕히 가세요'와 '안녕히 계세요'를 가장 많이 헷갈립니다. '누가 떠나고 누가 남지?'를 먼저 묻게 해 주세요. 높임말은 설명보다 생활 속에서 부모님이 조부모님께 쓰는 모습을 보여 주는 것이 가장 효과적입니다. 아이가 '진지 드세요'처럼 바르게 말하면 바로 칭찬해 주세요.", "narr": {"cover": "assets/audio/n/k1-18_cover.mp3", "s0": "assets/audio/n/k1-18_s0.mp3", "s1": "assets/audio/n/k1-18_s1.mp3", "s2": "assets/audio/n/k1-18_s2.mp3", "s3": "assets/audio/n/k1-18_s3.mp3", "kw": "assets/audio/n/k1-18_kw.mp3", "q0": "assets/audio/n/k1-18_q0.mp3", "q1": "assets/audio/n/k1-18_q1.mp3", "q2": "assets/audio/n/k1-18_q2.mp3", "q3": "assets/audio/n/k1-18_q3.mp3", "q4": "assets/audio/n/k1-18_q4.mp3", "sum": "assets/audio/n/k1-18_sum.mp3"}}$j$::jsonb,18) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','국어','3단계 · 인사말과 높임말',18,'k1-18' where not exists (select 1 from public.topics where lesson_slug='k1-18');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-01','3~4','국어','낱말의 뜻 짐작하기','처음 보는 낱말, 뜻을 어떻게 알아낼까?','assets/img/l_k3-01.jpg',$j${"intro": "책을 읽다가 처음 보는 낱말을 만나면 그냥 건너뛰고 싶지요? 하지만 탐정처럼 단서를 찾으면 사전 없이도 뜻을 짐작할 수 있어요.", "sections": [{"heading": "앞뒤 문장에 단서가 숨어 있어요", "paras": ["모르는 낱말이 나오면 그 낱말의 앞뒤 문장을 천천히 다시 읽어 보세요. 글쓴이는 낱말 둘레에 뜻을 알려 주는 단서를 남겨 두는 경우가 많아요.", "이렇게 앞뒤에 이어지는 내용을 ‘문맥’이라고 해요. 문맥을 살피면 낱말이 좋은 뜻인지 나쁜 뜻인지, 무엇과 관련된 말인지 알 수 있어요."], "example": "“동생은 배가 고파서 밥을 허겁지겁 먹었어요. 숟가락이 쉴 틈이 없었어요.” → ‘허겁지겁’은 ‘아주 급하게 서두르는 모양’이라고 짐작할 수 있어요.", "figure": "책을 펴 놓고 돋보기로 낱말 하나를 들여다보는 아이"}, {"heading": "비슷한 말을 넣어 보아요", "paras": ["짐작한 뜻을 그 낱말 자리에 바꾸어 넣고 문장을 다시 읽어 보세요. 문장이 자연스러우면 짐작이 잘 맞은 거예요.", "어색하다면 다른 뜻을 생각해 보고 다시 넣어 보면 돼요."], "example": "“할머니 댁 마당은 아주 널찍했어요.” → ‘넓은’을 넣어 “아주 넓었어요.”로 읽어도 자연스러워요. 그러니 ‘널찍하다’는 ‘꽤 넓다’는 뜻이에요.", "figure": "문장 카드의 빈칸에 낱말 카드를 바꾸어 끼워 보는 손"}, {"heading": "낱말을 나누어 보아요", "paras": ["긴 낱말은 아는 부분으로 나누어 보면 뜻이 보여요. 예를 들어 ‘맨발’은 ‘맨’과 ‘발’로 나눌 수 있어요.", "‘맨-’은 ‘다른 것이 없는’이라는 뜻을 더해 주어서 ‘맨발’은 양말이나 신을 신지 않은 발이에요. ‘맨손’, ‘맨눈’도 같은 방법으로 짐작할 수 있어요."], "example": "책가방 = 책 + 가방 → 책을 넣는 가방 / 눈사람 = 눈 + 사람 → 눈으로 만든 사람 모양", "figure": "낱말 카드를 가위로 두 조각으로 나누어 놓은 모습"}, {"heading": "짐작한 뜻은 국어사전으로 확인해요", "paras": ["짐작은 어디까지나 짐작이에요. 마지막에는 국어사전에서 낱말을 찾아 짐작한 뜻이 맞는지 확인해 보세요.", "짐작한 뜻과 사전의 뜻을 비교해 보면 낱말 실력이 쑥쑥 자라요."], "example": "짐작: ‘허겁지겁’ = 급하게 서두르는 모양 → 사전: ‘조급한 마음으로 몹시 허둥거리는 모양’", "figure": "책상 위에 펼쳐 놓은 국어사전과 연필, 메모지"}], "keywords": [{"word": "짐작", "meaning": "사정이나 형편을 어림잡아 헤아림"}, {"word": "문맥", "meaning": "글에서 낱말이나 문장의 앞뒤로 이어지는 내용"}, {"word": "단서", "meaning": "어떤 것을 알아내는 데 도움이 되는 실마리"}, {"word": "비슷한 말", "meaning": "뜻이 서로 비슷한 낱말 (예: 기쁘다 - 즐겁다)"}], "expressions": [], "quiz": [{"q": "모르는 낱말의 뜻을 짐작할 때 가장 먼저 해 보면 좋은 방법은?", "choices": ["그 낱말을 빼고 읽는다", "앞뒤 문장을 다시 읽어 본다", "그림만 본다", "아무 뜻이나 정한다"], "answer": 1, "explain": "낱말 앞뒤의 문장(문맥)에 뜻을 알려 주는 단서가 숨어 있어요."}, {"q": "“날이 저물어 사방이 캄캄해졌어요.”에서 ‘저물어’의 뜻으로 알맞은 것은?", "choices": ["해가 져서 어두워져", "비가 많이 와서", "해가 막 떠올라", "바람이 세게 불어"], "answer": 0, "explain": "뒤에 ‘캄캄해졌어요’가 있으니 해가 져서 어두워진다는 뜻임을 짐작할 수 있어요."}, {"q": "‘맨손’을 나누어 뜻을 짐작했어요. 알맞은 뜻은?", "choices": ["아주 큰 손", "다친 손", "장갑을 낀 손", "아무것도 끼거나 들지 않은 손"], "answer": 3, "explain": "‘맨-’은 ‘다른 것이 없는’이라는 뜻이라 ‘맨손’은 아무것도 끼거나 들지 않은 손이에요."}, {"q": "짐작한 뜻이 맞는지 확인하는 방법으로 알맞지 __않은__ 것은?", "choices": ["짐작한 뜻을 넣어 문장을 읽어 본다", "국어사전에서 찾아본다", "친구가 고른 뜻을 그대로 믿는다", "앞뒤 문장과 어울리는지 살핀다"], "answer": 2, "explain": "짐작한 뜻은 문장에 넣어 보거나 사전으로 확인해야 해요."}], "summary": ["모르는 낱말은 앞뒤 문장(문맥)에서 단서를 찾아 뜻을 짐작해요.", "짐작한 뜻을 낱말 자리에 넣어 자연스러운지 읽어 보거나, 낱말을 나누어 생각해요.", "짐작한 뜻은 마지막에 국어사전으로 확인해요."], "parent_tip": "아이들은 모르는 낱말을 만나면 건너뛰거나 바로 뜻을 물어보는 경우가 많습니다. 함께 책을 읽다가 낯선 낱말이 나오면 정답을 알려 주기보다 “앞뒤를 보면 어떤 뜻일 것 같아?”라고 먼저 물어봐 주세요. 짐작한 뒤 사전으로 함께 확인하면 스스로 뜻을 찾는 습관이 생깁니다."}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','낱말의 뜻 짐작하기',1,'k3-01' where not exists (select 1 from public.topics where lesson_slug='k3-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-02','3~4','국어','중심 문장 찾기','이 문단에서 가장 중요한 문장은 어디 있을까?','assets/img/l_k3-02.jpg',$j${"intro": "글을 다 읽었는데 무슨 내용이었는지 한마디로 말하기 어려웠던 적이 있나요? 문단마다 숨어 있는 ‘중심 문장’을 찾으면 글의 내용이 한눈에 들어와요.", "sections": [{"heading": "문단은 생각 하나를 담은 덩어리예요", "paras": ["글은 여러 개의 문단으로 이루어져 있어요. 문단은 하나의 생각을 담고 있는 문장들의 묶음이에요.", "새 문단이 시작될 때는 줄을 바꾸고 첫 칸을 한 칸 비우고 써요. 그래서 들여 쓴 곳을 보면 문단이 어디서 시작하는지 알 수 있어요."], "example": "글 한 편 = 문단 + 문단 + 문단 … / 문단 하나 = 중심 문장 1개 + 뒷받침 문장 여러 개", "figure": "공책에 쓴 글에서 문단마다 첫 칸이 들여쓰기된 모습"}, {"heading": "중심 문장과 뒷받침 문장", "paras": ["문단에서 가장 중요한 생각을 담은 문장을 ‘중심 문장’이라고 해요.", "중심 문장의 내용을 자세히 설명하거나 예를 들어 주는 문장은 ‘뒷받침 문장’이라고 해요. 뒷받침 문장은 중심 문장을 받쳐 주는 기둥과 같아요."], "example": "[중심 문장] 개미는 서로 도우며 살아가요. [뒷받침 문장] 먹이를 찾으면 동료에게 알려 줘요. 무거운 먹이는 여럿이 함께 옮겨요. 집을 지킬 때도 힘을 모아요.", "figure": "지붕(중심 문장)을 여러 기둥(뒷받침 문장)이 받치고 있는 집 그림"}, {"heading": "중심 문장은 어디에 있을까요?", "paras": ["중심 문장은 문단의 처음에 나오는 경우가 가장 많아요. 하지만 문단의 끝에서 앞의 내용을 정리하며 나오기도 해요.", "그러니 위치만 보고 정하지 말고, 문단의 모든 문장을 아우르는 문장인지 꼭 확인해야 해요."], "example": "끝에 있는 경우: “봄에는 진달래가 피어요. 여름에는 해바라기가 피어요. 가을에는 국화가 피어요. 이처럼 계절마다 피는 꽃이 달라요.”", "figure": "문단의 첫 문장과 마지막 문장에 각각 형광펜을 칠한 종이"}, {"heading": "이렇게 찾아요", "paras": ["① 문단을 끝까지 읽고 무엇에 대한 이야기인지 생각해요. ② 다른 문장들이 공통으로 설명하는 문장을 찾아요. ③ 그 문장을 빼면 문단의 내용을 알기 어려운지 확인해요.", "각 문단의 중심 문장을 모아 이으면 글 전체의 중심 생각을 짧게 정리할 수 있어요."], "example": "“우리 몸에 물은 꼭 필요해요. 물은 몸속 찌꺼기를 내보내요. 땀을 흘려 체온을 맞춰 줘요.” → 중심 문장: 우리 몸에 물은 꼭 필요해요.", "figure": "연필로 문단의 한 문장에 밑줄을 긋는 아이의 손"}], "keywords": [{"word": "문단", "meaning": "하나의 생각을 담고 있는 문장들의 묶음"}, {"word": "중심 문장", "meaning": "문단에서 가장 중요한 생각을 담은 문장"}, {"word": "뒷받침 문장", "meaning": "중심 문장을 자세히 설명하거나 예를 들어 주는 문장"}, {"word": "중심 생각", "meaning": "글 전체에서 글쓴이가 가장 말하고 싶은 생각"}], "expressions": [], "quiz": [{"q": "문단에서 가장 중요한 생각을 담은 문장은 무엇일까요?", "choices": ["뒷받침 문장", "중심 문장", "마지막 문장", "제목"], "answer": 1, "explain": "가장 중요한 생각을 담은 문장을 중심 문장이라고 해요."}, {"q": "중심 문장이 가장 많이 나오는 위치는 어디일까요?", "choices": ["문단의 처음", "문단의 가운데", "제목 바로 위", "글의 맨 끝 줄"], "answer": 0, "explain": "중심 문장은 문단의 처음에 많이 나오고, 끝에 나오기도 해요."}, {"q": "“고양이는 밤에도 잘 봐요. 고양이 눈은 적은 빛도 잘 모아요. 그래서 어두운 곳에서도 쥐를 잡을 수 있어요.” 이 문단의 중심 문장은?", "choices": ["고양이 눈은 적은 빛도 잘 모아요.", "그래서 어두운 곳에서도 쥐를 잡을 수 있어요.", "고양이는 쥐를 좋아해요.", "고양이는 밤에도 잘 봐요."], "answer": 3, "explain": "나머지 문장은 모두 고양이가 밤에도 잘 본다는 내용을 설명하고 있어요."}, {"q": "뒷받침 문장이 하는 일로 알맞은 것은?", "choices": ["중심 문장을 자세히 설명하거나 예를 든다", "글의 제목을 정한다", "새 문단을 시작한다", "중심 문장과 반대되는 말을 한다"], "answer": 0, "explain": "뒷받침 문장은 중심 문장의 내용을 자세히 풀어 주거나 예를 들어 줘요."}, {"q": "중심 문장을 찾는 방법으로 알맞은 것은?", "choices": ["가장 긴 문장을 고른다", "무조건 첫 문장을 고른다", "다른 문장들이 공통으로 설명하는 문장을 찾는다", "모르는 낱말이 있는 문장을 고른다"], "answer": 2, "explain": "중심 문장은 다른 문장들을 모두 아우르는 문장이에요. 위치만 보고 정하면 틀릴 수 있어요."}], "summary": ["문단은 하나의 생각을 담은 문장들의 묶음이에요.", "문단은 중심 문장과 그것을 설명하는 뒷받침 문장으로 이루어져요.", "중심 문장은 주로 문단의 처음이나 끝에 있고, 다른 문장들을 모두 아우르는 문장이에요."], "parent_tip": "아이들은 중심 문장을 ‘첫 문장’이라고만 외우는 경우가 많습니다. 끝에 정리하듯 나오는 문단도 함께 보여 주시고, “이 문장들이 모두 무엇에 대해 말하고 있어?”라고 물어 주세요. 신문 기사나 동화책 한 문단을 골라 한 문장으로 줄여 말해 보게 하면 요약하는 힘도 함께 자랍니다."}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','중심 문장 찾기',2,'k3-02' where not exists (select 1 from public.topics where lesson_slug='k3-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-03','3~4','국어','높임 표현 바르게 쓰기','할머니께 ‘밥 먹어’라고 해도 될까?','assets/img/l_k3-03.jpg',$j${"intro": "친구에게는 “밥 먹어.”라고 말하지만 할머니께는 “진지 드세요.”라고 말해요. 웃어른께 존중하는 마음을 담아 말하는 방법, 높임 표현을 알아보아요.", "sections": [{"heading": "높임 표현은 왜 쓸까요?", "paras": ["높임 표현은 상대를 높여 존중하는 마음을 나타내는 말이에요. 할아버지, 할머니, 부모님, 선생님처럼 나보다 웃어른께 말할 때 써요.", "높임 표현을 바르게 쓰면 예의 바른 사람으로 보이고, 듣는 분의 기분도 좋아져요."], "example": "친구에게: “같이 가자.” / 선생님께: “같이 가요.” 또는 “같이 가시겠어요?”", "figure": "아이가 할머니께 두 손으로 물컵을 건네는 모습"}, {"heading": "높임을 나타내는 낱말이 따로 있어요", "paras": ["어떤 낱말은 웃어른께 쓸 때 다른 낱말로 바꾸어 써요. 이런 낱말을 알아 두면 높임 표현을 자연스럽게 쓸 수 있어요.", "웃어른의 행동을 말할 때는 ‘먹다’ 대신 ‘드시다, 잡수시다’, ‘자다’ 대신 ‘주무시다’, ‘있다’ 대신 ‘계시다’를 써요."], "example": "밥 → 진지, 집 → 댁, 나이 → 연세, 이름 → 성함, 생일 → 생신, 말 → 말씀, 아프다 → 편찮으시다, 주다 → 드리다, 묻다 → 여쭙다", "figure": "왼쪽에 보통 말 카드, 오른쪽에 높임 말 카드가 짝지어 놓인 책상"}, {"heading": "‘-시-’와 ‘께서, 께’를 붙여요", "paras": ["웃어른이 문장의 주인공이 되면 ‘이/가’ 대신 ‘께서’를 쓰고, 움직임을 나타내는 말에 ‘-시-’를 넣어요. 웃어른께 무엇을 줄 때는 ‘에게’ 대신 ‘께’를 써요.", "또 웃어른께 직접 말할 때는 문장 끝을 ‘-요’나 ‘-습니다’로 맺어요."], "example": "할아버지가 신문을 읽는다. → 할아버지께서 신문을 읽으신다. / 엄마에게 꽃을 줬다. → 어머니께 꽃을 드렸어요.", "figure": "할아버지께서 안락의자에 앉아 신문을 읽으시는 모습"}, {"heading": "이런 높임은 틀려요", "paras": ["높임 표현은 사람을 높이는 말이에요. 물건이나 음식을 높이면 안 돼요. 가게에서 “커피 나오셨습니다.”라고 하는 것은 틀린 표현이에요.", "또 나를 높이면 안 돼요. 웃어른 앞에서는 ‘나’ 대신 ‘저’, ‘우리’ 대신 ‘저희’를 써서 나를 낮추어요."], "example": "✕ 주문하신 음식 나오셨습니다. → ○ 주문하신 음식 나왔습니다. / ✕ 선생님, 나도 할래요. → ○ 선생님, 저도 할래요.", "figure": "식탁 위에 놓인 주스 잔과 접시, 그 옆에 앞치마를 두른 손"}], "keywords": [{"word": "높임 표현", "meaning": "상대를 높여 존중하는 마음을 나타내는 말"}, {"word": "웃어른", "meaning": "나이나 지위, 항렬이 나보다 높은 어른"}, {"word": "께서", "meaning": "웃어른이 문장의 주인공일 때 ‘이/가’ 대신 쓰는 말"}, {"word": "께", "meaning": "웃어른에게 무엇을 할 때 ‘에게’ 대신 쓰는 말"}, {"word": "진지", "meaning": "‘밥’의 높임말"}], "expressions": [], "quiz": [{"q": "‘나이’의 높임말은 무엇일까요?", "choices": ["성함", "댁", "연세", "진지"], "answer": 2, "explain": "나이의 높임말은 연세예요. 성함은 이름, 댁은 집, 진지는 밥의 높임말이에요."}, {"q": "높임 표현을 바르게 쓴 문장은?", "choices": ["할머니께서 주무신다.", "할머니가 잔다.", "할머니께서 잔다.", "할머니가 밥을 먹는다."], "answer": 0, "explain": "‘께서’와 ‘주무시다’를 써서 할머니를 바르게 높였어요."}, {"q": "“선생님에게 질문을 했어요.”를 바르게 고친 것은?", "choices": ["선생님께서 질문을 했어요.", "선생님에게 질문을 하셨어요.", "선생님한테 물었어요.", "선생님께 여쭈어보았어요."], "answer": 3, "explain": "웃어른께는 ‘에게’ 대신 ‘께’, ‘묻다’ 대신 ‘여쭈다(여쭙다)’를 써요."}, {"q": "높임 표현을 __잘못__ 쓴 것은?", "choices": ["아버지께서 회사에 가셨어요.", "주문하신 커피 나오셨습니다.", "할아버지, 진지 드세요.", "저도 함께 가도 될까요?"], "answer": 1, "explain": "커피는 사람이 아니니 높이면 안 돼요. ‘커피 나왔습니다’가 맞아요."}], "summary": ["높임 표현은 웃어른을 존중하는 마음을 나타내는 말이에요.", "진지, 댁, 연세, 생신처럼 높임 낱말을 쓰고, ‘께서, 께’와 ‘-시-’를 붙여 높여요.", "물건이나 나 자신은 높이지 않아요. 웃어른 앞에서는 ‘저, 저희’를 써요."], "parent_tip": "아이들은 ‘께서’를 쓰고도 서술어에 ‘-시-’를 빠뜨리거나(할머니께서 잔다), 물건을 높이는(커피 나오셨습니다) 실수를 자주 합니다. 식사 시간에 “할아버지께 뭐라고 말씀드릴까?”처럼 실제 상황에서 연습하게 해 주세요. 가게나 방송에서 들리는 잘못된 높임 표현을 함께 찾아보는 것도 좋은 공부가 됩니다."}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','높임 표현 바르게 쓰기',3,'k3-03' where not exists (select 1 from public.topics where lesson_slug='k3-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-04','3~4','국어','국어사전 찾는 방법(기본형)','‘먹었다’는 왜 국어사전에 없을까?','assets/img/l_k3-04.jpg',$j${"intro": "국어사전에서 ‘먹었다’를 찾아보면 아무리 넘겨도 나오지 않아요. 국어사전에는 낱말이 정해진 순서와 정해진 모양으로 실려 있기 때문이에요. 그 비밀을 알아보아요.", "sections": [{"heading": "국어사전은 글자 순서대로 실려 있어요", "paras": ["국어사전에는 낱말이 자음자와 모음자의 순서에 따라 실려 있어요. 먼저 첫 글자의 첫 자음자를 보고, 같으면 모음자, 그다음 받침을 차례로 살펴요.", "첫 글자가 모두 같으면 두 번째 글자를 같은 방법으로 비교해요."], "example": "찾는 순서: ① 첫 자음자 → ② 모음자 → ③ 받침 (받침이 없는 글자가 받침 있는 글자보다 먼저 나와요.)", "figure": "책상 위에 펼친 국어사전의 옆면에 자음자 색인 표시가 보이는 모습"}, {"heading": "자음자와 모음자의 순서", "paras": ["자음자는 ㄱ부터 ㅎ까지의 순서이고, 된소리(ㄲ, ㄸ, ㅃ, ㅆ, ㅉ)는 짝이 되는 자음자 바로 뒤에 와요.", "모음자는 ㅏ부터 ㅣ까지의 순서이고, ㅐ나 ㅘ처럼 두 모음이 합쳐진 모음자는 정해진 자리에 끼어 있어요."], "example": "자음자: ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ\n모음자: ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ", "figure": "자음자 카드와 모음자 카드를 순서대로 한 줄씩 늘어놓은 책상"}, {"heading": "이렇게 순서를 정해요", "paras": ["‘나무’, ‘가방’, ‘누나’를 사전 순서로 놓아 볼까요? 첫 자음자를 보면 ‘가방’의 ㄱ이 가장 앞이에요.", "‘나무’와 ‘누나’는 첫 자음자가 ㄴ으로 같으니 모음자를 비교해요. ㅏ가 ㅜ보다 앞이므로 ‘나무’가 먼저예요."], "example": "가방 → 나무 → 누나 / 받침 비교: 가 → 각 → 간 (받침 없음 → ㄱ → ㄴ)", "figure": "낱말 카드 세 장을 순서대로 줄 세우는 아이의 손"}, {"heading": "모양이 바뀌는 낱말은 기본형으로 찾아요", "paras": ["‘먹었다, 먹고, 먹어서, 먹으니’처럼 쓰임에 따라 모양이 바뀌는 낱말이 있어요. 이런 낱말은 국어사전에 ‘먹다’라는 하나의 모양으로만 실려 있어요. 이 모양을 ‘기본형’이라고 해요.", "기본형은 모양이 바뀌지 않는 부분에 ‘-다’를 붙여 만들어요. ‘먹었다’에서 바뀌지 않는 부분은 ‘먹-’이니 ‘먹다’로 찾으면 돼요."], "example": "읽고, 읽어서, 읽으니 → 읽다 / 작아서, 작고, 작으니 → 작다 / 뛰었다, 뛰고 → 뛰다", "figure": "공책에 낱말의 바뀌지 않는 부분에 동그라미를 친 모습"}], "keywords": [{"word": "국어사전", "meaning": "우리말 낱말을 순서대로 모아 뜻과 쓰임을 풀이한 책"}, {"word": "자음자", "meaning": "ㄱ, ㄴ, ㄷ처럼 자음을 나타내는 글자"}, {"word": "모음자", "meaning": "ㅏ, ㅑ, ㅓ처럼 모음을 나타내는 글자"}, {"word": "받침", "meaning": "글자의 아래에 받쳐 적는 자음자"}, {"word": "기본형", "meaning": "모양이 바뀌는 낱말에서 바뀌지 않는 부분에 ‘-다’를 붙인 모양"}], "expressions": [], "quiz": [{"q": "국어사전에서 낱말을 찾을 때 가장 먼저 살펴보는 것은?", "choices": ["첫 글자의 받침", "첫 글자의 첫 자음자", "마지막 글자", "낱말의 길이"], "answer": 1, "explain": "첫 자음자 → 모음자 → 받침 순서로 살펴요."}, {"q": "‘달렸다’를 국어사전에서 찾으려면 어떤 모양으로 찾아야 할까요?", "choices": ["달렸다", "달려", "달리다", "달"], "answer": 2, "explain": "바뀌지 않는 부분 ‘달리-’에 ‘-다’를 붙인 ‘달리다’가 기본형이에요."}, {"q": "국어사전에 먼저 나오는 낱말은?", "choices": ["하늘", "바다", "구름", "사과"], "answer": 2, "explain": "첫 자음자를 비교하면 ㄱ(구름)이 ㅂ, ㅅ, ㅎ보다 앞이에요."}, {"q": "‘고기’와 ‘거미’ 중 국어사전에 먼저 나오는 낱말과 그 까닭으로 알맞은 것은?", "choices": ["고기 - ㅗ가 ㅓ보다 앞이라서", "거미 - ㅓ가 ㅗ보다 앞이라서", "고기 - 받침이 없어서", "거미 - 글자 수가 적어서"], "answer": 1, "explain": "첫 자음자가 ㄱ으로 같으니 모음자를 비교해요. ㅓ가 ㅗ보다 앞이라 ‘거미’가 먼저예요."}, {"q": "기본형이 ‘작다’인 낱말이 __아닌__ 것은?", "choices": ["작아서", "작고", "작으니", "잡아서"], "answer": 3, "explain": "‘잡아서’의 기본형은 ‘잡다’예요."}], "summary": ["국어사전에는 낱말이 첫 자음자 → 모음자 → 받침 순서로 실려 있어요.", "받침이 없는 글자가 받침이 있는 글자보다 먼저 나와요.", "모양이 바뀌는 낱말은 바뀌지 않는 부분에 ‘-다’를 붙인 기본형으로 찾아요."], "parent_tip": "요즘은 인터넷 사전에 활용형을 넣어도 기본형을 찾아 주지만, 종이 사전을 찾아보면 낱말의 짜임과 순서를 확실히 익힐 수 있습니다. 아이가 ‘먹었다’를 그대로 찾으려 하면 “모양이 바뀌지 않는 부분이 어디까지일까?”라고 물어 주세요. ㅐ, ㅔ, ㅚ 같은 모음자의 순서는 아이들이 많이 헷갈리니 사전 옆면을 함께 보며 확인하면 좋습니다."}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','국어사전 찾는 방법(기본형)',4,'k3-04' where not exists (select 1 from public.topics where lesson_slug='k3-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-05','3~4','국어','헷갈리는 말 바르게 쓰기(맞춤법)','감기가 ‘낫다’일까, ‘낳다’일까?','assets/img/l_k3-05.jpg',$j${"intro": "“감기가 빨리 낳았으면 좋겠어.” 어디가 틀렸는지 보이나요? 소리는 비슷한데 뜻과 모양이 다른 말, 자주 틀리는 말을 바르게 쓰는 방법을 알아보아요.", "sections": [{"heading": "소리는 같은데 뜻이 다른 말", "paras": ["‘낫다’와 ‘낮다’는 똑같이 [낟따]로 소리 나고, ‘낳다’[나타]도 소리가 비슷해서 헷갈리기 쉬워요. 이런 말은 문장의 뜻을 생각해서 알맞은 낱말을 골라야 해요.", "‘낫다’는 병이나 상처가 없어진다는 뜻, ‘낳다’는 아기나 알을 몸 밖으로 내놓는다는 뜻, ‘낮다’는 높지 않다는 뜻이에요."], "example": "감기가 다 나았어요. / 닭이 알을 낳았어요. / 담장이 낮아요.\n편지를 부쳐요(보내요). / 우표를 붙여요(달라붙게 해요).\n반드시(꼭) 지킬게요. / 반듯이(바르게) 앉아요.", "figure": "책상 위에 놓인 달걀 바구니, 반창고, 낮은 블록 탑"}, {"heading": "뜻이 헷갈리는 말", "paras": ["‘가르치다’는 지식이나 기술을 알려 준다는 뜻이고, ‘가리키다’는 손가락 등으로 방향이나 대상을 집어 보인다는 뜻이에요.", "‘잃어버리다’는 물건이 없어진 것이고, ‘잊어버리다’는 기억하지 못하는 것이에요. ‘맞히다’는 정답을 골라낸다는 뜻이고, ‘맞추다’는 서로 대어 보거나 제자리에 끼운다는 뜻이에요."], "example": "선생님께서 수학을 가르치세요. / 손가락으로 산을 가리켜요.\n지갑을 잃어버렸어요. / 숙제를 잊어버렸어요.\n퀴즈 정답을 맞혔어요. / 퍼즐 조각을 맞췄어요.", "figure": "손가락으로 창밖을 가리키는 아이와 칠판 앞에서 설명하는 손"}, {"heading": "‘안’과 ‘않’ 구별하기", "paras": ["‘안’은 ‘아니’를 줄인 말로, 움직임을 나타내는 말 앞에 써요. ‘않’은 ‘아니하’를 줄인 말로, ‘-지’ 뒤에 써요.", "헷갈릴 때는 그 낱말을 빼 보세요. ‘안’은 빼도 문장이 되지만 ‘않’은 빼면 문장이 어색해져요."], "example": "밥을 안 먹었어요. (아니 먹었어요) / 밥을 먹지 않았어요. (먹지 아니하였어요)", "figure": "공책에 ‘안’과 ‘않’을 두 칸으로 나누어 정리한 모습"}, {"heading": "자주 틀리는 말, 이렇게 써요", "paras": ["소리 나는 대로 쓰다가 자주 틀리는 말들이 있어요. 바른 모양을 눈에 익혀 두면 틀리지 않아요.", "‘되’와 ‘돼’가 헷갈리면 ‘하’와 ‘해’를 넣어 보세요. ‘하’가 어울리면 ‘되’, ‘해’가 어울리면 ‘돼’예요."], "example": "몇일 ✕ → 며칠 ○ / 금새 ✕ → 금세 ○ / 설겆이 ✕ → 설거지 ○ / 어떻해 ✕ → 어떻게, 어떡해 ○\n그러면 안 돼요(안 해요 ○). / 의사가 되고 싶어요(하고 ○).", "figure": "빨간 색연필로 틀린 낱말을 고친 받아쓰기 공책"}], "keywords": [{"word": "맞춤법", "meaning": "말을 글자로 바르게 적는 규칙"}, {"word": "낫다", "meaning": "병이나 상처가 없어져 본래대로 되다"}, {"word": "가리키다", "meaning": "손가락 등으로 방향이나 대상을 집어 보이다"}, {"word": "가르치다", "meaning": "지식이나 기술 등을 알려 주다"}, {"word": "잊어버리다", "meaning": "알았던 것을 기억하지 못하게 되다"}], "expressions": [], "quiz": [{"q": "바르게 쓴 문장은?", "choices": ["상처가 다 낳았어요.", "상처가 다 나았어요.", "상처가 다 낮았어요.", "상처가 다 낫았어요."], "answer": 1, "explain": "병이나 상처가 없어지는 것은 ‘낫다’예요. ‘나았어요’로 써요."}, {"q": "“손가락으로 북쪽을 ( ).” 빈칸에 알맞은 말은?", "choices": ["가르쳤어요", "가리켰어요", "가르켰어요", "가리쳤어요"], "answer": 1, "explain": "방향을 집어 보이는 것은 ‘가리키다’예요."}, {"q": "‘안’과 ‘않’을 바르게 쓴 문장은?", "choices": ["오늘은 학교에 가지 안았어요.", "나는 우유를 않 마셔요.", "숙제를 아직 안 했어요.", "동생이 울지 안는다."], "answer": 2, "explain": "‘안 했어요’는 ‘아니 했어요’의 줄임이라 바르게 썼어요. ‘-지’ 뒤에는 ‘않’을 써요."}, {"q": "바르게 쓴 낱말은?", "choices": ["몇일", "금새", "설겆이", "며칠"], "answer": 3, "explain": "‘며칠’, ‘금세’, ‘설거지’가 바른 말이에요."}, {"q": "“퀴즈의 정답을 ( ).” 빈칸에 알맞은 말은?", "choices": ["맞혔어요", "맞췄어요", "마쳤어요", "맡혔어요"], "answer": 0, "explain": "정답을 골라내는 것은 ‘맞히다’예요. ‘맞추다’는 퍼즐처럼 제자리에 끼우거나 서로 대어 볼 때 써요."}], "summary": ["소리가 같거나 비슷해도 뜻에 따라 낫다·낳다·낮다처럼 다르게 써요.", "가르치다·가리키다, 잃어버리다·잊어버리다, 맞히다·맞추다는 뜻을 생각해 골라 써요.", "‘안’은 빼도 말이 되고, ‘않’은 ‘-지’ 뒤에 써요. 며칠·금세·설거지처럼 바른 모양을 익혀요."], "parent_tip": "맞춤법은 규칙을 외우기보다 문장 속에서 자주 보고 써 보는 것이 효과적입니다. 아이의 일기나 문자 메시지에서 헷갈리는 말이 나오면 바로 고쳐 주기보다 “이 말은 무슨 뜻으로 쓴 거야?”라고 물어 스스로 고르게 해 주세요. ‘안/않’, ‘되/돼’는 빼 보기와 하/해 넣어 보기 방법을 함께 연습하면 오래 기억합니다."}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','헷갈리는 말 바르게 쓰기(맞춤법)',5,'k3-05' where not exists (select 1 from public.topics where lesson_slug='k3-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-06','3~4','국어','원인과 결과','왜 그런 일이 일어났을까?','assets/img/l_k3-06.jpg',$j${"intro": "아침에 늦잠을 잤더니 학교에 지각했어요. 이렇게 어떤 일에는 그 일이 일어나게 한 까닭이 있어요. 원인과 결과를 찾으며 글을 읽으면 내용이 훨씬 잘 이해돼요.", "sections": [{"heading": "원인과 결과란 무엇일까요?", "paras": ["어떤 일이 일어나게 된 까닭을 ‘원인’이라고 하고, 그 원인 때문에 생긴 일을 ‘결과’라고 해요.", "원인이 먼저 일어나고, 결과는 그 뒤에 일어나요. 그래서 ‘무엇 때문에 → 어떻게 되었다’로 이어서 말할 수 있어요."], "example": "원인: 밤새 눈이 많이 내렸어요. → 결과: 길이 미끄러워졌어요.", "figure": "눈이 쌓인 길 위에 놓인 장화와 털장갑"}, {"heading": "원인과 결과를 이어 주는 말", "paras": ["글에서 원인과 결과는 이어 주는 말로 연결될 때가 많아요. ‘그래서’, ‘-아서/-어서’, ‘-기 때문에’ 뒤에는 결과가 와요.", "‘왜냐하면’이 나오면 그 뒤에 원인이 와요. 이런 말을 찾으면 원인과 결과를 쉽게 알 수 있어요."], "example": "비가 왔어요. 그래서 소풍이 미루어졌어요. / 비가 와서 소풍이 미루어졌어요. / 소풍이 미루어졌어요. 왜냐하면 비가 왔기 때문이에요.", "figure": "창문에 빗방울이 맺히고 창가에 소풍 가방이 놓여 있는 모습"}, {"heading": "결과를 보고 원인을 찾아요", "paras": ["글을 읽을 때 어떤 일이 일어났으면 “왜 그렇게 되었을까?” 하고 질문해 보세요. 그 답이 원인이에요.", "하나의 원인이 여러 결과를 낳기도 하고, 한 결과에 원인이 여러 개 있기도 해요."], "example": "결과: 화분의 식물이 시들었어요. → 왜? 원인: 일주일 동안 물을 주지 않았어요.", "figure": "잎이 축 처진 화분 옆에 놓인 빈 물뿌리개"}, {"heading": "표로 정리하면 한눈에 보여요", "paras": ["설명하는 글을 읽을 때 원인과 결과를 표로 정리해 보세요. 왼쪽에 원인, 오른쪽에 결과를 쓰면 글의 내용이 한눈에 들어와요.", "원인과 결과를 잘 알면 앞으로 일어날 일을 미리 생각하고 대비할 수도 있어요."], "example": "원인: 이를 잘 닦지 않아요. → 결과: 충치가 생겨요. / 원인: 운동을 꾸준히 해요. → 결과: 몸이 튼튼해져요.", "figure": "공책에 두 칸 표를 그리고 화살표로 이은 모습"}], "keywords": [{"word": "원인", "meaning": "어떤 일이 일어나게 된 까닭"}, {"word": "결과", "meaning": "어떤 까닭 때문에 생긴 일"}, {"word": "그래서", "meaning": "앞의 내용이 원인이 되어 뒤의 결과가 생길 때 쓰는 이어 주는 말"}, {"word": "왜냐하면", "meaning": "뒤에 앞일의 까닭(원인)을 말할 때 쓰는 말"}], "expressions": [], "quiz": [{"q": "어떤 일이 일어나게 된 까닭을 무엇이라고 할까요?", "choices": ["결과", "원인", "의견", "제목"], "answer": 1, "explain": "일이 일어나게 된 까닭은 원인이에요."}, {"q": "“배탈이 나서 병원에 갔어요.”에서 결과는 무엇일까요?", "choices": ["배탈이 났어요.", "아이스크림을 먹었어요.", "병원에 갔어요.", "약을 샀어요."], "answer": 2, "explain": "배탈이 난 것이 원인이고, 그래서 병원에 간 것이 결과예요."}, {"q": "‘왜냐하면’ 뒤에 오는 내용은 무엇일까요?", "choices": ["원인", "결과", "제목", "인사"], "answer": 0, "explain": "‘왜냐하면’ 뒤에는 앞일이 일어난 까닭, 즉 원인이 와요."}, {"q": "원인과 결과가 바르게 이어진 것은?", "choices": ["옷이 젖었다 → 그래서 비를 맞았다", "얼음을 햇볕에 두었다 → 그래서 얼음이 녹았다", "배가 부르다 → 그래서 밥을 먹었다", "넘어졌다 → 그래서 뛰었다"], "answer": 1, "explain": "얼음을 햇볕에 둔 것이 원인이 되어 얼음이 녹는 결과가 생겼어요."}], "summary": ["원인은 어떤 일이 일어난 까닭이고, 결과는 그 때문에 생긴 일이에요.", "‘그래서, -아서/-어서, -기 때문에’ 뒤에는 결과가, ‘왜냐하면’ 뒤에는 원인이 와요.", "“왜 그렇게 되었을까?” 하고 물으며 읽고, 표로 정리하면 원인과 결과가 잘 보여요."], "parent_tip": "아이들은 원인과 결과의 순서를 거꾸로 말하는 경우가 많습니다(“옷이 젖어서 비가 왔어”). 일상에서 “왜 그렇게 됐을까?”, “그러면 어떻게 될까?”를 자주 물어봐 주세요. 뉴스나 날씨 이야기처럼 짧은 글에서 ‘그래서’, ‘때문에’를 찾아 원인과 결과를 나누어 말해 보면 설명하는 글 읽기에 큰 도움이 됩니다."}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','원인과 결과',6,'k3-06' where not exists (select 1 from public.topics where lesson_slug='k3-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-07','3~4','국어','의견과 까닭','내 생각을 어떻게 말해야 친구들이 고개를 끄덕일까?','assets/img/l_k3-07.jpg',$j${"intro": "“반려동물을 키우고 싶어요!”라고만 말하면 부모님은 쉽게 허락하지 않으실 거예요. 내 생각에 알맞은 까닭을 붙이면 듣는 사람을 설득할 수 있어요.", "sections": [{"heading": "의견이란 무엇일까요?", "paras": ["의견은 어떤 대상이나 문제에 대하여 내가 가진 생각이에요. 사람마다 생각이 다르기 때문에 같은 문제에도 서로 다른 의견이 나올 수 있어요.", "의견을 나타내는 문장은 보통 ‘~해야 한다’, ‘~하면 좋겠다’, ‘~라고 생각한다’처럼 끝나요."], "example": "의견: 복도에서는 걸어 다녀야 합니다. / 의견: 우리 반 학급 문고에 만화책을 더 두면 좋겠습니다.", "figure": "교실 칠판 앞에서 손을 들고 발표하는 아이의 뒷모습"}, {"heading": "까닭이 있어야 설득할 수 있어요", "paras": ["까닭은 왜 그런 의견을 가졌는지 알려 주는 이유예요. 까닭 없이 의견만 말하면 듣는 사람은 왜 그래야 하는지 알 수 없어요.", "의견을 말할 때는 ‘왜냐하면 ~ 때문입니다’처럼 까닭을 함께 말해요. 까닭은 두세 가지를 들면 더 설득력이 있어요."], "example": "의견: 복도에서는 걸어 다녀야 합니다. 왜냐하면 뛰다가 친구와 부딪쳐 다칠 수 있기 때문입니다. 또 뛰는 소리가 다른 반 수업에 방해가 되기 때문입니다.", "figure": "학교 복도에서 아이들이 줄을 맞춰 천천히 걸어가는 모습"}, {"heading": "알맞은 까닭은 이런 거예요", "paras": ["좋은 까닭은 의견과 관련이 있어야 하고, 듣는 사람이 고개를 끄덕일 만큼 믿을 만해야 해요.", "‘내가 하고 싶으니까’, ‘그냥’처럼 나만 생각한 까닭이나 의견과 관계없는 까닭은 알맞지 않아요."], "example": "의견: 급식을 남기지 말아야 합니다.\n○ 알맞은 까닭: 음식물 쓰레기가 줄어 환경을 지킬 수 있기 때문입니다.\n✕ 알맞지 않은 까닭: 급식실이 1층에 있기 때문입니다.", "figure": "깨끗하게 비운 급식판과 수저"}, {"heading": "의견을 나타내는 글의 짜임", "paras": ["의견이 드러나는 글은 보통 ‘처음-가운데-끝’으로 써요. 처음에는 문제 상황과 내 의견을, 가운데에는 까닭을, 끝에는 의견을 다시 한번 강조해요.", "글을 읽을 때도 이 짜임을 생각하면 글쓴이의 의견과 까닭을 쉽게 찾을 수 있어요."], "example": "처음: 우리 반은 쉬는 시간에 교실이 너무 시끄럽습니다. 교실에서는 조용히 이야기해야 합니다.\n가운데: 첫째, 책을 읽는 친구에게 방해가 됩니다. 둘째, 큰 소리는 귀 건강에 좋지 않습니다.\n끝: 모두가 편안한 교실을 위해 조용히 이야기합시다.", "figure": "공책에 처음·가운데·끝 세 칸으로 나누어 글의 짜임을 정리한 모습"}], "keywords": [{"word": "의견", "meaning": "어떤 대상이나 문제에 대하여 가지는 생각"}, {"word": "까닭", "meaning": "어떤 일이나 생각이 생기게 된 이유"}, {"word": "설득", "meaning": "상대가 내 생각을 따르도록 여러 가지로 깨우쳐 말함"}, {"word": "처음-가운데-끝", "meaning": "의견을 나타내는 글의 짜임 (문제와 의견 - 까닭 - 의견 강조)"}], "expressions": [], "quiz": [{"q": "어떤 대상이나 문제에 대하여 가지는 생각을 무엇이라고 할까요?", "choices": ["사실", "의견", "결과", "제목"], "answer": 1, "explain": "어떤 대상이나 문제에 대한 내 생각은 의견이에요."}, {"q": "의견을 나타낸 문장은 무엇일까요?", "choices": ["우리 학교 운동장에는 나무가 열 그루 있다.", "오늘은 월요일이다.", "학교 도서관을 토요일에도 열면 좋겠다.", "우리 반은 25명이다."], "answer": 2, "explain": "‘~하면 좋겠다’처럼 생각을 나타낸 문장이 의견이에요."}, {"q": "“숙제를 미리 해야 합니다.”라는 의견에 알맞은 까닭은?", "choices": ["숙제 공책이 예쁘기 때문입니다.", "미루면 시간에 쫓겨 실수를 하기 쉽기 때문입니다.", "그냥 그렇게 하고 싶기 때문입니다.", "어제 비가 왔기 때문입니다."], "answer": 1, "explain": "의견과 관련 있고 누구나 고개를 끄덕일 만한 까닭이에요."}, {"q": "의견을 나타내는 글의 ‘가운데’ 부분에 주로 쓰는 내용은?", "choices": ["의견을 뒷받침하는 까닭", "글쓴이의 이름", "인사말", "날짜"], "answer": 0, "explain": "처음에는 의견, 가운데에는 까닭, 끝에는 의견을 다시 강조해요."}, {"q": "알맞은 까닭의 조건이 __아닌__ 것은?", "choices": ["의견과 관련이 있다.", "듣는 사람이 믿을 만하다.", "여러 사람에게 도움이 된다.", "나만 좋으면 된다."], "answer": 3, "explain": "나만 생각한 까닭은 다른 사람을 설득하기 어려워요."}], "summary": ["의견은 어떤 대상이나 문제에 대한 내 생각이에요.", "의견을 말할 때는 ‘왜냐하면 ~ 때문입니다’처럼 알맞은 까닭을 함께 말해요.", "의견을 나타내는 글은 처음(의견) - 가운데(까닭) - 끝(의견 강조)으로 써요."], "parent_tip": "아이가 무언가를 요청할 때 “왜 그렇게 생각해? 까닭을 두 가지 말해 볼래?”라고 되물어 주세요. ‘그냥’, ‘하고 싶으니까’ 같은 까닭이 나오면 다른 사람도 고개를 끄덕일 만한 까닭인지 함께 따져 보면 좋습니다. 가족회의 안건(주말 나들이 장소 등)을 정해 의견과 까닭을 말해 보는 활동도 효과적입니다."}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','의견과 까닭',7,'k3-07' where not exists (select 1 from public.topics where lesson_slug='k3-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-08','3~4','국어','마음을 전하는 편지','고마운 마음, 편지로 어떻게 전할까?','assets/img/l_k3-08.jpg',$j${"intro": "얼굴을 보고 “고마워.”라고 말하기 쑥스러울 때가 있지요? 그럴 때 편지를 쓰면 내 마음을 차분하고 진심 있게 전할 수 있어요.", "sections": [{"heading": "편지로 전할 수 있는 마음", "paras": ["편지에는 여러 가지 마음을 담을 수 있어요. 도움을 받았을 때의 고마운 마음, 잘못했을 때의 미안한 마음, 좋은 일이 생겼을 때의 축하하는 마음, 힘든 일을 겪은 사람을 위로하는 마음이 있어요.", "어떤 마음을 전할지 먼저 정하면 편지에 쓸 내용이 또렷해져요."], "example": "고마운 마음: 우산을 함께 써 준 친구에게 / 미안한 마음: 말다툼한 동생에게 / 축하하는 마음: 대회에서 상을 받은 형에게 / 위로하는 마음: 다리를 다친 친구에게", "figure": "책상 위에 색깔이 다른 편지 봉투 네 장이 놓여 있는 모습"}, {"heading": "편지의 형식을 알아요", "paras": ["편지는 정해진 차례에 따라 써요. ① 받을 사람 ② 첫인사 ③ 전하고 싶은 말 ④ 끝인사 ⑤ 쓴 날짜 ⑥ 쓴 사람 순서예요.", "쓴 사람을 적을 때 친구에게는 ‘○○가’, 웃어른께는 ‘○○ 올림’이나 ‘○○ 드림’이라고 써요."], "example": "① 사랑하는 할머니께 ② 할머니, 안녕하세요? 저 지호예요. ③ (전하고 싶은 말) ④ 할머니, 건강하세요. ⑤ 20○○년 5월 8일 ⑥ 손자 지호 올림", "figure": "편지지 한 장 위에 차례를 나타내는 번호 스티커가 붙어 있는 모습"}, {"heading": "마음이 잘 드러나게 쓰는 방법", "paras": ["‘고마워’라는 말만 쓰기보다 어떤 일이 있었는지 구체적으로 쓰면 마음이 더 잘 전해져요. 그때 내 기분이 어땠는지도 함께 써 보세요.", "받는 사람에 맞게 말을 골라야 해요. 웃어른께는 높임 표현을 쓰고, 친구에게는 다정한 말로 써요."], "example": "✕ 서연아, 고마워.\n○ 서연아, 지난주 비 오는 날 우산을 같이 써 줘서 정말 고마워. 비에 젖을까 봐 걱정했는데 네 덕분에 마음이 따뜻해졌어.", "figure": "아이가 연필로 편지지에 정성껏 글씨를 쓰는 손"}, {"heading": "다 쓴 뒤에는 다시 읽어요", "paras": ["편지를 다 쓰면 받는 사람이 되었다고 생각하고 소리 내어 읽어 보세요. 형식을 빠뜨리지 않았는지, 맞춤법이 틀린 곳은 없는지 살펴요.", "편지를 받은 사람이 기분 좋게 읽을 수 있도록 글씨도 또박또박 써요."], "example": "확인할 것: 받을 사람·첫인사·끝인사·날짜·쓴 사람이 다 있나요? / 겪은 일과 내 마음이 드러나나요? / 높임 표현은 알맞나요?", "figure": "봉투에 편지를 넣고 스티커를 붙이는 손"}], "keywords": [{"word": "첫인사", "meaning": "편지의 처음에 받는 사람에게 건네는 인사"}, {"word": "끝인사", "meaning": "편지를 마무리하며 건네는 인사"}, {"word": "올림", "meaning": "웃어른께 편지를 쓸 때 쓴 사람의 이름 뒤에 붙이는 말"}, {"word": "위로", "meaning": "따뜻한 말이나 행동으로 괴로움이나 슬픔을 달래 줌"}], "expressions": [], "quiz": [{"q": "편지를 쓰는 차례로 알맞은 것은?", "choices": ["첫인사 → 받을 사람 → 끝인사 → 전하고 싶은 말", "받을 사람 → 첫인사 → 전하고 싶은 말 → 끝인사", "전하고 싶은 말 → 받을 사람 → 첫인사 → 끝인사", "끝인사 → 첫인사 → 받을 사람 → 전하고 싶은 말"], "answer": 1, "explain": "받을 사람 → 첫인사 → 전하고 싶은 말 → 끝인사 → 쓴 날짜 → 쓴 사람 순서로 써요."}, {"q": "선생님께 편지를 쓸 때 쓴 사람을 바르게 적은 것은?", "choices": ["제자 민준이가", "민준", "제자 민준 올림", "민준이 씀"], "answer": 2, "explain": "웃어른께는 이름 뒤에 ‘올림’이나 ‘드림’을 붙여요."}, {"q": "마음이 가장 잘 드러나게 쓴 문장은?", "choices": ["고마워.", "고마워, 고마워, 고마워.", "그냥 고맙다고 쓰는 거야.", "줄넘기를 못 해서 속상할 때 끝까지 가르쳐 줘서 정말 고마웠어."], "answer": 3, "explain": "있었던 일과 그때의 마음을 구체적으로 쓰면 마음이 잘 전해져요."}, {"q": "상을 받은 친구에게 쓸 편지에 담을 마음으로 알맞은 것은?", "choices": ["축하하는 마음", "미안한 마음", "위로하는 마음", "걱정하는 마음"], "answer": 0, "explain": "좋은 일이 생긴 친구에게는 축하하는 마음을 전해요."}], "summary": ["편지에는 고마움, 미안함, 축하, 위로 같은 마음을 담을 수 있어요.", "편지는 받을 사람 → 첫인사 → 전하고 싶은 말 → 끝인사 → 쓴 날짜 → 쓴 사람 순서로 써요.", "있었던 일과 그때의 마음을 구체적으로 쓰고, 받는 사람에 맞는 말을 골라 써요."], "parent_tip": "아이들은 편지에 ‘고마워, 사랑해’만 반복해서 쓰는 경우가 많습니다. “언제, 어떤 일 때문에 고마웠어?”라고 물어 구체적인 장면을 떠올리게 해 주세요. 어버이날이나 생일처럼 실제로 편지를 보낼 기회를 만들고, 받은 편지에 답장해 주시면 아이가 글로 마음을 전하는 즐거움을 느낄 수 있습니다."}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','마음을 전하는 편지',8,'k3-08' where not exists (select 1 from public.topics where lesson_slug='k3-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-09','3~4','국어','인물의 마음 짐작하기','이야기 속 인물은 지금 어떤 마음일까?','assets/img/l_k3-09.jpg',$j${"intro": "이야기 속 인물은 “나 지금 속상해.”라고 직접 말하지 않을 때가 많아요. 그래도 인물의 말과 행동을 잘 살피면 그 마음을 알아챌 수 있어요.", "sections": [{"heading": "인물의 말과 행동에 마음이 담겨 있어요", "paras": ["인물의 마음은 인물이 하는 말, 행동, 표정에 드러나요. 발을 동동 구르거나 고개를 푹 숙이는 행동에도 마음이 숨어 있어요.", "인물이 어떤 말투로 말하는지도 살펴보세요. 같은 말이라도 큰 소리로 외치는지, 작게 중얼거리는지에 따라 마음이 달라요."], "example": "“에이, 또 졌잖아!” 준이는 공을 바닥에 던지고 씩씩거렸어요. → 말과 행동을 보니 준이는 속상하고 화가 난 마음이에요.", "figure": "운동장 바닥에 놓인 축구공과 고개 숙인 아이의 운동화"}, {"heading": "인물이 처한 상황을 살펴요", "paras": ["인물에게 어떤 일이 일어났는지 생각해 보세요. 기다리던 생일 선물을 받았는지, 아끼던 물건을 잃어버렸는지에 따라 마음이 달라져요.", "그리고 “내가 저 인물이라면 어떤 마음일까?” 하고 나와 견주어 생각해 보면 마음을 짐작하기 쉬워요."], "example": "상황: 이사 가는 날, 단짝 친구와 헤어지게 되었어요. → 나라면? 슬프고 서운할 것 같아요.", "figure": "이삿짐 상자들 옆에서 친구 둘이 손을 흔드는 모습"}, {"heading": "마음을 나타내는 말을 알아 두어요", "paras": ["짐작한 마음을 말할 때 ‘좋다’, ‘나쁘다’만 쓰지 말고 알맞은 낱말을 골라 써 보세요. 마음을 더 정확하게 나타낼 수 있어요.", "기분 좋은 마음, 기분이 좋지 않은 마음을 나타내는 말이 아주 많아요."], "example": "기분 좋은 마음: 기쁘다, 설레다, 뿌듯하다, 반갑다, 고맙다\n기분이 좋지 않은 마음: 속상하다, 서운하다, 억울하다, 걱정스럽다, 부끄럽다", "figure": "웃는 얼굴과 우는 얼굴이 그려진 감정 카드 여러 장이 펼쳐진 책상"}, {"heading": "인물의 마음은 바뀌기도 해요", "paras": ["이야기가 흘러가면서 인물의 마음이 바뀌기도 해요. 처음, 가운데, 끝에서 인물의 마음이 어떻게 달라지는지 따라가 보세요.", "마음이 바뀐 까닭을 찾으면 이야기를 더 깊이 이해할 수 있어요."], "example": "처음: 발표 순서를 기다리며 가슴이 두근거렸어요(떨림). → 끝: 발표를 마치자 친구들이 손뼉을 쳐 주었어요(뿌듯함).", "figure": "교실 앞에서 발표를 마치고 웃는 아이와 손뼉 치는 친구들의 손"}], "keywords": [{"word": "인물", "meaning": "이야기에 나와서 말하고 행동하는 사람이나 동물"}, {"word": "짐작", "meaning": "사정이나 형편을 어림잡아 헤아림"}, {"word": "서운하다", "meaning": "기대하던 대로 되지 않아 마음이 섭섭하다"}, {"word": "뿌듯하다", "meaning": "기쁨이나 자랑스러움이 마음에 가득하다"}, {"word": "억울하다", "meaning": "잘못한 것 없이 꾸중을 듣거나 피해를 입어 속상하다"}], "expressions": [], "quiz": [{"q": "인물의 마음을 짐작하는 방법으로 알맞지 __않은__ 것은?", "choices": ["인물의 말을 살핀다", "인물의 행동과 표정을 살핀다", "인물이 처한 상황을 생각한다", "인물의 옷 색깔만 본다"], "answer": 3, "explain": "옷 색깔만으로는 마음을 알기 어려워요. 말, 행동, 표정, 상황을 살펴요."}, {"q": "“와, 내가 갖고 싶던 거야!” 하나는 선물 상자를 끌어안고 폴짝폴짝 뛰었어요. 하나의 마음은?", "choices": ["기쁘다", "억울하다", "걱정스럽다", "서운하다"], "answer": 0, "explain": "갖고 싶던 선물을 받고 폴짝폴짝 뛰는 행동에서 기쁜 마음을 알 수 있어요."}, {"q": "동생이 꽃병을 깼는데 엄마께서 나를 꾸중하셨어요. 이때 나의 마음으로 알맞은 것은?", "choices": ["뿌듯하다", "반갑다", "억울하다", "설레다"], "answer": 2, "explain": "잘못하지 않았는데 꾸중을 들었으니 억울한 마음이 들어요."}, {"q": "“내일 드디어 처음으로 바다에 가!” 민호는 밤늦게까지 잠을 이루지 못했어요. 민호의 마음은?", "choices": ["부끄럽다", "설레다", "속상하다", "미안하다"], "answer": 1, "explain": "기대되는 일을 앞두고 잠을 못 이루는 것은 설레는 마음이에요."}], "summary": ["인물의 마음은 말, 행동, 표정에 드러나요.", "인물이 처한 상황을 살피고 ‘나라면 어떨까?’ 생각하면 마음을 짐작하기 쉬워요.", "기쁘다, 서운하다, 뿌듯하다처럼 알맞은 말로 마음을 나타내고, 마음의 변화도 따라가 봐요."], "parent_tip": "책을 읽어 준 뒤 “이때 주인공은 어떤 마음이었을까? 왜 그렇게 생각해?”라고 근거를 함께 물어봐 주세요. 아이가 ‘좋았어, 나빴어’로만 답하면 감정 낱말(서운하다, 억울하다, 뿌듯하다 등)을 하나씩 알려 주시면 표현이 풍부해집니다. 아이 자신의 하루를 이야기할 때도 감정 낱말을 쓰도록 이끌면 공감 능력도 함께 자랍니다."}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','인물의 마음 짐작하기',9,'k3-09' where not exists (select 1 from public.topics where lesson_slug='k3-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k3-10','3~4','국어','시의 감각적 표현','시를 읽으면 왜 소리가 들리고 냄새가 날까?','assets/img/l_k3-10.jpg',$j${"intro": "시를 읽다 보면 눈앞에 장면이 그려지고, 소리가 들리는 것 같고, 냄새까지 나는 것 같을 때가 있어요. 그 비밀은 바로 ‘감각적 표현’에 있어요.", "sections": [{"heading": "우리 몸의 다섯 가지 감각", "paras": ["우리는 눈으로 보고, 귀로 듣고, 코로 냄새를 맡고, 혀로 맛을 보고, 피부로 만져서 느껴요. 이 다섯 가지를 감각이라고 해요.", "각각 보는 감각(시각), 듣는 감각(청각), 냄새 맡는 감각(후각), 맛보는 감각(미각), 만지는 감각(촉각)이라고 불러요."], "example": "👀 눈 - 빨간 단풍잎 / 👂 귀 - 졸졸 흐르는 시냇물 / 👃 코 - 고소한 빵 냄새 / 👅 혀 - 새콤한 귤 / ✋ 피부 - 보들보들한 강아지 털", "figure": "책상 위에 귤, 솔방울, 작은 종, 털실 뭉치, 빨간 단풍잎이 나란히 놓인 모습"}, {"heading": "감각적 표현이란?", "paras": ["보고, 듣고, 냄새 맡고, 맛보고, 만진 느낌을 생생하게 나타낸 표현을 ‘감각적 표현’이라고 해요.", "“눈이 왔다.”보다 “하얀 눈이 사뿐사뿐 내려와 볼에 닿으니 차가웠다.”라고 쓰면 읽는 사람도 그 장면을 함께 느낄 수 있어요."], "example": "밋밋한 표현: 바람이 분다. → 감각적 표현: 시원한 바람이 살랑살랑 내 볼을 간질인다.", "figure": "창가에서 커튼이 바람에 살짝 날리는 모습"}, {"heading": "흉내 내는 말이 감각을 살려요", "paras": ["‘졸졸’, ‘쨍그랑’처럼 소리를 흉내 내는 말은 귀로 듣는 듯한 느낌을 줘요. ‘반짝반짝’, ‘살금살금’처럼 모양이나 움직임을 흉내 내는 말은 눈앞에 그려지는 느낌을 줘요.", "시인들은 이런 말을 써서 짧은 글에도 생생한 느낌을 담아요."], "example": "소리를 흉내 내는 말: 졸졸, 똑똑, 멍멍, 바스락 / 모양을 흉내 내는 말: 반짝반짝, 뒤뚱뒤뚱, 몽글몽글, 살금살금", "figure": "낙엽 더미 위를 걷는 작은 장화"}, {"heading": "시에서 감각적 표현 찾기", "paras": ["시를 읽을 때 ‘이 표현은 어떤 감각으로 느낀 걸까?’ 하고 생각해 보세요. 눈, 귀, 코, 혀, 피부 가운데 어디로 느낀 것인지 찾으면 시를 더 깊이 즐길 수 있어요.", "아래 시에서 ‘톡톡톡’은 귀로, ‘촉촉한 흙냄새’는 코로, ‘연둣빛 새싹’은 눈으로 느낀 표현이에요."], "example": "봄비\n톡톡톡\n창문을 두드리는 봄비\n\n촉촉한 흙냄새가\n코끝에 살금살금\n\n연둣빛 새싹이\n고개를 쏙 내밀어요", "figure": "빗방울이 맺힌 유리창 너머로 화분의 작은 새싹이 보이는 모습"}], "keywords": [{"word": "감각", "meaning": "눈, 귀, 코, 혀, 피부로 바깥의 자극을 느끼는 것"}, {"word": "감각적 표현", "meaning": "보고, 듣고, 냄새 맡고, 맛보고, 만진 느낌을 생생하게 나타낸 표현"}, {"word": "흉내 내는 말", "meaning": "소리나 모양, 움직임을 흉내 낸 말 (예: 졸졸, 반짝반짝)"}, {"word": "시", "meaning": "느낌이나 생각을 짧은 말로 운율 있게 나타낸 글"}], "expressions": [], "quiz": [{"q": "“졸졸 흐르는 시냇물”은 어떤 감각으로 느낀 표현일까요?", "choices": ["눈으로 보는 감각", "귀로 듣는 감각", "코로 냄새 맡는 감각", "혀로 맛보는 감각"], "answer": 1, "explain": "‘졸졸’은 물이 흐르는 소리를 흉내 낸 말이라 귀로 듣는 감각이에요."}, {"q": "피부로 만져서 느낀 감각적 표현은?", "choices": ["새콤달콤한 딸기", "고소한 참기름 냄새", "보들보들한 아기 볼", "노랗게 핀 개나리"], "answer": 2, "explain": "‘보들보들한’은 손으로 만졌을 때의 느낌이에요."}, {"q": "감각적 표현을 쓰면 좋은 점은?", "choices": ["읽는 사람이 장면을 생생하게 느낄 수 있다", "글이 더 짧아진다", "맞춤법을 틀리지 않는다", "글의 제목이 생긴다"], "answer": 0, "explain": "감각적 표현을 쓰면 읽는 사람도 보고 듣고 만지는 것처럼 느낄 수 있어요."}, {"q": "모양이나 움직임을 흉내 내는 말은?", "choices": ["멍멍", "쨍그랑", "똑똑", "뒤뚱뒤뚱"], "answer": 3, "explain": "‘뒤뚱뒤뚱’은 걷는 모양을 흉내 낸 말이에요. 나머지는 소리를 흉내 낸 말이에요."}, {"q": "“구수한 된장찌개 냄새가 부엌에 가득해요.”에 쓰인 감각은?", "choices": ["듣는 감각", "만지는 감각", "냄새 맡는 감각", "보는 감각"], "answer": 2, "explain": "‘냄새가 가득해요’는 코로 냄새를 맡은 감각적 표현이에요."}], "summary": ["우리 몸에는 보고, 듣고, 냄새 맡고, 맛보고, 만지는 다섯 가지 감각이 있어요.", "감각으로 느낀 것을 생생하게 나타낸 표현을 감각적 표현이라고 해요.", "소리나 모양을 흉내 내는 말은 시를 더 생생하게 만들어요."], "parent_tip": "산책하거나 밥을 먹을 때 “지금 무슨 소리가 들려? 어떤 냄새가 나? 만져 보니 어때?”라고 다섯 감각을 하나씩 물어봐 주세요. 아이가 말한 표현을 모아 짧은 시를 함께 지어 보면 감각적 표현을 자연스럽게 익힐 수 있습니다. 같은 대상도 감각에 따라 다르게 표현할 수 있다는 점을 알려 주시면 좋습니다."}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '3~4','국어','시의 감각적 표현',10,'k3-10' where not exists (select 1 from public.topics where lesson_slug='k3-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-01','5~6','국어','비유하는 표현','"구름이 솜사탕 같아"라고 말하면 왜 더 잘 보일까?','assets/img/l_k5-01.jpg',$j${"intro": "하늘에 뜬 흰 구름을 보고 \"솜사탕 같다!\"라고 말해 본 적 있나요? 그냥 \"구름이 하얗다\"보다 훨씬 생생하게 느껴지지요. 이렇게 어떤 것을 다른 것에 빗대어 나타내는 방법을 '비유하는 표현'이라고 해요.", "sections": [{"heading": "비유는 '닮은 점'을 찾아 빗대는 것이에요", "paras": ["비유하는 표현은 나타내고 싶은 대상을 그것과 비슷한 점이 있는 다른 대상에 빗대어 표현하는 방법이에요.", "이때 표현하려는 대상과 빗대는 대상 사이에는 반드시 '닮은 점(공통점)'이 있어야 해요. 구름과 솜사탕은 둘 다 하얗고 폭신폭신해 보인다는 닮은 점이 있지요.", "닮은 점이 없는 것끼리 빗대면 읽는 사람이 무슨 뜻인지 알 수 없어요. 그래서 비유를 만들 때는 먼저 대상을 자세히 살펴보는 것이 중요해요."], "example": "구름(표현하려는 대상) → 솜사탕(빗대는 대상) / 닮은 점: 하얗고 폭신폭신해 보인다", "figure": "파란 하늘에 떠 있는 하얀 뭉게구름과, 그 옆에 놓인 비슷한 모양의 솜사탕을 나란히 보여 주는 그림"}, {"heading": "'~처럼', '~같이'를 쓰는 직유법", "paras": ["'~처럼', '~같이', '~같은', '~듯이'와 같은 말을 써서 두 대상을 직접 이어 주는 비유를 직유법이라고 해요.", "직유법은 '무엇을 무엇에 빗댔는지'가 문장에 그대로 드러나서 알아보기 쉬워요."], "example": "동생의 볼이 잘 익은 복숭아처럼 발그레하다. / 운동장에 쌓인 눈이 하얀 이불같이 덮여 있다. / 시냇물이 노래하듯이 졸졸 흐른다.", "figure": "발그레한 볼을 가진 아이 얼굴 옆에 복숭아가 놓여 있는 그림"}, {"heading": "'A는 B이다'로 말하는 은유법", "paras": ["'~처럼', '~같이' 같은 말 없이 'A는 B이다'처럼 두 대상을 바로 같은 것으로 말하는 비유를 은유법이라고 해요.", "은유법은 직유법보다 더 짧고 힘 있게 느껴져요. 읽는 사람이 둘 사이의 닮은 점을 스스로 떠올리게 하지요.", "\"내 마음은 호수예요\"라는 문장에서 마음과 호수의 닮은 점은 '넓고 고요하다'는 점이에요."], "example": "할머니의 손은 따뜻한 난로이다. / 도서관은 이야기가 가득한 보물 창고이다. / 우리 반은 한 그루의 커다란 나무다.", "figure": "책장이 가득한 도서관이 반짝이는 보물 상자처럼 보이는 상상 그림"}, {"heading": "시 속에서 비유하는 표현 찾기", "paras": ["시에는 비유하는 표현이 많이 쓰여요. 비유를 찾으면 시인이 대상을 어떻게 느꼈는지 더 잘 알 수 있어요.", "아래 시를 읽고 무엇을 무엇에 빗댔는지, 닮은 점은 무엇인지 생각해 보세요.", "비유를 찾을 때는 ① 표현하려는 대상 ② 빗대는 대상 ③ 닮은 점, 이 세 가지를 차례로 찾으면 쉬워요."], "example": "〈가을 운동장〉\n노란 은행잎이 / 나비처럼 팔랑팔랑 내려앉는다.\n운동장은 / 노랗게 물든 커다란 도화지.\n바람은 장난꾸러기 / 낙엽을 이리저리 몰고 다닌다.\n→ 은행잎을 나비에 빗댐(직유, 가볍게 날리는 모습) / 운동장을 도화지에 빗댐(은유, 넓고 색이 칠해진 모습) / 바람을 장난꾸러기에 빗댐(은유, 이리저리 움직이게 하는 모습)", "figure": "노란 은행잎이 흩날리는 학교 운동장 풍경"}, {"heading": "나만의 비유하는 표현 만들기", "paras": ["비유를 직접 만들어 보면 글이 훨씬 생생해져요. 먼저 표현하고 싶은 대상을 정하고, 그 대상의 모양·색깔·소리·느낌을 떠올려 보세요.", "그다음 그 특징과 닮은 다른 대상을 찾아 '~처럼'을 붙이면 직유법, 'A는 B이다'로 쓰면 은유법이 돼요.", "다른 사람이 쓰지 않은 새로운 비유를 찾으면 더 재미있는 글이 돼요."], "example": "대상: 아침 알람 소리 → 특징: 시끄럽고 갑작스럽다 → 직유: 알람 소리가 천둥처럼 울렸다. / 은유: 알람 소리는 아침을 깨우는 북소리다.", "figure": "책상 위 공책에 연필로 생각 그물을 그려 비유를 만드는 아이의 손"}], "keywords": [{"word": "비유하는 표현", "meaning": "나타내려는 대상을 닮은 점이 있는 다른 대상에 빗대어 표현하는 방법"}, {"word": "직유법", "meaning": "'~처럼', '~같이', '~듯이' 같은 말로 두 대상을 직접 이어 빗대는 방법"}, {"word": "은유법", "meaning": "'A는 B이다'처럼 연결하는 말 없이 두 대상을 같은 것으로 빗대는 방법"}, {"word": "닮은 점(공통점)", "meaning": "표현하려는 대상과 빗대는 대상이 서로 비슷한 점"}, {"word": "빗대다", "meaning": "어떤 것을 직접 말하지 않고 비슷한 다른 것에 견주어 말하다"}], "expressions": [], "quiz": [{"q": "다음 중 직유법이 쓰인 문장은 무엇일까요?", "choices": ["내 동생은 우리 집 비타민이다.", "별들이 보석처럼 반짝인다.", "교실이 아주 조용하다.", "엄마는 우리 집 해님이다."], "answer": 1, "explain": "'보석처럼'에 '~처럼'이 쓰여 별을 보석에 직접 빗대었으므로 직유법이에요."}, {"q": "\"시간은 화살이다.\"에서 시간과 화살의 닮은 점으로 알맞은 것은?", "choices": ["뾰족하다", "무겁다", "빠르게 지나간다", "나무로 만든다"], "answer": 2, "explain": "화살이 빠르게 날아가듯 시간도 빠르게 지나간다는 닮은 점으로 빗댄 은유법이에요."}, {"q": "은유법에 대한 설명으로 알맞은 것은?", "choices": ["'A는 B이다'처럼 두 대상을 바로 같은 것으로 말한다.", "반드시 '~처럼'을 쓴다.", "닮은 점이 없어도 된다.", "소리를 흉내 내는 말이다."], "answer": 0, "explain": "은유법은 연결하는 말 없이 'A는 B이다' 꼴로 빗대는 방법이에요."}, {"q": "비유하는 표현을 만들 때 가장 먼저 생각해야 할 것은?", "choices": ["글자 수를 맞추는 것", "어려운 낱말을 쓰는 것", "문장을 길게 쓰는 것", "대상의 특징과 닮은 점을 찾는 것"], "answer": 3, "explain": "두 대상 사이에 닮은 점이 있어야 비유가 이해돼요."}], "summary": ["비유하는 표현은 대상을 닮은 점이 있는 다른 대상에 빗대어 생생하게 나타내는 방법이에요.", "'~처럼', '~같이', '~듯이'를 쓰면 직유법, 'A는 B이다'로 쓰면 은유법이에요.", "비유를 찾을 때는 표현하려는 대상, 빗대는 대상, 닮은 점을 차례로 찾아요."], "parent_tip": "아이들은 '~처럼'만 보면 무조건 비유라고 생각하거나, 은유법에서 닮은 점을 설명하지 못하는 경우가 많습니다. 산책이나 식사 중에 \"저 구름은 무엇을 닮았을까?\", \"아빠의 목소리를 무엇에 빗댈 수 있을까? 왜 그렇게 생각해?\"처럼 닮은 점의 이유까지 말하게 해 보세요. 직유를 은유로, 은유를 직유로 바꿔 말해 보는 놀이도 도움이 됩니다."}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','비유하는 표현',1,'k5-01' where not exists (select 1 from public.topics where lesson_slug='k5-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-02','5~6','국어','글의 구조와 요약','긴 글을 짧게 정리하는 비법은 무엇일까?','assets/img/l_k5-02.jpg',$j${"intro": "설명하는 글을 다 읽었는데 친구가 \"무슨 내용이야?\" 하고 물으면 말문이 막힐 때가 있지요. 글이 어떤 짜임(구조)으로 쓰였는지 알면 긴 글도 몇 문장으로 쏙쏙 정리할 수 있어요.", "sections": [{"heading": "글의 구조란 무엇일까요?", "paras": ["글의 구조는 글쓴이가 내용을 어떤 순서와 방법으로 짜 놓았는지를 말해요. 집에 뼈대가 있듯이 글에도 뼈대가 있어요.", "설명하는 글에서 자주 쓰는 구조에는 '나열', '순서(시간)', '비교와 대조', '원인과 결과', '문제와 해결'이 있어요.", "글의 구조를 알면 중요한 내용이 어디에 있는지 쉽게 찾을 수 있어서 요약하기가 훨씬 편해져요."], "example": "", "figure": "집의 뼈대(기둥과 보) 그림 옆에 글의 문단들이 뼈대처럼 이어져 있는 도식"}, {"heading": "구조마다 자주 나오는 말이 있어요", "paras": ["나열 구조는 여러 가지 내용을 하나씩 늘어놓아요. '첫째, 둘째', '또한', '그리고' 같은 말이 자주 나와요.", "순서 구조는 시간이나 과정의 차례대로 써요. '먼저', '다음으로', '마지막으로', '처음에는' 같은 말이 나와요.", "비교와 대조 구조는 두 대상의 같은 점(비교)과 다른 점(대조)을 써요. '둘 다', '마찬가지로', '이와 달리', '반면에' 같은 말이 나와요.", "원인과 결과 구조는 어떤 일이 일어난 까닭과 그 결과를 써요. '왜냐하면', '그래서', '그 결과', '때문에' 같은 말이 나와요. 문제와 해결 구조는 문제 상황을 밝히고 해결 방법을 제시해요."], "example": "비교와 대조의 예: 고양이와 개는 둘 다 사람과 함께 사는 반려동물이다. 반면에 고양이는 혼자 있는 시간을 즐기고, 개는 주인과 함께 움직이기를 좋아한다.", "figure": "다섯 가지 글 구조(나열, 순서, 비교·대조, 원인·결과, 문제·해결)를 각각 간단한 도형 틀로 나타낸 표"}, {"heading": "구조에 알맞은 틀로 정리해요", "paras": ["글의 구조를 파악했으면 그 구조에 어울리는 틀(그림 틀)에 내용을 옮겨 적어 보세요.", "비교와 대조는 두 원이 겹친 벤 다이어그램이나 두 칸 표, 순서는 화살표로 이어진 칸, 원인과 결과는 '원인 → 결과' 화살표 틀이 알맞아요.", "틀에 정리하면 중요한 내용과 덜 중요한 내용이 한눈에 구분돼요."], "example": "〈글〉 갯벌에는 많은 생물이 산다. 그런데 갯벌을 메워 땅을 만드는 일이 늘어났다. 그 결과 갯벌에 사는 게와 조개가 살 곳을 잃었고, 이들을 먹고 사는 철새도 줄어들었다.\n〈틀〉 원인: 갯벌을 메워 땅을 만듦 → 결과: 게·조개가 살 곳을 잃음 → 철새도 줄어듦", "figure": "갯벌 사진 아래 '원인 → 결과' 화살표 틀이 그려진 공책"}, {"heading": "요약하는 방법: 지우고, 묶고, 고르기", "paras": ["요약은 글의 중요한 내용을 간추려 짧게 정리하는 것이에요. 요약할 때는 다음 방법을 써요.", "① 중요하지 않은 내용(자세한 예, 되풀이되는 말)은 지워요. ② 비슷한 내용은 더 큰 말로 묶어요. 예를 들어 '사과, 배, 감'은 '과일'로 묶을 수 있어요. ③ 문단마다 중심 문장을 골라요. 중심 문장이 없으면 중심 내용을 직접 만들어요.", "마지막으로 글의 구조가 드러나도록 문단의 중심 내용을 이어서 한두 문장으로 써요."], "example": "〈원래 문장〉 운동장에는 축구공, 농구공, 배구공, 줄넘기가 흩어져 있었다.\n〈묶어서 요약〉 운동장에 운동 기구가 흩어져 있었다.", "figure": "글에 연필로 줄을 긋고 동그라미를 친 공책 페이지"}, {"heading": "직접 요약해 봐요", "paras": ["아래 글은 순서 구조로 쓰였어요. '먼저, 다음으로, 마지막으로'를 찾아 과정을 정리한 다음 요약해 보세요.", "요약문에는 글쓴이의 생각을 바꾸거나 내 생각을 덧붙이지 않아요. 원래 글의 뜻을 그대로 짧게 나타내야 해요."], "example": "〈글〉 종이를 다시 쓸 수 있게 만드는 과정은 다음과 같다. 먼저 모은 헌 종이를 물에 불려 죽처럼 만든다. 다음으로 종이 죽에서 잉크와 이물질을 걸러 낸다. 그다음 깨끗해진 종이 죽을 얇게 펴서 눌러 물기를 뺀다. 마지막으로 뜨거운 열로 말리면 새 종이가 된다.\n〈요약〉 헌 종이는 물에 불려 종이 죽으로 만들고, 잉크와 이물질을 걸러 낸 뒤, 얇게 펴서 물기를 빼고 말리면 새 종이가 된다.", "figure": "헌 종이 → 종이 죽 → 거르기 → 펴서 누르기 → 말리기 과정을 화살표로 이은 그림"}], "keywords": [{"word": "글의 구조", "meaning": "글쓴이가 내용을 짜 놓은 방법이나 뼈대"}, {"word": "나열", "meaning": "여러 가지 내용을 하나씩 늘어놓는 구조"}, {"word": "비교와 대조", "meaning": "두 대상의 같은 점(비교)과 다른 점(대조)을 밝히는 구조"}, {"word": "원인과 결과", "meaning": "어떤 일이 일어난 까닭과 그로 인해 생긴 일을 밝히는 구조"}, {"word": "요약", "meaning": "글의 중요한 내용을 간추려 짧게 정리하는 것"}, {"word": "중심 문장", "meaning": "한 문단에서 가장 중요한 내용을 담은 문장"}], "expressions": [], "quiz": [{"q": "'반면에', '이와 달리' 같은 말이 자주 나오는 글의 구조는?", "choices": ["순서", "비교와 대조", "나열", "문제와 해결"], "answer": 1, "explain": "두 대상의 다른 점을 말할 때 '반면에', '이와 달리'를 써요."}, {"q": "'그래서', '그 결과'가 자주 나오는 구조에 알맞은 정리 틀은?", "choices": ["벤 다이어그램", "원인 → 결과 화살표 틀", "두 칸 비교표", "마인드맵의 가지 하나"], "answer": 1, "explain": "'그래서', '그 결과'는 원인과 결과 구조에 쓰이므로 원인 → 결과 틀이 알맞아요."}, {"q": "요약하는 방법으로 알맞지 __않은__ 것은?", "choices": ["자세한 예는 지운다.", "비슷한 내용은 더 큰 말로 묶는다.", "내 생각을 덧붙여 더 재미있게 쓴다.", "문단의 중심 문장을 고른다."], "answer": 2, "explain": "요약문에는 원래 글의 내용만 간추려 쓰고 내 생각은 덧붙이지 않아요."}, {"q": "'연필, 지우개, 자, 공책'을 하나로 묶을 때 가장 알맞은 말은?", "choices": ["학용품", "장난감", "음식", "옷"], "answer": 0, "explain": "모두 공부할 때 쓰는 물건이므로 '학용품'으로 묶을 수 있어요."}, {"q": "'먼저 – 다음으로 – 마지막으로'가 나오는 글은 어떤 구조일까요?", "choices": ["비교와 대조", "원인과 결과", "문제와 해결", "순서(시간)"], "answer": 3, "explain": "일이나 과정의 차례를 나타내는 말이므로 순서 구조예요."}], "summary": ["설명하는 글의 구조에는 나열, 순서, 비교와 대조, 원인과 결과, 문제와 해결이 있어요.", "구조를 알려 주는 말을 찾고, 구조에 알맞은 틀에 내용을 정리해요.", "요약은 중요하지 않은 내용은 지우고, 비슷한 것은 묶고, 중심 내용을 골라 짧게 쓰는 것이에요."], "parent_tip": "아이들은 요약을 '앞부분만 옮겨 적기'나 '마음에 드는 문장 고르기'로 오해하기 쉽습니다. 신문 기사나 책의 한 단락을 함께 읽고 \"이 글은 무엇과 무엇을 비교했니?\", \"세 문장으로 줄이면 어떻게 될까?\"라고 물어보세요. 구조를 알려 주는 말(반면에, 그 결과, 먼저 등)에 동그라미를 치는 습관을 들이면 좋습니다."}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','글의 구조와 요약',2,'k5-02' where not exists (select 1 from public.topics where lesson_slug='k5-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-03','5~6','국어','사실과 의견 구별하기','"떡볶이는 맛있다"는 사실일까, 의견일까?','assets/img/l_k5-03.jpg',$j${"intro": "\"우리 학교 급식에 떡볶이가 나왔다.\"와 \"떡볶이는 세상에서 제일 맛있는 음식이다.\"는 무엇이 다를까요? 하나는 누구나 확인할 수 있는 일이고, 다른 하나는 사람마다 생각이 다를 수 있는 말이에요. 오늘은 이 둘을 구별하는 방법을 배워요.", "sections": [{"heading": "사실은 '확인할 수 있는 일'이에요", "paras": ["사실은 실제로 있었던 일이나 지금 있는 일로, 누구나 조사하거나 확인해 볼 수 있는 내용이에요.", "사실은 맞는지 틀리는지 따져 볼 수 있어요. 예를 들어 \"한라산은 제주도에 있다.\"는 지도나 백과사전으로 확인할 수 있지요.", "숫자, 날짜, 장소, 조사 결과처럼 정확한 정보가 들어 있는 문장은 사실일 때가 많아요."], "example": "우리 반 학생은 모두 24명이다. / 물은 100℃에서 끓는다. / 어제 우리 동네에 비가 내렸다.", "figure": "백과사전과 지도, 온도계를 펼쳐 놓고 정보를 확인하는 장면"}, {"heading": "의견은 '나의 생각이나 느낌'이에요", "paras": ["의견은 어떤 대상이나 일에 대해 글쓴이나 말하는 사람이 가진 생각이나 느낌이에요.", "의견은 사람마다 다를 수 있어서 '맞다, 틀리다'로 확인할 수 없어요. 대신 '타당하다(알맞다), 타당하지 않다'로 판단해요.", "'~해야 한다', '~라고 생각한다', '~것 같다', '아름답다', '가장 좋다'처럼 생각이나 판단, 느낌을 나타내는 말이 들어가면 의견일 때가 많아요."], "example": "한라산은 우리나라에서 가장 아름다운 산이다. / 학교 도서관을 주말에도 열어야 한다. / 이 영화는 정말 감동적이다.", "figure": "말풍선 안에 하트와 물음표가 그려져 있고 아이가 생각에 잠긴 모습"}, {"heading": "글에서 사실과 의견을 구별해 봐요", "paras": ["논설문, 신문 기사, 광고 같은 글에는 사실과 의견이 함께 섞여 있어요.", "문장마다 '이것은 확인할 수 있는 내용인가?', '이것은 누군가의 생각인가?'를 스스로 물어보면 구별할 수 있어요."], "example": "〈글〉 ① 우리 마을 공원에는 놀이 기구가 다섯 개 있다. ② 그중 미끄럼틀은 10년 전에 설치되었다. ③ 미끄럼틀이 너무 낡아서 보기에 좋지 않다. ④ 구청은 미끄럼틀을 새것으로 바꿔야 한다.\n→ 사실: ①, ② (세어 보거나 기록으로 확인할 수 있음) / 의견: ③, ④ (글쓴이의 느낌과 주장)", "figure": "공원의 오래된 미끄럼틀과 다른 놀이 기구들이 있는 풍경"}, {"heading": "의견이 타당한지 판단해요", "paras": ["의견은 사람마다 다르지만, 모든 의견이 똑같이 설득력 있는 것은 아니에요. 좋은 의견에는 믿을 만한 사실이 근거로 함께 있어요.", "의견이 타당한지 판단하려면 ① 근거가 사실인가 ② 근거가 의견과 관련이 있는가 ③ 의견이 많은 사람에게 도움이 되는가를 살펴봐요.", "근거 없이 \"그냥 그래야 한다\"고만 말하는 의견은 다른 사람을 설득하기 어려워요."], "example": "타당한 의견: 학교 앞에 신호등을 설치해야 한다. 지난해 학교 앞에서 교통사고가 세 번 일어났기 때문이다.\n타당하지 않은 의견: 학교 앞에 신호등을 설치해야 한다. 신호등 색깔이 예쁘기 때문이다.", "figure": "학교 앞 횡단보도에 신호등이 서 있고 아이들이 안전하게 건너는 모습"}, {"heading": "왜 구별할 줄 알아야 할까요?", "paras": ["광고나 인터넷 글에는 의견을 마치 사실인 것처럼 쓴 경우가 있어요. \"누구나 좋아하는 최고의 과자\"는 사실이 아니라 광고하는 사람의 의견이에요.", "사실과 의견을 구별하면 글을 비판하며 읽을 수 있고, 잘못된 정보에 쉽게 속지 않아요. 또 내가 글을 쓸 때도 의견에 알맞은 사실 근거를 붙여 더 설득력 있게 쓸 수 있어요."], "example": "광고 문장: \"이 운동화는 하루에 1,000켤레가 팔렸습니다.(사실인지 확인 필요) 신기만 하면 누구나 달리기가 빨라집니다.(근거 없는 의견)\"", "figure": "운동화 광고지를 손에 들고 돋보기로 꼼꼼히 살펴보는 아이"}], "keywords": [{"word": "사실", "meaning": "실제로 있었거나 지금 있는 일로, 누구나 확인할 수 있는 내용"}, {"word": "의견", "meaning": "어떤 대상이나 일에 대한 사람의 생각이나 느낌"}, {"word": "근거", "meaning": "의견이 옳다고 뒷받침해 주는 까닭이나 자료"}, {"word": "타당하다", "meaning": "이치에 맞아 옳고 알맞다"}, {"word": "비판하며 읽기", "meaning": "글의 내용이 옳은지, 믿을 만한지 따져 가며 읽는 것"}], "expressions": [], "quiz": [{"q": "다음 중 사실인 문장은?", "choices": ["봄은 가장 좋은 계절이다.", "우리 학교는 1985년에 세워졌다.", "수학은 너무 어렵다.", "급식 시간이 더 길어야 한다."], "answer": 1, "explain": "학교가 세워진 해는 기록으로 확인할 수 있는 사실이에요."}, {"q": "다음 중 의견인 문장은?", "choices": ["서울은 우리나라의 수도이다.", "고래는 바다에 산다.", "강아지는 고양이보다 키우기 좋은 동물이다.", "일주일은 7일이다."], "answer": 2, "explain": "어떤 동물이 키우기 좋은지는 사람마다 생각이 다를 수 있으므로 의견이에요."}, {"q": "의견을 판단할 때 알맞은 기준은?", "choices": ["맞다, 틀리다", "길다, 짧다", "크다, 작다", "타당하다, 타당하지 않다"], "answer": 3, "explain": "의견은 확인으로 맞고 틀림을 가릴 수 없으므로 타당한지를 따져요."}, {"q": "\"공원에 쓰레기통을 더 놓아야 한다.\"는 의견의 근거로 가장 알맞은 것은?", "choices": ["지난달 공원 바닥에서 주운 쓰레기가 200봉지였다.", "쓰레기통은 초록색이 예쁘다.", "나는 공원을 좋아한다.", "공원은 넓다."], "answer": 0, "explain": "쓰레기가 많이 버려진다는 사실이 쓰레기통을 늘려야 하는 까닭과 바로 이어져요."}], "summary": ["사실은 실제로 있었던 일로 누구나 확인할 수 있고, 의견은 사람의 생각이나 느낌이에요.", "'~해야 한다', '~라고 생각한다', '가장 ~하다' 같은 말은 의견을 나타낼 때가 많아요.", "타당한 의견에는 믿을 만한 사실 근거가 함께 있어야 해요."], "parent_tip": "아이들은 '내가 확실히 믿는 것'을 사실로 착각하는 경우가 많습니다(예: \"피자가 제일 맛있다\"). \"그 말을 누구나 똑같이 확인할 수 있을까?\"라고 되물어 주세요. 함께 광고나 뉴스 기사를 보며 사실 문장과 의견 문장에 서로 다른 색으로 줄을 그어 보는 활동이 효과적입니다."}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','사실과 의견 구별하기',3,'k5-03' where not exists (select 1 from public.topics where lesson_slug='k5-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-04','5~6','국어','토론하기','생각이 다를 때, 싸우지 않고 결정하는 방법은?','assets/img/l_k5-04.jpg',$j${"intro": "\"교실에서 반려 식물을 키워야 할까?\" 반 친구들 생각이 둘로 나뉘었어요. 목소리 큰 사람이 이기는 게 아니라, 근거를 들어 차례대로 말하고 듣는 방법이 있어요. 바로 '토론'이에요.", "sections": [{"heading": "토론은 찬성과 반대로 나뉘어 말하는 것이에요", "paras": ["토론은 어떤 문제에 대해 찬성편과 반대편이 각각 근거를 들어 자기 주장이 옳다고 말하며 상대를 설득하는 말하기예요.", "여러 사람이 생각을 모아 좋은 방법을 찾는 '토의'와 달리, 토론은 찬성과 반대 가운데 어느 주장이 더 타당한지 따져 보는 것이에요.", "토론을 하면 한 가지 문제를 여러 쪽에서 생각해 볼 수 있고, 근거를 들어 말하는 힘이 길러져요."], "example": "토의: \"학급 문고를 어떻게 꾸밀까?\"(여러 의견을 모음) / 토론: \"학급 문고에 만화책을 두어야 한다.\"(찬성과 반대로 나뉨)", "figure": "교실 책상이 양쪽으로 마주 보게 놓이고 가운데에 사회자 자리가 있는 토론 모습"}, {"heading": "논제는 찬반이 나뉘는 한 가지 주장으로", "paras": ["토론에서 이야기할 주제를 '논제'라고 해요. 논제는 찬성과 반대로 의견이 뚜렷하게 나뉘어야 해요.", "논제는 한 가지 내용만 담아 '~해야 한다.' 꼴의 긍정문으로 써요. 누구나 알 수 있는 쉬운 말로 쓰고, 어느 한쪽 편을 드는 말은 넣지 않아요.", "\"수학이 어려울까?\"처럼 사실을 묻거나, \"점심 메뉴는 무엇이 좋을까?\"처럼 답이 여러 개인 것은 토론 논제로 알맞지 않아요."], "example": "알맞은 논제: 초등학생도 학교에서 휴대 전화를 쓸 수 있어야 한다.\n알맞지 않은 논제: 나쁜 게임은 금지하고 숙제는 줄여야 한다.(두 가지 내용이 섞이고 '나쁜'이라는 편드는 말이 들어감)", "figure": "칠판에 '~해야 한다.'로 끝나는 논제가 적혀 있고 그 아래 찬성·반대 칸이 나뉜 모습"}, {"heading": "토론의 절차를 알아봐요", "paras": ["토론은 정해진 차례에 따라 진행해요. 초등학교에서는 보통 '주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기'의 차례로 해요.", "① 주장 펼치기: 찬성편과 반대편이 차례로 자기 주장과 근거를 말해요. ② 반론하기: 상대편 근거의 문제점을 짚고 질문하거나 반박해요. ③ 주장 다지기: 반론을 듣고 자기편 주장을 한 번 더 정리해 강조해요. ④ 판정하기: 판정단이 어느 편이 더 설득력 있었는지 정해요.", "토론에는 토론을 이끄는 사회자, 주장을 펴는 토론자(찬성편·반대편), 결과를 판단하는 판정단이 있어요."], "example": "사회자: \"지금부터 '교실에서 반려 식물을 키워야 한다.'를 논제로 토론을 시작하겠습니다. 먼저 찬성편 주장을 들어 보겠습니다.\"", "figure": "주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기를 네 칸 화살표로 나타낸 도식"}, {"heading": "근거는 믿을 만한 자료로", "paras": ["토론에서 이기려면 주장보다 근거가 더 중요해요. 근거는 주장과 관련이 있고, 사실이며, 믿을 만한 자료여야 해요.", "조사 결과, 전문가의 말, 책이나 신문의 내용, 실제 경험 등을 근거 자료로 쓸 수 있어요. 자료를 쓸 때는 어디에서 가져왔는지(출처)를 밝혀요.", "반론할 때는 상대의 근거가 사실인지, 주장과 관련이 있는지, 자료가 믿을 만한지를 따져요."], "example": "찬성편 근거: 식물을 기르면 교실 공기가 맑아지고, 학생들이 생명을 돌보며 책임감을 기를 수 있습니다.\n반대편 반론: 방학 동안에는 아무도 물을 주지 못해 식물이 죽을 수 있습니다. 이것은 오히려 생명을 소중히 여기지 않는 일이 아닐까요?", "figure": "교실 창가에 놓인 작은 화분들과 물뿌리개"}, {"heading": "토론할 때 지킬 예절", "paras": ["토론은 다투는 것이 아니라 생각을 나누는 것이에요. 상대편 친구를 존중하는 태도가 꼭 필요해요.", "사회자의 안내에 따라 정해진 시간과 차례를 지켜 말해요. 상대가 말할 때는 끼어들지 말고 끝까지 들으며 메모해요.", "상대의 의견을 반박할 때도 사람을 탓하지 않고 근거만 따져요. 바른 말과 알맞은 목소리로 말해요."], "example": "좋은 반론: \"찬성편에서 공기가 맑아진다고 하셨는데, 화분 몇 개로 교실 공기가 얼마나 달라지는지 자료가 있나요?\"\n나쁜 반론: \"그건 말도 안 돼! 너는 아무것도 모르잖아.\"", "figure": "손을 들고 차례를 기다리는 아이와 메모하며 듣는 아이들"}], "keywords": [{"word": "토론", "meaning": "어떤 문제에 대해 찬성과 반대로 나뉘어 근거를 들어 상대를 설득하는 말하기"}, {"word": "논제", "meaning": "토론에서 다룰 주제로, 찬반이 나뉘는 한 가지 주장"}, {"word": "반론", "meaning": "상대편 주장이나 근거의 문제점을 짚어 반박하는 것"}, {"word": "사회자", "meaning": "토론의 차례와 시간을 안내하며 토론을 이끄는 사람"}, {"word": "판정단", "meaning": "토론을 듣고 어느 편이 더 설득력 있었는지 판단하는 사람들"}, {"word": "출처", "meaning": "자료나 정보가 나온 곳"}], "expressions": [], "quiz": [{"q": "토론 논제로 가장 알맞은 것은?", "choices": ["가을 운동회를 어디에서 할까?", "학교에서 실내화를 신어야 한다.", "운동회는 재미있다.", "쓸데없는 학원은 줄이고 놀이 시간은 늘려야 한다."], "answer": 1, "explain": "찬반이 나뉘는 한 가지 주장을 '~해야 한다.'로 썼어요. 4번은 두 가지 내용이 섞였고 '쓸데없는'이라는 편드는 말이 있어요."}, {"q": "초등학교 토론 절차의 차례로 알맞은 것은?", "choices": ["반론하기 → 주장 펼치기 → 판정하기 → 주장 다지기", "주장 다지기 → 주장 펼치기 → 반론하기 → 판정하기", "주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기", "판정하기 → 반론하기 → 주장 펼치기 → 주장 다지기"], "answer": 2, "explain": "먼저 주장을 펼치고, 반론하고, 주장을 다진 뒤 판정해요."}, {"q": "토론과 토의의 차이로 알맞은 것은?", "choices": ["토론은 찬성과 반대로 나뉘어 어느 주장이 타당한지 따진다.", "토론은 여러 사람이 의견을 모아 함께 방법을 찾는다.", "토의는 반드시 판정단이 있어야 한다.", "토론에는 근거가 필요 없다."], "answer": 0, "explain": "토론은 찬반으로 나뉘고, 토의는 의견을 모아 해결 방법을 찾아요."}, {"q": "토론할 때의 태도로 알맞지 __않은__ 것은?", "choices": ["상대가 말할 때 메모하며 듣는다.", "사회자의 안내에 따라 말한다.", "근거의 문제점을 따져 반론한다.", "상대가 틀렸다고 생각되면 바로 끼어들어 말한다."], "answer": 3, "explain": "상대의 말이 끝날 때까지 기다렸다가 자기 차례에 말해야 해요."}], "summary": ["토론은 찬성편과 반대편이 근거를 들어 상대를 설득하는 말하기예요.", "논제는 찬반이 나뉘는 한 가지 주장을 '~해야 한다.' 꼴로 써요.", "토론은 주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기 차례로 하고, 상대를 존중하며 차례를 지켜요."], "parent_tip": "아이들은 반론을 '상대를 이기는 말'로 생각해 감정적으로 말하기 쉽습니다. 집에서 \"주말에 게임 시간을 늘려야 한다\" 같은 가벼운 논제로 가족 토론을 해 보고, 아이에게 일부러 자기 생각과 반대편을 맡겨 보세요. 반대 입장의 근거를 찾아보는 경험이 생각을 넓혀 줍니다."}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','토론하기',4,'k5-04' where not exists (select 1 from public.topics where lesson_slug='k5-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-05','5~6','국어','논설문 쓰기','내 생각으로 다른 사람을 설득하는 글은 어떻게 쓸까?','assets/img/l_k5-05.jpg',$j${"intro": "\"우리 아파트 놀이터에 그늘막을 설치해 주세요!\" 이런 바람을 많은 사람에게 알리고 마음을 움직이려면 어떻게 써야 할까요? 주장과 근거를 짜임새 있게 쓰는 글, 논설문 쓰는 법을 알아봐요.", "sections": [{"heading": "논설문은 주장과 근거로 이루어져요", "paras": ["논설문은 글쓴이가 어떤 문제에 대한 자기 생각(주장)을 내세우고, 그 주장이 옳다는 것을 근거를 들어 읽는 사람을 설득하는 글이에요.", "주장은 글쓴이가 말하고 싶은 핵심 생각이고, 근거는 그 주장이 옳다고 뒷받침하는 까닭이에요.", "근거가 탄탄할수록 읽는 사람이 \"그래, 맞아!\" 하고 고개를 끄덕이게 돼요."], "example": "주장: 놀이터에 그늘막을 설치해야 한다.\n근거 1: 여름에 놀이 기구가 햇볕에 달궈져 화상을 입을 수 있다.\n근거 2: 그늘이 있으면 어린아이와 어른들이 함께 쉴 수 있다.", "figure": "뜨거운 햇볕 아래 텅 빈 놀이터와, 그늘막이 설치된 놀이터에서 아이들이 노는 모습을 나란히 보여 주는 그림"}, {"heading": "서론 – 본론 – 결론의 짜임", "paras": ["논설문은 보통 서론, 본론, 결론의 세 부분으로 짜여요.", "서론에서는 문제 상황을 소개하고 글쓴이의 주장을 밝혀요. 본론에서는 주장을 뒷받침하는 근거를 문단마다 하나씩 자세히 써요. 결론에서는 본론 내용을 간추리고 주장을 다시 한번 강조해요.", "본론의 각 문단은 '근거 문장(중심 문장) + 뒷받침 자료(예, 조사 결과, 경험)'로 쓰면 탄탄해져요."], "example": "서론: 문제 상황 + 주장 / 본론: 근거 1, 근거 2, 근거 3 (+ 자료) / 결론: 내용 요약 + 주장 강조", "figure": "서론·본론·결론을 머리·몸통·다리로 나타낸 사람 모양 도식"}, {"heading": "타당한 근거와 알맞은 자료", "paras": ["근거는 ① 주장과 관련이 있고 ② 주장을 뒷받침할 수 있으며 ③ 믿을 만해야 해요.", "근거를 뒷받침하는 자료로는 조사 결과, 통계(숫자 자료), 전문가의 말, 신문 기사, 실제 경험 등이 있어요. 자료를 쓸 때는 출처를 밝혀요.", "근거가 하나뿐이면 설득력이 약해요. 서로 다른 쪽에서 바라본 근거 두세 개를 들면 좋아요."], "example": "약한 근거: 그늘막을 설치하면 놀이터가 예뻐진다.\n탄탄한 근거: 우리 아파트 어린이 30명에게 물었더니 25명이 '여름에는 미끄럼틀이 뜨거워 탈 수 없다'고 답했다.", "figure": "설문 조사 결과를 막대그래프로 나타낸 종이와 연필"}, {"heading": "논설문에서 조심해야 할 표현", "paras": ["논설문에서는 읽는 사람이 믿을 수 있도록 표현을 알맞게 써야 해요.", "① 주관적인 표현(\"내 생각에는 그냥 좋은 것 같다\")보다 객관적인 표현을 써요. ② 모호한 표현(\"어느 정도\", \"아마도 그럴 수도 있다\")보다 분명한 표현을 써요. ③ 지나치게 단정하는 표현(\"반드시 모든 사람이\", \"절대로 ~하지 않는다\")은 피해요.", "또 상대를 비난하거나 감정적인 말을 쓰지 않고, 예의 바른 말로 설득해요."], "example": "고치기 전: 그늘막이 없으면 모든 아이가 반드시 화상을 입는다.\n고친 뒤: 그늘막이 없으면 한여름에 아이들이 뜨거운 놀이 기구에 화상을 입을 위험이 크다.", "figure": "공책의 문장에 빨간 펜으로 고칠 부분을 표시하는 손"}, {"heading": "논설문을 쓰는 차례", "paras": ["① 문제 찾기: 생활 속에서 고쳐야 할 문제를 찾아요. ② 주장 정하기: 문제에 대한 내 주장을 한 문장으로 정해요. ③ 근거와 자료 모으기: 주장을 뒷받침할 근거와 자료를 찾아요. ④ 개요 짜기: 서론·본론·결론에 쓸 내용을 간단히 정리해요.", "⑤ 글 쓰기: 개요에 따라 문단을 나누어 써요. ⑥ 고쳐 쓰기: 주장과 근거가 잘 이어지는지, 표현이 알맞은지, 맞춤법이 바른지 확인해요."], "example": "〈서론 예시〉 여름이 되면 우리 아파트 놀이터는 텅 비어 있다. 햇볕을 가릴 곳이 없어 놀이 기구가 뜨겁게 달궈지기 때문이다. 나는 아이들이 안전하게 놀 수 있도록 놀이터에 그늘막을 설치해야 한다고 생각한다.", "figure": "문제 찾기부터 고쳐 쓰기까지 여섯 단계를 계단 모양으로 나타낸 그림"}], "keywords": [{"word": "논설문", "meaning": "글쓴이의 주장을 근거를 들어 내세우며 읽는 사람을 설득하는 글"}, {"word": "주장", "meaning": "글쓴이가 내세우는 핵심 생각"}, {"word": "근거", "meaning": "주장이 옳다고 뒷받침하는 까닭"}, {"word": "서론·본론·결론", "meaning": "논설문의 짜임. 문제와 주장 제시 – 근거 제시 – 요약과 주장 강조"}, {"word": "개요", "meaning": "글을 쓰기 전에 쓸 내용의 뼈대를 간단히 정리한 것"}, {"word": "단정하는 표현", "meaning": "'반드시', '절대로'처럼 예외 없이 딱 잘라 말하는 표현"}], "expressions": [], "quiz": [{"q": "논설문의 서론에 들어갈 내용으로 알맞은 것은?", "choices": ["근거를 자세히 설명한다.", "문제 상황을 소개하고 주장을 밝힌다.", "본론 내용을 요약한다.", "읽은 책의 줄거리를 쓴다."], "answer": 1, "explain": "서론에서는 문제 상황과 글쓴이의 주장을 밝혀요."}, {"q": "논설문에 쓰기에 가장 알맞은 표현은?", "choices": ["모든 사람이 절대로 반대하지 않을 것이다.", "아마 어느 정도 좋을 수도 있다.", "운동을 하면 건강에 도움이 된다는 연구 결과가 있다.", "내 기분에는 그냥 좋은 것 같다."], "answer": 2, "explain": "근거 자료를 들어 객관적이고 분명하게 말한 표현이에요."}, {"q": "'급식을 남기지 말아야 한다.'는 주장의 근거로 알맞지 __않은__ 것은?", "choices": ["음식물 쓰레기를 처리하는 데 많은 돈이 든다.", "음식을 골고루 먹어야 건강하게 자란다.", "음식을 만들어 주시는 분들의 정성을 생각해야 한다.", "급식실 식탁이 새것이다."], "answer": 3, "explain": "식탁이 새것이라는 것은 주장과 관련이 없어요."}, {"q": "결론에서 하는 일로 알맞은 것은?", "choices": ["본론 내용을 간추리고 주장을 다시 강조한다.", "새로운 근거를 처음으로 길게 소개한다.", "문제 상황을 처음 소개한다.", "주장과 반대되는 생각만 쓴다."], "answer": 0, "explain": "결론은 글을 마무리하며 내용을 요약하고 주장을 강조해요."}, {"q": "논설문을 쓰는 차례에서 '근거와 자료 모으기' 다음에 할 일은?", "choices": ["문제 찾기", "고쳐 쓰기", "주장 정하기", "개요 짜기"], "answer": 3, "explain": "근거와 자료를 모은 뒤, 서론·본론·결론에 쓸 내용을 개요로 정리해요."}], "summary": ["논설문은 주장과 근거를 들어 읽는 사람을 설득하는 글이에요.", "서론(문제와 주장) – 본론(근거와 자료) – 결론(요약과 주장 강조)의 짜임으로 써요.", "주관적·모호한·단정하는 표현을 피하고, 믿을 만한 자료로 근거를 뒷받침해요."], "parent_tip": "아이들은 주장만 여러 번 되풀이하거나, 근거 대신 \"좋으니까\", \"재미있으니까\" 같은 막연한 까닭을 쓰기 쉽습니다. 아이가 평소 바라는 것(용돈 인상, 반려동물 등)을 주제로 논설문을 써 보게 하고, \"그 근거를 엄마·아빠가 믿을 수 있게 하려면 어떤 자료가 필요할까?\"라고 물어 주세요. 실제로 설득되면 그 주장을 들어주는 것도 큰 동기가 됩니다."}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','논설문 쓰기',5,'k5-05' where not exists (select 1 from public.topics where lesson_slug='k5-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-06','5~6','국어','관용 표현과 속담','"발이 넓다"는 정말 발이 크다는 뜻일까?','assets/img/l_k5-06.jpg',$j${"intro": "\"우리 이모는 발이 넓어서 모르는 사람이 없어.\" 이 말을 듣고 이모의 발 크기를 떠올린 친구는 없겠지요? 낱말 뜻만으로는 알 수 없는 특별한 뜻을 가진 말, 관용 표현과 속담을 알아봐요.", "sections": [{"heading": "관용 표현은 '새로운 뜻'으로 굳어진 말이에요", "paras": ["관용 표현은 두 개 이상의 낱말이 합쳐져서, 낱말 하나하나의 뜻과는 다른 새로운 뜻으로 굳어져 쓰이는 표현이에요.", "예를 들어 '발이 넓다'는 실제 발의 크기가 아니라 '아는 사람이 많다'는 뜻이에요. '손이 크다'는 '씀씀이가 넉넉하다'는 뜻이고요.", "관용 표현은 낱말을 바꾸면 그 뜻이 사라져요. '발이 넓다'를 '다리가 넓다'로 바꾸면 '아는 사람이 많다'는 뜻이 되지 않아요."], "example": "할머니는 손이 커서 김치를 담그면 온 동네에 나누어 주신다. → '손이 크다' = 씀씀이가 넉넉하다", "figure": "커다란 그릇에 김치를 가득 담아 이웃에게 나누어 주는 모습"}, {"heading": "몸과 관련된 관용 표현이 많아요", "paras": ["우리말에는 눈, 코, 입, 귀, 손, 발처럼 몸과 관련된 관용 표현이 특히 많아요.", "'귀가 얇다'는 남의 말을 쉽게 믿는다는 뜻, '입이 무겁다'는 비밀을 잘 지킨다는 뜻, '눈이 높다'는 좋은 것만 찾는다는 뜻이에요.", "'코가 납작해지다'는 몹시 창피를 당해 기가 죽다, '손을 놓다'는 하던 일을 그만두다라는 뜻이에요."], "example": "민준이는 입이 무거워서 친구들이 고민을 털어놓는다. / 동생은 귀가 얇아서 광고만 보면 사 달라고 조른다.", "figure": "입에 손가락을 대고 '쉿' 하는 아이와 귀를 기울이는 친구"}, {"heading": "속담은 조상들의 지혜가 담긴 말이에요", "paras": ["속담은 옛날부터 사람들 사이에서 전해 내려오는 짧은 말로, 생활 속 교훈이나 지혜가 담겨 있어요.", "속담은 대부분 하나의 짧은 문장으로 되어 있고, 어떤 상황을 빗대어 깨우침을 줘요.", "속담을 알맞게 쓰면 하고 싶은 말을 짧고 재치 있게 전할 수 있고, 듣는 사람도 쉽게 공감해요."], "example": "가는 말이 고와야 오는 말이 곱다. → 내가 남에게 좋게 말해야 남도 나에게 좋게 말한다.\n티끌 모아 태산 → 아주 작은 것도 모이면 큰 것이 된다.", "figure": "작은 동전들이 모여 저금통을 가득 채운 모습"}, {"heading": "상황에 알맞은 속담 쓰기", "paras": ["속담은 뜻을 정확히 알고 상황에 알맞게 써야 해요. 뜻에 맞지 않게 쓰면 오히려 말이 어색해져요.", "일이 잘못된 뒤에 뉘우쳐도 소용없을 때는 '소 잃고 외양간 고친다', 가까이 있는 것을 오히려 모를 때는 '등잔 밑이 어둡다', 아무리 잘하는 사람도 실수할 때가 있다는 것은 '원숭이도 나무에서 떨어진다'를 써요."], "example": "상황: 안경을 머리 위에 올려 둔 채 온 집 안을 찾아다녔다.\n알맞은 속담: 등잔 밑이 어둡다.\n상황: 반에서 받아쓰기를 가장 잘하는 지우가 쉬운 낱말을 틀렸다.\n알맞은 속담: 원숭이도 나무에서 떨어진다.", "figure": "머리 위에 안경을 올린 채 서랍을 뒤지는 사람"}, {"heading": "관용 표현과 속담을 쓰면 좋은 점", "paras": ["관용 표현과 속담을 쓰면 말이나 글이 짧으면서도 뜻이 풍부해지고, 생생하고 재미있어져요.", "하지만 듣는 사람이 뜻을 모르면 오해할 수 있으므로 상대와 상황을 생각해서 써야 해요. 또 놀리거나 상처 주는 데 쓰지 않도록 조심해요."], "example": "그냥 말하기: 여럿이 함께하면 일이 더 쉬워져. 같이 하자.\n속담 넣기: 백지장도 맞들면 낫다잖아. 같이 하자!", "figure": "친구 둘이 무거운 책상을 함께 들어 옮기는 모습"}], "keywords": [{"word": "관용 표현", "meaning": "두 개 이상의 낱말이 합쳐져 원래 뜻과 다른 새로운 뜻으로 굳어져 쓰이는 표현"}, {"word": "속담", "meaning": "예부터 전해 내려오는, 교훈이나 지혜가 담긴 짧은 말"}, {"word": "교훈", "meaning": "앞으로의 행동이나 생활에 도움이 되는 가르침"}, {"word": "굳어지다", "meaning": "어떤 말이 오랫동안 쓰여 일정한 뜻으로 자리 잡다"}], "expressions": [{"en": "발이 넓다", "ko": "아는 사람이 많다", "note": "관용 표현"}, {"en": "손이 크다", "ko": "씀씀이가 넉넉하다", "note": "관용 표현"}, {"en": "귀가 얇다", "ko": "남의 말을 쉽게 믿는다", "note": "관용 표현. [귀가 얄따]"}, {"en": "입이 무겁다", "ko": "말이 적고 비밀을 잘 지킨다", "note": "관용 표현"}, {"en": "눈이 높다", "ko": "좋은 것만 찾는다, 보는 수준이 높다", "note": "관용 표현"}, {"en": "가는 말이 고와야 오는 말이 곱다", "ko": "내가 남에게 좋게 해야 남도 나에게 좋게 한다", "note": "속담. [곱따]"}, {"en": "티끌 모아 태산", "ko": "아주 작은 것도 모이면 큰 것이 된다", "note": "속담"}, {"en": "소 잃고 외양간 고친다", "ko": "일이 잘못된 뒤에 손을 써도 소용없다", "note": "속담. 외양간은 소를 기르는 곳"}, {"en": "등잔 밑이 어둡다", "ko": "가까이 있는 것을 오히려 잘 모른다", "note": "속담. [어둡따]"}, {"en": "원숭이도 나무에서 떨어진다", "ko": "아무리 잘하는 사람도 실수할 때가 있다", "note": "속담"}, {"en": "백지장도 맞들면 낫다", "ko": "쉬운 일이라도 함께 힘을 합치면 더 쉽다", "note": "속담. [백찌짱도 맏뜰면 낟따]"}, {"en": "낮말은 새가 듣고 밤말은 쥐가 듣는다", "ko": "아무도 안 듣는 곳에서도 말을 조심해야 한다", "note": "속담"}], "quiz": [{"q": "'발이 넓다'의 뜻으로 알맞은 것은?", "choices": ["발 크기가 크다", "걸음이 빠르다", "아는 사람이 많다", "신발이 많다"], "answer": 2, "explain": "'발이 넓다'는 아는 사람이 많다는 뜻의 관용 표현이에요."}, {"q": "다음 상황에 어울리는 속담은?\n\"하루에 100원씩 꾸준히 모았더니 1년 뒤 3만 원이 넘었다.\"", "choices": ["티끌 모아 태산", "등잔 밑이 어둡다", "소 잃고 외양간 고친다", "원숭이도 나무에서 떨어진다"], "answer": 0, "explain": "작은 것도 모이면 큰 것이 된다는 뜻이므로 '티끌 모아 태산'이 알맞아요."}, {"q": "관용 표현에 대한 설명으로 알맞은 것은?", "choices": ["낱말 뜻을 그대로 합친 뜻이다.", "낱말을 마음대로 바꾸어도 뜻이 같다.", "외국에서 들어온 말이다.", "낱말이 합쳐져 새로운 뜻으로 굳어진 표현이다."], "answer": 3, "explain": "관용 표현은 원래 낱말의 뜻과 다른 새로운 뜻으로 굳어져 쓰여요."}, {"q": "'입이 무겁다'를 알맞게 쓴 문장은?", "choices": ["감기에 걸려 입이 무겁다.", "서윤이는 입이 무거워서 비밀을 꼭 지킨다.", "밥을 많이 먹어서 입이 무겁다.", "입이 무거워서 말이 너무 많다."], "answer": 1, "explain": "'입이 무겁다'는 비밀을 잘 지키고 말이 적다는 뜻이에요."}, {"q": "숙제를 미루다 혼난 뒤에야 계획표를 만든 상황에 어울리는 속담은?", "choices": ["백지장도 맞들면 낫다", "가는 말이 고와야 오는 말이 곱다", "소 잃고 외양간 고친다", "티끌 모아 태산"], "answer": 2, "explain": "일이 잘못된 뒤에야 대책을 세우는 상황이므로 '소 잃고 외양간 고친다'가 알맞아요."}], "summary": ["관용 표현은 낱말이 합쳐져 새로운 뜻으로 굳어진 표현이에요(발이 넓다, 손이 크다).", "속담은 예부터 전해 오는 교훈과 지혜가 담긴 짧은 말이에요.", "관용 표현과 속담은 뜻을 정확히 알고 상황에 알맞게 쓰면 말과 글이 생생해져요."], "parent_tip": "관용 표현은 글자 그대로 해석하기 쉬워 아이들이 자주 헷갈립니다. 대화 중에 자연스럽게 \"아빠가 요즘 눈코 뜰 새 없이 바빠\"처럼 써 보고 \"무슨 뜻일까?\" 하고 물어보세요. 속담 카드 놀이(앞부분을 말하면 뒷부분 맞히기)나 오늘 있었던 일에 어울리는 속담 찾기를 하면 오래 기억합니다."}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','관용 표현과 속담',6,'k5-06' where not exists (select 1 from public.topics where lesson_slug='k5-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-07','5~6','국어','매체 자료 읽기','뉴스와 광고, 인터넷 글을 똑똑하게 읽으려면?','assets/img/l_k5-07.jpg',$j${"intro": "우리는 하루에도 수없이 많은 뉴스, 광고, 영상, 인터넷 글을 만나요. 그런데 그 내용이 모두 정확할까요? 매체 자료가 어떻게 정보를 전하는지 알고, 믿을 만한지 따져 보며 읽는 방법을 배워요.", "sections": [{"heading": "매체와 매체 자료란?", "paras": ["매체는 정보나 생각을 전달하는 수단이에요. 책·신문·잡지 같은 인쇄 매체, 텔레비전·라디오 같은 방송 매체, 누리집·누리 소통망(SNS)·동영상 사이트 같은 인터넷 매체가 있어요.", "매체 자료는 이런 매체로 전달되는 뉴스, 광고, 기사, 영상, 게시글 같은 자료를 말해요.", "매체마다 정보를 전하는 방법이 달라요. 인쇄 매체는 글과 사진, 라디오는 소리, 텔레비전과 동영상은 영상·소리·자막을 함께 써요."], "example": "인쇄 매체: 신문, 잡지, 책 / 방송 매체: 텔레비전 뉴스, 라디오 / 인터넷 매체: 누리집 기사, 블로그, 동영상", "figure": "책상 위에 신문, 라디오, 태블릿 화면이 나란히 놓여 있는 모습"}, {"heading": "매체 자료는 여러 가지 표현 방법을 함께 써요", "paras": ["영상 매체 자료에서는 글(자막), 사진, 그림, 도표, 소리(말, 음악, 효과음), 움직이는 영상이 함께 쓰여요.", "예를 들어 텔레비전 뉴스는 기자의 말로 내용을 전하고, 자막으로 핵심을 정리하며, 그래프로 숫자를 한눈에 보여 주고, 현장 영상으로 생생함을 더해요.", "매체 자료를 읽을 때는 각 표현 방법이 어떤 효과를 주는지 생각하면 내용을 더 깊이 이해할 수 있어요."], "example": "뉴스 화면 예: 자막 \"올여름 열대야 일수 지난해의 두 배\" + 막대그래프 + 밤에 공원에서 더위를 식히는 시민들 영상", "figure": "뉴스 화면을 자막·그래프·현장 영상 부분으로 나누어 표시한 도식"}, {"heading": "뉴스를 읽을 때는 이렇게", "paras": ["뉴스는 사회에서 일어난 일을 사실에 따라 전하는 매체 자료예요. 그래도 만드는 사람이 어떤 내용을 고르고 어떻게 보여 주느냐에 따라 받아들이는 느낌이 달라질 수 있어요.", "뉴스를 볼 때는 ① 사실과 의견을 구별하고 ② 근거 자료(조사 결과, 인터뷰)가 믿을 만한지 ③ 한쪽 입장만 전하지 않았는지 살펴봐요.", "같은 일을 다룬 다른 뉴스와 비교해 보면 더 정확하게 알 수 있어요."], "example": "뉴스 A: \"새 공원 개장, 주민들 크게 반겨\" / 뉴스 B: \"새 공원 개장… 주차 공간 부족해 불편 호소도\"\n→ 같은 일이라도 어떤 면을 강조했는지에 따라 느낌이 달라요.", "figure": "같은 공원 사진에 서로 다른 제목이 붙은 두 개의 신문 기사"}, {"heading": "광고는 '사고 싶게' 만들어요", "paras": ["광고는 상품이나 생각을 알리고 사람들이 사거나 행동하도록 설득하는 매체 자료예요.", "광고는 짧고 기억하기 쉬운 문구, 눈에 띄는 색깔과 그림, 신나는 음악, 유명한 사람 등을 이용해 관심을 끌어요.", "그래서 광고를 볼 때는 과장된 표현이 없는지, 정말 필요한 물건인지, 광고에서 말하지 않은 단점은 없는지 따져 봐야 해요. 공익 광고처럼 좋은 생각이나 행동을 알리는 광고도 있어요."], "example": "상품 광고: \"마시기만 하면 키가 쑥쑥! 친구들 모두 마시는 바로 그 음료!\"(과장된 표현)\n공익 광고: \"양치하는 동안 수도꼭지를 잠그면 컵 몇 잔만으로도 충분해요.\"(물 절약 권유)", "figure": "음료 광고 포스터를 보며 고개를 갸웃하는 아이"}, {"heading": "인터넷 정보, 믿을 만한지 따져 봐요", "paras": ["인터넷에는 누구나 글을 올릴 수 있어서 잘못된 정보나 일부러 꾸며 낸 가짜 정보도 섞여 있어요.", "인터넷 정보를 볼 때는 ① 누가 썼는지(출처) ② 언제 쓴 글인지(최신 정보인지) ③ 근거가 있는지 ④ 다른 믿을 만한 자료에도 같은 내용이 있는지 확인해요.", "확인하지 않은 정보를 다른 사람에게 함부로 퍼뜨리지 않는 것도 중요한 매체 예절이에요."], "example": "점검표: □ 글쓴이나 기관이 밝혀져 있나요? □ 날짜가 최근인가요? □ 근거 자료가 있나요? □ 다른 곳에서도 같은 내용을 확인했나요?", "figure": "태블릿 화면 옆에 체크 표시가 된 점검표 종이"}], "keywords": [{"word": "매체", "meaning": "정보나 생각을 전달하는 수단(신문, 텔레비전, 인터넷 등)"}, {"word": "매체 자료", "meaning": "매체로 전달되는 뉴스, 광고, 기사, 영상 같은 자료"}, {"word": "자막", "meaning": "영상 화면에 글자로 나타낸 내용"}, {"word": "공익 광고", "meaning": "사회에 도움이 되는 생각이나 행동을 알리는 광고"}, {"word": "출처", "meaning": "정보나 자료가 나온 곳"}, {"word": "신뢰성", "meaning": "정보를 믿을 수 있는 정도"}], "expressions": [], "quiz": [{"q": "다음 중 방송 매체에 해당하는 것은?", "choices": ["신문", "텔레비전", "잡지", "책"], "answer": 1, "explain": "텔레비전과 라디오는 방송 매체예요. 나머지는 인쇄 매체예요."}, {"q": "뉴스 화면에서 숫자 자료를 한눈에 보여 주기 위해 주로 쓰는 표현 방법은?", "choices": ["효과음", "배경 음악", "그래프나 도표", "기자의 표정"], "answer": 2, "explain": "그래프나 도표는 숫자 자료를 한눈에 비교하게 해 줘요."}, {"q": "광고를 볼 때의 태도로 가장 알맞은 것은?", "choices": ["광고에 나온 말은 모두 사실이므로 그대로 믿는다.", "유명한 사람이 나오면 꼭 산다.", "과장된 표현은 없는지, 정말 필요한지 따져 본다.", "광고 음악이 신나면 좋은 상품이다."], "answer": 2, "explain": "광고는 설득하려는 목적이 있으므로 비판하며 봐야 해요."}, {"q": "인터넷 정보가 믿을 만한지 확인하는 방법으로 알맞지 __않은__ 것은?", "choices": ["글쓴이나 기관이 누구인지 확인한다.", "글을 쓴 날짜를 확인한다.", "다른 믿을 만한 자료와 비교한다.", "조회 수가 많으면 무조건 믿는다."], "answer": 3, "explain": "조회 수가 많다고 해서 정보가 정확한 것은 아니에요."}], "summary": ["매체는 정보를 전달하는 수단이고, 매체 자료는 글·그림·소리·영상 등 여러 표현 방법을 함께 써요.", "뉴스는 사실과 의견을 구별하고, 광고는 과장된 표현이 없는지 따져 보며 읽어요.", "인터넷 정보는 출처, 날짜, 근거를 확인하고 함부로 퍼뜨리지 않아요."], "parent_tip": "아이들은 영상이나 인터넷에 나온 내용을 그대로 믿는 경향이 있습니다. 함께 광고를 보며 \"이 광고가 말하지 않은 것은 무엇일까?\", 뉴스를 보며 \"이 내용은 누가 말한 거야? 다른 뉴스에서도 같은 말을 할까?\"라고 질문해 보세요. 아이가 친구에게 들은 '놀라운 소식'을 함께 검색해 사실인지 확인해 보는 경험도 좋습니다."}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','매체 자료 읽기',7,'k5-07' where not exists (select 1 from public.topics where lesson_slug='k5-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-08','5~6','국어','문장 성분의 호응','"나는 어제 숙제를 할 것이다"는 왜 어색할까?','assets/img/l_k5-08.jpg',$j${"intro": "\"나는 어제 숙제를 할 것이다.\" 읽자마자 뭔가 이상하지요? '어제'와 '할 것이다'가 서로 맞지 않기 때문이에요. 문장 속 말들이 서로 짝을 이루어 잘 어울리는 것을 '호응'이라고 해요.", "sections": [{"heading": "문장 성분과 호응이란?", "paras": ["문장을 이루는 각 부분을 문장 성분이라고 해요. 대표적으로 '누가/무엇이'에 해당하는 주어, '어찌하다/어떠하다/무엇이다'에 해당하는 서술어, '무엇을'에 해당하는 목적어, 서술어를 꾸며 주는 부사어 등이 있어요.", "호응은 문장에서 앞에 어떤 말이 오면 뒤에 그에 어울리는 말이 짝지어 오는 것이에요.", "호응이 맞지 않으면 문장이 어색해지고 뜻이 잘 전달되지 않아요."], "example": "동생이(주어) / 사과를(목적어) / 맛있게(부사어) / 먹는다(서술어).", "figure": "문장을 퍼즐 조각처럼 나누어 주어·목적어·부사어·서술어 이름표를 붙인 그림"}, {"heading": "주어와 서술어의 호응", "paras": ["주어와 서술어는 서로 어울려야 해요. 특히 문장이 길어지면 주어를 잊어버리고 서술어를 엉뚱하게 쓰기 쉬워요.", "호응을 확인하려면 주어와 서술어만 떼어 내어 이어 읽어 보세요. '내 꿈은 ~ 되고 싶다'처럼 어색하면 고쳐야 해요."], "example": "어색한 문장: 내 꿈은 멋진 요리사가 되고 싶다. (꿈은 ~ 되고 싶다 ✗)\n고친 문장: 내 꿈은 멋진 요리사가 되는 것이다. / 나는 멋진 요리사가 되고 싶다.", "figure": "요리사 모자를 쓴 아이가 공책에 문장을 고쳐 쓰는 모습"}, {"heading": "시간을 나타내는 말과 서술어의 호응", "paras": ["'어제', '지난주', '아까'처럼 지난 때를 나타내는 말에는 '~었다/~았다/~였다'처럼 과거를 나타내는 서술어가 어울려요.", "'지금', '요즘'에는 '~ㄴ다/~는다'처럼 현재를, '내일', '다음 주'에는 '~ㄹ 것이다', '~겠다'처럼 미래를 나타내는 서술어가 어울려요."], "example": "어색한 문장: 나는 어제 할머니 댁에 갈 것이다.\n고친 문장: 나는 어제 할머니 댁에 갔다. / 나는 내일 할머니 댁에 갈 것이다.", "figure": "어제·오늘·내일이 적힌 달력 위에 화살표가 그려진 그림"}, {"heading": "높임 표현의 호응", "paras": ["높여야 할 분(할아버지, 선생님 등)이 주어일 때는 서술어에 '-시-'를 넣어 높여요. 주어 뒤에는 '이/가' 대신 '께서'를 쓰기도 해요.", "또 '먹다 → 드시다(잡수시다)', '자다 → 주무시다', '있다 → 계시다'처럼 높임의 뜻을 가진 낱말로 바꾸어 써요.", "반대로 나를 높이면 안 돼요. \"제가 말씀하시겠습니다\"는 어색하고 \"제가 말씀드리겠습니다\"가 바른 표현이에요."], "example": "어색한 문장: 할아버지가 방에서 잔다.\n고친 문장: 할아버지께서 방에서 주무신다.", "figure": "방에서 이불을 덮고 주무시는 할아버지와 조용히 문을 닫는 아이"}, {"heading": "짝을 이루는 꾸며 주는 말(부사어)", "paras": ["어떤 부사어는 꼭 함께 써야 하는 서술어의 짝이 정해져 있어요.", "'결코, 절대로, 전혀' 뒤에는 '~지 않다, ~없다' 같은 부정하는 말이 와요. '만약, 만일' 뒤에는 '~면/~라면', '비록' 뒤에는 '~지만/~ㄹ지라도', '왜냐하면' 뒤에는 '~기 때문이다', '아마' 뒤에는 '~ㄹ 것이다'가 어울려요.", "글을 다 쓴 뒤 이런 짝꿍 말을 찾아 서로 잘 어울리는지 확인하는 습관을 들이면 좋아요."], "example": "어색한 문장: 나는 결코 포기할 것이다. → 고친 문장: 나는 결코 포기하지 않을 것이다.\n어색한 문장: 왜냐하면 비가 왔다. → 고친 문장: 왜냐하면 비가 왔기 때문이다.\n어색한 문장: 비록 키는 작은데 힘이 세다. → 고친 문장: 비록 키는 작지만 힘이 세다.", "figure": "짝을 이룬 낱말 카드(결코–않다, 만약–면, 왜냐하면–때문이다)가 책상 위에 놓인 모습"}], "keywords": [{"word": "문장 성분", "meaning": "주어, 서술어, 목적어, 부사어처럼 문장을 이루는 각 부분"}, {"word": "호응", "meaning": "문장에서 앞에 오는 말에 어울리는 말이 뒤에 짝지어 오는 것"}, {"word": "주어", "meaning": "문장에서 '누가', '무엇이'에 해당하는 부분"}, {"word": "서술어", "meaning": "문장에서 '어찌하다', '어떠하다', '무엇이다'에 해당하는 부분"}, {"word": "부사어", "meaning": "서술어 등을 꾸며 뜻을 자세하게 해 주는 부분"}, {"word": "높임 표현", "meaning": "말하는 대상이나 듣는 사람을 높여 나타내는 표현"}], "expressions": [], "quiz": [{"q": "호응이 바른 문장은?", "choices": ["나는 내일 수영장에 갔다.", "어제 눈이 많이 내렸다.", "지난 주말에 영화를 볼 것이다.", "아까 비가 오겠다."], "answer": 1, "explain": "'어제'와 과거를 나타내는 '내렸다'가 잘 어울려요."}, {"q": "\"선생님이 교실에 있다.\"를 높임 표현에 맞게 고친 것은?", "choices": ["선생님께서 교실에 계신다.", "선생님이 교실에 있으신다.", "선생님께서 교실에 있다.", "선생님이 교실에 있겠다."], "answer": 0, "explain": "'께서'와 '있다'의 높임말 '계시다'를 써야 해요."}, {"q": "빈칸에 들어갈 말로 알맞은 것은?\n\"나는 절대로 거짓말을 [  ].\"", "choices": ["한다", "했다", "할 것이다", "하지 않는다"], "answer": 3, "explain": "'절대로'는 '~지 않다' 같은 부정하는 말과 호응해요."}, {"q": "주어와 서술어의 호응이 바른 문장은?", "choices": ["내 바람은 가족과 여행을 가고 싶다.", "중요한 점은 손을 자주 씻어야 한다.", "내 취미는 그림을 그리는 것이다.", "이 책의 장점은 그림이 많다."], "answer": 2, "explain": "'취미는 ~ 것이다'로 주어와 서술어가 잘 어울려요."}, {"q": "\"만약 내일 날씨가 맑[  ] 소풍을 갈 것이다.\" 빈칸에 알맞은 말은?", "choices": ["지만", "아서", "으면", "는데"], "answer": 2, "explain": "'만약'은 '~면/~라면'과 호응해요."}], "summary": ["호응은 문장에서 앞에 오는 말과 뒤에 오는 말이 서로 어울려 짝을 이루는 것이에요.", "주어와 서술어, 시간을 나타내는 말과 서술어, 높임 대상과 서술어가 서로 어울려야 해요.", "'결코–않다', '만약–면', '비록–지만', '왜냐하면–때문이다'처럼 짝을 이루는 말을 지켜 써요."], "parent_tip": "아이들은 긴 문장을 쓸 때 주어를 잊고 서술어를 쓰는 실수(\"내 꿈은 ~ 되고 싶다\")를 가장 많이 합니다. 아이가 쓴 일기에서 주어와 서술어만 뽑아 소리 내어 이어 읽게 해 보세요. 어색함을 스스로 느끼는 것이 가장 좋은 공부입니다. 대화 중 \"할머니가 밥 먹었어?\" 같은 말이 나오면 \"할머니께서 진지 드셨어?\"로 자연스럽게 바꿔 말해 주세요."}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','문장 성분의 호응',8,'k5-08' where not exists (select 1 from public.topics where lesson_slug='k5-08');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-09','5~6','국어','기행문 쓰기','여행의 추억을 글로 오래 간직하려면?','assets/img/l_k5-09.jpg',$j${"intro": "가족과 다녀온 여행, 시간이 지나면 어디에 갔는지, 무엇을 느꼈는지 조금씩 잊혀요. 여행하며 겪은 일을 글로 남기면 언제든 그날로 돌아갈 수 있어요. 이런 글을 '기행문'이라고 해요.", "sections": [{"heading": "기행문은 여행의 기록이에요", "paras": ["기행문은 여행하면서 보고, 듣고, 겪은 일과 그때의 생각이나 느낌을 쓴 글이에요.", "일기와 비슷하지만, 기행문은 장소를 옮겨 다니는 여행을 중심으로 쓴다는 점이 달라요.", "기행문을 쓰면 여행의 추억을 오래 간직할 수 있고, 읽는 사람에게 그 장소에 대한 정보와 느낌을 함께 전할 수 있어요."], "example": "", "figure": "여행 가방 옆에 기차표, 지도, 작은 공책이 놓여 있는 모습"}, {"heading": "기행문의 세 요소: 여정, 견문, 감상", "paras": ["여정은 여행한 차례나 과정이에요. 언제, 어디에서 어디로 갔는지를 나타내요.", "견문은 여행하면서 보거나 들은 것이에요. 그곳의 모습, 안내판이나 해설사에게 들은 설명 등이 해당해요.", "감상은 보거나 들은 것에 대한 생각이나 느낌이에요. 기행문에는 이 세 가지가 골고루 들어가야 해요."], "example": "여정: 아침 일찍 기차를 타고 경주역에 도착했다.\n견문: 첨성대는 돌을 둥글게 쌓아 올린 모양이었다. 해설사께서 신라 사람들이 하늘을 관찰하던 곳으로 알려져 있다고 하셨다.\n감상: 오래전 사람들이 별을 보려고 이렇게 정성껏 돌을 쌓았다니 놀라웠다.", "figure": "여정·견문·감상을 발자국·눈과 귀·하트 그림으로 나타낸 세 칸 도식"}, {"heading": "기행문의 짜임: 처음 – 가운데 – 끝", "paras": ["처음 부분에는 여행을 떠나게 된 까닭, 떠날 때의 마음, 출발하는 모습을 써요.", "가운데 부분에는 여정에 따라 장소를 옮겨 가며 견문과 감상을 자세히 써요. 장소가 바뀔 때마다 문단을 나누면 읽기 쉬워요.", "끝부분에는 여행을 마치며 든 전체적인 생각과 느낌, 다짐 등을 써요."], "example": "처음: 사회 시간에 배운 신라의 문화재를 직접 보고 싶어서 가족과 경주로 떠났다.\n가운데: 첨성대 → 불국사 → 박물관 차례로 본 것과 느낀 점\n끝: 책으로만 보던 문화재를 직접 보니 우리 조상들의 솜씨가 더 자랑스럽게 느껴졌다.", "figure": "처음·가운데·끝을 출발역·여러 정류장·도착역이 있는 기찻길로 나타낸 그림"}, {"heading": "기행문 한 문단 읽어 보기", "paras": ["아래 글을 읽고 여정, 견문, 감상을 찾아보세요. 여정은 '~에 도착했다, ~로 이동했다', 견문은 '~이 보였다, ~라고 하셨다', 감상은 '~라고 느꼈다, ~ 신기했다' 같은 말에서 찾을 수 있어요."], "example": "점심을 먹고 버스를 타고 불국사로 향했다.(여정) 절 안으로 들어가니 대웅전 앞마당에 탑 두 개가 마주 서 있었다. 하나는 화려하게 장식된 다보탑이고, 다른 하나는 단정하고 반듯한 석가탑이었다.(견문) 같은 마당에 있는데도 두 탑의 모습이 이렇게 다르다는 것이 참 신기했다. 나는 꾸밈이 적은 석가탑이 더 마음에 들었다.(감상)", "figure": "절 마당에 서로 다른 모양의 두 석탑이 마주 서 있는 모습"}, {"heading": "생생한 기행문을 쓰는 방법", "paras": ["여행하면서 짧게라도 메모하고 사진을 찍어 두면 나중에 글을 쓸 때 큰 도움이 돼요. 안내판이나 안내 책자의 내용도 기록해 두세요.", "견문은 눈에 보이는 모습뿐 아니라 소리, 냄새, 맛까지 자세히 쓰면 생생해져요. 감상은 '좋았다, 재미있었다'로 끝내지 말고 왜 그렇게 느꼈는지 함께 써요.", "글을 다 쓰면 여정·견문·감상이 골고루 들어갔는지, 여정의 차례가 바른지 확인하며 고쳐 써요."], "example": "밋밋한 감상: 바다가 좋았다.\n생생한 감상: 철썩이는 파도 소리를 들으며 짭짤한 바닷바람을 맞으니 가슴속까지 시원해지는 것 같았다.", "figure": "바닷가 바위에 앉아 수첩에 메모하는 아이의 손과 파도"}], "keywords": [{"word": "기행문", "meaning": "여행하면서 보고 듣고 겪은 일과 생각·느낌을 쓴 글"}, {"word": "여정", "meaning": "여행한 차례나 과정"}, {"word": "견문", "meaning": "여행하면서 보거나 들은 것"}, {"word": "감상", "meaning": "보고 들은 것에 대한 생각이나 느낌"}, {"word": "해설사", "meaning": "관광지나 문화재에서 그곳에 대해 설명해 주는 사람"}], "expressions": [], "quiz": [{"q": "기행문의 세 요소가 __아닌__ 것은?", "choices": ["여정", "견문", "감상", "주장"], "answer": 3, "explain": "기행문의 세 요소는 여정, 견문, 감상이에요. 주장은 논설문의 요소예요."}, {"q": "\"오후 두 시쯤 배를 타고 섬에 도착했다.\"는 기행문의 어떤 요소일까요?", "choices": ["여정", "견문", "감상", "다짐"], "answer": 0, "explain": "언제, 어디로 이동했는지를 나타내므로 여정이에요."}, {"q": "\"등대 아래에서 바라본 바다는 하늘과 맞닿아 끝이 보이지 않았다.\"는 어떤 요소일까요?", "choices": ["여정", "견문", "감상", "까닭"], "answer": 1, "explain": "여행하며 본 모습을 나타내므로 견문이에요."}, {"q": "기행문의 '끝' 부분에 들어갈 내용으로 알맞은 것은?", "choices": ["여행을 떠나게 된 까닭", "출발할 때의 설레는 마음", "첫 번째 장소에서 본 것", "여행을 마치며 든 전체적인 생각과 느낌"], "answer": 3, "explain": "끝부분에는 여행 전체에 대한 생각과 느낌, 다짐을 써요."}], "summary": ["기행문은 여행하며 보고 듣고 겪은 일과 생각·느낌을 쓴 글이에요.", "기행문에는 여정(여행 차례), 견문(보고 들은 것), 감상(생각과 느낌)이 골고루 들어가요.", "처음 – 가운데 – 끝 짜임으로, 여정의 차례에 따라 문단을 나누어 써요."], "parent_tip": "아이들은 기행문을 \"어디 가서 뭐 했다\"는 여정 위주로만 쓰기 쉽습니다. 여행 중에 \"여기서 무슨 소리가 들려?\", \"이걸 보니 어떤 생각이 들어?\"처럼 견문과 감상을 끌어내는 질문을 해 주세요. 사진을 찍을 때 아이에게 한 줄 메모를 함께 남기게 하면 글쓰기가 훨씬 쉬워집니다. 먼 여행이 아니어도 동네 시장이나 공원 나들이로 충분히 연습할 수 있습니다."}$j$::jsonb,9) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','기행문 쓰기',9,'k5-09' where not exists (select 1 from public.topics where lesson_slug='k5-09');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('k5-10','5~6','국어','인물의 삶과 가치','이야기 속 인물은 무엇을 소중하게 여겼을까?','assets/img/l_k5-10.jpg',$j${"intro": "이야기를 읽고 나면 어떤 인물은 오래도록 마음에 남아요. 그 인물이 왜 그렇게 말하고 행동했는지 따라가 보면, 그 사람이 가장 소중하게 여긴 것, 곧 '추구하는 가치'를 발견할 수 있어요.", "sections": [{"heading": "가치란 무엇일까요?", "paras": ["가치는 사람이 살아가면서 소중하고 중요하다고 여기는 것이에요. 정직, 배려, 책임, 용기, 나눔, 성실, 우정, 자유, 평화 등이 있어요.", "사람마다 중요하게 여기는 가치가 달라서 같은 상황에서도 다르게 행동해요.", "인물이 추구하는 가치를 알면 그 인물의 삶을 더 깊이 이해할 수 있어요."], "example": "길에서 지갑을 주웠을 때: 정직을 중요하게 여기는 사람은 바로 주인을 찾아 주거나 경찰서에 맡겨요.", "figure": "정직, 배려, 용기, 나눔 같은 가치를 각각 작은 그림 아이콘(손잡은 손, 하트, 방패 등)으로 나타낸 카드"}, {"heading": "인물의 말과 행동에서 가치를 찾아요", "paras": ["이야기에서 인물이 추구하는 가치는 직접 쓰여 있지 않을 때가 많아요. 인물의 말, 행동, 그리고 인물이 처한 상황을 살펴서 알아내야 해요.", "특히 인물이 어려운 선택을 해야 할 때 무엇을 고르는지 보면 가치가 잘 드러나요. 손해를 보더라도 지키려는 것이 그 인물이 가장 소중히 여기는 가치예요.", "가치를 찾을 때는 '인물이 처한 상황 → 인물의 말과 행동 → 그렇게 한 까닭 → 추구하는 가치'의 차례로 생각해요."], "example": "상황: 달리기 대회에서 앞서 달리던 친구가 넘어졌다. / 행동: 주인공은 멈추어 친구를 일으켜 주었다. / 까닭: 1등보다 친구가 더 중요했다. / 가치: 배려, 우정", "figure": "달리기 트랙에서 넘어진 친구에게 손을 내미는 아이"}, {"heading": "이야기 읽고 가치 찾기", "paras": ["아래 이야기를 읽고 주인공 은호가 무엇을 소중하게 여겼는지 생각해 보세요."], "example": "〈약속의 화분〉\n은호네 반은 봄에 강낭콩을 심고, 방학 동안 한 사람씩 돌아가며 화분을 집에 가져가 돌보기로 했다. 은호의 차례가 된 주에 가족 여행이 잡혔다. 동생이 말했다.\n\"형, 그냥 베란다에 두고 가. 며칠 물 안 줘도 괜찮겠지.\"\n은호는 잠시 고민하다가 고개를 저었다.\n\"내가 맡겠다고 약속했잖아. 이 화분은 우리 반 모두의 거야.\"\n은호는 옆집 할머니께 사정을 말씀드리고 물 주는 방법을 적은 쪽지를 드렸다. 여행에서 돌아온 날, 강낭콩 줄기에는 하얀 꽃이 피어 있었다.\n→ 은호가 추구한 가치: 책임(맡은 일을 끝까지 지킴), 약속을 지키는 신뢰", "figure": "현관 앞에서 옆집 할머니께 강낭콩 화분과 쪽지를 건네는 아이"}, {"heading": "전기문 속 인물의 삶", "paras": ["전기문은 실제로 살았던 인물의 삶과 업적을 사실에 바탕을 두고 쓴 글이에요. 전기문에는 인물이 살았던 시대 상황, 인물이 한 일, 인물에 대한 글쓴이의 평가가 들어 있어요.", "전기문을 읽을 때는 인물이 살던 시대가 어떤 모습이었는지, 그 시대에 인물이 어떤 어려움을 이겨 내고 무엇을 이루었는지 살펴요.", "그러면 인물이 추구한 가치가 그 시대에 왜 중요했는지, 오늘날 우리에게는 어떤 의미가 있는지 생각해 볼 수 있어요."], "example": "전기문을 읽고 정리하는 틀: 시대 상황 / 인물이 겪은 어려움 / 인물이 한 일 / 추구한 가치 / 오늘날 나에게 주는 의미", "figure": "오래된 책을 펼쳐 놓고 표에 내용을 정리하는 아이의 손"}, {"heading": "인물의 가치와 내 삶을 비교해요", "paras": ["인물이 추구한 가치를 찾았다면 '나라면 어떻게 했을까?' 하고 내 삶과 비교해 보세요.", "인물의 가치에 공감하는 부분도 있고, 생각이 다른 부분도 있을 수 있어요. 중요한 것은 그 까닭을 들어 내 생각을 말하는 것이에요.", "인물의 삶에서 본받을 점을 찾아 내 생활에서 실천할 점을 정하면, 이야기 읽기가 나를 자라게 하는 시간이 돼요."], "example": "나라면: 나도 은호처럼 약속을 지켰을 것 같다. 하지만 부탁하는 것이 어려워서 고민을 많이 했을 것이다.\n실천할 점: 모둠 활동에서 맡은 역할을 끝까지 책임지겠다.", "figure": "거울을 보며 미소 짓는 아이와 그 옆의 다짐 쪽지"}], "keywords": [{"word": "가치", "meaning": "사람이 살아가면서 소중하고 중요하다고 여기는 것"}, {"word": "추구하다", "meaning": "목적한 것을 이루려고 끝까지 좇아 구하다"}, {"word": "전기문", "meaning": "실제 인물의 삶과 업적을 사실에 바탕을 두고 쓴 글"}, {"word": "업적", "meaning": "어떤 일을 하여 이루어 낸 훌륭한 결과"}, {"word": "공감", "meaning": "남의 생각이나 느낌에 대해 나도 그렇다고 느끼는 것"}], "expressions": [], "quiz": [{"q": "인물이 추구하는 가치를 알아보는 방법으로 가장 알맞은 것은?", "choices": ["인물의 옷차림만 살펴본다.", "인물이 처한 상황에서 한 말과 행동을 살펴본다.", "이야기의 제목 글자 수를 센다.", "등장인물의 수를 센다."], "answer": 1, "explain": "인물의 말과 행동, 특히 어려운 선택을 할 때 무엇을 고르는지에서 가치가 드러나요."}, {"q": "〈약속의 화분〉에서 은호가 여행 전에 옆집 할머니께 화분을 부탁한 까닭은?", "choices": ["화분이 무거워서", "할머니가 꽃을 좋아하셔서", "반 친구들과 한 약속을 지키고 맡은 일에 책임을 다하려고", "동생과 다투기 싫어서"], "answer": 2, "explain": "은호는 '내가 맡겠다고 약속했잖아.'라며 책임을 다하려고 했어요."}, {"q": "전기문에 대한 설명으로 알맞은 것은?", "choices": ["실제 인물의 삶과 업적을 사실에 바탕을 두고 쓴 글이다.", "상상으로 꾸며 낸 동물 이야기이다.", "여행하며 보고 들은 것을 쓴 글이다.", "주장과 근거를 들어 설득하는 글이다."], "answer": 0, "explain": "전기문은 실제로 살았던 인물의 삶을 사실에 바탕을 두고 써요."}, {"q": "\"용돈을 모아 어려운 이웃을 위해 기부했다.\"는 행동에서 찾을 수 있는 가치는?", "choices": ["경쟁", "나눔", "절약", "자유"], "answer": 1, "explain": "자기 것을 어려운 이웃과 나누었으므로 나눔의 가치를 추구했어요."}, {"q": "인물의 가치와 내 삶을 비교하는 태도로 알맞은 것은?", "choices": ["인물과 생각이 다르면 틀린 것이다.", "인물의 행동을 그대로 따라 해야만 한다.", "까닭을 들어 공감하는 점과 다른 점을 말하고 본받을 점을 찾는다.", "내 생각은 말하지 않는다."], "answer": 2, "explain": "까닭을 들어 내 생각을 말하고 실천할 점을 찾는 것이 바람직해요."}], "summary": ["가치는 사람이 소중하고 중요하다고 여기는 것이에요(정직, 배려, 책임, 용기, 나눔 등).", "인물이 처한 상황과 그때의 말과 행동, 특히 어려운 선택을 살펴 추구하는 가치를 찾아요.", "인물의 가치를 내 삶과 비교해 공감하는 점과 본받을 점을 찾아 실천해요."], "parent_tip": "아이들은 가치를 물으면 '착하다', '좋다'처럼 막연하게 답하는 경우가 많습니다. \"착하다는 말 대신 더 정확한 낱말(정직, 배려, 책임 등)로 말해 볼까?\"라고 이끌어 주세요. 함께 읽은 책이나 본 영화 속 인물에 대해 \"너라면 어떻게 했을 것 같아? 왜?\"라고 묻는 대화가 가장 좋은 공부입니다."}$j$::jsonb,10) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '5~6','국어','인물의 삶과 가치',10,'k5-10' where not exists (select 1 from public.topics where lesson_slug='k5-10');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-01','1~2','수학','9까지의 수','하나, 둘, 셋! 9까지 셀 수 있을까?','assets/img/l_m1-01.jpg',$j${"intro": "🍎 사과가 몇 개일까요? 손가락으로 하나씩 짚으며 세어 봐요. 오늘은 9까지 세는 법을 배워요.", "sections": [{"heading": "하나씩 짚으며 세어요", "paras": ["물건을 하나씩 짚어요.", "짚을 때마다 수를 하나씩 말해요.", "마지막에 말한 수가 전체 개수예요."], "example": "🍎🍎🍎 → 하나, 둘, 셋 → 3개", "figure": "책상 위 사과 세 개를 아이 손가락이 하나씩 짚는 모습"}, {"heading": "수는 두 가지로 읽어요", "paras": ["1은 '하나' 또는 '일'이라고 읽어요.", "개수를 셀 때는 하나, 둘, 셋으로 읽어요.", "아무것도 없으면 0(영)이에요."], "example": "1 하나·일, 2 둘·이, 3 셋·삼, 4 넷·사, 5 다섯·오, 6 여섯·육, 7 일곱·칠, 8 여덟·팔, 9 아홉·구", "figure": "1부터 9까지 수 카드 옆에 같은 개수의 구슬이 놓인 모습"}, {"heading": "몇째인지 말해요", "paras": ["줄을 선 차례는 '째'를 붙여 말해요.", "첫째, 둘째, 셋째, 넷째, 다섯째……", "어느 쪽부터 세는지 꼭 봐요."], "example": "🐰🐶🐱 → 왼쪽부터 첫째 🐰, 둘째 🐶, 셋째 🐱", "figure": "장난감 동물 인형이 한 줄로 서 있는 모습"}, {"heading": "이렇게 풀어요: 1 큰 수, 1 작은 수", "paras": ["수를 순서대로 써 봐요.", "바로 뒤의 수가 1 큰 수예요.", "바로 앞의 수가 1 작은 수예요."], "example": "① 4, 5, 6을 써요. ② 5 바로 뒤는 6 → 5보다 1 큰 수는 6 ③ 5 바로 앞은 4 → 5보다 1 작은 수는 4", "figure": "1부터 9까지 놓인 수 카드에서 5 양옆의 4와 6을 손가락으로 가리키는 모습"}], "keywords": [{"word": "세기", "meaning": "물건이 몇 개인지 하나씩 수를 말하는 것"}, {"word": "0(영)", "meaning": "아무것도 없을 때 쓰는 수"}, {"word": "몇째", "meaning": "줄을 선 차례를 말하는 말(첫째, 둘째……)"}, {"word": "1 큰 수", "meaning": "순서대로 셀 때 바로 뒤에 오는 수"}, {"word": "1 작은 수", "meaning": "순서대로 셀 때 바로 앞에 오는 수"}], "quiz": [{"q": "🐟🐟🐟🐟🐟🐟 물고기는 몇 마리일까요?", "choices": ["5", "6", "7", "8"], "answer": 1, "explain": "하나씩 짚으며 세면 하나, 둘, 셋, 넷, 다섯, 여섯이에요."}, {"q": "7을 바르게 읽은 것은?", "choices": ["여섯", "여덟", "일곱", "아홉"], "answer": 2, "explain": "7은 '일곱' 또는 '칠'이라고 읽어요."}, {"q": "🍪 접시에 과자가 하나도 없어요. 수로 쓰면?", "choices": ["0", "1", "9", "10"], "answer": 0, "explain": "아무것도 없을 때는 0이라고 써요."}, {"q": "8보다 1 큰 수는?", "choices": ["7", "6", "10", "9"], "answer": 3, "explain": "8 바로 뒤에 오는 수는 9예요."}, {"q": "🐻🐼🐨🐯 왼쪽부터 둘째에 있는 동물은?", "choices": ["🐻", "🐼", "🐨", "🐯"], "answer": 1, "explain": "왼쪽부터 첫째 🐻, 둘째 🐼예요."}], "summary": ["물건을 하나씩 짚으며 세고, 마지막 수가 개수예요.", "수는 '하나·일'처럼 두 가지로 읽고, 아무것도 없으면 0이에요.", "바로 뒤의 수는 1 큰 수, 바로 앞의 수는 1 작은 수예요."], "parent_tip": "아이들은 같은 물건을 두 번 세거나 빼먹는 실수를 자주 합니다. 센 물건을 옆으로 옮기며 세게 해 주세요. 계단을 오르며 '몇째 계단이야?', 식탁에서 '숟가락이 몇 개 필요할까?'처럼 생활 속에서 자주 물어봐 주세요.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-01_cover.mp3", "s0": "assets/audio/n/m1-01_s0.mp3", "s1": "assets/audio/n/m1-01_s1.mp3", "s2": "assets/audio/n/m1-01_s2.mp3", "s3": "assets/audio/n/m1-01_s3.mp3", "kw": "assets/audio/n/m1-01_kw.mp3", "q0": "assets/audio/n/m1-01_q0.mp3", "q1": "assets/audio/n/m1-01_q1.mp3", "q2": "assets/audio/n/m1-01_q2.mp3", "q3": "assets/audio/n/m1-01_q3.mp3", "q4": "assets/audio/n/m1-01_q4.mp3", "sum": "assets/audio/n/m1-01_sum.mp3"}}$j$::jsonb,1) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','9까지의 수',1,'m1-01' where not exists (select 1 from public.topics where lesson_slug='m1-01');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-02','1~2','수학','여러 가지 모양','상자, 공, 세모, 네모! 어떤 모양일까?','assets/img/l_m1-02.jpg',$j${"intro": "📦 상자, ⚽ 공, 🥫 캔. 우리 집 물건은 어떤 모양일까요? 손으로 만져 보며 모양을 찾아봐요.", "sections": [{"heading": "상자 모양, 둥근기둥 모양, 공 모양", "paras": ["📦 상자 모양은 평평한 부분만 있어요.", "🥫 둥근기둥 모양은 평평한 부분과 둥근 부분이 있어요.", "⚽ 공 모양은 모든 부분이 둥글어요."], "example": "📦 휴지 상자·🎲 주사위 → 상자 모양 / 🥫 캔·🧻 두루마리 휴지 → 둥근기둥 모양 / ⚽ 공·🍊 귤 → 공 모양", "figure": "책상 위에 상자, 음료 캔, 공이 나란히 놓인 모습"}, {"heading": "쌓아 보고 굴려 봐요", "paras": ["📦 상자 모양은 잘 쌓이고 굴러가지 않아요.", "🥫 둥근기둥 모양은 세우면 쌓을 수 있고, 눕히면 굴러가요.", "⚽ 공 모양은 어느 쪽으로도 잘 굴러가서 쌓기 어려워요."], "example": "블록 탑을 쌓을 때는 📦 상자 모양이 가장 좋아요.", "figure": "아이가 상자를 쌓고, 옆에서 공이 굴러가는 모습"}, {"heading": "□ △ ○ 모양", "paras": ["물건을 종이에 대고 본뜨면 평평한 모양이 나와요.", "네모(□), 세모(△), 동그라미(○) 모양이에요.", "□는 사각형, △는 삼각형, ○는 원이라고 불러요."], "example": "📦 상자 바닥을 본뜨면 □, 🥫 캔 바닥을 본뜨면 ○", "figure": "종이 위에 컵 바닥을 대고 연필로 동그라미를 따라 그리는 아이 손"}, {"heading": "이렇게 풀어요: 변과 꼭짓점 세기", "paras": ["곧은 선을 '변'이라고 해요.", "두 변이 만나는 뾰족한 점을 '꼭짓점'이라고 해요.", "하나씩 표시하며 세면 빠뜨리지 않아요."], "example": "① 삼각형의 곧은 선에 ✔ 표시 → 3개 ② 뾰족한 점에 ● 표시 → 3개 ③ 삼각형: 변 3개, 꼭짓점 3개 (사각형은 변 4개, 꼭짓점 4개 / 원은 변과 꼭짓점이 없어요)", "figure": "색종이로 오린 삼각형과 사각형의 꼭짓점에 스티커를 붙인 모습"}], "keywords": [{"word": "상자 모양", "meaning": "평평한 부분만 있어 잘 쌓이는 모양"}, {"word": "둥근기둥 모양", "meaning": "평평한 부분과 둥근 부분이 있는 모양"}, {"word": "공 모양", "meaning": "모든 부분이 둥글어 잘 굴러가는 모양"}, {"word": "변", "meaning": "도형을 이루는 곧은 선"}, {"word": "꼭짓점", "meaning": "두 변이 만나는 뾰족한 점"}], "quiz": [{"q": "🎲 주사위는 어떤 모양일까요?", "choices": ["공 모양", "상자 모양", "둥근기둥 모양", "○ 모양"], "answer": 1, "explain": "주사위는 평평한 부분만 있는 상자 모양이에요."}, {"q": "어느 쪽으로 굴려도 잘 굴러가는 모양은?", "choices": ["📦 상자 모양", "🥫 둥근기둥 모양", "⚽ 공 모양", "△ 모양"], "answer": 2, "explain": "공 모양은 모든 부분이 둥글어서 어느 쪽으로도 잘 굴러가요."}, {"q": "🥫 캔 바닥을 종이에 대고 따라 그리면 어떤 모양이 나올까요?", "choices": ["○ 모양", "△ 모양", "□ 모양", "상자 모양"], "answer": 0, "explain": "캔 바닥은 둥글어서 ○ 모양이 나와요."}, {"q": "삼각형의 꼭짓점은 몇 개일까요?", "choices": ["2개", "4개", "5개", "3개"], "answer": 3, "explain": "삼각형은 뾰족한 꼭짓점이 3개예요."}], "summary": ["📦 상자 모양은 잘 쌓이고, ⚽ 공 모양은 잘 굴러가요.", "🥫 둥근기둥 모양은 세우면 쌓이고 눕히면 굴러가요.", "삼각형은 변·꼭짓점 3개, 사각형은 4개, 원은 없어요."], "parent_tip": "아이들은 모양을 색깔이나 크기로 구분하려는 경우가 많습니다. '평평한 곳이 있니? 굴러가니?'처럼 성질로 묻게 해 주세요. 집 안에서 상자·캔·공 모양 물건을 찾아 모아 보고, 직접 쌓고 굴려 보게 하면 오래 기억합니다.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-02_cover.mp3", "s0": "assets/audio/n/m1-02_s0.mp3", "s1": "assets/audio/n/m1-02_s1.mp3", "s2": "assets/audio/n/m1-02_s2.mp3", "s3": "assets/audio/n/m1-02_s3.mp3", "kw": "assets/audio/n/m1-02_kw.mp3", "q0": "assets/audio/n/m1-02_q0.mp3", "q1": "assets/audio/n/m1-02_q1.mp3", "q2": "assets/audio/n/m1-02_q2.mp3", "q3": "assets/audio/n/m1-02_q3.mp3", "sum": "assets/audio/n/m1-02_sum.mp3"}}$j$::jsonb,2) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','여러 가지 모양',2,'m1-02' where not exists (select 1 from public.topics where lesson_slug='m1-02');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-03','1~2','수학','덧셈과 뺄셈(한 자리 수)','더하면 몇 개? 빼면 몇 개?','assets/img/l_m1-03.jpg',$j${"intro": "🍓 딸기 2개에 3개를 더 받으면 몇 개일까요? 먹고 나면 몇 개가 남을까요? 오늘은 덧셈과 뺄셈을 배워요.", "sections": [{"heading": "모으기와 가르기", "paras": ["두 수를 합치는 것을 '모으기'라고 해요.", "한 수를 두 수로 나누는 것을 '가르기'라고 해요."], "example": "🍓🍓 와 🍓🍓🍓 를 모으면 🍓🍓🍓🍓🍓 (5) / 5는 1과 4, 2와 3으로 가를 수 있어요.", "figure": "접시 두 개에 나뉜 딸기를 한 접시로 모으는 아이 손"}, {"heading": "더하기: 합치면 늘어나요", "paras": ["더할 때는 '+'를 써요.", "'2 더하기 3은 5와 같아요'라고 읽어요.", "어떤 수에 0을 더하면 그대로예요."], "example": "🐥🐥 + 🐥🐥🐥 → 2 + 3 = 5", "figure": "장난감 병아리 두 마리 옆으로 세 마리가 더 오는 모습"}, {"heading": "빼기: 덜어 내면 줄어요", "paras": ["뺄 때는 '−'를 써요.", "'5 빼기 2는 3과 같아요'라고 읽어요.", "누가 몇 개 더 많은지 알아볼 때도 빼요."], "example": "🍪🍪🍪🍪🍪 에서 2개를 먹으면 🍪🍪🍪 → 5 − 2 = 3", "figure": "쿠키 다섯 개 중 두 개를 집어 가는 손"}, {"heading": "이렇게 풀어요: 10을 만들어 더하기", "paras": ["8 + 5처럼 10이 넘을 때는 먼저 10을 만들어요.", "5를 2와 3으로 갈라요.", "8에 2를 더해 10, 남은 3을 더해 13이에요."], "example": "① 8 + 5 → 5를 2와 3으로 가르기 ② 8 + 2 = 10 ③ 10 + 3 = 13 → 8 + 5 = 13", "figure": "달걀판 10칸에 구슬 8개가 있고, 구슬 2개를 더 채운 뒤 3개가 옆에 놓인 모습"}], "keywords": [{"word": "모으기", "meaning": "두 수를 합쳐 하나의 수로 만드는 것"}, {"word": "가르기", "meaning": "한 수를 두 수로 나누는 것"}, {"word": "덧셈(+)", "meaning": "수를 더해 늘어난 수를 구하는 것"}, {"word": "뺄셈(−)", "meaning": "수를 덜어 내 남은 수나 차이를 구하는 것"}, {"word": "=", "meaning": "'~와 같아요'라는 뜻의 기호"}], "quiz": [{"q": "🐟🐟🐟🐟 + 🐟🐟 물고기는 모두 몇 마리일까요?", "choices": ["5", "6", "7", "2"], "answer": 1, "explain": "4 + 2 = 6이에요."}, {"q": "🎈 풍선 5개 중 3개가 터졌어요. 남은 풍선은?", "choices": ["8", "3", "2", "1"], "answer": 2, "explain": "5 − 3 = 2예요."}, {"q": "6을 두 수로 바르게 가른 것은?", "choices": ["2와 4", "3과 4", "1과 4", "5와 2"], "answer": 0, "explain": "2와 4를 모으면 6이에요."}, {"q": "7 + 0은 얼마일까요?", "choices": ["0", "1", "8", "7"], "answer": 3, "explain": "0을 더하면 수가 그대로예요."}, {"q": "7 + 4를 할 때 10을 만들려면 4를 어떻게 가를까요?", "choices": ["2와 2", "3과 1", "4와 0", "2와 1"], "answer": 1, "explain": "7에 3을 더하면 10이 돼요. 4를 3과 1로 가르면 10 + 1 = 11이에요."}], "summary": ["두 수를 합치면 모으기, 나누면 가르기예요.", "더하면 늘어나고(+), 빼면 줄어들어요(−).", "10이 넘을 때는 먼저 10을 만들어 더해요."], "parent_tip": "처음에는 손가락이나 바둑돌로 직접 세게 하고, 익숙해지면 머릿속으로 하게 해 주세요. '5는 무엇과 무엇으로 가를 수 있을까?' 같은 가르기 놀이가 덧셈·뺄셈의 기초가 됩니다. 간식을 나눠 먹으며 '몇 개 남았지?'라고 묻는 것도 좋습니다.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-03_cover.mp3", "s0": "assets/audio/n/m1-03_s0.mp3", "s1": "assets/audio/n/m1-03_s1.mp3", "s2": "assets/audio/n/m1-03_s2.mp3", "s3": "assets/audio/n/m1-03_s3.mp3", "kw": "assets/audio/n/m1-03_kw.mp3", "q0": "assets/audio/n/m1-03_q0.mp3", "q1": "assets/audio/n/m1-03_q1.mp3", "q2": "assets/audio/n/m1-03_q2.mp3", "q3": "assets/audio/n/m1-03_q3.mp3", "q4": "assets/audio/n/m1-03_q4.mp3", "sum": "assets/audio/n/m1-03_sum.mp3"}}$j$::jsonb,3) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','덧셈과 뺄셈(한 자리 수)',3,'m1-03' where not exists (select 1 from public.topics where lesson_slug='m1-03');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-04','1~2','수학','비교하기(길이·무게·넓이)','누가 더 길고, 무겁고, 넓을까?','assets/img/l_m1-04.jpg',$j${"intro": "✏️ 연필과 🖍️ 크레파스, 어느 것이 더 길까요? 🍉 수박과 🍎 사과는 어느 것이 더 무거울까요? 오늘은 비교하는 방법을 배워요.", "sections": [{"heading": "길이 비교: 끝을 맞춰요", "paras": ["길이를 비교할 때는 한쪽 끝을 맞춰요.", "다른 쪽 끝이 더 나온 것이 더 길어요.", "키는 발끝을 맞추고 서서 비교해요."], "example": "✏️ 연필과 🖍️ 크레파스의 왼쪽 끝을 맞추면 연필이 더 나와요 → 연필이 더 길어요.", "figure": "책상 위에 연필과 크레파스를 왼쪽 끝을 맞춰 나란히 놓은 모습"}, {"heading": "무게 비교: 들어 보고 달아 봐요", "paras": ["두 손에 하나씩 들어 보면 무게를 느낄 수 있어요.", "시소나 양팔 저울에서는 아래로 내려간 쪽이 더 무거워요."], "example": "🍉 수박과 🍎 사과를 양팔 저울에 올리면 수박 쪽이 내려가요 → 수박이 더 무거워요.", "figure": "장난감 양팔 저울에 큰 과일과 작은 과일이 올라가 한쪽이 기울어진 모습"}, {"heading": "넓이 비교: 겹쳐 봐요", "paras": ["넓이는 겹쳐 보면 알 수 있어요.", "겹쳤을 때 남는 부분이 있는 쪽이 더 넓어요.", "남는 부분이 없으면 더 좁아요."], "example": "📒 공책 위에 우표를 올리면 공책이 많이 남아요 → 공책이 더 넓어요.", "figure": "공책 위에 작은 메모지를 겹쳐 놓은 모습"}, {"heading": "이렇게 풀어요: 클립으로 재어 비교하기", "paras": ["끝을 맞추기 어려우면 같은 물건으로 재어요.", "클립 몇 개만큼인지 세어 봐요.", "클립 수가 많을수록 더 길어요."], "example": "① 줄 가: 클립 5개, 줄 나: 클립 8개 ② 8이 5보다 커요. ③ 줄 나가 더 길어요. 8 − 5 = 3이니 클립 3개만큼 더 길어요.", "figure": "끈 두 줄 옆에 종이 클립을 줄지어 놓아 길이를 잰 모습"}], "keywords": [{"word": "길다·짧다", "meaning": "길이를 비교할 때 쓰는 말"}, {"word": "무겁다·가볍다", "meaning": "무게를 비교할 때 쓰는 말"}, {"word": "넓다·좁다", "meaning": "넓이를 비교할 때 쓰는 말"}, {"word": "가장", "meaning": "여러 개 중에서 제일이라는 뜻(가장 길다, 가장 무겁다)"}], "quiz": [{"q": "길이를 비교할 때 먼저 할 일은?", "choices": ["한쪽 끝을 맞춰요", "색을 비교해요", "무게를 들어 봐요", "눈을 감아요"], "answer": 0, "explain": "한쪽 끝을 맞춰야 다른 쪽 끝을 보고 비교할 수 있어요."}, {"q": "시소에서 🐻 곰 쪽이 아래로 내려갔어요. 더 무거운 쪽은?", "choices": ["🐰 토끼", "🐻 곰", "똑같아요", "알 수 없어요"], "answer": 1, "explain": "아래로 내려간 쪽이 더 무거워요."}, {"q": "🚪 문과 📒 공책을 겹쳤을 때 문이 남았어요. 더 넓은 것은?", "choices": ["📒 공책", "똑같아요", "알 수 없어요", "🚪 문"], "answer": 3, "explain": "겹쳤을 때 남는 쪽이 더 넓어요."}, {"q": "줄 가는 클립 4개, 줄 나는 클립 7개 길이예요. 더 긴 줄은?", "choices": ["줄 가", "똑같아요", "줄 나", "알 수 없어요"], "answer": 2, "explain": "클립이 더 많이 필요한 줄 나가 더 길어요."}], "summary": ["길이는 한쪽 끝을 맞춰 비교해요.", "무게는 들어 보거나 저울에서 내려간 쪽이 더 무거워요.", "넓이는 겹쳐서 남는 쪽이 더 넓어요."], "parent_tip": "아이들은 '크다'라는 말을 길이·무게·넓이 모두에 쓰는 경우가 많습니다. '길다/무겁다/넓다'처럼 정확한 말로 바꿔 말하게 해 주세요. 큰 것이 늘 무겁지는 않다(풍선과 돌)는 것도 직접 들어 보며 느끼게 하면 좋습니다.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-04_cover.mp3", "s0": "assets/audio/n/m1-04_s0.mp3", "s1": "assets/audio/n/m1-04_s1.mp3", "s2": "assets/audio/n/m1-04_s2.mp3", "s3": "assets/audio/n/m1-04_s3.mp3", "kw": "assets/audio/n/m1-04_kw.mp3", "q0": "assets/audio/n/m1-04_q0.mp3", "q1": "assets/audio/n/m1-04_q1.mp3", "q2": "assets/audio/n/m1-04_q2.mp3", "q3": "assets/audio/n/m1-04_q3.mp3", "sum": "assets/audio/n/m1-04_sum.mp3"}}$j$::jsonb,4) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','비교하기(길이·무게·넓이)',4,'m1-04' where not exists (select 1 from public.topics where lesson_slug='m1-04');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-05','1~2','수학','100까지의 수','10개씩 묶어 세면 100까지 셀 수 있어요!','assets/img/l_m1-05.jpg',$j${"intro": "🍬 사탕이 아주 많아요. 하나씩 세면 헷갈리죠? 10개씩 묶어 세면 100까지도 쉽게 셀 수 있어요.", "sections": [{"heading": "10개씩 묶어요", "paras": ["10개를 한 묶음으로 묶어요.", "10개씩 묶음이 몇 개인지 세면 빨라요."], "example": "10개씩 묶음 2개 → 20 / 10개씩 묶음 5개 → 50", "figure": "빨대를 10개씩 고무줄로 묶어 책상 위에 늘어놓은 모습"}, {"heading": "몇십은 두 가지로 읽어요", "paras": ["20은 '이십' 또는 '스물'이라고 읽어요.", "개수를 셀 때는 스물, 서른처럼 읽어요."], "example": "10 십·열, 20 이십·스물, 30 삼십·서른, 40 사십·마흔, 50 오십·쉰, 60 육십·예순, 70 칠십·일흔, 80 팔십·여든, 90 구십·아흔, 100 백", "figure": "10개씩 묶은 빨대 묶음 옆에 수 카드가 놓인 모습"}, {"heading": "이렇게 풀어요: 묶음과 낱개로 쓰기", "paras": ["먼저 10개씩 묶음을 세요.", "남은 낱개를 세요.", "묶음 수를 앞에, 낱개 수를 뒤에 써요."], "example": "① 🍬 10개씩 묶음 3개 ② 낱개 6개 ③ 36 (삼십육, 서른여섯)", "figure": "사탕 봉지 3개와 낱개 사탕 6개가 놓인 모습"}, {"heading": "크기 비교와 짝수·홀수", "paras": ["10개씩 묶음 수가 큰 쪽이 더 커요.", "묶음 수가 같으면 낱개 수를 비교해요.", "둘씩 짝을 지어 남는 것이 없으면 짝수, 하나 남으면 홀수예요."], "example": "42 < 51 (묶음 4 < 5) / 38 > 35 (낱개 8 > 5) / 짝수: 2, 4, 6, 8, 10 / 홀수: 1, 3, 5, 7, 9", "figure": "양말을 둘씩 짝지어 놓았는데 한 짝이 남은 모습"}], "keywords": [{"word": "10개씩 묶음", "meaning": "10개를 한 덩어리로 묶은 것"}, {"word": "낱개", "meaning": "묶음에 들어가지 않고 하나씩 남은 것"}, {"word": "100(백)", "meaning": "99보다 1 큰 수, 10개씩 묶음 10개"}, {"word": "짝수", "meaning": "둘씩 짝을 지을 때 남는 것이 없는 수"}, {"word": "홀수", "meaning": "둘씩 짝을 지을 때 하나가 남는 수"}], "quiz": [{"q": "10개씩 묶음 4개는 얼마일까요?", "choices": ["4", "14", "40", "400"], "answer": 2, "explain": "10개씩 묶음 4개는 40이에요."}, {"q": "80을 바르게 읽은 것은?", "choices": ["여든", "아흔", "예순", "일흔"], "answer": 0, "explain": "80은 '팔십' 또는 '여든'이라고 읽어요."}, {"q": "10개씩 묶음 6개와 낱개 2개는?", "choices": ["26", "62", "8", "602"], "answer": 1, "explain": "묶음 수 6을 앞에, 낱개 2를 뒤에 써서 62예요."}, {"q": "둘 중 더 큰 수는? 57 , 75", "choices": ["57", "똑같아요", "알 수 없어요", "75"], "answer": 3, "explain": "10개씩 묶음이 7개인 75가 더 커요."}, {"q": "🧦 양말 9짝을 둘씩 짝지었더니 1짝이 남았어요. 9는?", "choices": ["짝수", "홀수", "몇십", "100"], "answer": 1, "explain": "하나가 남으니 9는 홀수예요."}], "summary": ["10개씩 묶음과 낱개로 두 자리 수를 나타내요.", "몇십은 '이십·스물'처럼 두 가지로 읽고, 99 다음은 100이에요.", "묶음 수부터 비교하고, 같으면 낱개를 비교해요."], "parent_tip": "아이들은 '서른여섯'을 '306'처럼 쓰는 실수를 자주 합니다. 빨대나 면봉을 10개씩 고무줄로 묶어 직접 묶음과 낱개를 만들어 보게 해 주세요. 엘리베이터 층수, 달력 날짜를 보며 '어느 수가 더 클까?'를 묻는 것도 좋습니다.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-05_cover.mp3", "s0": "assets/audio/n/m1-05_s0.mp3", "s1": "assets/audio/n/m1-05_s1.mp3", "s2": "assets/audio/n/m1-05_s2.mp3", "s3": "assets/audio/n/m1-05_s3.mp3", "kw": "assets/audio/n/m1-05_kw.mp3", "q0": "assets/audio/n/m1-05_q0.mp3", "q1": "assets/audio/n/m1-05_q1.mp3", "q2": "assets/audio/n/m1-05_q2.mp3", "q3": "assets/audio/n/m1-05_q3.mp3", "q4": "assets/audio/n/m1-05_q4.mp3", "sum": "assets/audio/n/m1-05_sum.mp3"}}$j$::jsonb,5) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','100까지의 수',5,'m1-05' where not exists (select 1 from public.topics where lesson_slug='m1-05');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-06','1~2','수학','두 자리 수의 덧셈과 뺄셈','두 자리 수, 어떻게 더하고 뺄까?','assets/img/l_m1-06.jpg',$j${"intro": "🚌 버스에 32명이 타고 있는데 15명이 더 탔어요. 모두 몇 명일까요? 두 자리 수도 차근차근 더하고 뺄 수 있어요.", "sections": [{"heading": "같은 자리끼리 계산해요", "paras": ["두 자리 수는 십의 자리와 일의 자리가 있어요.", "일의 자리는 일의 자리끼리, 십의 자리는 십의 자리끼리 계산해요."], "example": "32 + 15 → 일의 자리 2 + 5 = 7, 십의 자리 3 + 1 = 4 → 47", "figure": "10개씩 묶은 빨대 묶음과 낱개 빨대를 두 줄로 나란히 놓은 모습"}, {"heading": "이렇게 풀어요: 받아올림이 있는 덧셈", "paras": ["일의 자리 합이 10이 넘으면 10을 십의 자리로 올려요.", "올린 1을 십의 자리 계산에 꼭 더해요."], "example": "38 + 25 ① 일의 자리 8 + 5 = 13 → 3을 쓰고 1을 올려요 ② 십의 자리 1 + 3 + 2 = 6 ③ 답 63", "figure": "공책에 세로셈을 쓰고 십의 자리 위에 작은 1을 적은 모습"}, {"heading": "이렇게 풀어요: 받아내림이 있는 뺄셈", "paras": ["일의 자리에서 뺄 수 없으면 십의 자리에서 10을 빌려 와요.", "빌려 준 십의 자리는 1 작아져요."], "example": "52 − 27 ① 2에서 7을 뺄 수 없어요 ② 십의 자리에서 10을 빌려 12 − 7 = 5 ③ 십의 자리 4 − 2 = 2 ④ 답 25", "figure": "빨대 묶음 하나를 풀어 낱개 10개로 만드는 아이 손"}, {"heading": "덧셈과 뺄셈은 짝꿍이에요", "paras": ["덧셈식으로 뺄셈식을 만들 수 있어요.", "뺄셈을 하고 나서 덧셈으로 맞는지 확인해요."], "example": "25 + 27 = 52 ↔ 52 − 27 = 25, 52 − 25 = 27", "figure": "수 카드 25, 27, 52가 세모 모양으로 놓인 모습"}], "keywords": [{"word": "십의 자리", "meaning": "두 자리 수에서 10개씩 묶음 수를 나타내는 앞자리"}, {"word": "일의 자리", "meaning": "두 자리 수에서 낱개 수를 나타내는 뒷자리"}, {"word": "받아올림", "meaning": "일의 자리 합이 10이 넘을 때 10을 십의 자리로 올리는 것"}, {"word": "받아내림", "meaning": "일의 자리에서 뺄 수 없을 때 십의 자리에서 10을 빌려 오는 것"}], "quiz": [{"q": "44 + 23은 얼마일까요?", "choices": ["67", "21", "77", "66"], "answer": 0, "explain": "일의 자리 4 + 3 = 7, 십의 자리 4 + 2 = 6 → 67이에요."}, {"q": "65 − 21은 얼마일까요?", "choices": ["86", "34", "44", "43"], "answer": 2, "explain": "일의 자리 5 − 1 = 4, 십의 자리 6 − 2 = 4 → 44예요."}, {"q": "29 + 16에서 일의 자리 9 + 6 = 15예요. 다음에 할 일은?", "choices": ["15를 그대로 써요", "5를 쓰고 1을 십의 자리로 올려요", "9를 빼요", "그만 계산해요"], "answer": 1, "explain": "10을 십의 자리로 올리고 일의 자리에 5를 써요. 답은 45예요."}, {"q": "🍓 딸기 50개 중 24개를 먹었어요. 남은 딸기는?", "choices": ["74", "36", "34", "26"], "answer": 3, "explain": "0에서 4를 뺄 수 없어 10을 빌려 와요. 10 − 4 = 6, 4 − 2 = 2 → 26이에요."}], "summary": ["같은 자리끼리 계산해요.", "일의 자리 합이 10을 넘으면 십의 자리로 받아올려요.", "일의 자리에서 뺄 수 없으면 십의 자리에서 10을 받아내려요."], "parent_tip": "가장 흔한 실수는 받아올린 1을 더하지 않거나, 뺄셈에서 큰 수에서 작은 수를 거꾸로 빼는 것(52 − 27에서 7 − 2)입니다. 세로셈을 쓸 때 자리를 맞춰 쓰게 하고, 뺄셈 뒤에는 덧셈으로 검산하는 습관을 들여 주세요.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-06_cover.mp3", "s0": "assets/audio/n/m1-06_s0.mp3", "s1": "assets/audio/n/m1-06_s1.mp3", "s2": "assets/audio/n/m1-06_s2.mp3", "s3": "assets/audio/n/m1-06_s3.mp3", "kw": "assets/audio/n/m1-06_kw.mp3", "q0": "assets/audio/n/m1-06_q0.mp3", "q1": "assets/audio/n/m1-06_q1.mp3", "q2": "assets/audio/n/m1-06_q2.mp3", "q3": "assets/audio/n/m1-06_q3.mp3", "sum": "assets/audio/n/m1-06_sum.mp3"}}$j$::jsonb,6) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','두 자리 수의 덧셈과 뺄셈',6,'m1-06' where not exists (select 1 from public.topics where lesson_slug='m1-06');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-07','1~2','수학','시계 보기','시계 바늘이 알려 주는 시각은?','assets/img/l_m1-07.jpg',$j${"intro": "⏰ 학교 가는 시각, 잠자는 시각. 시계를 보면 알 수 있어요. 짧은바늘과 긴바늘을 읽는 법을 배워요.", "sections": [{"heading": "짧은바늘과 긴바늘", "paras": ["시계에는 바늘이 두 개 있어요.", "짧은바늘은 '시'를 알려 줘요.", "긴바늘은 '분'을 알려 줘요."], "example": "🕒 짧은바늘 3, 긴바늘 12 → 3시", "figure": "벽에 걸린 둥근 아날로그 시계를 아이가 손가락으로 가리키는 모습"}, {"heading": "몇 시, 몇 시 30분", "paras": ["긴바늘이 12를 가리키면 '몇 시'예요.", "긴바늘이 6을 가리키면 '몇 시 30분'이에요.", "30분일 때 짧은바늘은 두 숫자 사이에 있어요."], "example": "🕖 7시: 짧은바늘 7, 긴바늘 12 / 🕡 6시 30분: 짧은바늘 6과 7 사이, 긴바늘 6", "figure": "장난감 시계의 바늘을 6시 30분에 맞춘 모습"}, {"heading": "이렇게 풀어요: 몇 시 몇 분 읽기", "paras": ["긴바늘이 숫자 한 칸을 가면 5분이에요.", "긴바늘이 가리키는 숫자에 5씩 뛰어 세요.", "짧은바늘은 지나온 숫자를 읽어요."], "example": "① 짧은바늘 2와 3 사이 → 2시 ② 긴바늘 4 → 5, 10, 15, 20 → 20분 ③ 2시 20분", "figure": "시계 숫자 옆에 5, 10, 15……를 작은 스티커로 붙인 모습"}, {"heading": "1시간은 60분", "paras": ["긴바늘이 한 바퀴 돌면 60분이 지나요.", "60분은 1시간이에요.", "낮 12시 전은 오전, 낮 12시 후는 오후예요."], "example": "🕗 8시 → 1시간 뒤 → 🕘 9시 / 1시간 30분 = 90분", "figure": "아침 식탁 옆 시계와 저녁 창밖 노을이 함께 보이는 모습"}], "keywords": [{"word": "짧은바늘", "meaning": "'시'를 알려 주는 짧은 바늘"}, {"word": "긴바늘", "meaning": "'분'을 알려 주는 긴 바늘"}, {"word": "30분", "meaning": "긴바늘이 6을 가리킬 때, 1시간의 반"}, {"word": "1시간", "meaning": "긴바늘이 한 바퀴 도는 동안, 60분"}, {"word": "오전·오후", "meaning": "낮 12시 전과 후"}], "quiz": [{"q": "🕘 짧은바늘이 9, 긴바늘이 12를 가리켜요. 몇 시일까요?", "choices": ["12시", "9시 30분", "9시", "3시"], "answer": 2, "explain": "긴바늘이 12이면 '몇 시'예요. 짧은바늘이 9이니 9시예요."}, {"q": "긴바늘이 6을 가리키면 몇 분일까요?", "choices": ["30분", "6분", "60분", "12분"], "answer": 0, "explain": "숫자 하나에 5분씩, 6칸이면 30분이에요."}, {"q": "🕞 3시 30분일 때 짧은바늘은 어디에 있을까요?", "choices": ["3", "3과 4 사이", "6", "12"], "answer": 1, "explain": "30분일 때 짧은바늘은 3과 4의 가운데쯤에 있어요."}, {"q": "긴바늘이 11을 가리키면 몇 분일까요?", "choices": ["11분", "50분", "60분", "55분"], "answer": 3, "explain": "5씩 11번 뛰어 세면 55분이에요."}, {"q": "1시간은 몇 분일까요?", "choices": ["10분", "60분", "100분", "30분"], "answer": 1, "explain": "긴바늘이 한 바퀴 도는 60분이 1시간이에요."}], "summary": ["짧은바늘은 시, 긴바늘은 분을 알려 줘요.", "긴바늘 12는 '몇 시', 6은 '30분', 한 칸은 5분이에요.", "긴바늘이 한 바퀴 돌면 60분 = 1시간이에요."], "parent_tip": "아이들은 두 바늘을 바꿔 읽거나, 짧은바늘이 숫자 사이에 있을 때 다음 숫자로 읽는 실수(2시 50분을 3시 50분)를 자주 합니다. 디지털시계보다 바늘 시계를 집에 두고 '밥 먹는 시각', '잠자는 시각'을 함께 읽어 보세요.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-07_cover.mp3", "s0": "assets/audio/n/m1-07_s0.mp3", "s1": "assets/audio/n/m1-07_s1.mp3", "s2": "assets/audio/n/m1-07_s2.mp3", "s3": "assets/audio/n/m1-07_s3.mp3", "kw": "assets/audio/n/m1-07_kw.mp3", "q0": "assets/audio/n/m1-07_q0.mp3", "q1": "assets/audio/n/m1-07_q1.mp3", "q2": "assets/audio/n/m1-07_q2.mp3", "q3": "assets/audio/n/m1-07_q3.mp3", "q4": "assets/audio/n/m1-07_q4.mp3", "sum": "assets/audio/n/m1-07_sum.mp3"}}$j$::jsonb,7) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','시계 보기',7,'m1-07' where not exists (select 1 from public.topics where lesson_slug='m1-07');
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m1-08','1~2','수학','곱셈 기초(2단·5단)','2씩, 5씩 묶어 세면 곱셈이 돼요!','assets/img/l_m1-08.jpg',$j${"intro": "🧦 양말은 2짝이 한 켤레, ✋ 손 하나에는 손가락이 5개예요. 같은 수씩 묶어 세면 곱셈이 돼요.", "sections": [{"heading": "같은 수씩 묶어 세요", "paras": ["하나씩 세면 오래 걸려요.", "2씩, 5씩 뛰어 세면 빨라요."], "example": "🍒🍒 🍒🍒 🍒🍒 → 2, 4, 6 / ✋✋ → 5, 10", "figure": "체리를 두 개씩 짝지어 접시에 늘어놓은 모습"}, {"heading": "몇의 몇 배", "paras": ["2씩 3묶음은 2의 3배예요.", "2의 3배는 2 + 2 + 2 = 6이에요."], "example": "🍒🍒 🍒🍒 🍒🍒 → 2씩 3묶음 → 2의 3배 → 6", "figure": "작은 컵 세 개에 구슬이 두 개씩 담긴 모습"}, {"heading": "곱셈식으로 써요", "paras": ["2의 3배를 2 × 3 = 6이라고 써요.", "'2 곱하기 3은 6과 같아요'라고 읽어요."], "example": "2 × 3 = 6 은 2 + 2 + 2 = 6과 같아요. 5 × 3 = 15 는 5 + 5 + 5 = 15와 같아요.", "figure": "공책에 2 × 3 = 6 과 덧셈식을 나란히 쓴 모습"}, {"heading": "이렇게 풀어요: 2단과 5단", "paras": ["2단은 2씩 커져요.", "5단은 5씩 커지고, 끝자리가 5와 0으로 번갈아 나와요."], "example": "2단: 2×1=2, 2×2=4, 2×3=6, 2×4=8, 2×5=10, 2×6=12, 2×7=14, 2×8=16, 2×9=18 / 5단: 5×1=5, 5×2=10, 5×3=15, 5×4=20, 5×5=25, 5×6=30, 5×7=35, 5×8=40, 5×9=45", "figure": "계단 모양으로 놓인 블록에 2씩, 5씩 늘어나는 수가 표시된 모습"}], "keywords": [{"word": "묶어 세기", "meaning": "같은 수씩 묶어서 뛰어 세는 것"}, {"word": "몇의 몇 배", "meaning": "같은 수를 몇 번 더한 것(2의 3배 = 2 + 2 + 2)"}, {"word": "곱셈(×)", "meaning": "같은 수를 여러 번 더한 것을 간단히 나타내는 계산"}, {"word": "곱셈구구", "meaning": "1부터 9까지 곱한 값을 차례로 정리한 것(2단, 5단……)"}], "quiz": [{"q": "🍒🍒 🍒🍒 🍒🍒 🍒🍒 체리는 2씩 몇 묶음일까요?", "choices": ["2묶음", "8묶음", "4묶음", "6묶음"], "answer": 2, "explain": "2개씩 묶음이 4개 있어요."}, {"q": "5의 3배를 덧셈식으로 바르게 쓴 것은?", "choices": ["5 + 5 + 5", "5 + 3", "3 + 3 + 3", "5 + 5"], "answer": 0, "explain": "5의 3배는 5를 3번 더한 것이에요."}, {"q": "2 × 6은 얼마일까요?", "choices": ["8", "10", "26", "12"], "answer": 3, "explain": "2, 4, 6, 8, 10, 12 → 12예요."}, {"q": "✋✋✋✋✋ 손가락은 모두 몇 개일까요?", "choices": ["10", "25", "20", "55"], "answer": 1, "explain": "5씩 5묶음 → 5 × 5 = 25예요."}, {"q": "5단 곱셈구구의 값이 __아닌__ 것은?", "choices": ["35", "40", "45", "42"], "answer": 3, "explain": "5단의 값은 끝자리가 5나 0이에요. 42는 5단에 없어요."}], "summary": ["같은 수씩 묶어 세면 빨라요.", "2의 3배는 2 + 2 + 2이고, 2 × 3 = 6으로 써요.", "2단은 2씩, 5단은 5씩 커져요."], "parent_tip": "곱셈구구를 무작정 외우기 전에 '2씩 몇 묶음'을 직접 묶어 보며 곱셈의 뜻을 이해하게 해 주세요. 양말 짝, 젓가락, 손가락처럼 2와 5로 묶인 물건을 찾으며 '모두 몇 개일까?'라고 물어보면 좋습니다.", "expressions": [], "narr": {"cover": "assets/audio/n/m1-08_cover.mp3", "s0": "assets/audio/n/m1-08_s0.mp3", "s1": "assets/audio/n/m1-08_s1.mp3", "s2": "assets/audio/n/m1-08_s2.mp3", "s3": "assets/audio/n/m1-08_s3.mp3", "kw": "assets/audio/n/m1-08_kw.mp3", "q0": "assets/audio/n/m1-08_q0.mp3", "q1": "assets/audio/n/m1-08_q1.mp3", "q2": "assets/audio/n/m1-08_q2.mp3", "q3": "assets/audio/n/m1-08_q3.mp3", "q4": "assets/audio/n/m1-08_q4.mp3", "sum": "assets/audio/n/m1-08_sum.mp3"}}$j$::jsonb,8) on conflict (slug) do update set band=excluded.band,subject=excluded.subject,topic=excluded.topic,title=excluded.title,hero_image=excluded.hero_image,content=excluded.content,sort_order=excluded.sort_order;
insert into public.topics (band,subject,name,sort_order,lesson_slug) select '1~2','수학','곱셈 기초(2단·5단)',8,'m1-08' where not exists (select 1 from public.topics where lesson_slug='m1-08');
