-- 1~2학년 국어·영어·수학, 3~6학년 국어·중국어·일본어 단원 추가 (100단원)
alter table public.lessons drop constraint if exists lessons_band_check, add constraint lessons_band_check check (band in ('1~2','3~4','5~6'));
alter table public.lessons drop constraint if exists lessons_subject_check, add constraint lessons_subject_check check (subject in ('국어','수학','과학','영어','중국어','일본어'));
alter table public.topics drop constraint if exists topics_band_check, add constraint topics_band_check check (band in ('1~2','3~4','5~6'));
alter table public.topics drop constraint if exists topics_subject_check, add constraint topics_subject_check check (subject in ('국어','수학','과학','영어','중국어','일본어'));
alter table public.profiles drop constraint if exists profiles_band_check, add constraint profiles_band_check check (band in ('1~2','3~4','5~6'));
